CREATE OR REPLACE FUNCTION net._await_response(request_id bigint)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
declare
    rec net._http_response;
begin
    while rec is null loop
        select *
        into rec
        from net._http_response
        where id = request_id;

        if rec is null then
            -- Wait 50 ms before checking again
            perform pg_sleep(0.05);
        end if;
    end loop;

    return true;
end;
$function$

CREATE OR REPLACE FUNCTION net._http_collect_response(request_id bigint, async boolean DEFAULT true)
 RETURNS net.http_response_result
 LANGUAGE plpgsql
AS $function$
declare
    rec net._http_response;
    req_exists boolean;
begin

    if not async then
        perform net._await_response(request_id);
    end if;

    select *
    into rec
    from net._http_response
    where id = request_id;

    if rec is null or rec.error_msg is not null then
        -- The request is either still processing or the request_id provided does not exist

        -- TODO: request in progress is indistinguishable from request that doesn't exist

        -- No request matching request_id found
        return (
            'ERROR',
            coalesce(rec.error_msg, 'request matching request_id not found'),
            null
        )::net.http_response_result;

    end if;

    -- Return a valid, populated http_response_result
    return (
        'SUCCESS',
        'ok',
        (
            rec.status_code,
            rec.headers,
            rec.content
        )::net.http_response
    )::net.http_response_result;
end;
$function$

CREATE OR REPLACE FUNCTION net.http_collect_response(request_id bigint, async boolean DEFAULT true)
 RETURNS net.http_response_result
 LANGUAGE plpgsql
AS $function$
begin
  raise notice 'The net.http_collect_response function is deprecated.';
  select net._http_collect_response(request_id, async);
end;
$function$

CREATE OR REPLACE FUNCTION public._build_business_summary_before133(p_summary_type text, p_period_start date, p_period_end date, p_generated_at timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_result JSONB;
  v_facts JSONB;
  v_timezone TEXT;
BEGIN
  -- The inner builder validates the period and the configured timezone.
  v_result := public._build_business_summary_before_phase6(
    p_summary_type, p_period_start, p_period_end, p_generated_at
  );
  SELECT business_timezone INTO STRICT v_timezone
  FROM public.business_alert_settings WHERE id = true;
  v_facts := public.phase6_financial_facts_internal(
    NULL,
    p_period_start::TIMESTAMP AT TIME ZONE v_timezone,
    (p_period_end + 1)::TIMESTAMP AT TIME ZONE v_timezone,
    v_timezone,
    false
  );
  v_result := jsonb_set(v_result, '{sales}', (v_result->'sales') || (v_facts->'sales'));
  v_result := jsonb_set(v_result, '{balances}', (v_result->'balances') || (v_facts->'balances'));
  v_result := jsonb_set(v_result, '{expenses}', (v_result->'expenses') || (v_facts->'expenses'));
  v_result := v_result || jsonb_build_object(
    'cashFlow', v_facts->'cashFlow',
    'dailyBreakdown', v_facts->'dailyBreakdown'
  );
  IF jsonb_typeof(v_result) <> 'object'
    OR octet_length(v_result::TEXT) > 32768
  THEN
    RAISE EXCEPTION 'Business summary payload is invalid or too large.';
  END IF;
  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public._calculate_guest_promotion(p_code text, p_items jsonb, p_customer_phone text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_code TEXT := UPPER(NULLIF(TRIM(p_code), ''));
  v_phone TEXT := CASE
    WHEN NULLIF(TRIM(p_customer_phone), '') IS NULL THEN NULL
    ELSE public.normalize_customer_phone(p_customer_phone)
  END;
  v_promotion public.promotion_codes%ROWTYPE;
  v_item JSONB;
  v_product_id UUID;
  v_quantity INTEGER;
  v_package_price BIGINT;
  v_units_per_package INTEGER;
  v_subtotal BIGINT := 0;
  v_discount BIGINT := 0;
  v_total_redemptions INTEGER := 0;
  v_phone_redemptions INTEGER := 0;
BEGIN
  IF v_code IS NULL OR v_code !~ '^[A-Z0-9_-]{3,32}$' THEN
    RAISE EXCEPTION 'اكتب رمز خصم صحيحاً.';
  END IF;

  IF p_items IS NULL
    OR jsonb_typeof(p_items) <> 'array'
    OR jsonb_array_length(p_items) = 0
    OR jsonb_array_length(p_items) > 50
  THEN
    RAISE EXCEPTION 'سلة الطلب غير صالحة لحساب الخصم.';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_items) AS item(value)
    GROUP BY item.value->>'product_id'
    HAVING COUNT(*) > 1
  ) THEN
    RAISE EXCEPTION 'لا يمكن تكرار المنتج نفسه داخل الطلب.';
  END IF;

  FOR v_item IN
    SELECT item.value
    FROM jsonb_array_elements(p_items) AS item(value)
    ORDER BY item.value->>'product_id'
  LOOP
    BEGIN
      v_product_id := (v_item->>'product_id')::UUID;
      v_quantity := (v_item->>'quantity')::INTEGER;
    EXCEPTION
      WHEN invalid_text_representation THEN
        RAISE EXCEPTION 'بيانات أحد طرود الطلب غير صحيحة.';
    END;

    IF v_product_id IS NULL OR COALESCE(v_quantity, 0) <= 0 THEN
      RAISE EXCEPTION 'بيانات أحد طرود الطلب غير صحيحة.';
    END IF;

    SELECT
      p.default_sale_price_in_minor_units,
      p.units_per_sale_unit
    INTO v_package_price, v_units_per_package
    FROM public.products AS p
    WHERE p.id = v_product_id
      AND p.is_active = true;

    IF NOT FOUND
      OR COALESCE(v_package_price, 0) <= 0
      OR COALESCE(v_units_per_package, 0) <= 0
    THEN
      RAISE EXCEPTION 'أحد منتجات السلة غير متاح للبيع.';
    END IF;

    v_subtotal := v_subtotal + (v_quantity * v_package_price);
  END LOOP;

  SELECT pc.*
  INTO v_promotion
  FROM public.promotion_codes AS pc
  WHERE pc.code = v_code
  FOR UPDATE;

  IF NOT FOUND OR NOT v_promotion.is_active THEN
    RAISE EXCEPTION 'رمز الخصم غير صحيح أو غير فعال.';
  END IF;

  IF v_promotion.starts_at IS NOT NULL
    AND NOW() < v_promotion.starts_at
  THEN
    RAISE EXCEPTION 'رمز الخصم لم يبدأ بعد.';
  END IF;

  IF v_promotion.expires_at IS NOT NULL
    AND NOW() >= v_promotion.expires_at
  THEN
    RAISE EXCEPTION 'انتهت صلاحية رمز الخصم.';
  END IF;

  IF v_subtotal < v_promotion.minimum_subtotal_in_minor_units THEN
    RAISE EXCEPTION
      'الطلب لا يصل إلى الحد الأدنى المطلوب لهذا الخصم.';
  END IF;

  SELECT COUNT(*)::INTEGER
  INTO v_total_redemptions
  FROM public.promotion_redemptions AS pr
  WHERE pr.promotion_code_id = v_promotion.id;

  IF v_promotion.maximum_total_redemptions IS NOT NULL
    AND v_total_redemptions >= v_promotion.maximum_total_redemptions
  THEN
    RAISE EXCEPTION 'تم استنفاد عدد استخدامات رمز الخصم.';
  END IF;

  IF v_phone IS NOT NULL THEN
    IF v_phone !~ '^07[789][0-9]{7}$' THEN
      RAISE EXCEPTION 'رقم الهاتف الأردني غير صحيح.';
    END IF;

    SELECT COUNT(*)::INTEGER
    INTO v_phone_redemptions
    FROM public.promotion_redemptions AS pr
    WHERE pr.promotion_code_id = v_promotion.id
      AND pr.customer_phone = v_phone;

    IF v_phone_redemptions >=
      v_promotion.maximum_redemptions_per_phone
    THEN
      RAISE EXCEPTION 'تم استخدام رمز الخصم لهذا الرقم من قبل.';
    END IF;
  END IF;

  IF v_promotion.discount_type = 'fixed' THEN
    v_discount := LEAST(v_promotion.discount_value, v_subtotal);
  ELSE
    v_discount := FLOOR(
      (v_subtotal::NUMERIC * v_promotion.discount_value::NUMERIC)
      / 10000
    )::BIGINT;

    IF v_promotion.maximum_discount_in_minor_units IS NOT NULL THEN
      v_discount := LEAST(
        v_discount,
        v_promotion.maximum_discount_in_minor_units
      );
    END IF;
  END IF;

  v_discount := LEAST(GREATEST(v_discount, 0), v_subtotal);
  IF v_discount <= 0 THEN
    RAISE EXCEPTION 'قيمة الخصم المحسوبة غير صالحة لهذا الطلب.';
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'promotion_code_id', v_promotion.id,
    'code', v_promotion.code,
    'description', v_promotion.description_ar,
    'subtotal', v_subtotal,
    'discount', v_discount,
    'total', v_subtotal - v_discount,
    'message', 'تم تطبيق رمز الخصم بنجاح.'
  );
END;
$function$

CREATE OR REPLACE FUNCTION public._cancel_empty_cash_shift_before_return_events(p_shift_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_shift public.cash_shifts%ROWTYPE;
  v_reason TEXT := NULLIF(TRIM(p_reason), '');
BEGIN
  PERFORM public.assert_erp_role(
    ARRAY['owner', 'admin', 'manager'],
    'إلغاء وردية فُتحت بالخطأ'
  );

  IF v_reason IS NULL OR CHAR_LENGTH(v_reason) < 2 THEN
    RAISE EXCEPTION 'اكتب سبب إلغاء الوردية.';
  END IF;
  IF CHAR_LENGTH(v_reason) > 500 THEN
    RAISE EXCEPTION 'سبب إلغاء الوردية أطول من المسموح.';
  END IF;

  SELECT * INTO v_shift
  FROM public.cash_shifts
  WHERE id = p_shift_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'الوردية المحددة غير موجودة.';
  END IF;
  IF v_shift.status <> 'open' THEN
    RAISE EXCEPTION 'يمكن إلغاء وردية مفتوحة فقط.';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.orders
    WHERE cash_shift_id = p_shift_id
    UNION ALL
    SELECT 1 FROM public.customer_payments
    WHERE cash_shift_id = p_shift_id
    UNION ALL
    SELECT 1 FROM public.supplier_payments
    WHERE cash_shift_id = p_shift_id
    UNION ALL
    SELECT 1 FROM public.operational_expenses
    WHERE shift_id = p_shift_id
    UNION ALL
    SELECT 1 FROM public.sales_returns
    WHERE cash_shift_id = p_shift_id
  ) THEN
    RAISE EXCEPTION
      'لا يمكن إلغاء الوردية لأنها تحتوي حركة مالية. صحح العملية ثم أغلق الوردية طبيعيًا.';
  END IF;

  UPDATE public.cash_shifts
  SET
    status = 'cancelled',
    cancelled_by = v_user_id,
    cancelled_at = NOW(),
    cancellation_reason = v_reason,
    expected_cash_in_minor_units = opening_cash_in_minor_units,
    updated_at = NOW()
  WHERE id = p_shift_id;

  INSERT INTO public.audit_logs (
    user_id, action, entity_name, entity_id, details
  ) VALUES (
    v_user_id,
    'CANCEL_EMPTY_CASH_SHIFT',
    'cash_shifts',
    p_shift_id,
    jsonb_build_object(
      'shift_number', v_shift.shift_number,
      'opening_cash_in_minor_units',
        v_shift.opening_cash_in_minor_units,
      'reason', v_reason,
      'verified_empty', true
    )
  );

  RETURN public.get_cash_shift_display_summary(p_shift_id)
    || jsonb_build_object(
      'success', true,
      'message',
        'تم إلغاء الوردية الفارغة وحفظ السبب في سجل التدقيق.'
    );
END;
$function$

CREATE OR REPLACE FUNCTION public._cancel_order_impl_before_phase4_lock(p_order_id uuid, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_order_number TEXT;
  v_warehouse_id UUID;
  v_old_status TEXT;
  v_item RECORD;
  v_user_id UUID;
BEGIN
  v_user_id := auth.uid();

  -- Fetch order details
  SELECT order_number, warehouse_id, status
  INTO v_order_number, v_warehouse_id, v_old_status
  FROM public.orders
  WHERE id = p_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'الطلب المحدد غير موجود في قاعدة البيانات.';
  END IF;

  IF v_old_status = 'completed' THEN
    RAISE EXCEPTION 'لا يمكن إلغاء طلب مكتمل ومخصوم من المخزون بالفعل.';
  END IF;

  IF v_old_status = 'cancelled' THEN
    RAISE EXCEPTION 'الطلب ملغى بالفعل.';
  END IF;

  -- Release reserved stock for each order item if warehouse_id is set
  IF v_warehouse_id IS NOT NULL THEN
    FOR v_item IN
      SELECT product_id, quantity
      FROM public.order_items
      WHERE order_id = p_order_id
    LOOP
      UPDATE public.inventory_balances
      SET reserved_quantity = GREATEST(0, reserved_quantity - v_item.quantity),
          updated_at = NOW()
      WHERE warehouse_id = v_warehouse_id AND product_id = v_item.product_id;
    END LOOP;
  END IF;

  -- Update order status to cancelled
  UPDATE public.orders
  SET status = 'cancelled',
      updated_at = NOW()
  WHERE id = p_order_id;

  -- Record status history
  INSERT INTO public.order_status_history (
    order_id,
    old_status,
    new_status,
    changed_by,
    notes
  ) VALUES (
    p_order_id,
    v_old_status,
    'cancelled',
    v_user_id,
    COALESCE(p_notes, 'إلغاء الطلب وتحرير الكمية المحجوزة بالمخزون')
  );

  -- Record audit log
  INSERT INTO public.audit_logs (
    user_id,
    action,
    entity_name,
    entity_id,
    details
  ) VALUES (
    v_user_id,
    'cancel_order',
    'orders',
    p_order_id,
    jsonb_build_object(
      'order_number', v_order_number,
      'old_status', v_old_status,
      'new_status', 'cancelled'
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'order_id', p_order_id,
    'order_number', v_order_number,
    'status', 'cancelled',
    'message', 'تم إلغاء الطلب وتحرير المخزون المحجوز بنجاح.'
  );

EXCEPTION WHEN OTHERS THEN
  RAISE EXCEPTION 'فشلت عملية إلغاء الطلب: %', SQLERRM;
END;
$function$

CREATE OR REPLACE FUNCTION public._cancel_purchase_receipt_v2_before_phase4_lock(p_purchase_receipt_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_reason TEXT := NULLIF(BTRIM(p_reason), '');
  v_receipt public.purchase_receipts%ROWTYPE;
  v_reversal_operation_id UUID := gen_random_uuid();
  v_result JSONB;
  v_inventory_result JSONB;
  v_payment_total BIGINT;
  v_po_status TEXT;
BEGIN
  PERFORM public.assert_erp_role(
    ARRAY['owner', 'admin', 'manager', 'warehouse_keeper'],
    'إلغاء سند استلام أمر شراء'
  );
  PERFORM public.phase2_lock_receipt_payment_shifts_internal(
    NULL, p_purchase_receipt_id
  );
  IF v_reason IS NULL THEN
    RAISE EXCEPTION 'سبب إلغاء سند الاستلام مطلوب.';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.purchase_receipts receipt
    WHERE receipt.id = p_purchase_receipt_id
      AND receipt.phase2_finalized_at IS NOT NULL
  ) THEN
    PERFORM public.phase2_lock_inventory_products_internal(ARRAY(
      SELECT DISTINCT item.product_id
      FROM public.purchase_receipt_items item
      WHERE item.purchase_receipt_id = p_purchase_receipt_id
      ORDER BY item.product_id
    ));
  END IF;
  SELECT * INTO v_receipt
  FROM public.purchase_receipts receipt
  WHERE receipt.id = p_purchase_receipt_id
  FOR UPDATE;
  IF NOT FOUND OR v_receipt.phase2_finalized_at IS NULL THEN
    RAISE EXCEPTION 'سند الاستلام Phase 2 غير موجود.';
  END IF;
  IF v_receipt.status = 'cancelled' THEN
    SELECT operation.result_snapshot INTO v_result FROM public.business_operations operation
    WHERE operation.operation_type = 'purchase_receipt_cancellation_v2'
      AND operation.result_snapshot->>'original_operation_id' = v_receipt.operation_id::TEXT
      AND operation.result_snapshot->>'supplier_balance_contract_version' = '133'
    ORDER BY operation.completed_at, operation.id LIMIT 1;
    IF FOUND THEN RETURN v_result; END IF;
    RAISE EXCEPTION 'هذا السند ملغى أو معكوس مسبقاً.';
  END IF;
  IF v_receipt.status <> 'completed' THEN
    RAISE EXCEPTION 'هذا السند ملغى أو معكوس مسبقاً.';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.supplier_payments payment
    WHERE payment.purchase_receipt_id = v_receipt.id
      AND NOT payment.is_reversed
      AND payment.operation_id IS DISTINCT FROM v_receipt.operation_id
  ) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE2_LATER_PAYMENT_CANCELLATION_UNSUPPORTED: لا يمكن إلغاء سند لديه دفعات لاحقة دون سياسة رد أو ائتمان معتمدة.';
  END IF;

  PERFORM 1 FROM public.purchase_orders purchase_order
  WHERE purchase_order.id = v_receipt.purchase_order_id
  FOR UPDATE;
  PERFORM item.id
  FROM public.purchase_order_items item
  JOIN public.purchase_receipt_commercial_lines line
    ON line.purchase_order_item_id = item.id
  WHERE line.purchase_receipt_id = v_receipt.id
  ORDER BY item.id
  FOR UPDATE OF item;

  -- PO-wide payments remain genuine advances after cancelling a receipt.
  -- Only payments owned by this exact receipt are reversed by cancellation.
  SELECT COALESCE(SUM(payment.amount_in_minor_units), 0) INTO v_payment_total
  FROM public.supplier_payments payment
  WHERE payment.purchase_receipt_id = v_receipt.id AND NOT payment.is_reversed;

  -- Capture the complete immutable cancellation result BEFORE its first
  -- insertion. business_operations history is never updated or weakened.
  SELECT CASE WHEN EXISTS (
    SELECT 1 FROM public.purchase_order_items item
    LEFT JOIN public.purchase_receipt_commercial_lines line
      ON line.purchase_order_item_id=item.id AND line.purchase_receipt_id=v_receipt.id
    WHERE item.purchase_order_id=v_receipt.purchase_order_id
      AND item.received_quantity-COALESCE(line.received_base_unit_quantity,0)>0
  ) THEN 'partially_received' ELSE 'approved' END INTO v_po_status;
  v_result := jsonb_build_object(
    'success', true,
    'receipt_id', v_receipt.id,
    'receipt_number', v_receipt.receipt_number,
    'original_operation_id', v_receipt.operation_id,
    'reversal_operation_id', v_reversal_operation_id,
    'payments_marked_reversed_in_minor_units', v_payment_total,
    'purchase_order_status', v_po_status,
    'supplier_balance_contract_version', 133,
    'reversed_base_units', (SELECT COALESCE(SUM(movement.quantity),0)::INTEGER
      FROM public.inventory_movements movement WHERE movement.operation_id=v_receipt.operation_id
        AND movement.movement_type='purchase_receipt')
  );
  INSERT INTO public.business_operations (
    id, operation_type, initiated_by, result_snapshot, completed_at
  ) VALUES (
    v_reversal_operation_id, 'purchase_receipt_cancellation_v2',
    v_user_id, v_result, NOW()
  );

  v_inventory_result := public.phase2_reverse_inventory_and_wac_internal(
    v_receipt.operation_id, v_reversal_operation_id, v_receipt.warehouse_id,
    'purchase_receipt', v_receipt.id, v_user_id, v_reason
  );

  UPDATE public.purchase_order_items item
  SET
    received_quantity = item.received_quantity - line.received_base_unit_quantity,
    received_parcel_quantity = item.received_parcel_quantity
      - COALESCE(line.received_parcel_quantity, 0),
    updated_at = NOW()
  FROM public.purchase_receipt_commercial_lines line
  WHERE line.purchase_receipt_id = v_receipt.id
    AND item.id = line.purchase_order_item_id;

  SELECT CASE
    WHEN EXISTS (
      SELECT 1 FROM public.purchase_order_items item
      WHERE item.purchase_order_id = v_receipt.purchase_order_id
        AND item.received_quantity > 0
    ) THEN 'partially_received'
    ELSE 'approved'
  END INTO v_po_status;
  UPDATE public.purchase_orders
  SET status = v_po_status, received_at = NULL,
    amount_paid_in_minor_units = amount_paid_in_minor_units - v_payment_total,
    updated_at = NOW()
  WHERE id = v_receipt.purchase_order_id;

  UPDATE public.suppliers
  SET current_balance_in_minor_units = current_balance_in_minor_units
      - v_receipt.supplier_invoice_payable_total_snapshot_in_minor_units + v_payment_total,
    updated_at = NOW()
  WHERE id = v_receipt.supplier_id;

  -- v_payment_total was captured under the original document/shift locks.
  UPDATE public.supplier_payments
  SET is_reversed = true, reversed_at = NOW(), reversed_by = v_user_id,
    reversal_reason = v_reason
  WHERE purchase_receipt_id = v_receipt.id AND NOT is_reversed;
  UPDATE public.supplier_financial_invoice_identities
  SET is_active = false, cancelled_at = NOW()
  WHERE purchase_receipt_id = v_receipt.id AND is_active;
  UPDATE public.purchase_receipts
  SET status = 'cancelled', phase2_cancelled_at = NOW(),
    phase2_cancelled_by = v_user_id,
    phase2_cancellation_reason = v_reason
  WHERE id = v_receipt.id;

  INSERT INTO public.audit_logs (
    user_id, action, entity_name, entity_id, details
  ) VALUES (
    v_user_id, 'CANCEL_PURCHASE_RECEIPT_V2', 'purchase_receipts',
    v_receipt.id,
    jsonb_build_object(
      'original_operation_id', v_receipt.operation_id,
      'reversal_operation_id', v_reversal_operation_id,
      'supplier_outstanding_reversed_in_minor_units',
        v_receipt.supplier_invoice_payable_total_snapshot_in_minor_units - v_payment_total,
      'payments_marked_reversed_in_minor_units', v_payment_total,
      'purchase_order_status', v_po_status,
      'inventory', v_inventory_result
    )
  );
  IF v_inventory_result->>'reversed_base_units' IS DISTINCT FROM v_result->>'reversed_base_units'
    OR v_po_status IS DISTINCT FROM v_result->>'purchase_order_status'
  THEN RAISE EXCEPTION 'SUPPLIER_CANCELLATION_RESULT_MISMATCH'; END IF;
  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public._cancel_supplier_receipt_before_phase4_lock(p_supplier_receipt_id uuid, p_reason text DEFAULT 'إلغاء سند استلام البضائع'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_receipt public.supplier_receipts%ROWTYPE;
  v_user UUID:=auth.uid(); v_reason TEXT:=NULLIF(BTRIM(p_reason),'');
  v_operation UUID:=gen_random_uuid();v_paid BIGINT;v_result JSONB;v_inventory JSONB;
BEGIN
  PERFORM public.assert_erp_role(ARRAY['owner','admin','manager','warehouse_keeper'],'إلغاء سند استلام');
  IF v_reason IS NULL THEN RAISE EXCEPTION 'سبب الإلغاء مطلوب.'; END IF;
  PERFORM public.phase2_lock_receipt_payment_shifts_internal(p_supplier_receipt_id,NULL);
  PERFORM public.phase2_lock_inventory_products_internal(ARRAY(
    SELECT DISTINCT product_id FROM public.supplier_receipt_items WHERE supplier_receipt_id=p_supplier_receipt_id ORDER BY product_id));
  SELECT * INTO v_receipt FROM public.supplier_receipts WHERE id=p_supplier_receipt_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'سند الاستلام غير موجود.'; END IF;
  IF v_receipt.phase2_finalized_at IS NULL THEN
    RETURN public._cancel_supplier_receipt_legacy_guarded_v2(p_supplier_receipt_id,p_reason);
  END IF;
  IF v_receipt.status='cancelled' THEN
    SELECT result_snapshot INTO v_result FROM public.business_operations
    WHERE operation_type='supplier_receipt_cancellation_v2'
      AND result_snapshot->>'original_operation_id'=v_receipt.operation_id::TEXT
      AND result_snapshot->>'supplier_balance_contract_version'='133'
    ORDER BY completed_at,id LIMIT 1;
    IF FOUND THEN RETURN v_result; END IF;
    RAISE EXCEPTION 'السند ملغى مسبقاً.';
  END IF;
  IF v_receipt.status<>'completed' THEN RAISE EXCEPTION 'السند غير قابل للإلغاء.'; END IF;
  SELECT COALESCE(SUM(amount_in_minor_units),0)::BIGINT INTO v_paid
  FROM public.supplier_payments WHERE supplier_receipt_id=v_receipt.id AND NOT is_reversed;
  v_result:=jsonb_build_object('success',true,'receipt_id',v_receipt.id,'receipt_number',v_receipt.receipt_number,
    'original_operation_id',v_receipt.operation_id,'reversal_operation_id',v_operation,
    'supplier_balance_contract_version',133,'payments_marked_reversed_in_minor_units',v_paid,
    'reversed_base_units',(SELECT COALESCE(SUM(quantity),0)::INTEGER FROM public.inventory_movements
      WHERE operation_id=v_receipt.operation_id AND movement_type='purchase_receipt'));
  INSERT INTO public.business_operations(id,operation_type,initiated_by,result_snapshot,completed_at)
  VALUES(v_operation,'supplier_receipt_cancellation_v2',v_user,v_result,NOW());
  v_inventory:=public.phase2_reverse_inventory_and_wac_internal(v_receipt.operation_id,v_operation,
    v_receipt.warehouse_id,'supplier_receipt',v_receipt.id,v_user,v_reason);
  UPDATE public.suppliers SET current_balance_in_minor_units=current_balance_in_minor_units
    -v_receipt.supplier_invoice_payable_total_snapshot_in_minor_units+v_paid,updated_at=NOW()
  WHERE id=v_receipt.supplier_id;
  UPDATE public.supplier_payments SET is_reversed=true,reversed_at=NOW(),reversed_by=v_user,reversal_reason=v_reason
  WHERE supplier_receipt_id=v_receipt.id AND NOT is_reversed;
  UPDATE public.supplier_financial_invoice_identities SET is_active=false,cancelled_at=NOW()
  WHERE supplier_receipt_id=v_receipt.id AND is_active;
  UPDATE public.supplier_receipts SET status='cancelled',is_archived=true,phase2_cancelled_at=NOW(),
    phase2_cancelled_by=v_user,phase2_cancellation_reason=v_reason,updated_at=NOW() WHERE id=v_receipt.id;
  INSERT INTO public.audit_logs(user_id,action,entity_name,entity_id,details)
  VALUES(v_user,'CANCEL_SUPPLIER_RECEIPT_V2','supplier_receipts',v_receipt.id,
    v_result||jsonb_build_object('inventory',v_inventory,'supplier_outstanding_reversed_in_minor_units',
      v_receipt.supplier_invoice_payable_total_snapshot_in_minor_units-v_paid));
  IF v_inventory->>'reversed_base_units' IS DISTINCT FROM v_result->>'reversed_base_units'
  THEN RAISE EXCEPTION 'SUPPLIER_CANCELLATION_RESULT_MISMATCH'; END IF;
  RETURN v_result;
END; $function$

CREATE OR REPLACE FUNCTION public._cancel_supplier_receipt_legacy_guarded_v2(p_supplier_receipt_id uuid, p_reason text DEFAULT 'إلغاء سند استلام البضائع'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_receipt public.supplier_receipts%ROWTYPE;
  v_item RECORD;
  v_on_hand BIGINT;
  v_reserved BIGINT;
  v_total_on_hand BIGINT;
BEGIN
  PERFORM public.assert_erp_role(
    ARRAY['owner', 'admin', 'manager', 'warehouse_keeper'],
    'إلغاء سندات الاستلام'
  );

  SELECT * INTO v_receipt
  FROM public.supplier_receipts
  WHERE id = p_supplier_receipt_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'سند الاستلام غير موجود.';
  END IF;
  IF v_receipt.status <> 'completed' THEN
    RAISE EXCEPTION 'هذا السند ملغى أو معكوس مسبقاً.';
  END IF;

  FOR v_item IN
    SELECT sri.product_id, sri.total_base_units, p.name_ar AS product_name
    FROM public.supplier_receipt_items sri
    JOIN public.products p ON p.id = sri.product_id
    WHERE sri.supplier_receipt_id = p_supplier_receipt_id
    ORDER BY sri.product_id
  LOOP
    SELECT ib.on_hand_quantity, ib.reserved_quantity
    INTO v_on_hand, v_reserved
    FROM public.inventory_balances ib
    WHERE ib.warehouse_id = v_receipt.warehouse_id
      AND ib.product_id = v_item.product_id
    FOR UPDATE;

    IF COALESCE(v_on_hand, 0) <> v_item.total_base_units
      OR COALESCE(v_reserved, 0) <> 0
    THEN
      RAISE EXCEPTION
        'لا يمكن إلغاء سند الاستلام مباشرة للمنتج % لأن المخزون تحرك بعده أو أصبح محجوزاً. استخدم مرتجع المورد للحفاظ على متوسط التكلفة.',
        v_item.product_name;
    END IF;

    SELECT COALESCE(SUM(ib.on_hand_quantity), 0)
    INTO v_total_on_hand
    FROM public.inventory_balances ib
    WHERE ib.product_id = v_item.product_id;

    IF v_total_on_hand <> v_item.total_base_units THEN
      RAISE EXCEPTION
        'لا يمكن إلغاء سند الاستلام مباشرة للمنتج % لأن متوسط التكلفة يتضمن مخزوناً سابقاً أو لاحقاً. استخدم مرتجع المورد للحفاظ على متوسط التكلفة.',
        v_item.product_name;
    END IF;

    IF EXISTS (
      SELECT 1
      FROM public.inventory_movements im
      WHERE im.product_id = v_item.product_id
        AND im.reference_id IS DISTINCT FROM p_supplier_receipt_id
        AND im.created_at >= v_receipt.received_at
    ) THEN
      RAISE EXCEPTION
        'لا يمكن إلغاء سند الاستلام مباشرة للمنتج % بعد وجود حركة مخزون لاحقة. استخدم مرتجع المورد للحفاظ على متوسط التكلفة.',
        v_item.product_name;
    END IF;
  END LOOP;

  RETURN public._cancel_supplier_receipt_impl(
    p_supplier_receipt_id,
    p_reason
  );
END;
$function$

CREATE OR REPLACE FUNCTION public._complete_order_impl_before_phase4_lock(p_order_id uuid, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_order_number TEXT;
  v_warehouse_id UUID;
  v_old_status TEXT;
  v_item RECORD;
  v_on_hand INT;
  v_reserved INT;
  v_new_on_hand INT;
  v_new_reserved INT;
  v_user_id UUID;
BEGIN
  v_user_id := auth.uid();

  -- Fetch order details with lock
  SELECT order_number, warehouse_id, status
  INTO v_order_number, v_warehouse_id, v_old_status
  FROM public.orders
  WHERE id = p_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'الطلب المحدد غير موجود في قاعدة البيانات.';
  END IF;

  IF v_old_status = 'completed' THEN
    RAISE EXCEPTION 'الطلب مكتمل ومخصوم من المخزون بالفعل، ولا يمكن إكماله مرة أخرى.';
  END IF;

  IF v_old_status = 'cancelled' THEN
    RAISE EXCEPTION 'لا يمكن إكمال طلب ملغى.';
  END IF;

  IF v_warehouse_id IS NULL THEN
    RAISE EXCEPTION 'المستودع الخاص بالطلب غير محدد.';
  END IF;

  -- Process inventory deduction for each order item
  FOR v_item IN
    SELECT product_id, quantity
    FROM public.order_items
    WHERE order_id = p_order_id
  LOOP
    SELECT on_hand_quantity, reserved_quantity
    INTO v_on_hand, v_reserved
    FROM public.inventory_balances
    WHERE warehouse_id = v_warehouse_id AND product_id = v_item.product_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'لم يتم العثور على رصيد المخزون للمنتج برقم (%) في المستودع.', v_item.product_id;
    END IF;

    v_new_on_hand := v_on_hand - v_item.quantity;
    v_new_reserved := GREATEST(0, v_reserved - v_item.quantity);

    IF v_new_on_hand < 0 THEN
      RAISE EXCEPTION 'الكمية الفعلية بالمخزون غير كافية لخصم الطلب. المتوفر الفعلي: %', v_on_hand;
    END IF;

    -- Update balance row
    UPDATE public.inventory_balances
    SET on_hand_quantity = v_new_on_hand,
        reserved_quantity = v_new_reserved,
        updated_at = NOW()
    WHERE warehouse_id = v_warehouse_id AND product_id = v_item.product_id;

    -- Record sales deduction movement
    INSERT INTO public.inventory_movements (
      warehouse_id,
      product_id,
      movement_type,
      quantity,
      balance_before,
      balance_after,
      reference_type,
      reference_id,
      notes,
      created_by
    ) VALUES (
      v_warehouse_id,
      v_item.product_id,
      'sales_deduction',
      -v_item.quantity,
      v_on_hand,
      v_new_on_hand,
      'order',
      p_order_id,
      'خصم مبيعات نهائي للطلب رقم ' || v_order_number,
      v_user_id
    );
  END LOOP;

  -- Update order status to completed and payment_status to paid
  UPDATE public.orders
  SET status = 'completed',
      payment_status = 'paid',
      updated_at = NOW()
  WHERE id = p_order_id;

  -- Record status history
  INSERT INTO public.order_status_history (
    order_id,
    old_status,
    new_status,
    changed_by,
    notes
  ) VALUES (
    p_order_id,
    v_old_status,
    'completed',
    v_user_id,
    COALESCE(p_notes, 'تسليم الطلب وإكمال الخصم النهائي من المخزون وتحصيل المبلغ')
  );

  -- Record audit log
  INSERT INTO public.audit_logs (
    user_id,
    action,
    entity_name,
    entity_id,
    details
  ) VALUES (
    v_user_id,
    'complete_order',
    'orders',
    p_order_id,
    jsonb_build_object(
      'order_number', v_order_number,
      'old_status', v_old_status,
      'new_status', 'completed'
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'order_id', p_order_id,
    'order_number', v_order_number,
    'status', 'completed',
    'message', 'تم إكمال الطلب وخصم الكميات من المخزون وتحديث الحسابات بنجاح.'
  );

EXCEPTION WHEN OTHERS THEN
  RAISE EXCEPTION 'فشلت عملية إكمال الطلب: %', SQLERRM;
END;
$function$

CREATE OR REPLACE FUNCTION public._complete_website_order_with_settlement_before_phase4_lock(p_order_id uuid, p_payment_method text, p_amount_collected_in_minor_units bigint DEFAULT NULL::bigint, p_delivery_fee_in_minor_units bigint DEFAULT NULL::bigint, p_reference_number text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_order public.orders%ROWTYPE;
  v_payment_method TEXT := LOWER(NULLIF(TRIM(p_payment_method), ''));
  v_delivery_fee BIGINT;
  v_total BIGINT;
  v_collected BIGINT;
  v_remaining BIGINT;
  v_shift_id UUID;
  v_shift_number TEXT;
  v_result JSONB;
  v_payment_result JSONB;
BEGIN
  PERFORM public.assert_erp_role(
    ARRAY['owner', 'admin', 'manager', 'sales'],
    'تسليم الطلب وتسجيل التحصيل والذمة'
  );

  IF v_payment_method = 'cash_on_delivery' THEN
    v_payment_method := 'cash';
  END IF;
  IF v_payment_method NOT IN ('cash', 'cliq', 'debt') THEN
    RAISE EXCEPTION 'طريقة التحصيل يجب أن تكون كاش أو CliQ أو على الحساب.';
  END IF;

  SELECT *
  INTO v_order
  FROM public.orders
  WHERE id = p_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'الطلب المحدد غير موجود.';
  END IF;
  IF v_order.source = 'pos' THEN
    RAISE EXCEPTION 'طلبات البيع المباشر تُحصّل من شاشة نقطة البيع.';
  END IF;
  IF v_order.status NOT IN ('ready', 'out_for_delivery') THEN
    RAISE EXCEPTION 'لا يمكن تسليم الطلب من حالته الحالية (%).', v_order.status;
  END IF;
  IF v_order.branch_id IS NULL THEN
    RAISE EXCEPTION 'لا يمكن إتمام الطلب دون فرع محدد.';
  END IF;

  v_delivery_fee := COALESCE(
    p_delivery_fee_in_minor_units,
    v_order.delivery_fee_in_minor_units,
    0
  );
  IF v_delivery_fee < 0 THEN
    RAISE EXCEPTION 'أجرة التوصيل لا يمكن أن تكون سالبة.';
  END IF;

  v_total := v_order.subtotal_in_minor_units
    - v_order.discount_in_minor_units
    + v_delivery_fee;
  IF v_total < 0 THEN
    RAISE EXCEPTION 'إجمالي الطلب بعد الخصم والتوصيل غير صحيح.';
  END IF;

  v_collected := CASE
    WHEN v_payment_method = 'debt' THEN 0
    ELSE COALESCE(p_amount_collected_in_minor_units, v_total)
  END;
  IF v_collected < 0 OR v_collected > v_total THEN
    RAISE EXCEPTION 'المبلغ المقبوض يجب أن يكون بين صفر وإجمالي الطلب.';
  END IF;
  IF v_collected = 0 THEN
    v_payment_method := 'debt';
  END IF;
  IF v_payment_method = 'cliq'
    AND v_collected > 0
    AND NULLIF(TRIM(p_reference_number), '') IS NULL
  THEN
    RAISE EXCEPTION 'رقم مرجع CliQ مطلوب عند تسجيل التحويل.';
  END IF;
  IF CHAR_LENGTH(COALESCE(TRIM(p_reference_number), '')) > 120 THEN
    RAISE EXCEPTION 'رقم مرجع الدفع أطول من الحد المسموح.';
  END IF;

  v_remaining := v_total - v_collected;
  IF v_remaining > 0 AND v_order.customer_id IS NULL THEN
    RAISE EXCEPTION 'يجب ربط الطلب بعميل مسجل قبل تسجيل ذمة.';
  END IF;

  SELECT id, shift_number
  INTO v_shift_id, v_shift_number
  FROM public.cash_shifts
  WHERE branch_id = v_order.branch_id
    AND status = 'open'
  FOR SHARE;

  IF v_collected > 0 AND v_shift_id IS NULL THEN
    RAISE EXCEPTION 'افتح وردية الصندوق أولًا قبل تسجيل المبلغ المقبوض.';
  END IF;

  UPDATE public.orders
  SET
    delivery_fee_in_minor_units = v_delivery_fee,
    total_in_minor_units = v_total,
    payment_method = CASE
      WHEN v_remaining > 0 THEN 'debt'
      WHEN v_payment_method = 'cash' THEN 'cash_on_delivery'
      ELSE 'cliq'
    END,
    amount_paid_in_minor_units = 0,
    payment_reference_number = CASE
      WHEN v_payment_method = 'cliq' THEN NULLIF(TRIM(p_reference_number), '')
      ELSE NULL
    END,
    payment_confirmed_at = CASE WHEN v_collected > 0 THEN NOW() ELSE NULL END,
    payment_confirmed_by = CASE WHEN v_collected > 0 THEN v_user_id ELSE NULL END,
    cash_shift_id = v_shift_id,
    updated_at = NOW()
  WHERE id = p_order_id;

  v_result := public.complete_order(
    p_order_id,
    COALESCE(
      NULLIF(TRIM(p_notes), ''),
      CASE
        WHEN v_remaining = 0 THEN 'تم التسليم وقبض كامل المبلغ'
        WHEN v_collected = 0 THEN 'تم التسليم وكامل المبلغ على حساب العميل'
        ELSE 'تم التسليم وتسجيل دفعة جزئية والباقي ذمة'
      END
    )
  );

  IF v_remaining > 0 AND v_collected > 0 THEN
    v_payment_result := public.record_customer_order_payment(
      p_order_id,
      v_collected,
      v_payment_method,
      NULLIF(TRIM(p_reference_number), ''),
      COALESCE(NULLIF(TRIM(p_notes), ''), 'دفعة مستلمة عند تسليم الطلب')
    );
  END IF;

  INSERT INTO public.audit_logs (
    user_id, action, entity_name, entity_id, details
  ) VALUES (
    v_user_id,
    'COMPLETE_WEBSITE_ORDER_WITH_SETTLEMENT',
    'orders',
    p_order_id,
    jsonb_build_object(
      'order_number', v_order.order_number,
      'delivery_fee_in_minor_units', v_delivery_fee,
      'total_in_minor_units', v_total,
      'collected_in_minor_units', v_collected,
      'remaining_in_minor_units', v_remaining,
      'collection_method', v_payment_method,
      'customer_payment_number', v_payment_result->>'payment_number',
      'cash_shift_id', v_shift_id,
      'cash_shift_number', v_shift_number
    )
  );

  RETURN v_result || jsonb_build_object(
    'payment_method', CASE WHEN v_remaining > 0 THEN 'debt' ELSE v_payment_method END,
    'payment_status', CASE
      WHEN v_remaining = 0 THEN 'paid'
      WHEN v_collected > 0 THEN 'partially_paid'
      ELSE 'unpaid'
    END,
    'total_in_minor_units', v_total,
    'amount_paid_in_minor_units', v_collected,
    'remaining_in_minor_units', v_remaining,
    'customer_payment_number', v_payment_result->>'payment_number',
    'cash_shift_id', v_shift_id,
    'cash_shift_number', v_shift_number,
    'message', CASE
      WHEN v_remaining = 0 THEN 'تم التسليم وقبض كامل المبلغ وخصم المخزون.'
      WHEN v_collected = 0 THEN 'تم التسليم وخصم المخزون وتسجيل كامل المبلغ ذمة على العميل.'
      ELSE 'تم التسليم وتسجيل الدفعة والباقي ذمة على العميل.'
    END
  );
END;
$function$

CREATE OR REPLACE FUNCTION public._complete_website_order_with_settlement_v2_before_phase4_lock(p_order_id uuid, p_idempotency_key text, p_payment_method text, p_amount_collected_in_minor_units bigint DEFAULT NULL::bigint, p_delivery_fee_in_minor_units bigint DEFAULT NULL::bigint, p_reference_number text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_key TEXT := NULLIF(BTRIM(p_idempotency_key), '');
  v_payment_method TEXT := LOWER(NULLIF(BTRIM(p_payment_method), ''));
  v_actor_hash TEXT;
  v_request JSONB;
  v_fingerprint TEXT;
  v_replay JSONB;
  v_order public.orders%ROWTYPE;
  v_creation_operation public.business_operations%ROWTYPE;
  v_lifecycle_operation_id UUID := gen_random_uuid();
  v_delivery_fee BIGINT;
  v_total BIGINT;
  v_collected BIGINT;
  v_remaining BIGINT;
  v_shift_id UUID;
  v_shift_number TEXT;
  v_product_ids UUID[];
  v_reservation RECORD;
  v_line RECORD;
  v_instance RECORD;
  v_component RECORD;
  v_balance_before INTEGER;
  v_reserved_before INTEGER;
  v_balance_after INTEGER;
  v_line_exact_cogs NUMERIC(30,6);
  v_line_cogs BIGINT;
  v_instance_allocation JSONB;
  v_allocation_component JSONB;
  v_component_inputs JSONB;
  v_payment_result JSONB;
  v_result JSONB;
  v_now TIMESTAMPTZ := NOW();
BEGIN
  PERFORM public.assert_erp_role(
    ARRAY['owner', 'admin', 'manager', 'sales'],
    'إكمال طلب عميل V2 وتسوية الحجز'
  );
  IF v_user_id IS NULL OR v_key IS NULL OR CHAR_LENGTH(v_key) NOT BETWEEN 16 AND 200 THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_IDEMPOTENCY_INPUT_INVALID: Completion identity is invalid.';
  END IF;
  IF v_payment_method = 'cash_on_delivery' THEN v_payment_method := 'cash'; END IF;
  IF v_payment_method NOT IN ('cash', 'cliq', 'debt')
    OR COALESCE(p_amount_collected_in_minor_units, 0) < 0
    OR COALESCE(p_delivery_fee_in_minor_units, 0) < 0
    OR CHAR_LENGTH(COALESCE(BTRIM(p_reference_number), '')) > 120
  THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_CUSTOMER_SETTLEMENT_INVALID: Settlement input is invalid.';
  END IF;
  IF v_payment_method = 'cliq'
    AND COALESCE(p_amount_collected_in_minor_units, 1) > 0
    AND NULLIF(BTRIM(p_reference_number), '') IS NULL
  THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_CUSTOMER_SETTLEMENT_INVALID: CliQ reference is required.';
  END IF;

  v_actor_hash := public.phase3_actor_scope_hash_internal(
    'erp_user', v_user_id, NULL, NULL
  );
  v_request := JSONB_BUILD_OBJECT(
    'contract_version', 'phase3-customer-completion-v1',
    'actor_scope_hash', v_actor_hash,
    'order_id', LOWER(p_order_id::TEXT),
    'payment_method', v_payment_method,
    'amount_collected_in_minor_units', p_amount_collected_in_minor_units,
    'delivery_fee_in_minor_units', p_delivery_fee_in_minor_units,
    'reference_number', NULLIF(BTRIM(p_reference_number), ''),
    'notes', NULLIF(BTRIM(p_notes), '')
  );
  v_fingerprint := public.phase3_request_fingerprint_internal(v_request);
  v_replay := public.phase3_resolve_operation_replay_internal(
    'phase3_customer_completion_v1', v_key, 'erp_user', v_actor_hash, v_fingerprint
  );
  IF v_replay->>'decision' = 'REPLAY' THEN
    RETURN v_replay->'result_snapshot';
  END IF;

  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_CUSTOMER_ORDER_NOT_FOUND: Customer order is unavailable.';
  END IF;
  SELECT * INTO v_creation_operation FROM public.business_operations
  WHERE id = v_order.operation_id FOR SHARE;
  IF NOT FOUND OR v_creation_operation.operation_type IS DISTINCT FROM
      'phase3_customer_reservation_v1'
  THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_CUSTOMER_LIFECYCLE_CONTRACT_MISMATCH: Order is not Customer V2.';
  END IF;
  IF v_order.status NOT IN ('ready', 'out_for_delivery')
    OR v_order.cost_finalized_at IS NOT NULL
  THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_CUSTOMER_LIFECYCLE_INVALID: Order cannot be completed from current state.';
  END IF;

  v_delivery_fee := COALESCE(
    p_delivery_fee_in_minor_units, v_order.delivery_fee_in_minor_units, 0
  );
  v_total := v_order.subtotal_in_minor_units - v_order.discount_in_minor_units
    + v_delivery_fee;
  v_collected := CASE WHEN v_payment_method = 'debt' THEN 0
    ELSE COALESCE(p_amount_collected_in_minor_units, v_total) END;
  IF v_total < 0 OR v_collected < 0 OR v_collected > v_total THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_CUSTOMER_SETTLEMENT_INVALID: Collected amount is invalid.';
  END IF;
  IF v_collected = 0 THEN v_payment_method := 'debt'; END IF;
  v_remaining := v_total - v_collected;
  IF v_remaining > 0 AND v_order.customer_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_CUSTOMER_SETTLEMENT_INVALID: Registered customer is required for debt.';
  END IF;

  SELECT id, shift_number INTO v_shift_id, v_shift_number
  FROM public.cash_shifts
  WHERE branch_id = v_order.branch_id AND status = 'open'
  ORDER BY id LIMIT 1 FOR SHARE;
  IF v_collected > 0 AND v_shift_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_CUSTOMER_OPEN_SHIFT_REQUIRED: Open Shift is required.';
  END IF;

  SELECT ARRAY_AGG(DISTINCT reservation.product_id ORDER BY reservation.product_id)
  INTO v_product_ids
  FROM public.order_inventory_reservations reservation
  WHERE reservation.order_id = p_order_id
    AND reservation.reservation_state = 'active';
  IF COALESCE(CARDINALITY(v_product_ids), 0) = 0 THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_CUSTOMER_RESERVATION_TERMINAL: No active reservation remains.';
  END IF;
  PERFORM public.phase3_lock_inventory_products_internal(v_product_ids);
  PERFORM 1 FROM public.inventory_balances balance
  WHERE balance.warehouse_id = v_order.warehouse_id
    AND balance.product_id = ANY(v_product_ids)
  ORDER BY balance.product_id FOR UPDATE;

  IF EXISTS (
    SELECT 1 FROM public.order_inventory_reservations reservation
    WHERE reservation.order_id = p_order_id
      AND reservation.reservation_state = 'active'
      AND reservation.warehouse_id IS DISTINCT FROM v_order.warehouse_id
  ) OR EXISTS (
    SELECT 1
    FROM public.order_inventory_reservations reservation
    LEFT JOIN public.inventory_balances balance
      ON balance.warehouse_id = reservation.warehouse_id
      AND balance.product_id = reservation.product_id
    WHERE reservation.order_id = p_order_id
      AND reservation.reservation_state = 'active'
      AND (balance.product_id IS NULL
        OR balance.on_hand_quantity < reservation.reserved_quantity
        OR balance.reserved_quantity < reservation.reserved_quantity)
  ) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_CUSTOMER_RESERVATION_MISMATCH: Reservation inventory is inconsistent.';
  END IF;

  PERFORM SET_CONFIG(
    'nawasrah.customer_cost_finalization_operation_id',
    v_lifecycle_operation_id::TEXT, true
  );
  INSERT INTO public.phase3_customer_cost_finalization_guards(
    transaction_id, lifecycle_operation_id, order_id, row_kind, row_id
  ) VALUES (
    pg_current_xact_id(), v_lifecycle_operation_id, p_order_id, 'order', p_order_id
  );
  INSERT INTO public.phase3_customer_cost_finalization_guards(
    transaction_id, lifecycle_operation_id, order_id, row_kind, row_id
  ) SELECT pg_current_xact_id(), v_lifecycle_operation_id, p_order_id,
      'order_item', item.id
    FROM public.order_items item WHERE item.order_id = p_order_id;
  INSERT INTO public.phase3_customer_cost_finalization_guards(
    transaction_id, lifecycle_operation_id, order_id, row_kind, row_id
  ) SELECT pg_current_xact_id(), v_lifecycle_operation_id, p_order_id,
      'parcel_instance', instance.id
    FROM public.order_parcel_instances instance WHERE instance.order_id = p_order_id;
  INSERT INTO public.phase3_customer_cost_finalization_guards(
    transaction_id, lifecycle_operation_id, order_id, row_kind, row_id
  ) SELECT pg_current_xact_id(), v_lifecycle_operation_id, p_order_id,
      'parcel_component', component.id
    FROM public.order_parcel_components component
    JOIN public.order_parcel_instances instance
      ON instance.id = component.parcel_instance_id
    WHERE instance.order_id = p_order_id;

  FOR v_line IN
    SELECT * FROM public.order_items WHERE order_id = p_order_id ORDER BY id FOR UPDATE
  LOOP
    IF v_line.commercial_line_kind = 'configurable_parcel' THEN
      v_line_exact_cogs := 0;
      v_line_cogs := 0;
      FOR v_instance IN
        SELECT * FROM public.order_parcel_instances
        WHERE order_item_id = v_line.id ORDER BY instance_sequence, id FOR UPDATE
      LOOP
        SELECT JSONB_AGG(JSONB_BUILD_OBJECT(
          'product_id', component.product_id,
          'base_quantity', component.base_quantity,
          'unit_cost_in_minor_units_exact', product.wac_cost_in_minor_units_exact
        ) ORDER BY component.product_id)
        INTO v_component_inputs
        FROM public.order_parcel_components component
        JOIN public.products product ON product.id = component.product_id
        WHERE component.parcel_instance_id = v_instance.id;
        IF EXISTS (
          SELECT 1 FROM JSONB_ARRAY_ELEMENTS(v_component_inputs) candidate
          WHERE candidate->'unit_cost_in_minor_units_exact' = 'null'::JSONB
        ) THEN
          RAISE EXCEPTION USING ERRCODE = 'P0001',
            MESSAGE = 'PHASE3_EXACT_WAC_UNAVAILABLE: Exact WAC is required at completion.';
        END IF;
        v_instance_allocation := public.phase3_allocate_parcel_cogs_internal(
          v_component_inputs
        );
        FOR v_component IN
          SELECT * FROM public.order_parcel_components
          WHERE parcel_instance_id = v_instance.id ORDER BY product_id FOR UPDATE
        LOOP
          SELECT value INTO v_allocation_component
          FROM JSONB_ARRAY_ELEMENTS(v_instance_allocation->'components') value
          WHERE (value->>'product_id')::UUID = v_component.product_id;
          UPDATE public.order_parcel_components SET
            unit_cost_snapshot_in_minor_units =
              (v_allocation_component->>'unit_cost_in_minor_units_exact')::NUMERIC(24,6),
            cogs_snapshot_in_minor_units =
              (v_allocation_component->>'allocated_cogs_in_minor_units')::BIGINT,
            exact_cogs_snapshot_in_minor_units =
              (v_allocation_component->>'exact_cogs_in_minor_units')::NUMERIC(30,6),
            cost_finalized_at = v_now
          WHERE id = v_component.id;
        END LOOP;
        UPDATE public.order_parcel_instances SET
          cogs_snapshot_in_minor_units =
            (v_instance_allocation->>'total_cogs_in_minor_units')::BIGINT,
          exact_cogs_snapshot_in_minor_units = (
            SELECT SUM((candidate->>'exact_cogs_in_minor_units')::NUMERIC(30,6))
            FROM JSONB_ARRAY_ELEMENTS(v_instance_allocation->'components') candidate
          ),
          cost_finalized_at = v_now
        WHERE id = v_instance.id;
        v_line_cogs := v_line_cogs
          + (v_instance_allocation->>'total_cogs_in_minor_units')::BIGINT;
        v_line_exact_cogs := v_line_exact_cogs + (
          SELECT SUM((candidate->>'exact_cogs_in_minor_units')::NUMERIC(30,6))
          FROM JSONB_ARRAY_ELEMENTS(v_instance_allocation->'components') candidate
        );
      END LOOP;
      UPDATE public.order_items SET
        unit_cost_snapshot_in_minor_units_exact = ROUND(
          v_line_exact_cogs / NULLIF((
            SELECT SUM(reservation.reserved_quantity)
            FROM public.order_inventory_reservations reservation
            WHERE reservation.order_item_id = v_line.id
          ), 0), 6
        ),
        exact_cogs_snapshot_in_minor_units = v_line_exact_cogs,
        unit_cost_in_minor_units = ROUND(v_line_exact_cogs / NULLIF((
          SELECT SUM(reservation.reserved_quantity)
          FROM public.order_inventory_reservations reservation
          WHERE reservation.order_item_id = v_line.id
        ), 0))::BIGINT,
        cogs_in_minor_units = v_line_cogs,
        profit_in_minor_units = v_line.net_refundable_amount_snapshot_in_minor_units
          - v_line_cogs,
        cost_finalized_at = v_now
      WHERE id = v_line.id;
    ELSE
      SELECT SUM(reservation.reserved_quantity * product.wac_cost_in_minor_units_exact)
      INTO v_line_exact_cogs
      FROM public.order_inventory_reservations reservation
      JOIN public.products product ON product.id = reservation.product_id
      WHERE reservation.order_item_id = v_line.id
        AND reservation.reservation_state = 'active';
      IF v_line_exact_cogs IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001',
          MESSAGE = 'PHASE3_EXACT_WAC_UNAVAILABLE: Exact WAC is required at completion.';
      END IF;
      v_line_cogs := ROUND(v_line_exact_cogs, 0)::BIGINT;
      UPDATE public.order_items SET
        unit_cost_snapshot_in_minor_units_exact = ROUND(
          v_line_exact_cogs / NULLIF(quantity, 0), 6
        ),
        exact_cogs_snapshot_in_minor_units = v_line_exact_cogs,
        unit_cost_in_minor_units = ROUND(v_line_exact_cogs / NULLIF(quantity, 0))::BIGINT,
        cogs_in_minor_units = v_line_cogs,
        profit_in_minor_units = net_refundable_amount_snapshot_in_minor_units - v_line_cogs,
        cost_finalized_at = v_now
      WHERE id = v_line.id;
    END IF;
  END LOOP;

  FOR v_reservation IN
    SELECT * FROM public.order_inventory_reservations
    WHERE order_id = p_order_id AND reservation_state = 'active'
    ORDER BY product_id, id FOR UPDATE
  LOOP
    SELECT on_hand_quantity, reserved_quantity
    INTO v_balance_before, v_reserved_before
    FROM public.inventory_balances
    WHERE warehouse_id = v_reservation.warehouse_id
      AND product_id = v_reservation.product_id
    FOR UPDATE;
    v_balance_after := v_balance_before - v_reservation.reserved_quantity;
    IF v_balance_after < 0 OR v_reserved_before < v_reservation.reserved_quantity THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001',
        MESSAGE = 'PHASE3_CUSTOMER_RESERVATION_MISMATCH: Reservation cannot be consumed.';
    END IF;
    UPDATE public.inventory_balances SET
      on_hand_quantity = v_balance_after,
      reserved_quantity = v_reserved_before - v_reservation.reserved_quantity,
      updated_at = v_now
    WHERE warehouse_id = v_reservation.warehouse_id
      AND product_id = v_reservation.product_id;
    UPDATE public.order_inventory_reservations SET
      reservation_state = 'consumed', resolved_at = v_now
    WHERE id = v_reservation.id;
    INSERT INTO public.inventory_movements(
      warehouse_id, product_id, movement_type, quantity,
      balance_before, balance_after, reference_type, reference_id,
      notes, created_by, operation_id, parcel_component_id, reservation_id
    ) VALUES (
      v_reservation.warehouse_id, v_reservation.product_id,
      'sales_deduction', -v_reservation.reserved_quantity,
      v_balance_before, v_balance_after, 'customer_order', p_order_id,
      'استهلاك حجز طلب عميل V2 رقم ' || v_order.order_number,
      v_user_id, v_reservation.operation_id,
      CASE WHEN v_reservation.parcel_instance_id IS NULL THEN NULL ELSE (
        SELECT component.id FROM public.order_parcel_components component
        WHERE component.parcel_instance_id = v_reservation.parcel_instance_id
          AND component.product_id = v_reservation.product_id
      ) END,
      v_reservation.id
    );
  END LOOP;

  PERFORM SET_CONFIG(
    'nawasrah.customer_lifecycle_operation_id',
    v_lifecycle_operation_id::TEXT, true
  );
  INSERT INTO public.phase3_customer_lifecycle_transition_guards(
    transaction_id, lifecycle_operation_id, order_id, target_status
  ) VALUES (
    pg_current_xact_id(), v_lifecycle_operation_id, p_order_id, 'completed'
  );

  UPDATE public.orders SET
    status = 'completed', delivery_fee_in_minor_units = v_delivery_fee,
    total_in_minor_units = v_total,
    payment_method = CASE WHEN v_remaining > 0 THEN 'debt'
      WHEN v_payment_method = 'cash' THEN 'cash_on_delivery' ELSE 'cliq' END,
    payment_status = CASE WHEN v_remaining = 0 THEN 'paid'
      WHEN v_collected > 0 THEN 'partially_paid' ELSE 'unpaid' END,
    amount_paid_in_minor_units = 0,
    payment_reference_number = CASE WHEN v_payment_method = 'cliq'
      THEN NULLIF(BTRIM(p_reference_number), '') ELSE NULL END,
    payment_confirmed_at = CASE WHEN v_collected > 0 THEN v_now ELSE NULL END,
    payment_confirmed_by = CASE WHEN v_collected > 0 THEN v_user_id ELSE NULL END,
    cash_shift_id = v_shift_id, cost_finalized_at = v_now, updated_at = v_now
  WHERE id = p_order_id;

  IF v_remaining > 0 AND v_collected > 0 THEN
    v_payment_result := public.record_customer_order_payment(
      p_order_id, v_collected, v_payment_method,
      NULLIF(BTRIM(p_reference_number), ''),
      COALESCE(NULLIF(BTRIM(p_notes), ''), 'دفعة مستلمة عند تسليم طلب V2')
    );
  END IF;

  INSERT INTO public.order_status_history(order_id, old_status, new_status, changed_by, notes)
  VALUES (p_order_id, v_order.status, 'completed', v_user_id,
    COALESCE(NULLIF(BTRIM(p_notes), ''), 'إكمال طلب V2 واستهلاك الحجز ذريًا'));

  v_result := JSONB_BUILD_OBJECT(
    'success', true, 'idempotent_replay', false,
    'operation_id', v_lifecycle_operation_id, 'order_id', p_order_id,
    'order_number', v_order.order_number, 'status', 'completed',
    'payment_method', CASE WHEN v_remaining > 0 THEN 'debt' ELSE v_payment_method END,
    'payment_status', CASE WHEN v_remaining = 0 THEN 'paid'
      WHEN v_collected > 0 THEN 'partially_paid' ELSE 'unpaid' END,
    'total_in_minor_units', v_total,
    'amount_paid_in_minor_units', v_collected,
    'remaining_in_minor_units', v_remaining,
    'customer_payment_number', v_payment_result->>'payment_number',
    'cash_shift_id', v_shift_id, 'cash_shift_number', v_shift_number,
    'cost_finalized_at', v_now,
    'message', 'تم إكمال طلب V2 واستهلاك مكوناته وتجميد تكلفته مرة واحدة.'
  );

  DELETE FROM public.phase3_customer_cost_finalization_guards
  WHERE transaction_id = pg_current_xact_id()
    AND lifecycle_operation_id = v_lifecycle_operation_id;
  DELETE FROM public.phase3_customer_lifecycle_transition_guards
  WHERE transaction_id = pg_current_xact_id()
    AND lifecycle_operation_id = v_lifecycle_operation_id;
  INSERT INTO public.business_operations(
    id, operation_type, idempotency_key, request_fingerprint, initiated_by,
    result_snapshot, completed_at, request_identity_version,
    request_identity_snapshot, actor_scope_type, actor_scope_hash
  ) VALUES (
    v_lifecycle_operation_id, 'phase3_customer_completion_v1', v_key,
    v_fingerprint, v_user_id, v_result, v_now, 301, v_request,
    'erp_user', v_actor_hash
  );
  INSERT INTO public.audit_logs(user_id, action, entity_name, entity_id, details)
  VALUES (v_user_id, 'COMPLETE_CUSTOMER_ORDER_V2', 'orders', p_order_id,
    JSONB_BUILD_OBJECT('operation_id', v_lifecycle_operation_id,
      'creation_operation_id', v_order.operation_id,
      'consumed_reservations', (SELECT COUNT(*)
        FROM public.order_inventory_reservations WHERE order_id = p_order_id
          AND reservation_state = 'consumed')));
  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public._confirm_order_impl(p_order_id uuid, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_order_number TEXT;
  v_old_status TEXT;
  v_user_id UUID;
BEGIN
  v_user_id := auth.uid();

  -- Fetch order details with row lock
  SELECT order_number, status
  INTO v_order_number, v_old_status
  FROM public.orders
  WHERE id = p_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'الطلب المحدد غير موجود في قاعدة البيانات.';
  END IF;

  IF v_old_status = 'cancelled' THEN
    RAISE EXCEPTION 'لا يمكن تأكيد طلب ملغى.';
  END IF;

  IF v_old_status = 'completed' THEN
    RAISE EXCEPTION 'الطلب مكتمل بالفعل.';
  END IF;

  -- Update order status to confirmed
  UPDATE public.orders
  SET status = 'confirmed',
      updated_at = NOW()
  WHERE id = p_order_id;

  -- Record status transition
  INSERT INTO public.order_status_history (
    order_id,
    old_status,
    new_status,
    changed_by,
    notes
  ) VALUES (
    p_order_id,
    v_old_status,
    'confirmed',
    v_user_id,
    COALESCE(p_notes, 'تأكيد الطلب وبدء تحضيره (المخزون محجوز)')
  );

  -- Record audit log
  INSERT INTO public.audit_logs (
    user_id,
    action,
    entity_name,
    entity_id,
    details
  ) VALUES (
    v_user_id,
    'confirm_order',
    'orders',
    p_order_id,
    jsonb_build_object(
      'order_number', v_order_number,
      'old_status', v_old_status,
      'new_status', 'confirmed'
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'order_id', p_order_id,
    'order_number', v_order_number,
    'status', 'confirmed',
    'message', 'تم تأكيد الطلب بنجاح ويبقى المخزون محجوزاً.'
  );

EXCEPTION WHEN OTHERS THEN
  RAISE EXCEPTION 'فشلت عملية تأكيد الطلب: %', SQLERRM;
END;
$function$

CREATE OR REPLACE FUNCTION public._create_direct_supplier_receipt_impl(p_supplier_id uuid, p_warehouse_id uuid, p_branch_id uuid DEFAULT NULL::uuid, p_supplier_invoice_number text DEFAULT NULL::text, p_supplier_invoice_date date DEFAULT NULL::date, p_received_at timestamp with time zone DEFAULT now(), p_delivery_fee_in_minor_units bigint DEFAULT 0, p_discount_in_minor_units bigint DEFAULT 0, p_tax_in_minor_units bigint DEFAULT 0, p_amount_paid_in_minor_units bigint DEFAULT 0, p_payment_method text DEFAULT 'cash'::text, p_payment_reference text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_internal_notes text DEFAULT NULL::text, p_idempotency_key uuid DEFAULT NULL::uuid, p_items jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_receipt_id UUID;
  v_receipt_number TEXT;
  v_item JSONB;
  v_product_id UUID;
  v_purchase_unit_id UUID;
  v_base_unit_id UUID;
  v_purchase_unit_name TEXT;
  v_base_unit_name TEXT;
  v_pkg_qty INTEGER;
  v_units_per_pkg INTEGER;
  v_total_base_units INTEGER;
  v_pkg_price BIGINT;
  v_selling_price BIGINT;
  v_current_sale_price BIGINT;
  v_base_unit_cost BIGINT;
  v_item_discount BIGINT;
  v_line_total BIGINT;
  v_update_product_defaults BOOLEAN;
  v_subtotal BIGINT := 0;
  v_total BIGINT;
  v_amount_due BIGINT;
  v_payment_status TEXT;
  v_item_count INTEGER := 0;
  v_total_inventory_added INTEGER := 0;
  v_old_on_hand INTEGER;
  v_new_on_hand INTEGER;
  v_total_existing_stock INTEGER;
  v_current_cost BIGINT;
  v_new_wac_cost BIGINT;
  v_existing_receipt JSONB;
  v_batch_number TEXT;
  v_production_date DATE;
  v_expiry_date DATE;
  v_item_notes TEXT;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'يجب تسجيل الدخول لتنفيذ عملية الاستلام.';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    SELECT jsonb_build_object(
      'success', true,
      'receipt_id', sr.id,
      'receipt_number', sr.receipt_number,
      'total', sr.total_in_minor_units,
      'paid', sr.amount_paid_in_minor_units,
      'due', sr.amount_due_in_minor_units,
      'products_count', (
        SELECT COUNT(*) FROM public.supplier_receipt_items sri
        WHERE sri.supplier_receipt_id = sr.id
      ),
      'total_inventory_units_added', (
        SELECT COALESCE(SUM(sri.total_base_units), 0)
        FROM public.supplier_receipt_items sri
        WHERE sri.supplier_receipt_id = sr.id
      ),
      'is_duplicate', true
    )
    INTO v_existing_receipt
    FROM public.supplier_receipts sr
    WHERE sr.idempotency_key = p_idempotency_key;

    IF v_existing_receipt IS NOT NULL THEN
      RETURN v_existing_receipt;
    END IF;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.suppliers
    WHERE id = p_supplier_id AND is_active = true
  ) THEN
    RAISE EXCEPTION 'المورد المحدد غير موجود أو غير نشط.';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.warehouses
    WHERE id = p_warehouse_id AND is_active = true
  ) THEN
    RAISE EXCEPTION 'المستودع المحدد غير موجود أو غير نشط.';
  END IF;

  IF p_branch_id IS NOT NULL AND EXISTS (
    SELECT 1
    FROM public.warehouses
    WHERE id = p_warehouse_id
      AND branch_id IS NOT NULL
      AND branch_id <> p_branch_id
  ) THEN
    RAISE EXCEPTION 'المستودع المحدد لا يتبع الفرع المختار.';
  END IF;

  IF p_items IS NULL
    OR jsonb_typeof(p_items) <> 'array'
    OR jsonb_array_length(p_items) = 0
  THEN
    RAISE EXCEPTION 'يجب إضافة منتج واحد على الأقل للاستلام.';
  END IF;

  IF p_delivery_fee_in_minor_units < 0
    OR p_discount_in_minor_units < 0
    OR p_tax_in_minor_units < 0
    OR p_amount_paid_in_minor_units < 0
  THEN
    RAISE EXCEPTION 'قيم الخصم والضريبة والتوصيل والدفعة لا يمكن أن تكون سالبة.';
  END IF;

  IF COALESCE(p_payment_method, 'cash') NOT IN (
    'cash', 'bank', 'cliq', 'transfer', 'deferred'
  ) THEN
    RAISE EXCEPTION 'طريقة الدفع غير مدعومة.';
  END IF;

  IF p_payment_method = 'deferred' AND p_amount_paid_in_minor_units > 0 THEN
    RAISE EXCEPTION 'الاستلام الآجل لا يقبل دفعة فورية.';
  END IF;

  IF NULLIF(TRIM(p_supplier_invoice_number), '') IS NOT NULL
    AND EXISTS (
      SELECT 1
      FROM public.supplier_receipts
      WHERE supplier_id = p_supplier_id
        AND LOWER(supplier_invoice_number) =
          LOWER(TRIM(p_supplier_invoice_number))
        AND status <> 'cancelled'
    )
  THEN
    RAISE EXCEPTION 'رقم فاتورة المورد مسجل مسبقاً لهذا المورد.';
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    v_product_id := NULLIF(v_item->>'product_id', '')::UUID;
    v_pkg_qty := COALESCE((v_item->>'package_quantity')::INTEGER, 0);
    v_units_per_pkg :=
      COALESCE((v_item->>'units_per_package')::INTEGER, 0);
    v_pkg_price :=
      COALESCE((v_item->>'package_price_in_minor_units')::BIGINT, 0);
    v_item_discount :=
      COALESCE((v_item->>'discount_in_minor_units')::BIGINT, 0);
    v_selling_price :=
      COALESCE((v_item->>'selling_price_in_minor_units')::BIGINT, 0);

    IF NOT EXISTS (
      SELECT 1 FROM public.products
      WHERE id = v_product_id AND is_active = true
    ) THEN
      RAISE EXCEPTION 'أحد المنتجات غير موجود أو غير نشط.';
    END IF;
    IF v_pkg_qty <= 0 OR v_units_per_pkg <= 0 THEN
      RAISE EXCEPTION 'عدد الطرود ومحتوى الطرد يجب أن يكونا أكبر من صفر.';
    END IF;
    IF v_pkg_price < 0 OR v_item_discount < 0 OR v_selling_price < 0 THEN
      RAISE EXCEPTION 'أسعار الصنف وخصمه لا يمكن أن تكون سالبة.';
    END IF;
    IF v_item_discount > (v_pkg_qty * v_pkg_price) THEN
      RAISE EXCEPTION 'خصم الصنف يتجاوز إجمالي الصنف.';
    END IF;

    v_line_total := (v_pkg_qty * v_pkg_price) - v_item_discount;
    v_subtotal := v_subtotal + v_line_total;
    v_item_count := v_item_count + 1;
    v_total_inventory_added :=
      v_total_inventory_added + (v_pkg_qty * v_units_per_pkg);
  END LOOP;

  IF p_discount_in_minor_units > v_subtotal THEN
    RAISE EXCEPTION 'خصم السند يتجاوز مجموع الأصناف.';
  END IF;

  v_total :=
    v_subtotal
    - p_discount_in_minor_units
    + p_delivery_fee_in_minor_units
    + p_tax_in_minor_units;

  IF p_amount_paid_in_minor_units > v_total THEN
    RAISE EXCEPTION 'المبلغ المدفوع يتجاوز إجمالي السند.';
  END IF;

  v_amount_due := v_total - p_amount_paid_in_minor_units;
  v_payment_status := CASE
    WHEN v_amount_due = 0 THEN 'paid'
    WHEN p_amount_paid_in_minor_units > 0 THEN 'partially_paid'
    ELSE 'unpaid'
  END;

  v_receipt_number :=
    'GRN-' || TO_CHAR(NOW(), 'YYYY') || '-' ||
    LPAD(NEXTVAL('public.supplier_receipt_seq')::TEXT, 6, '0');

  INSERT INTO public.supplier_receipts (
    receipt_number,
    supplier_id,
    warehouse_id,
    branch_id,
    supplier_invoice_number,
    supplier_invoice_date,
    received_at,
    received_by,
    subtotal_in_minor_units,
    discount_in_minor_units,
    delivery_fee_in_minor_units,
    tax_in_minor_units,
    total_in_minor_units,
    amount_paid_in_minor_units,
    amount_due_in_minor_units,
    payment_status,
    payment_method,
    payment_reference,
    notes,
    internal_notes,
    status,
    idempotency_key
  ) VALUES (
    v_receipt_number,
    p_supplier_id,
    p_warehouse_id,
    p_branch_id,
    NULLIF(TRIM(p_supplier_invoice_number), ''),
    p_supplier_invoice_date,
    COALESCE(p_received_at, NOW()),
    v_user_id,
    v_subtotal,
    p_discount_in_minor_units,
    p_delivery_fee_in_minor_units,
    p_tax_in_minor_units,
    v_total,
    p_amount_paid_in_minor_units,
    v_amount_due,
    v_payment_status,
    COALESCE(p_payment_method, 'cash'),
    NULLIF(TRIM(p_payment_reference), ''),
    p_notes,
    p_internal_notes,
    'completed',
    p_idempotency_key
  )
  RETURNING id INTO v_receipt_id;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    v_product_id := (v_item->>'product_id')::UUID;
    v_pkg_qty := (v_item->>'package_quantity')::INTEGER;
    v_units_per_pkg := (v_item->>'units_per_package')::INTEGER;
    v_total_base_units := v_pkg_qty * v_units_per_pkg;
    v_pkg_price :=
      (v_item->>'package_price_in_minor_units')::BIGINT;
    v_item_discount :=
      COALESCE((v_item->>'discount_in_minor_units')::BIGINT, 0);
    v_line_total := (v_pkg_qty * v_pkg_price) - v_item_discount;
    v_update_product_defaults :=
      COALESCE((v_item->>'update_product_defaults')::BOOLEAN, false);

    SELECT
      p.unit_id,
      p.purchase_unit_id,
      p.cost_price_in_minor_units,
      p.sale_price_in_minor_units
    INTO
      v_base_unit_id,
      v_purchase_unit_id,
      v_current_cost,
      v_current_sale_price
    FROM public.products p
    WHERE p.id = v_product_id
    FOR UPDATE;

    v_purchase_unit_id := COALESCE(
      NULLIF(v_item->>'purchase_unit_id', '')::UUID,
      v_purchase_unit_id,
      v_base_unit_id
    );

    IF v_purchase_unit_id IS NOT NULL
      AND NOT EXISTS (
        SELECT 1 FROM public.units WHERE id = v_purchase_unit_id
      )
    THEN
      RAISE EXCEPTION 'وحدة الشراء المحددة غير موجودة.';
    END IF;

    SELECT name_ar
    INTO v_purchase_unit_name
    FROM public.units
    WHERE id = v_purchase_unit_id;

    SELECT name_ar
    INTO v_base_unit_name
    FROM public.units
    WHERE id = v_base_unit_id;

    v_purchase_unit_name := COALESCE(
      v_purchase_unit_name,
      NULLIF(v_item->>'purchase_unit_name', ''),
      'طرد'
    );
    v_base_unit_name := COALESCE(
      v_base_unit_name,
      NULLIF(v_item->>'base_unit_name', ''),
      'حبة'
    );

    IF v_item ? 'selling_price_in_minor_units' THEN
      v_selling_price :=
        COALESCE((v_item->>'selling_price_in_minor_units')::BIGINT, 0);
    ELSE
      v_selling_price := v_current_sale_price;
    END IF;

    v_base_unit_cost := ROUND(
      v_line_total::NUMERIC / v_total_base_units
    )::BIGINT;

    v_batch_number := NULLIF(TRIM(v_item->>'batch_number'), '');
    v_production_date := NULLIF(v_item->>'production_date', '')::DATE;
    v_expiry_date := NULLIF(v_item->>'expiry_date', '')::DATE;
    v_item_notes := NULLIF(v_item->>'notes', '');

    IF v_production_date IS NOT NULL
      AND v_expiry_date IS NOT NULL
      AND v_expiry_date < v_production_date
    THEN
      RAISE EXCEPTION 'تاريخ الانتهاء لا يمكن أن يسبق تاريخ الإنتاج.';
    END IF;

    INSERT INTO public.supplier_receipt_items (
      supplier_receipt_id,
      product_id,
      purchase_unit_id,
      base_unit_id,
      purchase_unit_name,
      base_unit_name,
      package_quantity,
      units_per_package,
      total_base_units,
      package_price_in_minor_units,
      base_unit_cost_in_minor_units,
      selling_price_in_minor_units,
      discount_in_minor_units,
      line_total_in_minor_units,
      batch_number,
      production_date,
      expiry_date,
      notes
    ) VALUES (
      v_receipt_id,
      v_product_id,
      v_purchase_unit_id,
      v_base_unit_id,
      v_purchase_unit_name,
      v_base_unit_name,
      v_pkg_qty,
      v_units_per_pkg,
      v_total_base_units,
      v_pkg_price,
      v_base_unit_cost,
      v_selling_price,
      v_item_discount,
      v_line_total,
      v_batch_number,
      v_production_date,
      v_expiry_date,
      v_item_notes
    );

    INSERT INTO public.inventory_balances (
      warehouse_id,
      product_id,
      on_hand_quantity,
      reserved_quantity
    ) VALUES (
      p_warehouse_id,
      v_product_id,
      0,
      0
    )
    ON CONFLICT (warehouse_id, product_id) DO NOTHING;

    SELECT on_hand_quantity
    INTO v_old_on_hand
    FROM public.inventory_balances
    WHERE warehouse_id = p_warehouse_id
      AND product_id = v_product_id
    FOR UPDATE;

    SELECT COALESCE(SUM(on_hand_quantity), 0)
    INTO v_total_existing_stock
    FROM public.inventory_balances
    WHERE product_id = v_product_id;

    v_new_wac_cost := CASE
      WHEN v_total_existing_stock <= 0 OR v_current_cost <= 0
        THEN v_base_unit_cost
      ELSE ROUND(
        (
          (v_total_existing_stock::NUMERIC * v_current_cost::NUMERIC)
          + (v_total_base_units::NUMERIC * v_base_unit_cost::NUMERIC)
        ) / (v_total_existing_stock + v_total_base_units)
      )::BIGINT
    END;

    UPDATE public.products
    SET
      cost_price_in_minor_units = v_new_wac_cost,
      purchase_unit_id = CASE
        WHEN v_update_product_defaults THEN v_purchase_unit_id
        ELSE purchase_unit_id
      END,
      units_per_purchase_unit = CASE
        WHEN v_update_product_defaults THEN v_units_per_pkg
        ELSE units_per_purchase_unit
      END,
      default_purchase_price_in_minor_units = CASE
        WHEN v_update_product_defaults THEN v_pkg_price
        ELSE default_purchase_price_in_minor_units
      END,
      sale_price_in_minor_units = CASE
        WHEN v_update_product_defaults THEN v_selling_price
        ELSE sale_price_in_minor_units
      END,
      updated_at = NOW()
    WHERE id = v_product_id;

    v_new_on_hand := v_old_on_hand + v_total_base_units;

    UPDATE public.inventory_balances
    SET
      on_hand_quantity = v_new_on_hand,
      updated_at = NOW()
    WHERE warehouse_id = p_warehouse_id
      AND product_id = v_product_id;

    INSERT INTO public.inventory_movements (
      warehouse_id,
      product_id,
      movement_type,
      quantity,
      balance_before,
      balance_after,
      reference_type,
      reference_id,
      notes,
      created_by
    ) VALUES (
      p_warehouse_id,
      v_product_id,
      'purchase_receipt',
      v_total_base_units,
      v_old_on_hand,
      v_new_on_hand,
      'supplier_receipt',
      v_receipt_id,
      'استلام مباشر من المورد - سند ' || v_receipt_number,
      v_user_id
    );
  END LOOP;

  UPDATE public.suppliers
  SET
    current_balance_in_minor_units =
      current_balance_in_minor_units + v_amount_due,
    updated_at = NOW()
  WHERE id = p_supplier_id;

  IF p_amount_paid_in_minor_units > 0 THEN
    INSERT INTO public.supplier_payments (
      supplier_id,
      supplier_receipt_id,
      amount_in_minor_units,
      payment_method,
      reference_number,
      payment_date,
      notes,
      created_by
    ) VALUES (
      p_supplier_id,
      v_receipt_id,
      p_amount_paid_in_minor_units,
      COALESCE(p_payment_method, 'cash'),
      NULLIF(TRIM(p_payment_reference), ''),
      COALESCE(p_received_at, NOW()),
      'دفعة عند الاستلام - سند ' || v_receipt_number,
      v_user_id
    );
  END IF;

  INSERT INTO public.audit_logs (
    user_id,
    action,
    entity_name,
    entity_id,
    details
  ) VALUES (
    v_user_id,
    'CREATE_DIRECT_SUPPLIER_RECEIPT',
    'supplier_receipts',
    v_receipt_id,
    jsonb_build_object(
      'receipt_number', v_receipt_number,
      'supplier_id', p_supplier_id,
      'warehouse_id', p_warehouse_id,
      'total', v_total,
      'paid', p_amount_paid_in_minor_units,
      'due', v_amount_due,
      'products_count', v_item_count,
      'total_units_added', v_total_inventory_added
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'receipt_id', v_receipt_id,
    'receipt_number', v_receipt_number,
    'total', v_total,
    'paid', p_amount_paid_in_minor_units,
    'due', v_amount_due,
    'products_count', v_item_count,
    'total_inventory_units_added', v_total_inventory_added
  );
END;
$function$

CREATE OR REPLACE FUNCTION public._create_pos_sale_package_legacy(p_warehouse_id uuid, p_branch_id uuid, p_customer_id uuid, p_customer_name text, p_payment_method text, p_items jsonb, p_discount_in_minor_units bigint DEFAULT 0, p_amount_received_in_minor_units bigint DEFAULT 0, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_item JSONB;
  v_product_id UUID;
  v_package_quantity INTEGER;
  v_units_per_package INTEGER;
  v_package_price BIGINT;
  v_package_name TEXT;
  v_base_quantity INTEGER;
  v_line_total BIGINT;
  v_exact_subtotal BIGINT := 0;
  v_exact_total BIGINT;
  v_exact_paid BIGINT;
  v_exact_change BIGINT;
  v_base_items JSONB := '[]'::jsonb;
  v_line_snapshots JSONB := '[]'::jsonb;
  v_legacy_result JSONB;
  v_order_id UUID;
  v_order public.orders%ROWTYPE;
  v_items_result JSONB;
  v_idempotent_replay BOOLEAN := false;
BEGIN
  PERFORM public.assert_erp_role(
    ARRAY['owner', 'admin', 'manager', 'sales'],
    'تنفيذ بيع الجملة المباشر'
  );

  IF p_items IS NULL
    OR jsonb_typeof(p_items) <> 'array'
    OR jsonb_array_length(p_items) = 0
  THEN
    RAISE EXCEPTION 'سلة بيع الجملة فارغة.';
  END IF;

  IF COALESCE(p_discount_in_minor_units, -1) < 0 THEN
    RAISE EXCEPTION 'خصم الفاتورة لا يمكن أن يكون سالباً.';
  END IF;

  FOR v_item IN
    SELECT item.value
    FROM jsonb_array_elements(p_items) AS item(value)
    ORDER BY item.value->>'product_id'
  LOOP
    BEGIN
      v_product_id := (v_item->>'product_id')::UUID;
      v_package_quantity := (v_item->>'quantity')::INTEGER;
    EXCEPTION
      WHEN invalid_text_representation THEN
        RAISE EXCEPTION 'بيانات أحد طرود البيع غير صحيحة.';
    END;

    IF v_product_id IS NULL
      OR v_package_quantity IS NULL
      OR v_package_quantity <= 0
    THEN
      RAISE EXCEPTION 'كل صنف يحتاج منتجاً وعدد طرود صحيحاً أكبر من صفر.';
    END IF;

    SELECT
      p.units_per_sale_unit,
      p.default_sale_price_in_minor_units,
      COALESCE(su.name_ar, 'طرد')
    INTO
      v_units_per_package,
      v_package_price,
      v_package_name
    FROM public.products p
    LEFT JOIN public.units su ON su.id = p.sale_unit_id
    WHERE p.id = v_product_id
      AND p.is_active = true;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'أحد منتجات سلة البيع غير موجود أو غير نشط.';
    END IF;

    IF COALESCE(v_units_per_package, 0) <= 0
      OR COALESCE(v_package_price, 0) <= 0
    THEN
      RAISE EXCEPTION 'طرد بيع المنتج غير مضبوط، راجع بطاقة المنتج.';
    END IF;

    v_base_quantity := v_package_quantity * v_units_per_package;
    v_line_total := v_package_quantity * v_package_price;
    v_exact_subtotal := v_exact_subtotal + v_line_total;

    v_base_items := v_base_items || jsonb_build_array(
      jsonb_build_object(
        'product_id', v_product_id,
        'quantity', v_base_quantity
      )
    );
    v_line_snapshots := v_line_snapshots || jsonb_build_array(
      jsonb_build_object(
        'product_id', v_product_id,
        'package_quantity', v_package_quantity,
        'units_per_package', v_units_per_package,
        'package_name', v_package_name,
        'package_price', v_package_price,
        'line_total', v_line_total
      )
    );
  END LOOP;

  IF p_discount_in_minor_units > v_exact_subtotal THEN
    RAISE EXCEPTION 'خصم الفاتورة لا يمكن أن يتجاوز مجموع طرود البيع.';
  END IF;

  v_exact_total :=
    v_exact_subtotal - COALESCE(p_discount_in_minor_units, 0);

  IF p_payment_method = 'cash'
    AND COALESCE(p_amount_received_in_minor_units, 0) > 0
    AND p_amount_received_in_minor_units < v_exact_total
  THEN
    RAISE EXCEPTION 'المبلغ النقدي المستلم أقل من إجمالي الفاتورة.';
  END IF;

  v_legacy_result := public.create_pos_sale_base_units_legacy(
    p_warehouse_id,
    p_branch_id,
    p_customer_id,
    p_customer_name,
    p_payment_method,
    v_base_items,
    0,
    CASE
      WHEN p_payment_method = 'cash'
        THEN GREATEST(
          COALESCE(p_amount_received_in_minor_units, 0),
          v_exact_total + 1000000
        )
      ELSE COALESCE(p_amount_received_in_minor_units, 0)
    END,
    p_idempotency_key
  );

  IF NOT COALESCE((v_legacy_result->>'success')::BOOLEAN, false) THEN
    RETURN v_legacy_result;
  END IF;

  v_order_id := (v_legacy_result->>'orderId')::UUID;
  v_idempotent_replay := COALESCE(
    (v_legacy_result->>'idempotentReplay')::BOOLEAN,
    false
  );

  FOR v_item IN SELECT * FROM jsonb_array_elements(v_line_snapshots)
  LOOP
    UPDATE public.order_items
    SET
      sale_package_quantity =
        (v_item->>'package_quantity')::INTEGER,
      units_per_sale_package =
        (v_item->>'units_per_package')::INTEGER,
      sale_package_name_snapshot = v_item->>'package_name',
      sale_package_price_in_minor_units =
        (v_item->>'package_price')::BIGINT,
      line_total_in_minor_units =
        (v_item->>'line_total')::BIGINT,
      cogs_in_minor_units =
        quantity * unit_cost_in_minor_units,
      profit_in_minor_units =
        (v_item->>'line_total')::BIGINT
        - (quantity * unit_cost_in_minor_units)
    WHERE order_id = v_order_id
      AND product_id = (v_item->>'product_id')::UUID;
  END LOOP;

  v_exact_paid := CASE
    WHEN p_payment_method = 'debt' THEN 0
    ELSE v_exact_total
  END;
  v_exact_change := CASE
    WHEN p_payment_method = 'cash' THEN
      GREATEST(
        COALESCE(p_amount_received_in_minor_units, v_exact_total)
        - v_exact_total,
        0
      )
    ELSE 0
  END;

  UPDATE public.orders
  SET
    subtotal_in_minor_units = v_exact_subtotal,
    discount_in_minor_units =
      COALESCE(p_discount_in_minor_units, 0),
    total_in_minor_units = v_exact_total,
    amount_paid_in_minor_units = v_exact_paid,
    change_due_in_minor_units = v_exact_change,
    updated_at = NOW()
  WHERE id = v_order_id
  RETURNING * INTO v_order;

  INSERT INTO public.audit_logs (
    user_id,
    action,
    entity_name,
    entity_id,
    details
  ) VALUES (
    auth.uid(),
    CASE
      WHEN v_idempotent_replay
        THEN 'REPLAY_WHOLESALE_POS_SALE'
      ELSE 'APPLY_WHOLESALE_POS_ACCOUNTING'
    END,
    'orders',
    v_order_id,
    jsonb_build_object(
      'subtotal_in_minor_units', v_exact_subtotal,
      'discount_in_minor_units',
        COALESCE(p_discount_in_minor_units, 0),
      'total_in_minor_units', v_exact_total,
      'package_lines', v_line_snapshots
    )
  );

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', oi.id,
    'productId', oi.product_id,
    'productName', oi.product_name_snapshot,
    'sku', oi.sku_snapshot,
    'quantity', COALESCE(oi.sale_package_quantity, oi.quantity),
    'baseQuantity', oi.quantity,
    'unitsPerSalePackage',
      COALESCE(oi.units_per_sale_package, 1),
    'salePackage',
      COALESCE(oi.sale_package_name_snapshot, 'طرد'),
    'unitPriceInMinorUnits',
      COALESCE(
        oi.sale_package_price_in_minor_units,
        oi.unit_price_in_minor_units
      ),
    'lineTotalInMinorUnits', oi.line_total_in_minor_units,
    'cogsInMinorUnits', oi.cogs_in_minor_units,
    'profitInMinorUnits', oi.profit_in_minor_units
  ) ORDER BY oi.created_at), '[]'::jsonb)
  INTO v_items_result
  FROM public.order_items oi
  WHERE oi.order_id = v_order_id;

  RETURN jsonb_build_object(
    'success', true,
    'idempotentReplay', v_idempotent_replay,
    'orderId', v_order.id,
    'orderNumber', v_order.order_number,
    'customerName',
      COALESCE(v_order.customer_name_snapshot, 'زبون نقدي'),
    'warehouseId', v_order.warehouse_id,
    'branchId', v_order.branch_id,
    'subtotalInMinorUnits', v_order.subtotal_in_minor_units,
    'discountInMinorUnits', v_order.discount_in_minor_units,
    'totalInMinorUnits', v_order.total_in_minor_units,
    'amountPaidInMinorUnits', v_order.amount_paid_in_minor_units,
    'changeDueInMinorUnits', v_order.change_due_in_minor_units,
    'paymentMethod', v_order.payment_method,
    'paymentStatus', v_order.payment_status,
    'items', v_items_result,
    'message', 'تم بيع طرود الجملة وخصم حباتها من المخزون بدقة.'
  );
END;
$function$

CREATE OR REPLACE FUNCTION public._create_pos_sale_v2_before_registered_customer_lock(p_warehouse_id uuid, p_branch_id uuid, p_customer_id uuid, p_customer_name text, p_payment_method text, p_lines jsonb, p_discount_in_minor_units bigint DEFAULT 0, p_amount_received_in_minor_units bigint DEFAULT 0, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_key TEXT := NULLIF(BTRIM(p_idempotency_key), '');
  v_payment_method TEXT := LOWER(COALESCE(NULLIF(BTRIM(p_payment_method), ''), 'cash'));
  v_customer_name TEXT := COALESCE(NULLIF(BTRIM(p_customer_name), ''), 'زبون نقدي');
  v_customer_identity_hash TEXT;
  v_actor_hash TEXT;
  v_request JSONB;
  v_canonical_request JSONB;
  v_fingerprint TEXT;
  v_replay JSONB;
  v_line JSONB;
  v_instance JSONB;
  v_validated JSONB;
  v_cogs_allocation JSONB;
  v_plan_lines JSONB := '[]'::JSONB;
  v_final_lines JSONB := '[]'::JSONB;
  v_plan_instances JSONB;
  v_final_instances JSONB;
  v_plan_components JSONB;
  v_line_weighted_keys JSONB;
  v_instance_weighted_keys JSONB;
  v_product_ids UUID[];
  v_configuration_ids UUID[];
  v_family_ids UUID[];
  v_line_sequence INTEGER := 0;
  v_line_kind TEXT;
  v_product public.products%ROWTYPE;
  v_order_id UUID := gen_random_uuid();
  v_operation_id UUID := gen_random_uuid();
  v_order_item_id UUID;
  v_parcel_instance_id UUID;
  v_order_number TEXT;
  v_shift_id UUID;
  v_base_unit_name TEXT;
  v_parcel_unit_name TEXT;
  v_commercial_quantity INTEGER;
  v_base_quantity BIGINT;
  v_units_per_parcel INTEGER;
  v_unit_price BIGINT;
  v_line_gross BIGINT;
  v_line_cogs BIGINT;
  v_line_discount BIGINT;
  v_line_net BIGINT;
  v_line_profit BIGINT;
  v_instance_discount BIGINT;
  v_subtotal BIGINT := 0;
  v_total BIGINT;
  v_paid BIGINT;
  v_change BIGINT;
  v_demand RECORD;
  v_on_hand INTEGER;
  v_reserved INTEGER;
  v_balance_after INTEGER;
  v_result_items JSONB;
  v_result JSONB;
  v_component JSONB;
  v_movement_quantity INTEGER;
  v_constraint_name TEXT;
BEGIN
  PERFORM public.assert_erp_role(
    ARRAY['owner', 'admin', 'manager', 'sales'],
    'تنفيذ بيع نقطة البيع بالإصدار المحمي'
  );

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_ACTOR_NOT_AUTHORIZED: المستخدم الحالي غير مصادق عليه.';
  END IF;
  IF v_key IS NULL OR CHAR_LENGTH(v_key) NOT BETWEEN 16 AND 200 THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_IDEMPOTENCY_INPUT_INVALID: مفتاح إعادة المحاولة غير صالح.';
  END IF;
  IF p_warehouse_id IS NULL OR p_branch_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_POS_LOCATION_REQUIRED: المستودع والفرع مطلوبان.';
  END IF;
  IF COALESCE(p_discount_in_minor_units, -1) < 0
    OR COALESCE(p_amount_received_in_minor_units, -1) < 0
  THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_POS_MONEY_INVALID: قيم الخصم أو المبلغ المستلم غير صالحة.';
  END IF;
  IF v_payment_method NOT IN (
    'cash', 'cliq', 'card', 'bank_transfer', 'debt', 'mixed'
  ) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_POS_PAYMENT_METHOD_INVALID: طريقة الدفع غير معتمدة.';
  END IF;

  -- Cross-version order is deliberate: V1 and V2 first serialize on the exact
  -- same raw-key lock.  Only then may V2 enter its versioned operation lock.
  PERFORM pg_advisory_xact_lock(hashtext(v_key));

  v_actor_hash := public.phase3_actor_scope_hash_internal(
    'erp_user', v_user_id, NULL, NULL
  );
  IF p_customer_id IS NULL THEN
    v_customer_identity_hash := ENCODE(extensions.digest(
      'phase3:walk-in-customer:v1|' || LOWER(v_customer_name),
      'sha256'::TEXT
    ), 'hex');
  END IF;

  v_request := JSONB_BUILD_OBJECT(
    'contract_version', 'phase3-sale-v1',
    'actor_scope_type', 'erp_user',
    'actor_scope_hash', v_actor_hash,
    'operation_source', 'admin_pos',
    'warehouse_id', p_warehouse_id,
    'branch_id', p_branch_id,
    'customer_id', p_customer_id,
    'customer_identity_hash', v_customer_identity_hash,
    'payment_method', v_payment_method,
    'order_discount_in_minor_units', COALESCE(p_discount_in_minor_units, 0),
    'amount_received_in_minor_units', COALESCE(p_amount_received_in_minor_units, 0),
    'lines', p_lines
  );
  v_canonical_request := public.phase3_canonicalize_sale_request_internal(v_request);
  v_fingerprint := public.phase3_request_fingerprint_internal(v_canonical_request);
  v_replay := public.phase3_resolve_operation_replay_internal(
    'phase3_pos_sale_v1', v_key, 'erp_user', v_actor_hash, v_fingerprint
  );
  IF v_replay->>'decision' = 'REPLAY' THEN
    RETURN v_replay->'result_snapshot';
  END IF;

  -- A key already consumed by V1 can never be reconstructed as a proven V2
  -- request.  Reject generically without exposing the historical order.
  IF EXISTS (
    SELECT 1 FROM public.orders existing_order
    WHERE existing_order.idempotency_key = v_key
  ) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_IDEMPOTENCY_CONFLICT: Operation identity is unavailable.';
  END IF;

  PERFORM 1
  FROM public.warehouses warehouse
  WHERE warehouse.id = p_warehouse_id
    AND warehouse.branch_id = p_branch_id
    AND warehouse.is_active;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_POS_LOCATION_INVALID: المستودع لا يتبع الفرع المحدد أو غير نشط.';
  END IF;

  IF p_customer_id IS NOT NULL THEN
    SELECT customer.full_name INTO v_customer_name
    FROM public.customers customer
    WHERE customer.id = p_customer_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001',
        MESSAGE = 'PHASE3_POS_CUSTOMER_INVALID: العميل المحدد غير موجود.';
    END IF;
  ELSIF v_payment_method = 'debt' THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_POS_DEBT_CUSTOMER_REQUIRED: البيع الآجل يحتاج عميلاً مسجلاً.';
  END IF;

  -- Shift precedes configuration/product/inventory locks throughout the paid
  -- operational paths and their reversal orchestrator.
  SELECT shift.id INTO v_shift_id
  FROM public.cash_shifts shift
  WHERE shift.branch_id = p_branch_id AND shift.status = 'open'
  ORDER BY shift.id
  LIMIT 1
  FOR SHARE;
  IF v_shift_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_POS_OPEN_SHIFT_REQUIRED: افتح وردية الصندوق قبل إتمام البيع.';
  END IF;

  IF EXISTS (
    SELECT 1 FROM JSONB_ARRAY_ELEMENTS(v_canonical_request->'lines') candidate
    WHERE candidate->>'commercial_line_kind' = 'configurable_parcel'
  ) THEN
    PERFORM public.phase3_assert_configurable_parcel_creation_allowed_internal(
      'erp_user', v_user_id
    );
  END IF;

  IF EXISTS (
    SELECT 1 FROM JSONB_ARRAY_ELEMENTS(v_canonical_request->'lines') candidate
    WHERE COALESCE((candidate->>'line_discount_in_minor_units')::BIGINT, 0) <> 0
      OR candidate->>'price_authority' <> 'server_catalog'
      OR candidate->'commercial_unit_price_override_in_minor_units' <> 'null'::JSONB
  ) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_POS_PRICE_AUTHORITY_INVALID: هذا المسار يعتمد سعر الخادم وخصم الطلب الحالي فقط.';
  END IF;

  SELECT
    ARRAY_AGG(DISTINCT (candidate->>'parcel_configuration_id')::UUID
      ORDER BY (candidate->>'parcel_configuration_id')::UUID),
    ARRAY_AGG(DISTINCT (candidate->>'family_product_id')::UUID
      ORDER BY (candidate->>'family_product_id')::UUID)
  INTO v_configuration_ids, v_family_ids
  FROM JSONB_ARRAY_ELEMENTS(v_canonical_request->'lines') candidate
  WHERE candidate->>'commercial_line_kind' = 'configurable_parcel';

  IF COALESCE(CARDINALITY(v_configuration_ids), 0) > 0 THEN
    PERFORM configuration.id
    FROM public.product_parcel_configurations configuration
    WHERE configuration.id = ANY(v_configuration_ids)
    ORDER BY configuration.id
    FOR SHARE;

    PERFORM family.id
    FROM public.products family
    WHERE family.id = ANY(v_family_ids)
    ORDER BY family.id
    FOR SHARE;
  END IF;

  SELECT ARRAY_AGG(DISTINCT identity.product_id ORDER BY identity.product_id)
  INTO v_product_ids
  FROM (
    SELECT (candidate->>'product_id')::UUID AS product_id
    FROM JSONB_ARRAY_ELEMENTS(v_canonical_request->'lines') candidate
    WHERE candidate->>'commercial_line_kind' IN ('base_unit', 'legacy_single_sku_parcel')
    UNION ALL
    SELECT (component->>'product_id')::UUID
    FROM JSONB_ARRAY_ELEMENTS(v_canonical_request->'lines') candidate
    CROSS JOIN LATERAL JSONB_ARRAY_ELEMENTS(candidate->'parcel_instances') parcel
    CROSS JOIN LATERAL JSONB_ARRAY_ELEMENTS(parcel->'components') component
    WHERE candidate->>'commercial_line_kind' = 'configurable_parcel'
  ) identity;

  -- Family is commercial identity, never stock identity. Keep its shared
  -- snapshot lock ahead of the global stock-product hierarchy, but never pass
  -- it to the inventory helper (which would attempt a row-lock upgrade).
  PERFORM public.phase3_lock_inventory_products_internal(v_product_ids);

  -- Build a complete immutable plan before any business row is inserted.
  FOR v_line IN
    SELECT value FROM JSONB_ARRAY_ELEMENTS(v_canonical_request->'lines')
    ORDER BY value::TEXT
  LOOP
    v_line_sequence := v_line_sequence + 1;
    v_order_item_id := gen_random_uuid();
    v_line_kind := v_line->>'commercial_line_kind';
    v_plan_instances := '[]'::JSONB;

    IF v_line_kind = 'base_unit' THEN
      SELECT * INTO v_product FROM public.products
      WHERE id = (v_line->>'product_id')::UUID AND is_active;
      IF NOT FOUND OR v_product.is_flavor_master THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001',
          MESSAGE = 'PHASE3_POS_PRODUCT_INVALID: منتج الوحدة الأساسية غير صالح للبيع.';
      END IF;
      v_commercial_quantity := (v_line->>'base_quantity')::INTEGER;
      v_base_quantity := v_commercial_quantity;
      v_units_per_parcel := 1;
      v_unit_price := v_product.sale_price_in_minor_units;
      v_line_cogs := v_base_quantity * v_product.cost_price_in_minor_units;
      SELECT COALESCE(unit.name_ar, 'وحدة') INTO v_base_unit_name
      FROM public.units unit WHERE unit.id = v_product.unit_id;
      v_base_unit_name := COALESCE(v_base_unit_name, 'وحدة');
      v_parcel_unit_name := v_base_unit_name;
    ELSIF v_line_kind = 'legacy_single_sku_parcel' THEN
      SELECT * INTO v_product FROM public.products
      WHERE id = (v_line->>'product_id')::UUID AND is_active;
      IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001',
          MESSAGE = 'PHASE3_POS_PRODUCT_INVALID: منتج الطرد التجاري غير صالح للبيع.';
      END IF;
      IF v_product.units_per_sale_unit IS DISTINCT FROM
          (v_line->>'units_per_parcel')::INTEGER
        OR COALESCE(v_product.default_sale_price_in_minor_units, 0) <= 0
      THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001',
          MESSAGE = 'PHASE3_POS_PRICE_OR_PACKAGE_STALE: إعداد الطرد أو سعره تغير.';
      END IF;
      v_commercial_quantity := (v_line->>'parcel_quantity')::INTEGER;
      v_units_per_parcel := v_product.units_per_sale_unit;
      v_base_quantity := v_commercial_quantity::BIGINT * v_units_per_parcel::BIGINT;
      IF v_base_quantity > 2147483647 THEN
        RAISE EXCEPTION USING ERRCODE = '22003',
          MESSAGE = 'PHASE3_POS_QUANTITY_OVERFLOW: كمية الوحدات الأساسية تتجاوز الحد الآمن.';
      END IF;
      v_unit_price := v_product.default_sale_price_in_minor_units;
      v_line_cogs := v_base_quantity * v_product.cost_price_in_minor_units;
      SELECT COALESCE(base_unit.name_ar, 'وحدة'), COALESCE(parcel_unit.name_ar, 'طرد')
      INTO v_base_unit_name, v_parcel_unit_name
      FROM public.products product
      LEFT JOIN public.units base_unit ON base_unit.id = product.unit_id
      LEFT JOIN public.units parcel_unit ON parcel_unit.id = product.sale_unit_id
      WHERE product.id = v_product.id;
    ELSE
      SELECT * INTO v_product FROM public.products
      WHERE id = (v_line->>'family_product_id')::UUID AND is_active;
      IF NOT FOUND OR NOT v_product.is_flavor_master
        OR COALESCE(v_product.default_sale_price_in_minor_units, 0) <= 0
      THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001',
          MESSAGE = 'PHASE3_POS_PRICE_OR_PACKAGE_STALE: عائلة الطرد أو سعرها غير صالح.';
      END IF;
      v_commercial_quantity := (v_line->>'parcel_quantity')::INTEGER;
      v_units_per_parcel := v_product.units_per_sale_unit;
      v_base_quantity := v_commercial_quantity::BIGINT * v_units_per_parcel::BIGINT;
      v_unit_price := v_product.default_sale_price_in_minor_units;
      v_line_cogs := 0;
      SELECT COALESCE(base_unit.name_ar, 'وحدة'), COALESCE(parcel_unit.name_ar, 'طرد')
      INTO v_base_unit_name, v_parcel_unit_name
      FROM public.products product
      LEFT JOIN public.units base_unit ON base_unit.id = product.unit_id
      LEFT JOIN public.units parcel_unit ON parcel_unit.id = product.sale_unit_id
      WHERE product.id = v_product.id;

      FOR v_instance IN
        SELECT value FROM JSONB_ARRAY_ELEMENTS(v_line->'parcel_instances')
        ORDER BY (value->>'instance_sequence')::INTEGER
      LOOP
        v_validated := public.phase3_validate_configurable_parcel_internal(
          'erp_user', v_user_id, (v_line->>'family_product_id')::UUID,
          (v_line->>'parcel_configuration_id')::UUID,
          (v_line->>'configuration_revision')::INTEGER,
          v_instance->'components'
        );
        v_cogs_allocation := public.phase3_allocate_parcel_cogs_internal(
          v_validated->'components'
        );
        v_parcel_instance_id := gen_random_uuid();
        SELECT JSONB_AGG(JSONB_BUILD_OBJECT(
          'component_id', gen_random_uuid(),
          'product_id', validated_component->>'product_id',
          'base_quantity', (validated_component->>'base_quantity')::INTEGER,
          'product_name_snapshot', validated_component->>'product_name_snapshot',
          'sku_snapshot', validated_component->>'sku_snapshot',
          'base_unit_name_snapshot', COALESCE(
            NULLIF(validated_component->>'base_unit_name_snapshot', ''),
            v_base_unit_name
          ),
          'unit_cost_in_minor_units_exact',
            (validated_component->>'unit_cost_in_minor_units_exact')::NUMERIC(24,6),
          'exact_cogs_in_minor_units',
            (allocated_component->>'exact_cogs_in_minor_units')::NUMERIC,
          'allocated_cogs_in_minor_units',
            (allocated_component->>'allocated_cogs_in_minor_units')::BIGINT
        ) ORDER BY (validated_component->>'product_id')::UUID)
        INTO v_plan_components
        FROM JSONB_ARRAY_ELEMENTS(v_validated->'components') validated_component
        JOIN JSONB_ARRAY_ELEMENTS(v_cogs_allocation->'components') allocated_component
          ON allocated_component->>'product_id' = validated_component->>'product_id';

        v_line_cogs := v_line_cogs
          + (v_cogs_allocation->>'total_cogs_in_minor_units')::BIGINT;
        v_plan_instances := v_plan_instances || JSONB_BUILD_ARRAY(JSONB_BUILD_OBJECT(
          'instance_id', v_parcel_instance_id,
          'instance_sequence', (v_instance->>'instance_sequence')::INTEGER,
          'configuration_revision', (v_line->>'configuration_revision')::INTEGER,
          'units_per_parcel', (v_validated->>'units_per_parcel')::INTEGER,
          'composition_fingerprint', v_validated->>'composition_fingerprint',
          'gross_amount_in_minor_units', v_unit_price,
          'allocated_discount_in_minor_units', 0,
          'net_refundable_amount_in_minor_units', v_unit_price,
          'cogs_in_minor_units',
            (v_cogs_allocation->>'total_cogs_in_minor_units')::BIGINT,
          'components', v_plan_components
        ));
      END LOOP;
    END IF;

    v_line_gross := v_commercial_quantity::BIGINT * v_unit_price;
    IF v_line_gross < 0 THEN
      RAISE EXCEPTION USING ERRCODE = '22003',
        MESSAGE = 'PHASE3_POS_MONEY_OVERFLOW: إجمالي السطر تجاوز الحد الآمن.';
    END IF;
    v_subtotal := v_subtotal + v_line_gross;
    v_plan_lines := v_plan_lines || JSONB_BUILD_ARRAY(JSONB_BUILD_OBJECT(
      'line_sequence', v_line_sequence,
      'order_item_id', v_order_item_id,
      'commercial_line_kind', v_line_kind,
      'product_id', v_product.id,
      'product_name_snapshot', v_product.name_ar,
      'sku_snapshot', v_product.sku,
      'family_product_id', CASE WHEN v_line_kind = 'configurable_parcel'
        THEN v_line->>'family_product_id' ELSE NULL END,
      'parcel_configuration_id', CASE WHEN v_line_kind = 'configurable_parcel'
        THEN v_line->>'parcel_configuration_id' ELSE NULL END,
      'configuration_revision', CASE WHEN v_line_kind = 'configurable_parcel'
        THEN (v_line->>'configuration_revision')::INTEGER ELSE NULL END,
      'commercial_quantity', v_commercial_quantity,
      'base_quantity', v_base_quantity,
      'units_per_parcel', v_units_per_parcel,
      'base_unit_name_snapshot', v_base_unit_name,
      'parcel_unit_name_snapshot', v_parcel_unit_name,
      'unit_price_in_minor_units', v_unit_price,
      'gross_amount_in_minor_units', v_line_gross,
      'cogs_in_minor_units', v_line_cogs,
      'unit_cost_in_minor_units', CASE WHEN v_base_quantity = 0 THEN 0
        ELSE ROUND(v_line_cogs::NUMERIC / v_base_quantity)::BIGINT END,
      'parcel_instances', v_plan_instances
    ));
  END LOOP;

  IF COALESCE(p_discount_in_minor_units, 0) > v_subtotal THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_POS_DISCOUNT_EXCEEDS_SUBTOTAL: الخصم يتجاوز مجموع البيع.';
  END IF;
  v_total := v_subtotal - COALESCE(p_discount_in_minor_units, 0);
  IF v_payment_method = 'cash'
    AND COALESCE(p_amount_received_in_minor_units, 0) > 0
    AND p_amount_received_in_minor_units < v_total
  THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_POS_TENDER_INSUFFICIENT: المبلغ النقدي المستلم أقل من الإجمالي.';
  END IF;

  SELECT JSONB_AGG(JSONB_BUILD_OBJECT(
    'key', line->>'line_sequence',
    'weight', (line->>'gross_amount_in_minor_units')::BIGINT
  ) ORDER BY (line->>'line_sequence')::INTEGER)
  INTO v_line_weighted_keys
  FROM JSONB_ARRAY_ELEMENTS(v_plan_lines) line;

  FOR v_line IN
    SELECT value FROM JSONB_ARRAY_ELEMENTS(v_plan_lines)
    ORDER BY (value->>'line_sequence')::INTEGER
  LOOP
    SELECT allocated_amount INTO v_line_discount
    FROM public.phase2_allocate_largest_remainder_internal(
      COALESCE(p_discount_in_minor_units, 0), v_line_weighted_keys
    ) allocation
    WHERE allocation.allocation_key = v_line->>'line_sequence';
    v_line_discount := COALESCE(v_line_discount, 0);
    v_line_gross := (v_line->>'gross_amount_in_minor_units')::BIGINT;
    v_line_cogs := (v_line->>'cogs_in_minor_units')::BIGINT;
    v_line_net := v_line_gross - v_line_discount;
    v_line_profit := v_line_net - v_line_cogs;
    v_final_instances := v_line->'parcel_instances';

    IF v_line->>'commercial_line_kind' = 'configurable_parcel' THEN
      SELECT JSONB_AGG(JSONB_BUILD_OBJECT(
        'key', instance->>'instance_sequence',
        'weight', (instance->>'gross_amount_in_minor_units')::BIGINT
      ) ORDER BY (instance->>'instance_sequence')::INTEGER)
      INTO v_instance_weighted_keys
      FROM JSONB_ARRAY_ELEMENTS(v_line->'parcel_instances') instance;

      v_final_instances := '[]'::JSONB;
      FOR v_instance IN
        SELECT value FROM JSONB_ARRAY_ELEMENTS(v_line->'parcel_instances')
        ORDER BY (value->>'instance_sequence')::INTEGER
      LOOP
        SELECT allocated_amount INTO v_instance_discount
        FROM public.phase2_allocate_largest_remainder_internal(
          v_line_discount, v_instance_weighted_keys
        ) allocation
        WHERE allocation.allocation_key = v_instance->>'instance_sequence';
        v_instance_discount := COALESCE(v_instance_discount, 0);
        v_final_instances := v_final_instances || JSONB_BUILD_ARRAY(
          v_instance || JSONB_BUILD_OBJECT(
            'allocated_discount_in_minor_units', v_instance_discount,
            'net_refundable_amount_in_minor_units',
              (v_instance->>'gross_amount_in_minor_units')::BIGINT
                - v_instance_discount
          )
        );
      END LOOP;
    END IF;

    v_final_lines := v_final_lines || JSONB_BUILD_ARRAY(
      v_line || JSONB_BUILD_OBJECT(
        'allocated_discount_in_minor_units', v_line_discount,
        'net_refundable_amount_in_minor_units', v_line_net,
        'profit_in_minor_units', v_line_profit,
        'parcel_instances', v_final_instances
      )
    );
  END LOOP;

  IF (SELECT COALESCE(SUM((line->>'allocated_discount_in_minor_units')::BIGINT), 0)
      FROM JSONB_ARRAY_ELEMENTS(v_final_lines) line)
      IS DISTINCT FROM COALESCE(p_discount_in_minor_units, 0)
  THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_POS_DISCOUNT_RECONCILIATION_FAILED: تعذر توزيع الخصم بدقة.';
  END IF;

  -- Authoritative stock is rechecked only after every relevant balance is
  -- locked by the shared Phase-2/3 product protocol.
  FOR v_demand IN
    WITH demand AS (
      SELECT (line->>'product_id')::UUID AS product_id,
        (line->>'base_quantity')::INTEGER AS quantity
      FROM JSONB_ARRAY_ELEMENTS(v_final_lines) line
      WHERE line->>'commercial_line_kind' <> 'configurable_parcel'
      UNION ALL
      SELECT (component->>'product_id')::UUID,
        (component->>'base_quantity')::INTEGER
      FROM JSONB_ARRAY_ELEMENTS(v_final_lines) line
      CROSS JOIN LATERAL JSONB_ARRAY_ELEMENTS(line->'parcel_instances') instance
      CROSS JOIN LATERAL JSONB_ARRAY_ELEMENTS(instance->'components') component
      WHERE line->>'commercial_line_kind' = 'configurable_parcel'
    )
    SELECT product_id, SUM(quantity)::INTEGER AS quantity
    FROM demand GROUP BY product_id ORDER BY product_id
  LOOP
    SELECT balance.on_hand_quantity, balance.reserved_quantity
    INTO v_on_hand, v_reserved
    FROM public.inventory_balances balance
    WHERE balance.warehouse_id = p_warehouse_id
      AND balance.product_id = v_demand.product_id
    FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001',
        MESSAGE = 'PARCEL_COMPONENT_NOT_STOCKED: أحد مكونات البيع لا يملك رصيدًا في المستودع.';
    END IF;
    IF v_on_hand - v_reserved < v_demand.quantity THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001',
        MESSAGE = 'PHASE3_POS_INSUFFICIENT_INVENTORY: مخزون أحد مكونات البيع غير كافٍ.';
    END IF;
  END LOOP;

  v_paid := CASE WHEN v_payment_method = 'debt' THEN 0 ELSE v_total END;
  v_change := CASE WHEN v_payment_method = 'cash' THEN GREATEST(
    COALESCE(p_amount_received_in_minor_units, v_total) - v_total, 0
  ) ELSE 0 END;
  v_order_number := 'POS-' || TO_CHAR(NOW(), 'YYYYMMDD') || '-'
    || LPAD(NEXTVAL('public.pos_sale_number_seq')::TEXT, 6, '0');

  SELECT COALESCE(JSONB_AGG(JSONB_BUILD_OBJECT(
    'id', line->>'order_item_id',
    'productId', line->>'product_id',
    'productName', line->>'product_name_snapshot',
    'sku', line->>'sku_snapshot',
    'commercialLineKind', line->>'commercial_line_kind',
    'quantity', (line->>'commercial_quantity')::INTEGER,
    'baseQuantity', (line->>'base_quantity')::BIGINT,
    'unitsPerSalePackage', (line->>'units_per_parcel')::INTEGER,
    'salePackage', line->>'parcel_unit_name_snapshot',
    'unitPriceInMinorUnits', (line->>'unit_price_in_minor_units')::BIGINT,
    'lineTotalInMinorUnits', (line->>'gross_amount_in_minor_units')::BIGINT,
    'allocatedDiscountInMinorUnits',
      (line->>'allocated_discount_in_minor_units')::BIGINT,
    'netRefundableAmountInMinorUnits',
      (line->>'net_refundable_amount_in_minor_units')::BIGINT,
    'cogsInMinorUnits', (line->>'cogs_in_minor_units')::BIGINT,
    'profitInMinorUnits', (line->>'profit_in_minor_units')::BIGINT,
    'parcelInstances', line->'parcel_instances'
  ) ORDER BY (line->>'line_sequence')::INTEGER), '[]'::JSONB)
  INTO v_result_items
  FROM JSONB_ARRAY_ELEMENTS(v_final_lines) line;

  v_result := JSONB_BUILD_OBJECT(
    'success', true,
    'idempotentReplay', false,
    'operationId', v_operation_id,
    'orderId', v_order_id,
    'orderNumber', v_order_number,
    'customerName', v_customer_name,
    'warehouseId', p_warehouse_id,
    'branchId', p_branch_id,
    'cashShiftId', v_shift_id,
    'subtotalInMinorUnits', v_subtotal,
    'discountInMinorUnits', COALESCE(p_discount_in_minor_units, 0),
    'totalInMinorUnits', v_total,
    'amountPaidInMinorUnits', v_paid,
    'changeDueInMinorUnits', v_change,
    'paymentMethod', v_payment_method,
    'paymentStatus', CASE WHEN v_payment_method = 'debt' THEN 'unpaid' ELSE 'paid' END,
    'items', v_result_items,
    'message', 'تم حفظ بيع نقطة البيع بالإصدار المحمي وخصم الوحدات الأساسية بدقة.'
  );

  INSERT INTO public.business_operations (
    id, operation_type, idempotency_key, request_fingerprint, initiated_by,
    result_snapshot, completed_at, request_identity_version,
    request_identity_snapshot, actor_scope_type, actor_scope_hash
  ) VALUES (
    v_operation_id, 'phase3_pos_sale_v1', v_key, v_fingerprint, v_user_id,
    v_result, NOW(), 301, v_canonical_request, 'erp_user', v_actor_hash
  );

  BEGIN
    INSERT INTO public.orders (
      id, order_number, customer_id, customer_name_snapshot, branch_id,
      warehouse_id, status, payment_method, payment_status,
      subtotal_in_minor_units, delivery_fee_in_minor_units,
      discount_in_minor_units, total_in_minor_units,
      amount_paid_in_minor_units, change_due_in_minor_units,
      internal_notes, source, idempotency_key, operation_id
    ) VALUES (
      v_order_id, v_order_number, p_customer_id, v_customer_name, p_branch_id,
      p_warehouse_id, 'completed', v_payment_method,
      CASE WHEN v_payment_method = 'debt' THEN 'unpaid' ELSE 'paid' END,
      v_subtotal, 0, COALESCE(p_discount_in_minor_units, 0), v_total,
      v_paid, v_change, 'بيع POS V2 محمي', 'pos', v_key, v_operation_id
    );
  EXCEPTION WHEN unique_violation THEN
    GET STACKED DIAGNOSTICS v_constraint_name = CONSTRAINT_NAME;
    IF v_constraint_name = 'idx_orders_idempotency_key' THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001',
        MESSAGE = 'PHASE3_IDEMPOTENCY_CONFLICT: Operation identity is unavailable.';
    END IF;
    RAISE;
  END;

  FOR v_line IN
    SELECT value FROM JSONB_ARRAY_ELEMENTS(v_final_lines)
    ORDER BY (value->>'line_sequence')::INTEGER
  LOOP
    INSERT INTO public.order_items (
      id, order_id, product_id, product_name_snapshot, sku_snapshot,
      quantity, unit_price_in_minor_units, line_total_in_minor_units,
      unit_cost_in_minor_units, cogs_in_minor_units, profit_in_minor_units,
      sale_package_quantity, units_per_sale_package,
      sale_package_name_snapshot, sale_package_price_in_minor_units,
      commercial_line_kind, family_product_id, parcel_configuration_id,
      parcel_configuration_revision, base_unit_name_snapshot,
      allocated_discount_snapshot_in_minor_units,
      net_refundable_amount_snapshot_in_minor_units
    ) VALUES (
      (v_line->>'order_item_id')::UUID, v_order_id,
      (v_line->>'product_id')::UUID, v_line->>'product_name_snapshot',
      v_line->>'sku_snapshot',
      CASE WHEN v_line->>'commercial_line_kind' = 'configurable_parcel'
        THEN (v_line->>'commercial_quantity')::INTEGER
        ELSE (v_line->>'base_quantity')::INTEGER END,
      (v_line->>'unit_price_in_minor_units')::BIGINT,
      (v_line->>'gross_amount_in_minor_units')::BIGINT,
      (v_line->>'unit_cost_in_minor_units')::BIGINT,
      (v_line->>'cogs_in_minor_units')::BIGINT,
      (v_line->>'profit_in_minor_units')::BIGINT,
      (v_line->>'commercial_quantity')::INTEGER,
      (v_line->>'units_per_parcel')::INTEGER,
      v_line->>'parcel_unit_name_snapshot',
      (v_line->>'unit_price_in_minor_units')::BIGINT,
      v_line->>'commercial_line_kind',
      NULLIF(v_line->>'family_product_id', '')::UUID,
      NULLIF(v_line->>'parcel_configuration_id', '')::UUID,
      NULLIF(v_line->>'configuration_revision', '')::INTEGER,
      v_line->>'base_unit_name_snapshot',
      (v_line->>'allocated_discount_in_minor_units')::BIGINT,
      (v_line->>'net_refundable_amount_in_minor_units')::BIGINT
    );

    -- The legacy insert trigger snapshots product cost.  Replace that draft
    -- value before any Parcel child exists, using the already planned COGS.
    UPDATE public.order_items
    SET unit_cost_in_minor_units = (v_line->>'unit_cost_in_minor_units')::BIGINT,
      cogs_in_minor_units = (v_line->>'cogs_in_minor_units')::BIGINT,
      profit_in_minor_units = (v_line->>'profit_in_minor_units')::BIGINT
    WHERE id = (v_line->>'order_item_id')::UUID;

    IF v_line->>'commercial_line_kind' = 'configurable_parcel' THEN
      FOR v_instance IN
        SELECT value FROM JSONB_ARRAY_ELEMENTS(v_line->'parcel_instances')
        ORDER BY (value->>'instance_sequence')::INTEGER
      LOOP
        INSERT INTO public.order_parcel_instances (
          id, order_item_id, order_id, operation_id, parcel_configuration_id,
          family_product_id, instance_sequence, configuration_revision,
          units_per_parcel_snapshot, parcel_unit_name_snapshot,
          gross_amount_snapshot_in_minor_units,
          allocated_discount_snapshot_in_minor_units,
          net_refundable_amount_snapshot_in_minor_units,
          cogs_snapshot_in_minor_units, composition_fingerprint
        ) VALUES (
          (v_instance->>'instance_id')::UUID,
          (v_line->>'order_item_id')::UUID, v_order_id, v_operation_id,
          (v_line->>'parcel_configuration_id')::UUID,
          (v_line->>'family_product_id')::UUID,
          (v_instance->>'instance_sequence')::INTEGER,
          (v_instance->>'configuration_revision')::INTEGER,
          (v_instance->>'units_per_parcel')::INTEGER,
          v_line->>'parcel_unit_name_snapshot',
          (v_instance->>'gross_amount_in_minor_units')::BIGINT,
          (v_instance->>'allocated_discount_in_minor_units')::BIGINT,
          (v_instance->>'net_refundable_amount_in_minor_units')::BIGINT,
          (v_instance->>'cogs_in_minor_units')::BIGINT,
          v_instance->>'composition_fingerprint'
        );

        FOR v_component IN
          SELECT value FROM JSONB_ARRAY_ELEMENTS(v_instance->'components')
          ORDER BY (value->>'product_id')::UUID
        LOOP
          INSERT INTO public.order_parcel_components (
            id, parcel_instance_id, operation_id, product_id, base_quantity,
            product_name_snapshot, sku_snapshot, base_unit_name_snapshot,
            unit_cost_snapshot_in_minor_units, cogs_snapshot_in_minor_units
          ) VALUES (
            (v_component->>'component_id')::UUID,
            (v_instance->>'instance_id')::UUID, v_operation_id,
            (v_component->>'product_id')::UUID,
            (v_component->>'base_quantity')::INTEGER,
            v_component->>'product_name_snapshot', v_component->>'sku_snapshot',
            v_component->>'base_unit_name_snapshot',
            (v_component->>'unit_cost_in_minor_units_exact')::NUMERIC(24,6),
            (v_component->>'allocated_cogs_in_minor_units')::BIGINT
          );
        END LOOP;
        PERFORM public.finalize_order_parcel_instance_internal(
          (v_instance->>'instance_id')::UUID
        );
      END LOOP;
    END IF;
  END LOOP;

  -- Apply the planned stock effects in deterministic commercial/component
  -- order.  Every balance was already checked and locked above.
  FOR v_line IN
    SELECT value FROM JSONB_ARRAY_ELEMENTS(v_final_lines)
    ORDER BY (value->>'line_sequence')::INTEGER
  LOOP
    IF v_line->>'commercial_line_kind' <> 'configurable_parcel' THEN
      v_movement_quantity := (v_line->>'base_quantity')::INTEGER;
      SELECT on_hand_quantity INTO v_on_hand
      FROM public.inventory_balances
      WHERE warehouse_id = p_warehouse_id
        AND product_id = (v_line->>'product_id')::UUID
      FOR UPDATE;
      v_balance_after := v_on_hand - v_movement_quantity;
      UPDATE public.inventory_balances
      SET on_hand_quantity = v_balance_after, updated_at = NOW()
      WHERE warehouse_id = p_warehouse_id
        AND product_id = (v_line->>'product_id')::UUID;
      INSERT INTO public.inventory_movements (
        warehouse_id, product_id, movement_type, quantity,
        balance_before, balance_after, reference_type, reference_id,
        notes, created_by, operation_id
      ) VALUES (
        p_warehouse_id, (v_line->>'product_id')::UUID,
        'sales_deduction', -v_movement_quantity, v_on_hand, v_balance_after,
        'pos_sale', v_order_id, 'بيع POS V2 رقم ' || v_order_number,
        v_user_id, v_operation_id
      );
    ELSE
      FOR v_instance IN
        SELECT value FROM JSONB_ARRAY_ELEMENTS(v_line->'parcel_instances')
        ORDER BY (value->>'instance_sequence')::INTEGER
      LOOP
        FOR v_component IN
          SELECT value FROM JSONB_ARRAY_ELEMENTS(v_instance->'components')
          ORDER BY (value->>'product_id')::UUID
        LOOP
          v_movement_quantity := (v_component->>'base_quantity')::INTEGER;
          SELECT on_hand_quantity INTO v_on_hand
          FROM public.inventory_balances
          WHERE warehouse_id = p_warehouse_id
            AND product_id = (v_component->>'product_id')::UUID
          FOR UPDATE;
          v_balance_after := v_on_hand - v_movement_quantity;
          UPDATE public.inventory_balances
          SET on_hand_quantity = v_balance_after, updated_at = NOW()
          WHERE warehouse_id = p_warehouse_id
            AND product_id = (v_component->>'product_id')::UUID;
          INSERT INTO public.inventory_movements (
            warehouse_id, product_id, movement_type, quantity,
            balance_before, balance_after, reference_type, reference_id,
            notes, created_by, operation_id, parcel_component_id
          ) VALUES (
            p_warehouse_id, (v_component->>'product_id')::UUID,
            'sales_deduction', -v_movement_quantity, v_on_hand, v_balance_after,
            'pos_sale', v_order_id, 'مكوّن طرد POS V2 رقم ' || v_order_number,
            v_user_id, v_operation_id, (v_component->>'component_id')::UUID
          );
        END LOOP;
      END LOOP;
    END IF;
  END LOOP;

  INSERT INTO public.order_status_history (
    order_id, old_status, new_status, changed_by, notes
  ) VALUES (
    v_order_id, NULL, 'completed', v_user_id,
    'بيع POS V2 مكتمل وخصم ذري للوحدات الأساسية'
  );

  INSERT INTO public.audit_logs (
    user_id, action, entity_name, entity_id, details
  ) VALUES (
    v_user_id, 'CREATE_POS_SALE_V2', 'orders', v_order_id,
    JSONB_BUILD_OBJECT(
      'operation_id', v_operation_id,
      'order_number', v_order_number,
      'cash_shift_id', v_shift_id,
      'subtotal_in_minor_units', v_subtotal,
      'discount_in_minor_units', COALESCE(p_discount_in_minor_units, 0),
      'total_in_minor_units', v_total,
      'commercial_lines', JSONB_ARRAY_LENGTH(v_final_lines)
    )
  );

  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public._create_purchase_order_impl(p_supplier_id uuid, p_branch_id uuid DEFAULT NULL::uuid, p_warehouse_id uuid DEFAULT NULL::uuid, p_expected_delivery_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_delivery_fee_in_minor_units bigint DEFAULT 0, p_discount_in_minor_units bigint DEFAULT 0, p_supplier_invoice_number text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_internal_notes text DEFAULT NULL::text, p_items jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id UUID;
  v_po_id UUID;
  v_po_number TEXT;
  v_item JSONB;
  v_product_id UUID;
  v_ordered_qty INT;
  v_unit_price BIGINT;
  v_item_discount BIGINT;
  v_line_total BIGINT;
  v_subtotal BIGINT := 0;
  v_total BIGINT := 0;
  v_item_count INT := 0;
BEGIN
  v_user_id := auth.uid();

  -- 1. Validate Supplier
  IF p_supplier_id IS NULL OR NOT EXISTS (SELECT 1 FROM public.suppliers WHERE id = p_supplier_id AND is_active = true) THEN
    RAISE EXCEPTION 'المورد المحدد غير موجود أو غير مفعل.';
  END IF;

  -- 2. Validate Items Array
  IF p_items IS NULL OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'يجب إضافة منتج واحد على الأقل في أمر الشراء.';
  END IF;

  -- 3. Calculate Subtotal & Validate Items
  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    v_product_id := (v_item->>'product_id')::UUID;
    v_ordered_qty := COALESCE((v_item->>'ordered_quantity')::INT, 0);
    v_unit_price := COALESCE((v_item->>'purchase_price_in_minor_units')::BIGINT, 0);
    v_item_discount := COALESCE((v_item->>'discount_in_minor_units')::BIGINT, 0);

    IF v_product_id IS NULL OR NOT EXISTS (SELECT 1 FROM public.products WHERE id = v_product_id AND is_active = true) THEN
      RAISE EXCEPTION 'أحد المنتجات المحددة غير موجود أو غير مفعل.';
    END IF;

    IF v_ordered_qty <= 0 THEN
      RAISE EXCEPTION 'الكمية المطلوبة لكل منتج يجب أن تكون أكبر من صفر.';
    END IF;

    IF v_unit_price < 0 THEN
      RAISE EXCEPTION 'سعر الشراء لا يمكن أن يكون بالسالب.';
    END IF;

    v_line_total := (v_ordered_qty * v_unit_price) - v_item_discount;
    IF v_line_total < 0 THEN v_line_total := 0; END IF;

    v_subtotal := v_subtotal + v_line_total;
    v_item_count := v_item_count + 1;
  END LOOP;

  v_total := v_subtotal - COALESCE(p_discount_in_minor_units, 0) + COALESCE(p_delivery_fee_in_minor_units, 0);
  IF v_total < 0 THEN v_total := 0; END IF;

  -- 4. Generate Unique PO Number: PO-2026-XXXX
  v_po_number := 'PO-' || TO_CHAR(NOW(), 'YYYY') || '-' || LPAD(CAST(FLOOR(1000 + RANDOM() * 9000) AS TEXT), 4, '0');
  WHILE EXISTS (SELECT 1 FROM public.purchase_orders WHERE purchase_order_number = v_po_number) LOOP
    v_po_number := 'PO-' || TO_CHAR(NOW(), 'YYYY') || '-' || LPAD(CAST(FLOOR(1000 + RANDOM() * 9000) AS TEXT), 4, '0');
  END LOOP;

  -- 5. Insert Purchase Order Header
  INSERT INTO public.purchase_orders (
    purchase_order_number,
    supplier_id,
    branch_id,
    warehouse_id,
    status,
    order_date,
    expected_delivery_date,
    subtotal_in_minor_units,
    discount_in_minor_units,
    delivery_fee_in_minor_units,
    total_in_minor_units,
    amount_paid_in_minor_units,
    supplier_invoice_number,
    notes,
    internal_notes,
    created_by
  ) VALUES (
    v_po_number,
    p_supplier_id,
    p_branch_id,
    p_warehouse_id,
    'draft',
    NOW(),
    p_expected_delivery_date,
    v_subtotal,
    COALESCE(p_discount_in_minor_units, 0),
    COALESCE(p_delivery_fee_in_minor_units, 0),
    v_total,
    0,
    p_supplier_invoice_number,
    p_notes,
    p_internal_notes,
    v_user_id
  )
  RETURNING id INTO v_po_id;

  -- 6. Insert Purchase Order Items
  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    v_product_id := (v_item->>'product_id')::UUID;
    v_ordered_qty := (v_item->>'ordered_quantity')::INT;
    v_unit_price := (v_item->>'purchase_price_in_minor_units')::BIGINT;
    v_item_discount := COALESCE((v_item->>'discount_in_minor_units')::BIGINT, 0);
    v_line_total := (v_ordered_qty * v_unit_price) - v_item_discount;
    IF v_line_total < 0 THEN v_line_total := 0; END IF;

    INSERT INTO public.purchase_order_items (
      purchase_order_id,
      product_id,
      ordered_quantity,
      received_quantity,
      purchase_price_in_minor_units,
      discount_in_minor_units,
      line_total_in_minor_units
    ) VALUES (
      v_po_id,
      v_product_id,
      v_ordered_qty,
      0,
      v_unit_price,
      v_item_discount,
      v_line_total
    );
  END LOOP;

  -- 7. Audit Log
  INSERT INTO public.audit_logs (
    user_id,
    action,
    entity_name,
    entity_id,
    details
  ) VALUES (
    v_user_id,
    'إنشاء أمر شراء',
    'purchase_orders',
    v_po_id,
    jsonb_build_object(
      'purchase_order_number', v_po_number,
      'supplier_id', p_supplier_id,
      'total_in_minor_units', v_total,
      'items_count', v_item_count
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'purchase_order_id', v_po_id,
    'purchase_order_number', v_po_number,
    'total_in_minor_units', v_total,
    'message', 'تم إنشاء أمر الشراء مسودة بنجاح'
  );
END;
$function$

CREATE OR REPLACE FUNCTION public._get_cash_shift_closing_report_before_return_events(p_shift_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_report JSONB;
  v_shift public.cash_shifts%ROWTYPE;
  v_summary JSONB;
  v_reversed_receipt_count INTEGER := 0;
  v_reversed_expense_count INTEGER := 0;
  v_expense_breakdown JSONB := '[]'::JSONB;
  v_gross_sales BIGINT := 0;
  v_total_refunds BIGINT := 0;
  v_total_inflows BIGINT := 0;
  v_total_outflows BIGINT := 0;
  v_net_cliq BIGINT := 0;
BEGIN
  PERFORM public.assert_erp_role(
    ARRAY['owner', 'admin', 'manager', 'accountant'],
    'عرض تقرير إغلاق الوردية'
  );

  SELECT * INTO v_shift
  FROM public.cash_shifts
  WHERE id = p_shift_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'الوردية المحددة غير موجودة.'; END IF;

  v_report := public._get_cash_shift_closing_report_v1(p_shift_id);
  IF v_shift.status <> 'open' THEN RETURN v_report; END IF;

  v_summary := public.get_cash_shift_summary(p_shift_id);
  SELECT COUNT(*)::INTEGER INTO v_reversed_receipt_count
  FROM public.customer_payments cp
  JOIN public.orders o ON o.id = cp.order_id
  WHERE cp.cash_shift_id = p_shift_id
    AND o.payment_method = 'debt'
    AND cp.is_reversed = true;

  SELECT COUNT(*)::INTEGER INTO v_reversed_expense_count
  FROM public.operational_expenses
  WHERE shift_id = p_shift_id
    AND is_reversed = true;

  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'category', category,
      'count', item_count,
      'amountInMinorUnits', amount_in_minor_units
    ) ORDER BY amount_in_minor_units DESC, category
  ), '[]'::JSONB)
  INTO v_expense_breakdown
  FROM (
    SELECT
      category,
      COUNT(*)::INTEGER AS item_count,
      SUM(amount_in_minor_units)::BIGINT AS amount_in_minor_units
    FROM public.operational_expenses
    WHERE shift_id = p_shift_id
      AND is_reversed = false
    GROUP BY category
  ) active_expense_groups;

  v_gross_sales := COALESCE((v_report #>> '{sales,grossSalesInMinorUnits}')::BIGINT, 0);
  v_total_refunds := COALESCE((v_report #>> '{sales,refundsInMinorUnits}')::BIGINT, 0);
  v_total_inflows := v_gross_sales
    + COALESCE((v_summary->>'cashReceiptsInMinorUnits')::BIGINT, 0)
    + COALESCE((v_summary->>'cliqReceiptsInMinorUnits')::BIGINT, 0);
  v_total_outflows :=
    COALESCE((v_summary->>'cashSupplierPaymentsInMinorUnits')::BIGINT, 0)
    + COALESCE((v_summary->>'cliqSupplierPaymentsInMinorUnits')::BIGINT, 0)
    + COALESCE((v_summary->>'cashExpensesInMinorUnits')::BIGINT, 0)
    + COALESCE((v_summary->>'cliqExpensesInMinorUnits')::BIGINT, 0)
    + v_total_refunds;
  v_net_cliq :=
    COALESCE((v_summary->>'cliqSalesInMinorUnits')::BIGINT, 0)
    + COALESCE((v_summary->>'cliqReceiptsInMinorUnits')::BIGINT, 0)
    - COALESCE((v_summary->>'cliqSupplierPaymentsInMinorUnits')::BIGINT, 0)
    - COALESCE((v_summary->>'cliqExpensesInMinorUnits')::BIGINT, 0)
    - COALESCE((v_summary->>'cliqRefundsInMinorUnits')::BIGINT, 0);

  v_report := jsonb_set(v_report, '{shift}', v_summary, true);
  v_report := jsonb_set(
    v_report,
    '{collections}',
    jsonb_build_object(
      'count', GREATEST(COALESCE((v_report #>> '{collections,count}')::INTEGER, 0) - v_reversed_receipt_count, 0),
      'cashInMinorUnits', COALESCE((v_summary->>'cashReceiptsInMinorUnits')::BIGINT, 0),
      'cliqInMinorUnits', COALESCE((v_summary->>'cliqReceiptsInMinorUnits')::BIGINT, 0)
    ),
    true
  );
  v_report := jsonb_set(
    v_report,
    '{outflows}',
    jsonb_build_object(
      'supplierPaymentCount', COALESCE((v_report #>> '{outflows,supplierPaymentCount}')::INTEGER, 0),
      'cashSupplierPaymentsInMinorUnits', COALESCE((v_summary->>'cashSupplierPaymentsInMinorUnits')::BIGINT, 0),
      'cliqSupplierPaymentsInMinorUnits', COALESCE((v_summary->>'cliqSupplierPaymentsInMinorUnits')::BIGINT, 0),
      'expenseCount', GREATEST(COALESCE((v_report #>> '{outflows,expenseCount}')::INTEGER, 0) - v_reversed_expense_count, 0),
      'cashExpensesInMinorUnits', COALESCE((v_summary->>'cashExpensesInMinorUnits')::BIGINT, 0),
      'cliqExpensesInMinorUnits', COALESCE((v_summary->>'cliqExpensesInMinorUnits')::BIGINT, 0),
      'returnCount', COALESCE((v_report #>> '{outflows,returnCount}')::INTEGER, 0),
      'cashRefundsInMinorUnits', COALESCE((v_summary->>'cashRefundsInMinorUnits')::BIGINT, 0),
      'cliqRefundsInMinorUnits', COALESCE((v_summary->>'cliqRefundsInMinorUnits')::BIGINT, 0)
    ),
    true
  );
  v_report := jsonb_set(v_report, '{expenseBreakdown}', v_expense_breakdown, true);
  RETURN jsonb_set(
    v_report,
    '{reconciliation}',
    jsonb_build_object(
      'totalInflowsInMinorUnits', v_total_inflows,
      'totalOutflowsInMinorUnits', v_total_outflows,
      'netMovementInMinorUnits', v_total_inflows - v_total_outflows,
      'netCliqMovementInMinorUnits', v_net_cliq,
      'openingCashInMinorUnits', COALESCE((v_summary->>'openingCashInMinorUnits')::BIGINT, 0),
      'expectedCashInMinorUnits', COALESCE((v_summary->>'expectedCashInMinorUnits')::BIGINT, 0),
      'actualCashInMinorUnits', CASE WHEN v_summary ? 'actualCashInMinorUnits' THEN v_summary->'actualCashInMinorUnits' ELSE 'null'::JSONB END,
      'cashDiscrepancyInMinorUnits', CASE WHEN v_summary ? 'cashDiscrepancyInMinorUnits' THEN v_summary->'cashDiscrepancyInMinorUnits' ELSE 'null'::JSONB END,
      'isBalanced', NULL
    ),
    true
  );
END;
$function$

CREATE OR REPLACE FUNCTION public._get_cash_shift_summary_before_return_events(p_shift_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_summary JSONB;
  v_shift_status TEXT;
  v_reversed_cash_receipts BIGINT := 0;
  v_reversed_cliq_receipts BIGINT := 0;
  v_reversed_cash_expenses BIGINT := 0;
  v_reversed_cliq_expenses BIGINT := 0;
BEGIN
  PERFORM public.assert_erp_role(
    ARRAY['owner', 'admin', 'manager', 'accountant', 'sales'],
    'عرض ملخص الوردية'
  );

  SELECT status INTO v_shift_status
  FROM public.cash_shifts
  WHERE id = p_shift_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'الوردية المحددة غير موجودة.'; END IF;

  v_summary := public._get_cash_shift_summary_v1(p_shift_id);
  IF v_shift_status <> 'open' THEN RETURN v_summary; END IF;

  SELECT
    COALESCE(SUM(cp.amount_in_minor_units) FILTER (WHERE cp.payment_method = 'cash'), 0),
    COALESCE(SUM(cp.amount_in_minor_units) FILTER (WHERE cp.payment_method = 'cliq'), 0)
  INTO v_reversed_cash_receipts, v_reversed_cliq_receipts
  FROM public.customer_payments cp
  JOIN public.orders o ON o.id = cp.order_id
  WHERE cp.cash_shift_id = p_shift_id
    AND o.payment_method = 'debt'
    AND cp.is_reversed = true;

  SELECT
    COALESCE(SUM(amount_in_minor_units) FILTER (WHERE payment_method = 'cash'), 0),
    COALESCE(SUM(amount_in_minor_units) FILTER (WHERE payment_method = 'cliq'), 0)
  INTO v_reversed_cash_expenses, v_reversed_cliq_expenses
  FROM public.operational_expenses
  WHERE shift_id = p_shift_id
    AND is_reversed = true;

  v_summary := jsonb_set(
    v_summary,
    '{cashReceiptsInMinorUnits}',
    to_jsonb(GREATEST(COALESCE((v_summary->>'cashReceiptsInMinorUnits')::BIGINT, 0) - v_reversed_cash_receipts, 0)),
    true
  );
  v_summary := jsonb_set(
    v_summary,
    '{cliqReceiptsInMinorUnits}',
    to_jsonb(GREATEST(COALESCE((v_summary->>'cliqReceiptsInMinorUnits')::BIGINT, 0) - v_reversed_cliq_receipts, 0)),
    true
  );
  v_summary := jsonb_set(
    v_summary,
    '{cashExpensesInMinorUnits}',
    to_jsonb(GREATEST(COALESCE((v_summary->>'cashExpensesInMinorUnits')::BIGINT, 0) - v_reversed_cash_expenses, 0)),
    true
  );
  v_summary := jsonb_set(
    v_summary,
    '{cliqExpensesInMinorUnits}',
    to_jsonb(GREATEST(COALESCE((v_summary->>'cliqExpensesInMinorUnits')::BIGINT, 0) - v_reversed_cliq_expenses, 0)),
    true
  );
  RETURN jsonb_set(
    v_summary,
    '{expectedCashInMinorUnits}',
    to_jsonb(
      COALESCE((v_summary->>'expectedCashInMinorUnits')::BIGINT, 0)
      + v_reversed_cash_expenses
      - v_reversed_cash_receipts
    ),
    true
  );
END;
$function$

CREATE OR REPLACE FUNCTION public._get_cash_shift_summary_v1(p_shift_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_shift public.cash_shifts%ROWTYPE;
  v_period_end TIMESTAMPTZ;
  v_cash_sales BIGINT := 0;
  v_cliq_sales BIGINT := 0;
  v_card_sales BIGINT := 0;
  v_cash_receipts BIGINT := 0;
  v_cliq_receipts BIGINT := 0;
  v_cash_supplier_payments BIGINT := 0;
  v_cliq_supplier_payments BIGINT := 0;
  v_cash_expenses BIGINT := 0;
  v_cliq_expenses BIGINT := 0;
  v_cash_refunds BIGINT := 0;
  v_cliq_refunds BIGINT := 0;
  v_expected_cash BIGINT := 0;
  v_cashier_name TEXT;
  v_closed_by_name TEXT;
BEGIN
  SELECT * INTO v_shift
  FROM public.cash_shifts
  WHERE id = p_shift_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'الوردية المحددة غير موجودة.';
  END IF;

  SELECT full_name INTO v_cashier_name
  FROM public.profiles WHERE id = v_shift.opened_by;
  SELECT full_name INTO v_closed_by_name
  FROM public.profiles WHERE id = v_shift.closed_by;

  IF v_shift.status = 'closed' THEN
    v_cash_sales := v_shift.cash_sales_in_minor_units;
    v_cliq_sales := v_shift.cliq_sales_in_minor_units;
    v_card_sales := v_shift.card_sales_in_minor_units;
    v_cash_receipts := v_shift.cash_receipts_in_minor_units;
    v_cliq_receipts := v_shift.cliq_receipts_in_minor_units;
    v_cash_supplier_payments :=
      v_shift.cash_supplier_payments_in_minor_units;
    v_cliq_supplier_payments :=
      v_shift.cliq_supplier_payments_in_minor_units;
    v_cash_expenses := v_shift.cash_expenses_in_minor_units;
    v_cliq_expenses := v_shift.cliq_expenses_in_minor_units;
    v_cash_refunds := v_shift.cash_refunds_in_minor_units;
    v_cliq_refunds := v_shift.cliq_refunds_in_minor_units;
    v_expected_cash := v_shift.expected_cash_in_minor_units;
  ELSE
    v_period_end := NOW();

    WITH completed_orders AS (
      SELECT
        o.total_in_minor_units,
        o.payment_method,
        o.source,
        o.cash_shift_id,
        COALESCE((
          SELECT MIN(osh.created_at)
          FROM public.order_status_history osh
          WHERE osh.order_id = o.id
            AND osh.new_status = 'completed'
        ), o.updated_at) AS completed_at
      FROM public.orders o
      WHERE o.branch_id = v_shift.branch_id
        AND o.status IN ('completed', 'returned')
    ), attributed_orders AS (
      SELECT * FROM completed_orders
      WHERE cash_shift_id = v_shift.id
        OR (
          cash_shift_id IS NULL
          AND completed_at >= v_shift.opened_at
          AND completed_at <= v_period_end
        )
    )
    SELECT
      COALESCE(SUM(total_in_minor_units) FILTER (
        WHERE payment_method IN ('cash', 'cash_on_delivery')
      ), 0),
      COALESCE(SUM(total_in_minor_units) FILTER (
        WHERE payment_method = 'cliq'
      ), 0),
      COALESCE(SUM(total_in_minor_units) FILTER (
        WHERE payment_method = 'card'
      ), 0)
    INTO v_cash_sales, v_cliq_sales, v_card_sales
    FROM attributed_orders;

    SELECT
      COALESCE(SUM(cp.amount_in_minor_units) FILTER (
        WHERE cp.payment_method = 'cash'
      ), 0),
      COALESCE(SUM(cp.amount_in_minor_units) FILTER (
        WHERE cp.payment_method = 'cliq'
      ), 0)
    INTO v_cash_receipts, v_cliq_receipts
    FROM public.customer_payments cp
    JOIN public.orders o ON o.id = cp.order_id
    WHERE o.branch_id = v_shift.branch_id
      AND o.payment_method = 'debt'
      AND (
        cp.cash_shift_id = v_shift.id
        OR (
          cp.cash_shift_id IS NULL
          AND cp.created_at >= v_shift.opened_at
          AND cp.created_at <= v_period_end
        )
      );

    SELECT
      COALESCE(SUM(sp.amount_in_minor_units) FILTER (
        WHERE sp.payment_method = 'cash'
      ), 0),
      COALESCE(SUM(sp.amount_in_minor_units) FILTER (
        WHERE sp.payment_method = 'cliq'
      ), 0)
    INTO v_cash_supplier_payments, v_cliq_supplier_payments
    FROM public.supplier_payments sp
    LEFT JOIN public.purchase_orders po
      ON po.id = sp.purchase_order_id
    LEFT JOIN public.supplier_receipts sr
      ON sr.id = sp.supplier_receipt_id
    WHERE COALESCE(po.branch_id, sr.branch_id) = v_shift.branch_id
      AND COALESCE(sp.is_reversed, false) = false
      AND (
        sp.cash_shift_id = v_shift.id
        OR (
          sp.cash_shift_id IS NULL
          AND sp.payment_date >= v_shift.opened_at
          AND sp.payment_date <= v_period_end
        )
      );

    SELECT
      COALESCE(SUM(amount_in_minor_units) FILTER (
        WHERE payment_method = 'cash'
      ), 0),
      COALESCE(SUM(amount_in_minor_units) FILTER (
        WHERE payment_method = 'cliq'
      ), 0)
    INTO v_cash_expenses, v_cliq_expenses
    FROM public.operational_expenses
    WHERE shift_id = v_shift.id;

    SELECT
      COALESCE(SUM(refund_amount_in_minor_units) FILTER (
        WHERE refund_method = 'cash'
      ), 0),
      COALESCE(SUM(refund_amount_in_minor_units) FILTER (
        WHERE refund_method = 'cliq'
      ), 0)
    INTO v_cash_refunds, v_cliq_refunds
    FROM public.sales_returns
    WHERE cash_shift_id = v_shift.id;

    v_expected_cash := v_shift.opening_cash_in_minor_units
      + v_cash_sales
      + v_cash_receipts
      - v_cash_supplier_payments
      - v_cash_expenses
      - v_cash_refunds;
  END IF;

  RETURN jsonb_build_object(
    'id', v_shift.id,
    'shiftNumber', v_shift.shift_number,
    'branchId', v_shift.branch_id,
    'cashierName', COALESCE(v_cashier_name, 'مستخدم النظام'),
    'startTime', v_shift.opened_at,
    'endTime', v_shift.closed_at,
    'openingCashInMinorUnits', v_shift.opening_cash_in_minor_units,
    'cashSalesInMinorUnits', v_cash_sales,
    'cliqSalesInMinorUnits', v_cliq_sales,
    'cardSalesInMinorUnits', v_card_sales,
    'cashReceiptsInMinorUnits', v_cash_receipts,
    'cliqReceiptsInMinorUnits', v_cliq_receipts,
    'cashSupplierPaymentsInMinorUnits', v_cash_supplier_payments,
    'cliqSupplierPaymentsInMinorUnits', v_cliq_supplier_payments,
    'cashExpensesInMinorUnits', v_cash_expenses,
    'cliqExpensesInMinorUnits', v_cliq_expenses,
    'cashRefundsInMinorUnits', v_cash_refunds,
    'cliqRefundsInMinorUnits', v_cliq_refunds,
    'expectedCashInMinorUnits', v_expected_cash,
    'actualCashInMinorUnits', v_shift.actual_cash_in_minor_units,
    'cashDiscrepancyInMinorUnits',
      v_shift.cash_discrepancy_in_minor_units,
    'discrepancyReason', v_shift.discrepancy_reason,
    'status', v_shift.status,
    'managerSignOffBy', v_closed_by_name
  );
END;
$function$

CREATE OR REPLACE FUNCTION public._get_operational_business_report_before133(p_branch_id uuid, p_date_from date, p_date_to date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_report JSONB;
  v_facts JSONB;
BEGIN
  -- The inner reader authorizes the caller and validates the period first.
  v_report := public._get_operational_business_report_before_phase6(p_branch_id, p_date_from, p_date_to);
  v_facts := public.phase6_financial_facts_internal(
    p_branch_id,
    p_date_from::TIMESTAMP AT TIME ZONE 'Asia/Amman',
    (p_date_to + 1)::TIMESTAMP AT TIME ZONE 'Asia/Amman',
    'Asia/Amman',
    false
  );
  v_report := jsonb_set(v_report, '{sales}', (v_report->'sales') || (v_facts->'sales'));
  v_report := jsonb_set(v_report, '{balances}', (v_report->'balances') || (v_facts->'balances'));
  v_report := jsonb_set(v_report, '{expenses}', (v_report->'expenses') || (v_facts->'expenses'));
  RETURN v_report || jsonb_build_object('cashFlow', v_facts->'cashFlow');
END;
$function$

CREATE OR REPLACE FUNCTION public._receive_inventory_impl(p_warehouse_id uuid, p_product_id uuid, p_quantity integer, p_reference_type text DEFAULT 'purchase_order'::text, p_reference_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT 'استلام كميات جديدة للمخزن'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_current_on_hand INT := 0;
  v_new_on_hand INT := 0;
  v_user_id UUID;
  v_result JSONB;
BEGIN
  v_user_id := auth.uid();

  -- Validations
  IF p_quantity <= 0 THEN
    RAISE EXCEPTION 'يجب أن تكون الكمية المستلمة أكبر من صفر.';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.warehouses WHERE id = p_warehouse_id) THEN
    RAISE EXCEPTION 'المستودع المحدد غير موجود.';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.products WHERE id = p_product_id) THEN
    RAISE EXCEPTION 'المنتج المحدد غير موجود.';
  END IF;

  -- Serialize this RPC even before the balance row exists.
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'receive_inventory:' || p_warehouse_id::TEXT || ':' || p_product_id::TEXT, 0
  ));

  -- Lock row and fetch existing stock level if available
  SELECT on_hand_quantity INTO v_current_on_hand
  FROM public.inventory_balances
  WHERE warehouse_id = p_warehouse_id AND product_id = p_product_id
  FOR UPDATE;

  IF NOT FOUND THEN
    v_current_on_hand := 0;
    v_new_on_hand := p_quantity;

    INSERT INTO public.inventory_balances (
      warehouse_id,
      product_id,
      on_hand_quantity,
      reserved_quantity
    ) VALUES (
      p_warehouse_id,
      p_product_id,
      v_new_on_hand,
      0
    );
  ELSE
    v_new_on_hand := v_current_on_hand + p_quantity;

    UPDATE public.inventory_balances
    SET on_hand_quantity = v_new_on_hand,
        updated_at = NOW()
    WHERE warehouse_id = p_warehouse_id AND product_id = p_product_id;
  END IF;

  -- Record Movement
  INSERT INTO public.inventory_movements (
    warehouse_id,
    product_id,
    movement_type,
    quantity,
    balance_before,
    balance_after,
    reference_type,
    reference_id,
    notes,
    created_by
  ) VALUES (
    p_warehouse_id,
    p_product_id,
    'purchase_receipt',
    p_quantity,
    v_current_on_hand,
    v_new_on_hand,
    p_reference_type,
    p_reference_id,
    p_notes,
    v_user_id
  );

  -- Record Audit Log
  INSERT INTO public.audit_logs (
    user_id,
    action,
    entity_name,
    entity_id,
    details
  ) VALUES (
    v_user_id,
    'receive_inventory',
    'inventory_balances',
    p_product_id,
    jsonb_build_object(
      'warehouse_id', p_warehouse_id,
      'received_quantity', p_quantity,
      'previous_balance', v_current_on_hand,
      'new_balance', v_new_on_hand,
      'reference_type', p_reference_type
    )
  );

  v_result := jsonb_build_object(
    'success', true,
    'warehouse_id', p_warehouse_id,
    'product_id', p_product_id,
    'received_quantity', p_quantity,
    'balance_before', v_current_on_hand,
    'balance_after', v_new_on_hand,
    'message', 'تم استلام وتزويد المخزون وتسجيل الحركة بنجاح.'
  );

  RETURN v_result;

EXCEPTION WHEN OTHERS THEN
  RAISE EXCEPTION 'فشلت عملية استلام وتزويد المخزون: %', SQLERRM;
END;
$function$

CREATE OR REPLACE FUNCTION public._receive_purchase_order_impl(p_purchase_order_id uuid, p_warehouse_id uuid DEFAULT NULL::uuid, p_supplier_delivery_note text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_items jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id UUID;
  v_po public.purchase_orders%ROWTYPE;
  v_target_warehouse_id UUID;
  v_receipt_id UUID;
  v_receipt_number TEXT;
  v_item JSONB;
  v_po_item_id UUID;
  v_recv_qty INT;
  v_unit_cost BIGINT;
  v_po_item public.purchase_order_items%ROWTYPE;
  v_remaining_qty INT;
  v_current_on_hand INT := 0;
  v_total_on_hand_all_wh INT := 0;
  v_new_on_hand INT := 0;
  v_current_cost BIGINT := 0;
  v_new_weighted_cost BIGINT := 0;
  v_all_completed BOOLEAN := true;
  v_receipt_item_count INT := 0;
  v_check_item RECORD;
BEGIN
  v_user_id := auth.uid();

  -- Lock PO row
  SELECT * INTO v_po
  FROM public.purchase_orders
  WHERE id = p_purchase_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'أمر الشراء المحدد غير موجود.';
  END IF;

  IF v_po.status NOT IN ('approved', 'partially_received') THEN
    RAISE EXCEPTION 'يجب أن يكون أمر الشراء معتمداً أو مستلماً جزئياً لاستلام البضائع. الحالة الحالية: %', v_po.status;
  END IF;

  v_target_warehouse_id := COALESCE(p_warehouse_id, v_po.warehouse_id);
  IF v_target_warehouse_id IS NULL THEN
    RAISE EXCEPTION 'يرجى تحديد المستودع المستلم للبضائع.';
  END IF;

  IF p_items IS NULL OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'يجب إدخال منتج واحد على الأقل للاستلام.';
  END IF;

  -- Generate Receipt Number: GRN-2026-XXXX
  v_receipt_number := 'GRN-' || TO_CHAR(NOW(), 'YYYY') || '-' || LPAD(CAST(FLOOR(1000 + RANDOM() * 9000) AS TEXT), 4, '0');
  WHILE EXISTS (SELECT 1 FROM public.purchase_receipts WHERE receipt_number = v_receipt_number) LOOP
    v_receipt_number := 'GRN-' || TO_CHAR(NOW(), 'YYYY') || '-' || LPAD(CAST(FLOOR(1000 + RANDOM() * 9000) AS TEXT), 4, '0');
  END LOOP;

  -- Create Purchase Receipt Header
  INSERT INTO public.purchase_receipts (
    receipt_number,
    purchase_order_id,
    supplier_id,
    warehouse_id,
    received_by,
    received_at,
    supplier_delivery_note,
    notes
  ) VALUES (
    v_receipt_number,
    p_purchase_order_id,
    v_po.supplier_id,
    v_target_warehouse_id,
    v_user_id,
    NOW(),
    p_supplier_delivery_note,
    p_notes
  )
  RETURNING id INTO v_receipt_id;

  -- Loop through received items
  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    v_po_item_id := (v_item->>'purchase_order_item_id')::UUID;
    -- Preserve the previous malformed UUID rejection. Product resolution
    -- remains authoritative through the locked purchase-order item below.
    PERFORM (v_item->>'product_id')::UUID;
    v_recv_qty := COALESCE((v_item->>'received_quantity')::INT, 0);
    v_unit_cost := COALESCE((v_item->>'unit_cost_in_minor_units')::BIGINT, 0);

    IF v_recv_qty <= 0 THEN
      CONTINUE; -- skip zero quantity items
    END IF;

    -- Lock & Fetch PO Item
    SELECT * INTO v_po_item
    FROM public.purchase_order_items
    WHERE id = v_po_item_id AND purchase_order_id = p_purchase_order_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'عنصر أمر الشراء غير موجود.';
    END IF;

    v_remaining_qty := v_po_item.ordered_quantity - v_po_item.received_quantity;
    IF v_recv_qty > v_remaining_qty THEN
      RAISE EXCEPTION 'الكمية المستلمة (%s) تتجاوز الكمية المتبقية (%s) للمنتج.', v_recv_qty, v_remaining_qty;
    END IF;

    -- 1. Insert Receipt Item
    INSERT INTO public.purchase_receipt_items (
      purchase_receipt_id,
      purchase_order_item_id,
      product_id,
      received_quantity,
      unit_cost_in_minor_units
    ) VALUES (
      v_receipt_id,
      v_po_item_id,
      v_po_item.product_id,
      v_recv_qty,
      v_unit_cost
    );

    -- 2. Update PO Item received_quantity
    UPDATE public.purchase_order_items
    SET received_quantity = received_quantity + v_recv_qty,
        updated_at = NOW()
    WHERE id = v_po_item_id;

    -- 3. Update Inventory Balance
    SELECT COALESCE(on_hand_quantity, 0) INTO v_current_on_hand
    FROM public.inventory_balances
    WHERE warehouse_id = v_target_warehouse_id AND product_id = v_po_item.product_id;

    IF NOT FOUND THEN
      v_current_on_hand := 0;
      INSERT INTO public.inventory_balances (
        warehouse_id,
        product_id,
        on_hand_quantity,
        reserved_quantity
      ) VALUES (
        v_target_warehouse_id,
        v_po_item.product_id,
        v_recv_qty,
        0
      );
      v_new_on_hand := v_recv_qty;
    ELSE
      v_new_on_hand := v_current_on_hand + v_recv_qty;
      UPDATE public.inventory_balances
      SET on_hand_quantity = v_new_on_hand,
          updated_at = NOW()
      WHERE warehouse_id = v_target_warehouse_id AND product_id = v_po_item.product_id;
    END IF;

    -- 4. Record Inventory Movement
    INSERT INTO public.inventory_movements (
      warehouse_id,
      product_id,
      movement_type,
      quantity,
      balance_before,
      balance_after,
      reference_type,
      reference_id,
      notes,
      created_by
    ) VALUES (
      v_target_warehouse_id,
      v_po_item.product_id,
      'purchase_receipt',
      v_recv_qty,
      v_current_on_hand,
      v_new_on_hand,
      'purchase_receipt',
      v_receipt_id,
      'استلام مشتريات سند رقم ' || v_receipt_number || ' - طلب شراء ' || v_po.purchase_order_number,
      v_user_id
    );

    -- 5. Calculate Weighted Average Cost & Update Product Cost
    SELECT COALESCE(cost_price_in_minor_units, 0) INTO v_current_cost
    FROM public.products
    WHERE id = v_po_item.product_id;

    SELECT COALESCE(SUM(on_hand_quantity), 0) INTO v_total_on_hand_all_wh
    FROM public.inventory_balances
    WHERE product_id = v_po_item.product_id;

    -- Note: v_total_on_hand_all_wh already includes v_recv_qty
    IF (v_total_on_hand_all_wh) > 0 AND v_unit_cost > 0 THEN
      v_new_weighted_cost := (( (v_total_on_hand_all_wh - v_recv_qty) * v_current_cost ) + ( v_recv_qty * v_unit_cost )) / v_total_on_hand_all_wh;

      UPDATE public.products
      SET cost_price_in_minor_units = v_new_weighted_cost,
          updated_at = NOW()
      WHERE id = v_po_item.product_id;
    END IF;

    v_receipt_item_count := v_receipt_item_count + 1;
  END LOOP;

  -- Determine if PO is fully received
  FOR v_check_item IN SELECT ordered_quantity, received_quantity FROM public.purchase_order_items WHERE purchase_order_id = p_purchase_order_id
  LOOP
    IF v_check_item.received_quantity < v_check_item.ordered_quantity THEN
      v_all_completed := false;
      EXIT;
    END IF;
  END LOOP;

  UPDATE public.purchase_orders
  SET status = CASE WHEN v_all_completed THEN 'received' ELSE 'partially_received' END,
      received_at = CASE WHEN v_all_completed THEN NOW() ELSE received_at END,
      updated_at = NOW()
  WHERE id = p_purchase_order_id;

  -- Audit Log
  INSERT INTO public.audit_logs (
    user_id,
    action,
    entity_name,
    entity_id,
    details
  ) VALUES (
    v_user_id,
    'استلام بضائع أمر شراء',
    'purchase_receipts',
    v_receipt_id,
    jsonb_build_object(
      'receipt_number', v_receipt_number,
      'purchase_order_id', p_purchase_order_id,
      'is_fully_received', v_all_completed,
      'items_received_count', v_receipt_item_count
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'receipt_id', v_receipt_id,
    'receipt_number', v_receipt_number,
    'is_fully_received', v_all_completed,
    'new_status', CASE WHEN v_all_completed THEN 'received' ELSE 'partially_received' END,
    'message', 'تم استلام البضائع وزيادة المخزون وتحديث متوسط التكلفة بنجاح'
  );
END;
$function$

CREATE OR REPLACE FUNCTION public._record_customer_order_payment_before_phase42_financial_guard(p_order_id uuid, p_amount_in_minor_units bigint, p_payment_method text, p_reference_number text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  PERFORM public.assert_erp_role(
    ARRAY['owner', 'admin', 'manager', 'accountant', 'sales'],
    'تسجيل دفعة عميل'
  );
  PERFORM public.phase4_lock_customer_order_context_internal(
    p_order_id,
    LOWER(COALESCE(p_payment_method, '')) IN ('cash', 'cliq'),
    false
  );
  RETURN public._record_customer_order_payment_before_phase4_lock(
    p_order_id, p_amount_in_minor_units, p_payment_method,
    p_reference_number, p_notes
  );
END;
$function$

CREATE OR REPLACE FUNCTION public._record_customer_order_payment_before_phase4_lock(p_order_id uuid, p_amount_in_minor_units bigint, p_payment_method text, p_reference_number text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_order RECORD;
  v_due BIGINT;
  v_new_paid BIGINT;
  v_payment_id UUID;
  v_payment_number TEXT;
BEGIN
  PERFORM public.assert_erp_role(
    ARRAY['owner', 'admin', 'manager', 'accountant', 'sales'],
    'تسجيل دفعة عميل'
  );

  IF p_amount_in_minor_units IS NULL
    OR p_amount_in_minor_units <= 0
  THEN
    RAISE EXCEPTION 'مبلغ الدفعة يجب أن يكون أكبر من صفر.';
  END IF;
  IF p_payment_method NOT IN (
    'cash',
    'cliq',
    'card',
    'bank_transfer',
    'cheque'
  ) THEN
    RAISE EXCEPTION 'طريقة الدفع غير معتمدة.';
  END IF;

  SELECT *
  INTO v_order
  FROM public.orders
  WHERE id = p_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'الطلب غير موجود.';
  END IF;
  IF v_order.status <> 'completed' THEN
    RAISE EXCEPTION 'يمكن تسجيل الدفعة على طلب مكتمل فقط.';
  END IF;
  IF v_order.customer_id IS NULL THEN
    RAISE EXCEPTION 'الطلب غير مرتبط بعميل مسجل.';
  END IF;

  v_due := GREATEST(
    v_order.total_in_minor_units -
      v_order.amount_paid_in_minor_units,
    0
  );
  IF v_due = 0 THEN
    RAISE EXCEPTION 'الطلب مدفوع بالكامل.';
  END IF;
  IF p_amount_in_minor_units > v_due THEN
    RAISE EXCEPTION
      'مبلغ الدفعة أكبر من المتبقي على الطلب (% د.أ).',
      TO_CHAR(v_due::NUMERIC / 1000, 'FM999999990.000');
  END IF;

  v_new_paid :=
    v_order.amount_paid_in_minor_units + p_amount_in_minor_units;
  v_payment_number :=
    'CRV-' ||
    TO_CHAR(NOW(), 'YYYYMMDD') ||
    '-' ||
    LPAD(
      NEXTVAL('public.customer_payment_number_seq')::TEXT,
      6,
      '0'
    );

  UPDATE public.orders
  SET
    amount_paid_in_minor_units = v_new_paid,
    payment_status = CASE
      WHEN v_new_paid >= total_in_minor_units THEN 'paid'
      ELSE 'partially_paid'
    END,
    updated_at = NOW()
  WHERE id = p_order_id;

  INSERT INTO public.customer_payments (
    payment_number,
    customer_id,
    order_id,
    amount_in_minor_units,
    payment_method,
    reference_number,
    notes,
    created_by
  ) VALUES (
    v_payment_number,
    v_order.customer_id,
    p_order_id,
    p_amount_in_minor_units,
    p_payment_method,
    NULLIF(TRIM(p_reference_number), ''),
    NULLIF(TRIM(p_notes), ''),
    v_user_id
  )
  RETURNING id INTO v_payment_id;

  INSERT INTO public.audit_logs (
    user_id,
    action,
    entity_name,
    entity_id,
    details
  ) VALUES (
    v_user_id,
    'RECORD_CUSTOMER_PAYMENT',
    'customer_payments',
    v_payment_id,
    jsonb_build_object(
      'payment_number', v_payment_number,
      'order_id', p_order_id,
      'order_number', v_order.order_number,
      'customer_id', v_order.customer_id,
      'amount_in_minor_units', p_amount_in_minor_units,
      'remaining_in_minor_units',
        v_order.total_in_minor_units - v_new_paid
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'payment_id', v_payment_id,
    'payment_number', v_payment_number,
    'order_id', p_order_id,
    'order_number', v_order.order_number,
    'amount_in_minor_units', p_amount_in_minor_units,
    'remaining_in_minor_units',
      v_order.total_in_minor_units - v_new_paid
  );
END;
$function$

CREATE OR REPLACE FUNCTION public._record_supplier_payment_impl(p_supplier_id uuid, p_purchase_order_id uuid DEFAULT NULL::uuid, p_amount_in_minor_units bigint DEFAULT 0, p_payment_method text DEFAULT 'cash'::text, p_reference_number text DEFAULT NULL::text, p_payment_date timestamp with time zone DEFAULT now(), p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id UUID;
  v_payment_id UUID;
  v_po public.purchase_orders%ROWTYPE;
  v_due_amount NUMERIC;
BEGIN
  v_user_id := auth.uid();

  IF p_supplier_id IS NULL OR NOT EXISTS (SELECT 1 FROM public.suppliers WHERE id = p_supplier_id) THEN
    RAISE EXCEPTION 'المورد المحدد غير موجود.';
  END IF;

  IF p_amount_in_minor_units <= 0 THEN
    RAISE EXCEPTION 'مبلغ الدفعة يجب أن يكون أكبر من صفر.';
  END IF;

  -- If tied to specific PO
  IF p_purchase_order_id IS NOT NULL THEN
    SELECT * INTO v_po
    FROM public.purchase_orders
    WHERE id = p_purchase_order_id AND supplier_id = p_supplier_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'أمر الشراء غير موجود أو لا يتبع للمورد المحدد.';
    END IF;

    v_due_amount := GREATEST(v_po.total_in_minor_units::NUMERIC,
      COALESCE((SELECT SUM(r.supplier_invoice_payable_total_snapshot_in_minor_units::NUMERIC)
        FROM public.purchase_receipts r WHERE r.purchase_order_id=p_purchase_order_id
          AND r.status='completed' AND r.phase2_finalized_at IS NOT NULL),0)
      +COALESCE((SELECT payable::NUMERIC FROM public.phase133_legacy_po_payables_internal()
        WHERE purchase_order_id=p_purchase_order_id),0))
      -COALESCE((SELECT SUM(amount_in_minor_units::NUMERIC) FROM public.supplier_payments
        WHERE purchase_order_id=p_purchase_order_id AND NOT is_reversed),0);
    IF p_amount_in_minor_units > v_due_amount THEN
      RAISE EXCEPTION 'مبلغ الدفعة (%s) يتجاوز الرصيد المستحق على أمر الشراء (%s).', p_amount_in_minor_units, v_due_amount;
    END IF;

    UPDATE public.purchase_orders
    SET amount_paid_in_minor_units = amount_paid_in_minor_units + p_amount_in_minor_units,
        updated_at = NOW()
    WHERE id = p_purchase_order_id;
  END IF;

  INSERT INTO public.supplier_payments (
    supplier_id,
    purchase_order_id,
    amount_in_minor_units,
    payment_method,
    reference_number,
    payment_date,
    notes,
    created_by
  ) VALUES (
    p_supplier_id,
    p_purchase_order_id,
    p_amount_in_minor_units,
    p_payment_method,
    p_reference_number,
    COALESCE(p_payment_date, NOW()),
    p_notes,
    v_user_id
  )
  RETURNING id INTO v_payment_id;

  -- Audit Log
  INSERT INTO public.audit_logs (
    user_id,
    action,
    entity_name,
    entity_id,
    details
  ) VALUES (
    v_user_id,
    'تسجيل سند صرف مورد',
    'supplier_payments',
    v_payment_id,
    jsonb_build_object(
      'supplier_id', p_supplier_id,
      'purchase_order_id', p_purchase_order_id,
      'amount_in_minor_units', p_amount_in_minor_units,
      'payment_method', p_payment_method
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'payment_id', v_payment_id,
    'message', 'تم تسجيل دفعة المورد (سند الصرف) بنجاح'
  );
END;
$function$

CREATE OR REPLACE FUNCTION public._record_supplier_receipt_payment_impl(p_receipt_id uuid, p_amount_in_minor_units bigint, p_payment_method text DEFAULT 'cash'::text, p_reference_number text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_supplier_id UUID;
  v_receipt_number TEXT;
  v_status TEXT;
  v_total BIGINT;
  v_old_paid BIGINT;
  v_old_due BIGINT;
  v_new_paid BIGINT;
  v_new_due BIGINT;
  v_new_payment_status TEXT;
  v_payment_id UUID;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'يجب تسجيل الدخول لتسجيل دفعة مورد.';
  END IF;
  IF p_amount_in_minor_units IS NULL OR p_amount_in_minor_units <= 0 THEN
    RAISE EXCEPTION 'مبلغ الدفعة يجب أن يكون أكبر من صفر.';
  END IF;
  IF COALESCE(p_payment_method, 'cash') NOT IN (
    'cash', 'bank', 'cliq', 'transfer'
  ) THEN
    RAISE EXCEPTION 'طريقة الدفع غير مدعومة.';
  END IF;

  SELECT
    supplier_id,
    receipt_number,
    status,
    total_in_minor_units,
    amount_paid_in_minor_units,
    amount_due_in_minor_units
  INTO
    v_supplier_id,
    v_receipt_number,
    v_status,
    v_total,
    v_old_paid,
    v_old_due
  FROM public.supplier_receipts
  WHERE id = p_receipt_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'سند الاستلام غير موجود.';
  END IF;
  IF v_status <> 'completed' THEN
    RAISE EXCEPTION 'لا يمكن تسجيل دفعة على سند غير مكتمل.';
  END IF;
  IF p_amount_in_minor_units > v_old_due THEN
    RAISE EXCEPTION 'مبلغ الدفعة يتجاوز المبلغ المتبقي.';
  END IF;

  v_new_paid := v_old_paid + p_amount_in_minor_units;
  v_new_due := v_total - v_new_paid;
  v_new_payment_status := CASE
    WHEN v_new_due = 0 THEN 'paid'
    ELSE 'partially_paid'
  END;

  UPDATE public.supplier_receipts
  SET
    amount_paid_in_minor_units = v_new_paid,
    amount_due_in_minor_units = v_new_due,
    payment_status = v_new_payment_status,
    updated_at = NOW()
  WHERE id = p_receipt_id;

  UPDATE public.suppliers
  SET
    current_balance_in_minor_units =
      current_balance_in_minor_units - p_amount_in_minor_units,
    updated_at = NOW()
  WHERE id = v_supplier_id;

  INSERT INTO public.supplier_payments (
    supplier_id,
    supplier_receipt_id,
    amount_in_minor_units,
    payment_method,
    reference_number,
    payment_date,
    notes,
    created_by
  ) VALUES (
    v_supplier_id,
    p_receipt_id,
    p_amount_in_minor_units,
    COALESCE(p_payment_method, 'cash'),
    NULLIF(TRIM(p_reference_number), ''),
    NOW(),
    COALESCE(p_notes, 'دفعة على سند ' || v_receipt_number),
    v_user_id
  )
  RETURNING id INTO v_payment_id;

  INSERT INTO public.audit_logs (
    user_id,
    action,
    entity_name,
    entity_id,
    details
  ) VALUES (
    v_user_id,
    'RECORD_SUPPLIER_RECEIPT_PAYMENT',
    'supplier_receipts',
    p_receipt_id,
    jsonb_build_object(
      'payment_id', v_payment_id,
      'amount', p_amount_in_minor_units,
      'remaining_due', v_new_due
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'payment_id', v_payment_id,
    'total_paid', v_new_paid,
    'amount_due', v_new_due,
    'payment_status', v_new_payment_status
  );
END;
$function$

