$function$

CREATE OR REPLACE FUNCTION public._reverse_supplier_payment_before_phase4_lock(p_supplier_payment_id uuid, p_reason text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id UUID;
  v_payment public.supplier_payments%ROWTYPE;
  v_shift public.cash_shifts%ROWTYPE;
  v_receipt public.supplier_receipts%ROWTYPE;
  v_purchase_order public.purchase_orders%ROWTYPE;
  v_existing public.supplier_payment_reversals%ROWTYPE;
  v_reason TEXT := NULLIF(TRIM(p_reason), '');
  v_key TEXT := NULLIF(TRIM(p_idempotency_key), '');
  v_new_paid BIGINT;
  v_new_due BIGINT;
  v_effect JSONB;
BEGIN
  v_user_id := public.assert_reversal_owner('عكس دفعة مورد');
  IF p_supplier_payment_id IS NULL THEN
    RAISE EXCEPTION 'دفعة المورد المطلوب عكسها غير محددة.';
  END IF;
  IF v_reason IS NULL OR CHAR_LENGTH(v_reason) NOT BETWEEN 3 AND 500 THEN
    RAISE EXCEPTION 'سبب عكس دفعة المورد مطلوب ويجب أن يكون بين 3 و500 حرف.';
  END IF;
  IF v_key IS NULL OR CHAR_LENGTH(v_key) NOT BETWEEN 16 AND 200 THEN
    RAISE EXCEPTION 'مفتاح منع التكرار لعكس دفعة المورد غير صالح.';
  END IF;

  PERFORM set_config('lock_timeout', '3s', true);
  PERFORM set_config('statement_timeout', '30s', true);

  SELECT * INTO v_payment
  FROM public.supplier_payments
  WHERE id = p_supplier_payment_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'دفعة المورد غير موجودة.';
  END IF;
  IF v_payment.cash_shift_id IS NULL THEN
    RAISE EXCEPTION 'دفعة المورد غير مرتبطة بورديّة صريحة.';
  END IF;

  -- Match the orchestrator's canonical order: shift advisory, operation
  -- advisory, shift row, payment row, then receipt/PO and supplier rows.
  PERFORM pg_advisory_xact_lock(
    hashtextextended('cash-shift-full-reversal:' || v_payment.cash_shift_id::TEXT, 0)
  );
  PERFORM pg_advisory_xact_lock(
    hashtextextended('supplier-payment-reversal:' || p_supplier_payment_id::TEXT, 0)
  );

  SELECT * INTO v_shift
  FROM public.cash_shifts
  WHERE id = v_payment.cash_shift_id
  FOR UPDATE;
  IF NOT FOUND OR v_shift.status <> 'open' THEN
    RAISE EXCEPTION 'لا يمكن عكس دفعة مورد مرتبطة بورديّة غير مفتوحة.';
  END IF;

  SELECT * INTO v_existing
  FROM public.supplier_payment_reversals
  WHERE requested_by = v_user_id
    AND idempotency_key = v_key
  FOR UPDATE;
  IF FOUND THEN
    IF v_existing.supplier_payment_id <> p_supplier_payment_id THEN
      RAISE EXCEPTION 'مفتاح منع التكرار مستخدم لعكس دفعة مورد أخرى.';
    END IF;
    RETURN jsonb_build_object(
      'success', true,
      'idempotent', true,
      'reversal_id', v_existing.id,
      'supplier_payment_id', v_existing.supplier_payment_id,
      'cash_shift_id', v_existing.cash_shift_id,
      'actual_effect', v_existing.actual_effect
    );
  END IF;

  SELECT * INTO v_payment
  FROM public.supplier_payments
  WHERE id = p_supplier_payment_id
  FOR UPDATE;
  IF NOT FOUND OR v_payment.cash_shift_id <> v_shift.id OR v_payment.is_reversed THEN
    RAISE EXCEPTION 'دفعة المورد لم تعد قابلة للعكس.';
  END IF;
  IF (v_payment.supplier_receipt_id IS NULL AND v_payment.purchase_order_id IS NULL)
    OR (v_payment.supplier_receipt_id IS NOT NULL AND v_payment.purchase_order_id IS NOT NULL)
  THEN
    RAISE EXCEPTION 'دفعة المورد لا تحمل مرجعًا ماليًا واحدًا واضحًا يمكن عكسه بأمان.';
  END IF;

  IF v_payment.supplier_receipt_id IS NOT NULL THEN
    SELECT * INTO v_receipt
    FROM public.supplier_receipts
    WHERE id = v_payment.supplier_receipt_id
    FOR UPDATE;
    IF NOT FOUND OR v_receipt.status <> 'completed' OR v_receipt.supplier_id <> v_payment.supplier_id THEN
      RAISE EXCEPTION 'سند استلام المورد لم يعد صالحًا لعكس الدفعة.';
    END IF;
    IF v_receipt.amount_paid_in_minor_units < v_payment.amount_in_minor_units THEN
      RAISE EXCEPTION 'رصيد دفعات سند المورد لا يسمح بعكس هذه الدفعة بأمان.';
    END IF;

    v_new_paid := v_receipt.amount_paid_in_minor_units - v_payment.amount_in_minor_units;
    v_new_due := v_receipt.total_in_minor_units - v_new_paid;

    PERFORM 1 FROM public.suppliers
    WHERE id = v_payment.supplier_id
    FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'المورد المرتبط بالدفعة غير موجود.';
    END IF;

    UPDATE public.supplier_receipts
    SET
      amount_paid_in_minor_units = v_new_paid,
      amount_due_in_minor_units = v_new_due,
      payment_status = CASE
        WHEN v_new_paid = 0 THEN 'unpaid'
        WHEN v_new_paid = v_receipt.total_in_minor_units THEN 'paid'
        ELSE 'partially_paid'
      END,
      updated_at = NOW()
    WHERE id = v_receipt.id;

    UPDATE public.suppliers
    SET
      current_balance_in_minor_units = current_balance_in_minor_units + v_payment.amount_in_minor_units,
      updated_at = NOW()
    WHERE id = v_payment.supplier_id;

    v_effect := jsonb_build_object(
      'reference_type', 'supplier_receipt',
      'reference_id', v_receipt.id,
      'supplier_balance_restored_in_minor_units', v_payment.amount_in_minor_units,
      'receipt_amount_paid_after_in_minor_units', v_new_paid,
      'receipt_amount_due_after_in_minor_units', v_new_due,
      'cash_in_minor_units', CASE WHEN v_payment.payment_method = 'cash' THEN v_payment.amount_in_minor_units ELSE 0 END,
      'cliq_in_minor_units', CASE WHEN v_payment.payment_method = 'cliq' THEN v_payment.amount_in_minor_units ELSE 0 END
    );
  ELSE
    SELECT * INTO v_purchase_order
    FROM public.purchase_orders
    WHERE id = v_payment.purchase_order_id
    FOR UPDATE;
    IF NOT FOUND OR v_purchase_order.supplier_id <> v_payment.supplier_id THEN
      RAISE EXCEPTION 'أمر شراء المورد لم يعد صالحًا لعكس الدفعة.';
    END IF;
    IF v_purchase_order.amount_paid_in_minor_units < v_payment.amount_in_minor_units THEN
      RAISE EXCEPTION 'رصيد دفعات أمر الشراء لا يسمح بعكس هذه الدفعة بأمان.';
    END IF;

    PERFORM 1 FROM public.suppliers
    WHERE id = v_payment.supplier_id FOR NO KEY UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'المورد المرتبط بالدفعة غير موجود.'; END IF;
    UPDATE public.suppliers
    SET current_balance_in_minor_units = current_balance_in_minor_units + v_payment.amount_in_minor_units,
      updated_at = NOW()
    WHERE id = v_payment.supplier_id;

    v_new_paid := v_purchase_order.amount_paid_in_minor_units - v_payment.amount_in_minor_units;
    UPDATE public.purchase_orders
    SET amount_paid_in_minor_units = v_new_paid, updated_at = NOW()
    WHERE id = v_purchase_order.id;

    v_effect := jsonb_build_object(
      'reference_type', 'purchase_order',
      'reference_id', v_purchase_order.id,
      'purchase_order_amount_paid_after_in_minor_units', v_new_paid,
      'supplier_balance_restored_in_minor_units', v_payment.amount_in_minor_units,
      'cash_in_minor_units', CASE WHEN v_payment.payment_method = 'cash' THEN v_payment.amount_in_minor_units ELSE 0 END,
      'cliq_in_minor_units', CASE WHEN v_payment.payment_method = 'cliq' THEN v_payment.amount_in_minor_units ELSE 0 END
    );
  END IF;

  INSERT INTO public.supplier_payment_reversals (
    supplier_payment_id, cash_shift_id, requested_by, reason, idempotency_key,
    expected_effect, actual_effect
  ) VALUES (
    v_payment.id, v_shift.id, v_user_id, v_reason, v_key, v_effect, v_effect
  ) RETURNING id INTO v_existing.id;

  UPDATE public.supplier_payments
  SET
    is_reversed = true,
    reversed_at = NOW(),
    reversed_by = v_user_id,
    reversal_reason = v_reason
  WHERE id = v_payment.id;

  INSERT INTO public.audit_logs (
    user_id, action, entity_name, entity_id, details
  ) VALUES (
    v_user_id, 'REVERSE_SUPPLIER_PAYMENT', 'supplier_payment_reversals', v_existing.id,
    jsonb_build_object(
      'supplier_payment_id', v_payment.id,
      'cash_shift_id', v_shift.id,
      'reason', v_reason,
      'effect', v_effect
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'idempotent', false,
    'reversal_id', v_existing.id,
    'supplier_payment_id', v_payment.id,
    'cash_shift_id', v_shift.id,
    'actual_effect', v_effect
  );
END;
$function$

CREATE OR REPLACE FUNCTION public._submit_guest_customer_order_v1_before_phase3(p_idempotency_key text, p_customer_full_name text, p_customer_phone text, p_governorate text, p_city text, p_area text, p_street text, p_building text DEFAULT NULL::text, p_address_notes text DEFAULT NULL::text, p_google_maps_url text DEFAULT NULL::text, p_latitude double precision DEFAULT NULL::double precision, p_longitude double precision DEFAULT NULL::double precision, p_customer_notes text DEFAULT NULL::text, p_items jsonb DEFAULT '[]'::jsonb, p_promotion_code text DEFAULT NULL::text, p_payment_method text DEFAULT 'cash_on_delivery'::text, p_delivery_zone text DEFAULT 'inside_ramtha'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_payment_method TEXT := LOWER(NULLIF(TRIM(p_payment_method), ''));
  v_delivery_zone TEXT := LOWER(NULLIF(TRIM(p_delivery_zone), ''));
  v_result JSONB;
  v_order_id UUID;
  v_existing_payment_method TEXT;
  v_existing_delivery_zone TEXT;
  v_existing_delivery_fee BIGINT;
  v_existing_total BIGINT;
  v_tracking_token UUID;
  v_settings public.storefront_settings%ROWTYPE;
  v_is_replay BOOLEAN;
  v_delivery_fee BIGINT;
  v_total BIGINT;
BEGIN
  IF v_payment_method NOT IN ('cash_on_delivery', 'cliq') THEN
    RAISE EXCEPTION 'طريقة الدفع غير مدعومة. اختر كاش عند الاستلام أو CliQ.';
  END IF;

  IF v_delivery_zone NOT IN ('inside_ramtha', 'outside_ramtha') THEN
    RAISE EXCEPTION 'اختر منطقة التوصيل: داخل الرمثا أو خارج الرمثا.';
  END IF;

  IF v_delivery_zone = 'inside_ramtha'
    AND CONCAT_WS(' ', p_governorate, p_city, p_area) NOT ILIKE '%الرمثا%'
  THEN
    RAISE EXCEPTION 'العنوان لا يظهر أنه داخل الرمثا. اختر خارج الرمثا أو صحح المدينة.';
  END IF;

  SELECT * INTO v_settings
  FROM public.storefront_settings
  WHERE id = '00000000-0000-0000-0000-000000000001'::UUID;

  v_result := public.submit_guest_customer_order_core(
    p_idempotency_key, p_customer_full_name, p_customer_phone,
    p_governorate, p_city, p_area, p_street, p_building,
    p_address_notes, p_google_maps_url, p_latitude, p_longitude,
    p_customer_notes, p_items, p_promotion_code
  );

  IF NOT COALESCE((v_result->>'success')::BOOLEAN, false) THEN
    RETURN v_result;
  END IF;

  v_is_replay := COALESCE((v_result->>'idempotent_replay')::BOOLEAN, false);
  v_order_id := (v_result->>'order_id')::UUID;

  SELECT
    payment_method,
    delivery_zone,
    delivery_fee_in_minor_units,
    total_in_minor_units,
    tracking_token
  INTO
    v_existing_payment_method,
    v_existing_delivery_zone,
    v_existing_delivery_fee,
    v_existing_total,
    v_tracking_token
  FROM public.orders
  WHERE id = v_order_id
  FOR UPDATE;

  IF v_is_replay THEN
    IF v_existing_payment_method IS DISTINCT FROM v_payment_method THEN
      RAISE EXCEPTION 'تغيرت طريقة الدفع لطلب محفوظ مسبقًا. أعد إرسال الطلب.';
    END IF;

    IF v_existing_delivery_zone IS NOT NULL
      AND v_existing_delivery_zone IS DISTINCT FROM v_delivery_zone
    THEN
      RAISE EXCEPTION 'تغيرت منطقة التوصيل لطلب محفوظ مسبقًا. أعد إرسال الطلب.';
    END IF;

    IF v_existing_delivery_zone IS NULL THEN
      UPDATE public.orders
      SET delivery_zone = v_delivery_zone,
          updated_at = NOW()
      WHERE id = v_order_id;
      v_existing_delivery_zone := v_delivery_zone;
    END IF;

    RETURN v_result || jsonb_build_object(
      'total', v_existing_total,
      'delivery_fee', v_existing_delivery_fee,
      'delivery_zone', v_existing_delivery_zone,
      'payment_method', v_payment_method,
      'payment_status', 'unpaid',
      'tracking_token', v_tracking_token,
      'tracking_path', '/#track=' || v_tracking_token::TEXT
    );
  END IF;

  IF NOT COALESCE(v_settings.orders_enabled, false) THEN
    RAISE EXCEPTION 'الطلبات متوقفة مؤقتًا من إدارة المتجر. تواصل معنا عبر واتساب.';
  END IF;

  IF (v_result->>'subtotal')::BIGINT < v_settings.minimum_order_in_minor_units THEN
    RAISE EXCEPTION 'قيمة الطلب أقل من الحد الأدنى المطلوب وهو % د.أ.',
      to_char(v_settings.minimum_order_in_minor_units / 1000.0, 'FM999999990.000');
  END IF;

  v_delivery_fee := CASE v_delivery_zone
    WHEN 'inside_ramtha' THEN
      v_settings.inside_ramtha_delivery_fee_in_minor_units
    ELSE
      v_settings.outside_ramtha_delivery_fee_in_minor_units
  END;
  v_total := (v_result->>'total')::BIGINT + v_delivery_fee;

  UPDATE public.orders
  SET delivery_zone = v_delivery_zone,
      delivery_fee_in_minor_units = v_delivery_fee,
      total_in_minor_units = v_total,
      payment_method = v_payment_method,
      payment_status = 'unpaid',
      updated_at = NOW()
  WHERE id = v_order_id;

  RETURN v_result || jsonb_build_object(
    'total', v_total,
    'delivery_fee', v_delivery_fee,
    'delivery_zone', v_delivery_zone,
    'payment_method', v_payment_method,
    'payment_status', 'unpaid',
    'tracking_token', v_tracking_token,
    'tracking_path', '/#track=' || v_tracking_token::TEXT
  );
END;
$function$

CREATE OR REPLACE FUNCTION public._transfer_inventory_between_warehouses_phase2_legacy(p_product_id uuid, p_source_warehouse_id uuid, p_destination_warehouse_id uuid, p_quantity integer, p_notes text DEFAULT NULL::text, p_transfer_date timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_source_warehouse_name TEXT;
  v_destination_warehouse_name TEXT;
  v_source_before INTEGER;
  v_source_reserved INTEGER;
  v_source_after INTEGER;
  v_destination_before INTEGER;
  v_destination_after INTEGER;
  v_out_movement_id UUID;
  v_in_movement_id UUID;
BEGIN
  PERFORM public.assert_erp_role(
    ARRAY['owner', 'admin', 'manager', 'warehouse_keeper'],
    'نقل المخزون بين المستودعات'
  );

  IF p_product_id IS NULL
     OR p_source_warehouse_id IS NULL
     OR p_destination_warehouse_id IS NULL
  THEN
    RAISE EXCEPTION 'المنتج والمستودع المصدر والمستودع الهدف مطلوبة.';
  END IF;

  IF p_quantity IS NULL OR p_quantity <= 0 THEN
    RAISE EXCEPTION 'الكمية المنقولة يجب أن تكون عددًا صحيحًا أكبر من صفر.';
  END IF;

  IF p_source_warehouse_id = p_destination_warehouse_id THEN
    RAISE EXCEPTION 'لا يمكن نقل المخزون إلى المستودع نفسه.';
  END IF;

  PERFORM 1
  FROM public.products
  WHERE id = p_product_id
    AND is_active = true;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'المنتج المحدد غير موجود أو غير نشط.';
  END IF;

  SELECT name_ar
  INTO v_source_warehouse_name
  FROM public.warehouses
  WHERE id = p_source_warehouse_id
    AND is_active = true;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'المستودع المصدر غير موجود أو غير نشط.';
  END IF;

  SELECT name_ar
  INTO v_destination_warehouse_name
  FROM public.warehouses
  WHERE id = p_destination_warehouse_id
    AND is_active = true;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'المستودع الهدف غير موجود أو غير نشط.';
  END IF;

  -- One stable operation key prevents opposing transfers of the same product
  -- between this warehouse pair from deadlocking or overspending stock.
  PERFORM pg_advisory_xact_lock(
    hashtextextended(
      p_product_id::TEXT || ':' ||
      LEAST(p_source_warehouse_id::TEXT, p_destination_warehouse_id::TEXT) || ':' ||
      GREATEST(p_source_warehouse_id::TEXT, p_destination_warehouse_id::TEXT),
      0
    )
  );

  SELECT on_hand_quantity, reserved_quantity
  INTO v_source_before, v_source_reserved
  FROM public.inventory_balances
  WHERE warehouse_id = p_source_warehouse_id
    AND product_id = p_product_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'لا يوجد رصيد لهذا المنتج في المستودع المصدر.';
  END IF;

  IF (v_source_before - p_quantity) < v_source_reserved THEN
    RAISE EXCEPTION
      'لا يمكن نقل % قطعة؛ المتاح للنقل في المستودع المصدر هو % قطعة بعد حجز الطلبات.',
      p_quantity,
      v_source_before - v_source_reserved;
  END IF;

  v_source_after := v_source_before - p_quantity;
  UPDATE public.inventory_balances
  SET on_hand_quantity = v_source_after, updated_at = NOW()
  WHERE warehouse_id = p_source_warehouse_id
    AND product_id = p_product_id;

  INSERT INTO public.inventory_balances (
    warehouse_id,
    product_id,
    on_hand_quantity,
    reserved_quantity
  ) VALUES (
    p_destination_warehouse_id,
    p_product_id,
    p_quantity,
    0
  ) ON CONFLICT (warehouse_id, product_id)
  DO UPDATE
  SET
    on_hand_quantity = public.inventory_balances.on_hand_quantity + EXCLUDED.on_hand_quantity,
    updated_at = NOW()
  RETURNING on_hand_quantity - p_quantity, on_hand_quantity
  INTO v_destination_before, v_destination_after;

  INSERT INTO public.inventory_movements (
    warehouse_id, product_id, movement_type, quantity, balance_before,
    balance_after, reference_type, notes, created_by
  ) VALUES (
    p_source_warehouse_id, p_product_id, 'transfer_out', -p_quantity,
    v_source_before, v_source_after, 'warehouse_transfer',
    COALESCE(NULLIF(BTRIM(p_notes), ''), 'نقل مخزون إلى ' || v_destination_warehouse_name),
    v_user_id
  ) RETURNING id INTO v_out_movement_id;

  INSERT INTO public.inventory_movements (
    warehouse_id, product_id, movement_type, quantity, balance_before,
    balance_after, reference_type, notes, created_by
  ) VALUES (
    p_destination_warehouse_id, p_product_id, 'transfer_in', p_quantity,
    v_destination_before, v_destination_after, 'warehouse_transfer',
    COALESCE(NULLIF(BTRIM(p_notes), ''), 'نقل مخزون من ' || v_source_warehouse_name),
    v_user_id
  ) RETURNING id INTO v_in_movement_id;

  INSERT INTO public.audit_logs (
    user_id, action, entity_name, entity_id, details
  ) VALUES (
    v_user_id,
    'TRANSFER_INVENTORY',
    'inventory_balances',
    p_product_id,
    jsonb_build_object(
      'source_warehouse_id', p_source_warehouse_id,
      'destination_warehouse_id', p_destination_warehouse_id,
      'quantity', p_quantity,
      'source_before', v_source_before,
      'source_after', v_source_after,
      'destination_before', v_destination_before,
      'destination_after', v_destination_after,
      'out_movement_id', v_out_movement_id,
      'in_movement_id', v_in_movement_id
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'productId', p_product_id,
    'quantityTransferred', p_quantity,
    'sourceNewQuantity', v_source_after,
    'destinationNewQuantity', v_destination_after,
    'movementOutId', v_out_movement_id,
    'movementInId', v_in_movement_id,
    'message', 'تم نقل المخزون من ' || v_source_warehouse_name || ' إلى ' || v_destination_warehouse_name || ' بنجاح.'
  );
END;
$function$

CREATE OR REPLACE FUNCTION public._transition_business_alert_incident(p_incident_key text, p_event_type text, p_entity_id uuid, p_is_active boolean, p_observed_at timestamp with time zone, p_payload jsonb DEFAULT '{}'::jsonb, p_emit_recovery boolean DEFAULT true)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_incident public.business_alert_incidents%ROWTYPE;
  v_occurrence INTEGER;
BEGIN
  IF p_incident_key IS NULL OR NULLIF(TRIM(p_incident_key), '') IS NULL
    OR length(p_incident_key) > 240 OR p_entity_id IS NULL OR p_observed_at IS NULL
    OR p_event_type NOT IN (
      'order_unprocessed', 'order_near_expiry',
      'shift_close_reminder', 'shift_close_overdue',
      'purchase_order_overdue', 'expense_daily_threshold',
      'business_integrity_warning'
    )
  THEN
    RAISE EXCEPTION 'Invalid Business alert incident transition.';
  END IF;

  SELECT * INTO v_incident FROM public.business_alert_incidents
  WHERE incident_key = p_incident_key FOR UPDATE;

  IF p_is_active THEN
    IF NOT FOUND THEN
      v_occurrence := 1;
      INSERT INTO public.business_alert_incidents(
        incident_key, alert_type, entity_id, state, occurrence,
        opened_at, last_seen_at, resolved_at, updated_at
      ) VALUES (
        p_incident_key, p_event_type, p_entity_id, 'open', v_occurrence,
        p_observed_at, p_observed_at, NULL, p_observed_at
      );
    ELSIF v_incident.state = 'resolved' THEN
      v_occurrence := v_incident.occurrence + 1;
      UPDATE public.business_alert_incidents
      SET alert_type=p_event_type, entity_id=p_entity_id, state='open',
          occurrence=v_occurrence, opened_at=p_observed_at,
          last_seen_at=p_observed_at, resolved_at=NULL, updated_at=p_observed_at
      WHERE incident_key=p_incident_key;
    ELSE
      UPDATE public.business_alert_incidents
      SET last_seen_at=p_observed_at, updated_at=p_observed_at
      WHERE incident_key=p_incident_key;
      RETURN 'unchanged';
    END IF;
    PERFORM public.enqueue_automation_event(
      'business:'||p_incident_key||':open:'||v_occurrence::TEXT,
      p_event_type, p_entity_id,
      COALESCE(p_payload,'{}'::JSONB)||jsonb_build_object(
        'incidentKey',p_incident_key,'state','open',
        'occurrence',v_occurrence,'observedAt',p_observed_at)
    );
    RETURN 'opened';
  END IF;

  IF NOT FOUND OR v_incident.state <> 'open' THEN RETURN 'unchanged'; END IF;
  UPDATE public.business_alert_incidents
  SET state='resolved', last_seen_at=p_observed_at, resolved_at=p_observed_at,
      updated_at=p_observed_at WHERE incident_key=p_incident_key;
  IF p_emit_recovery THEN
    PERFORM public.enqueue_automation_event(
      'business:'||p_incident_key||':resolved:'||v_incident.occurrence::TEXT,
      'business_alert_recovery', p_entity_id,
      COALESCE(p_payload,'{}'::JSONB)||jsonb_build_object(
        'incidentKey',p_incident_key,'resolvedAlertType',p_event_type,
        'state','resolved','occurrence',v_incident.occurrence,
        'observedAt',p_observed_at)
    );
  END IF;
  RETURN 'resolved';
END;
$function$

CREATE OR REPLACE FUNCTION public._update_order_status_impl(p_order_id uuid, p_new_status text, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_order_number TEXT;
  v_old_status TEXT;
  v_user_id UUID;
  v_valid_transition BOOLEAN := false;
BEGIN
  v_user_id := auth.uid();

  -- Normalize target status if needed
  IF p_new_status = 'processing' THEN
    p_new_status := 'preparing';
  ELSIF p_new_status = 'delivered' THEN
    p_new_status := 'completed';
  END IF;

  -- Lock and fetch current order
  SELECT order_number, status
  INTO v_order_number, v_old_status
  FROM public.orders
  WHERE id = p_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'الطلب المحدد غير موجود في قاعدة البيانات.';
  END IF;

  -- Delegate special atomic transitions
  IF p_new_status = 'confirmed' AND v_old_status = 'new' THEN
    RETURN public.confirm_order(p_order_id, p_notes);
  ELSIF p_new_status = 'completed' THEN
    RETURN public.complete_order(p_order_id, p_notes);
  ELSIF p_new_status = 'cancelled' THEN
    RETURN public.cancel_order(p_order_id, p_notes);
  END IF;

  -- Validate permitted status transitions
  IF v_old_status = 'new' AND p_new_status IN ('confirmed', 'preparing', 'cancelled') THEN
    v_valid_transition := true;
  ELSIF v_old_status = 'confirmed' AND p_new_status IN ('preparing', 'cancelled') THEN
    v_valid_transition := true;
  ELSIF v_old_status = 'preparing' AND p_new_status IN ('ready', 'out_for_delivery', 'cancelled') THEN
    v_valid_transition := true;
  ELSIF v_old_status = 'ready' AND p_new_status IN ('out_for_delivery', 'completed', 'cancelled') THEN
    v_valid_transition := true;
  ELSIF v_old_status = 'out_for_delivery' AND p_new_status IN ('completed', 'cancelled') THEN
    v_valid_transition := true;
  END IF;

  IF NOT v_valid_transition THEN
    RAISE EXCEPTION 'انتقال حالة الطلب غير مسموح به من (%) إلى (%).', v_old_status, p_new_status;
  END IF;

  -- Update status
  UPDATE public.orders
  SET status = p_new_status,
      updated_at = NOW()
  WHERE id = p_order_id;

  -- Record order status history
  INSERT INTO public.order_status_history (
    order_id,
    old_status,
    new_status,
    changed_by,
    notes
  ) VALUES (
    p_order_id,
    v_old_status,
    p_new_status,
    v_user_id,
    COALESCE(p_notes, 'تغيير حالة الطلب إلى ' || p_new_status)
  );

  -- Record audit log
  INSERT INTO public.audit_logs (
    user_id,
    action,
    entity_name,
    entity_id,
    details
  ) VALUES (
    v_user_id,
    'update_order_status',
    'orders',
    p_order_id,
    jsonb_build_object(
      'order_number', v_order_number,
      'old_status', v_old_status,
      'new_status', p_new_status,
      'notes', p_notes
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'order_id', p_order_id,
    'order_number', v_order_number,
    'old_status', v_old_status,
    'status', p_new_status,
    'message', 'تم تحديث حالة الطلب بنجاح إلى ' || p_new_status
  );

EXCEPTION WHEN OTHERS THEN
  RAISE EXCEPTION 'فشلت عملية تحديث حالة الطلب: %', SQLERRM;
END;
$function$

CREATE OR REPLACE FUNCTION public._update_purchase_order_status_impl(p_purchase_order_id uuid, p_new_status text, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id UUID;
  v_po public.purchase_orders%ROWTYPE;
  v_total_received INT := 0;
BEGIN
  v_user_id := auth.uid();

  -- Lock PO row
  SELECT * INTO v_po
  FROM public.purchase_orders
  WHERE id = p_purchase_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'طلب الشراء المحدد غير موجود.';
  END IF;

  IF v_po.status = p_new_status THEN
    RETURN jsonb_build_object('success', true, 'message', 'الحالة الحالية هي بالفعل الحالة المطلوبة.');
  END IF;

  -- Calculate total received quantity across all items
  SELECT COALESCE(SUM(received_quantity), 0) INTO v_total_received
  FROM public.purchase_order_items
  WHERE purchase_order_id = p_purchase_order_id;

  -- Validate Transitions
  IF v_po.status = 'draft' AND p_new_status NOT IN ('sent', 'cancelled') THEN
    RAISE EXCEPTION 'طلب الشراء المسودة يمكن تحويله إلى مرسل أو ملغى فقط.';
  ELSIF v_po.status = 'sent' AND p_new_status NOT IN ('approved', 'cancelled') THEN
    RAISE EXCEPTION 'طلب الشراء المرسل يمكن تحويله إلى معتمد أو ملغى فقط.';
  ELSIF v_po.status = 'approved' AND p_new_status NOT IN ('partially_received', 'received', 'cancelled') THEN
    RAISE EXCEPTION 'طلب الشراء المعتمد يمكن استلامه جزئياً/كلياً أو إلغاؤه.';
  ELSIF v_po.status = 'approved' AND p_new_status = 'cancelled' AND v_total_received > 0 THEN
    RAISE EXCEPTION 'لا يمكن إلغاء طلب شراء معتمد تم استلام جزء من بضائعه بالفعل.';
  ELSIF v_po.status = 'partially_received' AND p_new_status NOT IN ('partially_received', 'received') THEN
    RAISE EXCEPTION 'طلب الشراء المستلم جزئياً لا يمكن تحويله إلا إلى مستلم كلياً.';
  ELSIF v_po.status = 'received' THEN
    RAISE EXCEPTION 'أمر الشراء المكتمل والمستلم بالكامل لا يمكن تغيير حالته أو إلغاؤه.';
  ELSIF v_po.status = 'cancelled' THEN
    RAISE EXCEPTION 'أمر الشراء الملغى لا يمكن تعديل حالته.';
  END IF;

  -- Apply Update
  UPDATE public.purchase_orders
  SET
    status = p_new_status,
    approved_by = CASE WHEN p_new_status = 'approved' THEN v_user_id ELSE approved_by END,
    approved_at = CASE WHEN p_new_status = 'approved' THEN NOW() ELSE approved_at END,
    cancelled_at = CASE WHEN p_new_status = 'cancelled' THEN NOW() ELSE cancelled_at END,
    received_at = CASE WHEN p_new_status = 'received' THEN NOW() ELSE received_at END,
    notes = CASE WHEN p_notes IS NOT NULL THEN COALESCE(notes, '') || ' | ' || p_notes ELSE notes END,
    updated_at = NOW()
  WHERE id = p_purchase_order_id;

  -- Audit Log
  INSERT INTO public.audit_logs (
    user_id,
    action,
    entity_name,
    entity_id,
    details
  ) VALUES (
    v_user_id,
    'تحديث حالة أمر شراء',
    'purchase_orders',
    p_purchase_order_id,
    jsonb_build_object(
      'old_status', v_po.status,
      'new_status', p_new_status,
      'notes', p_notes
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'purchase_order_id', p_purchase_order_id,
    'status', p_new_status,
    'message', 'تم تحديث حالة طلب الشراء بنجاح'
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.accept_order_for_preparation(p_order_id uuid, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_status TEXT;
  v_result JSONB;
BEGIN
  PERFORM public.assert_erp_role(
    ARRAY['owner', 'admin', 'manager', 'sales'],
    'قبول الطلب وبدء التجهيز'
  );

  SELECT status
  INTO v_status
  FROM public.orders
  WHERE id = p_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'الطلب المحدد غير موجود.';
  END IF;

  IF v_status = 'new' THEN
    PERFORM public.confirm_order(
      p_order_id,
      COALESCE(NULLIF(TRIM(p_notes), ''), 'قبول الطلب وحجز المخزون')
    );
    v_status := 'confirmed';
  END IF;

  IF v_status = 'confirmed' THEN
    v_result := public.update_order_status(
      p_order_id,
      'preparing',
      COALESCE(NULLIF(TRIM(p_notes), ''), 'تم قبول الطلب وبدأ التجهيز')
    );
  ELSIF v_status = 'preparing' THEN
    v_result := jsonb_build_object(
      'success', true,
      'order_id', p_order_id,
      'status', 'preparing'
    );
  ELSE
    RAISE EXCEPTION 'لا يمكن قبول الطلب وبدء تجهيزه من الحالة الحالية (%).', v_status;
  END IF;

  RETURN v_result || jsonb_build_object(
    'message', 'تم قبول الطلب وحجز المخزون وبدء التجهيز.'
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.adjust_inventory_stock(p_warehouse_id uuid, p_product_id uuid, p_actual_quantity integer, p_reason text, p_adjustment_type text DEFAULT 'stock_count'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_product_name TEXT;
  v_previous_quantity INTEGER;
  v_reserved_quantity INTEGER;
  v_quantity_change INTEGER;
  v_movement_type TEXT;
  v_movement_id UUID;
BEGIN
  PERFORM public.assert_erp_role(
    ARRAY['owner', 'admin', 'manager', 'warehouse_keeper'],
    'جرد وتسوية المخزون'
  );

  IF p_warehouse_id IS NULL OR p_product_id IS NULL THEN
    RAISE EXCEPTION 'المنتج والمستودع مطلوبان.';
  END IF;
  IF p_actual_quantity IS NULL OR p_actual_quantity < 0 THEN
    RAISE EXCEPTION 'الكمية الفعلية يجب أن تكون عدداً صحيحاً لا يقل عن صفر.';
  END IF;
  IF NULLIF(TRIM(p_reason), '') IS NULL THEN
    RAISE EXCEPTION 'سبب الجرد أو التسوية مطلوب.';
  END IF;
  IF COALESCE(p_adjustment_type, 'stock_count') NOT IN (
    'stock_count',
    'damage',
    'expired',
    'manual'
  ) THEN
    RAISE EXCEPTION 'نوع تسوية المخزون غير معتمد.';
  END IF;

  SELECT p.name_ar
  INTO v_product_name
  FROM public.products p
  WHERE p.id = p_product_id
    AND p.is_active = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'المنتج المحدد غير موجود أو غير نشط.';
  END IF;

  SELECT on_hand_quantity, reserved_quantity
  INTO v_previous_quantity, v_reserved_quantity
  FROM public.inventory_balances
  WHERE warehouse_id = p_warehouse_id
    AND product_id = p_product_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'لا يوجد رصيد لهذا المنتج في المستودع المحدد.';
  END IF;

  IF p_actual_quantity < v_reserved_quantity THEN
    RAISE EXCEPTION
      'لا يمكن جعل المخزون الفعلي (%) أقل من الكمية المحجوزة (%).',
      p_actual_quantity,
      v_reserved_quantity;
  END IF;

  v_quantity_change := p_actual_quantity - v_previous_quantity;
  v_movement_type :=
    CASE WHEN v_quantity_change >= 0
      THEN 'adjustment_add'
      ELSE 'adjustment_subtract'
    END;

  UPDATE public.inventory_balances
  SET
    on_hand_quantity = p_actual_quantity,
    updated_at = NOW()
  WHERE warehouse_id = p_warehouse_id
    AND product_id = p_product_id;

  IF v_quantity_change <> 0 THEN
    INSERT INTO public.inventory_movements (
      warehouse_id,
      product_id,
      movement_type,
      quantity,
      balance_before,
      balance_after,
      reference_type,
      reference_id,
      notes,
      created_by
    ) VALUES (
      p_warehouse_id,
      p_product_id,
      v_movement_type,
      v_quantity_change,
      v_previous_quantity,
      p_actual_quantity,
      COALESCE(p_adjustment_type, 'stock_count'),
      NULL,
      TRIM(p_reason),
      v_user_id
    )
    RETURNING id INTO v_movement_id;
  END IF;

  INSERT INTO public.audit_logs (
    user_id,
    action,
    entity_name,
    entity_id,
    details
  ) VALUES (
    v_user_id,
    'ADJUST_INVENTORY_STOCK',
    'inventory_balances',
    p_product_id,
    jsonb_build_object(
      'warehouse_id', p_warehouse_id,
      'product_name', v_product_name,
      'previous_quantity', v_previous_quantity,
      'actual_quantity', p_actual_quantity,
      'quantity_change', v_quantity_change,
      'adjustment_type', COALESCE(p_adjustment_type, 'stock_count'),
      'reason', TRIM(p_reason),
      'movement_id', v_movement_id
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'productId', p_product_id,
    'productName', v_product_name,
    'warehouseId', p_warehouse_id,
    'previousQuantity', v_previous_quantity,
    'actualQuantity', p_actual_quantity,
    'quantityChange', v_quantity_change,
    'availableQuantity', p_actual_quantity - v_reserved_quantity,
    'movementId', v_movement_id,
    'message', 'تم حفظ الجرد وتسوية المخزون في Supabase بنجاح.'
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.apply_inventory_opening_setup(p_warehouse_id uuid, p_rows jsonb, p_notes text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_warehouse public.warehouses%ROWTYPE;
  v_existing_session public.inventory_opening_sessions%ROWTYPE;
  v_session_id UUID;
  v_session_number TEXT;
  v_row JSONB;
  v_product_id UUID;
  v_product_name TEXT;
  v_cost_price_in_minor_units BIGINT;
  v_purchase_package_name TEXT;
  v_base_unit_name TEXT;
  v_units_per_package INTEGER;
  v_package_count INTEGER;
  v_loose_units INTEGER;
  v_actual_quantity_big BIGINT;
  v_actual_quantity INTEGER;
  v_previous_quantity INTEGER;
  v_reserved_quantity INTEGER;
  v_quantity_change INTEGER;
  v_movement_id UUID;
  v_item_count INTEGER := 0;
  v_total_previous INTEGER := 0;
  v_total_actual INTEGER := 0;
  v_total_change INTEGER := 0;
  v_notes TEXT := NULLIF(TRIM(p_notes), '');
BEGIN
  PERFORM public.assert_erp_role(
    ARRAY['owner', 'admin', 'manager', 'warehouse_keeper'],
    'اعتماد تهيئة المخزون الافتتاحي'
  );

  IF p_warehouse_id IS NULL THEN
    RAISE EXCEPTION 'المستودع مطلوب.';
  END IF;
  IF v_notes IS NULL OR CHAR_LENGTH(v_notes) < 5 THEN
    RAISE EXCEPTION 'اكتب ملاحظة واضحة لجلسة المخزون الافتتاحي.';
  END IF;
  IF CHAR_LENGTH(v_notes) > 500 THEN
    RAISE EXCEPTION 'ملاحظة جلسة المخزون الافتتاحي أطول من المسموح.';
  END IF;
  IF NULLIF(TRIM(p_idempotency_key), '') IS NULL
    OR CHAR_LENGTH(TRIM(p_idempotency_key)) < 16
    OR CHAR_LENGTH(TRIM(p_idempotency_key)) > 100
  THEN
    RAISE EXCEPTION 'مفتاح منع التكرار غير صالح.';
  END IF;
  IF p_rows IS NULL OR jsonb_typeof(p_rows) <> 'array' THEN
    RAISE EXCEPTION 'بيانات أصناف المخزون الافتتاحي غير صحيحة.';
  END IF;
  IF jsonb_array_length(p_rows) NOT BETWEEN 1 AND 500 THEN
    RAISE EXCEPTION 'اختر صنفاً واحداً على الأقل وبحد أقصى 500 صنف.';
  END IF;
  IF (
    SELECT COUNT(*)
    FROM jsonb_array_elements(p_rows)
  ) <> (
    SELECT COUNT(DISTINCT row_data->>'productId')
    FROM jsonb_array_elements(p_rows) row_data
  ) THEN
    RAISE EXCEPTION 'لا يمكن تكرار الصنف داخل جلسة التهيئة.';
  END IF;

  -- Serialize concurrent retries that carry the same idempotency key.
  PERFORM pg_advisory_xact_lock(
    hashtextextended(TRIM(p_idempotency_key), 0)
  );

  SELECT * INTO v_existing_session
  FROM public.inventory_opening_sessions
  WHERE idempotency_key = TRIM(p_idempotency_key);

  IF FOUND THEN
    RETURN jsonb_build_object(
      'success', true,
      'idempotentReplay', true,
      'sessionId', v_existing_session.id,
      'sessionNumber', v_existing_session.session_number,
      'itemCount', v_existing_session.item_count,
      'totalActualQuantity', v_existing_session.total_actual_quantity,
      'message', 'تم اعتماد جلسة المخزون الافتتاحي سابقاً دون تكرار الحركات.'
    );
  END IF;

  SELECT * INTO v_warehouse
  FROM public.warehouses
  WHERE id = p_warehouse_id
    AND is_active = true
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'المستودع المحدد غير موجود أو غير نشط.';
  END IF;

  v_session_id := gen_random_uuid();
  v_session_number :=
    'IOS-' || TO_CHAR(CURRENT_DATE, 'YYYYMMDD') || '-' ||
    LPAD(nextval('public.inventory_opening_session_number_seq')::TEXT, 6, '0');

  INSERT INTO public.inventory_opening_sessions (
    id,
    session_number,
    idempotency_key,
    branch_id,
    warehouse_id,
    notes,
    created_by
  ) VALUES (
    v_session_id,
    v_session_number,
    TRIM(p_idempotency_key),
    v_warehouse.branch_id,
    p_warehouse_id,
    v_notes,
    v_user_id
  );

  FOR v_row IN SELECT value FROM jsonb_array_elements(p_rows)
  LOOP
    IF jsonb_typeof(v_row) <> 'object'
      OR COALESCE(v_row->>'productId', '') = ''
      OR COALESCE(v_row->>'packageCount', '') !~ '^\d+$'
      OR COALESCE(v_row->>'looseUnits', '') !~ '^\d+$'
    THEN
      RAISE EXCEPTION 'بيانات أحد الأصناف غير صحيحة.';
    END IF;

    v_product_id := (v_row->>'productId')::UUID;
    v_package_count := (v_row->>'packageCount')::INTEGER;
    v_loose_units := (v_row->>'looseUnits')::INTEGER;

    SELECT
      p.name_ar,
      p.cost_price_in_minor_units,
      COALESCE(pu.name_ar, bu.name_ar, 'طرد'),
      COALESCE(bu.name_ar, 'قطعة'),
      GREATEST(1, COALESCE(p.units_per_purchase_unit, 1))
    INTO
      v_product_name,
      v_cost_price_in_minor_units,
      v_purchase_package_name,
      v_base_unit_name,
      v_units_per_package
    FROM public.products p
    LEFT JOIN public.units bu ON bu.id = p.unit_id
    LEFT JOIN public.units pu ON pu.id = p.purchase_unit_id
    WHERE p.id = v_product_id
      AND p.is_active = true
    FOR SHARE OF p;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'أحد الأصناف غير موجود أو غير نشط.';
    END IF;
    IF v_loose_units >= v_units_per_package THEN
      RAISE EXCEPTION
        'الحبات المتبقية للصنف (%) يجب أن تكون أقل من محتوى الطرد (%).',
        v_product_name,
        v_units_per_package;
    END IF;

    v_actual_quantity_big :=
      v_package_count::BIGINT * v_units_per_package + v_loose_units;
    IF v_actual_quantity_big > 2147483647 THEN
      RAISE EXCEPTION 'كمية الصنف (%) أكبر من الحد المسموح.', v_product_name;
    END IF;
    v_actual_quantity := v_actual_quantity_big::INTEGER;

    IF v_actual_quantity > 0 AND v_cost_price_in_minor_units <= 0 THEN
      RAISE EXCEPTION
        'لا يمكن اعتماد مخزون للصنف (%) قبل إدخال تكلفة الشراء.',
        v_product_name;
    END IF;

    IF EXISTS (
      SELECT 1
      FROM public.inventory_movements im
      WHERE im.warehouse_id = p_warehouse_id
        AND im.product_id = v_product_id
        AND im.movement_type IN (
          'purchase_receipt',
          'sales_deduction',
          'transfer_in',
          'transfer_out',
          'return_in',
          'return_out'
        )
    ) THEN
      RAISE EXCEPTION
        'بدأت حركات الصنف (%). استخدم الجرد الموثق بدلاً من الرصيد الافتتاحي.',
        v_product_name;
    END IF;

    INSERT INTO public.inventory_balances (
      warehouse_id,
      product_id,
      on_hand_quantity,
      reserved_quantity
    ) VALUES (
      p_warehouse_id,
      v_product_id,
      0,
      0
    ) ON CONFLICT (warehouse_id, product_id) DO NOTHING;

    SELECT on_hand_quantity, reserved_quantity
    INTO v_previous_quantity, v_reserved_quantity
    FROM public.inventory_balances
    WHERE warehouse_id = p_warehouse_id
      AND product_id = v_product_id
    FOR UPDATE;

    IF v_reserved_quantity > 0 THEN
      RAISE EXCEPTION
        'الصنف (%) عليه كمية محجوزة. عالج الطلبات قبل التهيئة.',
        v_product_name;
    END IF;

    v_quantity_change := v_actual_quantity - v_previous_quantity;
    v_movement_id := NULL;

    UPDATE public.inventory_balances
    SET
      on_hand_quantity = v_actual_quantity,
      updated_at = NOW()
    WHERE warehouse_id = p_warehouse_id
      AND product_id = v_product_id;

    IF v_quantity_change <> 0 THEN
      INSERT INTO public.inventory_movements (
        warehouse_id,
        product_id,
        movement_type,
        quantity,
        balance_before,
        balance_after,
        reference_type,
        reference_id,
        notes,
        created_by
      ) VALUES (
        p_warehouse_id,
        v_product_id,
        'opening_balance',
        v_quantity_change,
        v_previous_quantity,
        v_actual_quantity,
        'inventory_opening_session',
        v_session_id,
        v_notes || ' - ' || v_session_number,
        v_user_id
      ) RETURNING id INTO v_movement_id;
    END IF;

    INSERT INTO public.inventory_opening_items (
      session_id,
      product_id,
      purchase_package_name,
      base_unit_name,
      units_per_package,
      package_count,
      loose_units,
      previous_quantity,
      actual_quantity,
      quantity_change,
      cost_price_in_minor_units,
      movement_id
    ) VALUES (
      v_session_id,
      v_product_id,
      v_purchase_package_name,
      v_base_unit_name,
      v_units_per_package,
      v_package_count,
      v_loose_units,
      v_previous_quantity,
      v_actual_quantity,
      v_quantity_change,
      v_cost_price_in_minor_units,
      v_movement_id
    );

    v_item_count := v_item_count + 1;
    v_total_previous := v_total_previous + v_previous_quantity;
    v_total_actual := v_total_actual + v_actual_quantity;
    v_total_change := v_total_change + v_quantity_change;
  END LOOP;

  UPDATE public.inventory_opening_sessions
  SET
    item_count = v_item_count,
    total_previous_quantity = v_total_previous,
    total_actual_quantity = v_total_actual,
    total_quantity_change = v_total_change
  WHERE id = v_session_id;

  INSERT INTO public.audit_logs (
    user_id,
    action,
    entity_name,
    entity_id,
    details
  ) VALUES (
    v_user_id,
    'APPLY_INVENTORY_OPENING_SETUP',
    'inventory_opening_sessions',
    v_session_id,
    jsonb_build_object(
      'session_number', v_session_number,
      'warehouse_id', p_warehouse_id,
      'branch_id', v_warehouse.branch_id,
      'item_count', v_item_count,
      'total_previous_quantity', v_total_previous,
      'total_actual_quantity', v_total_actual,
      'total_quantity_change', v_total_change,
      'notes', v_notes
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'sessionId', v_session_id,
    'sessionNumber', v_session_number,
    'itemCount', v_item_count,
    'totalPreviousQuantity', v_total_previous,
    'totalActualQuantity', v_total_actual,
    'totalQuantityChange', v_total_change,
    'message',
      'تم اعتماد المخزون الافتتاحي وتسجيل الحركات دون إنشاء فاتورة مورد أو مديونية.'
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.assert_configurable_parcel_creation_allowed()
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_feature_state TEXT := public.get_configurable_parcel_feature_state();
BEGIN
  IF v_feature_state = 'ENABLED' THEN
    RETURN;
  END IF;

  IF v_feature_state = 'OWNER_PILOT'
    AND auth.uid() IS NOT NULL
    AND public.has_erp_role(ARRAY['owner'])
  THEN
    RETURN;
  END IF;

  RAISE EXCEPTION USING
    ERRCODE = 'P0001',
    MESSAGE = 'CONFIGURABLE_PARCEL_DISABLED: الوظيفة غير مفعلة لإنشاء عمليات جديدة.';
END;
$function$

CREATE OR REPLACE FUNCTION public.assert_erp_role(p_allowed_roles text[], p_operation text DEFAULT 'تنفيذ العملية'::text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'يجب تسجيل الدخول من حساب موظف معتمد.';
  END IF;

  IF NOT public.is_mfa_policy_satisfied() THEN
    RAISE EXCEPTION 'يجب تأكيد رمز المصادقة الثنائية قبل %.',
      COALESCE(p_operation, 'تنفيذ العملية');
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.profiles p
    JOIN public.user_roles ur ON ur.user_id = p.id
    JOIN public.roles r ON r.id = ur.role_id
    WHERE p.id = v_user_id
      AND p.is_active = true
      AND r.code = ANY(p_allowed_roles)
  ) THEN
    RAISE EXCEPTION 'ليس لديك صلاحية %.', COALESCE(p_operation, 'تنفيذ العملية');
  END IF;
END;
$function$

