CREATE OR REPLACE FUNCTION public.authorize_admin_ai_assistant_request()
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_now TIMESTAMPTZ := NOW();
  v_requests_in_window INTEGER;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'يجب تسجيل الدخول لاستخدام مساعد الإدارة الذكي.'
      USING ERRCODE = '28000';
  END IF;

  PERFORM public.assert_erp_role(
    ARRAY['owner', 'admin', 'manager', 'accountant'],
    'استخدام مساعد الإدارة الذكي'
  );

  -- Serialise checks per user so parallel browser requests cannot bypass the limit.
  PERFORM pg_advisory_xact_lock(hashtextextended(v_user_id::TEXT, 0));

  DELETE FROM public.admin_ai_assistant_usage_events
  WHERE created_at < v_now - INTERVAL '2 days';

  SELECT COUNT(*)::INTEGER
    INTO v_requests_in_window
  FROM public.admin_ai_assistant_usage_events
  WHERE user_id = v_user_id
    AND created_at >= v_now - INTERVAL '15 minutes';

  IF v_requests_in_window >= 20 THEN
    RAISE EXCEPTION 'تم بلوغ الحد المؤقت للمساعد. حاول بعد بضع دقائق.'
      USING ERRCODE = '42901';
  END IF;

  INSERT INTO public.admin_ai_assistant_usage_events (user_id, created_at)
  VALUES (v_user_id, v_now);

  RETURN v_now;
END;
$function$

CREATE OR REPLACE FUNCTION public.authorize_guest_order_gateway(p_idempotency_key uuid, p_ip_hash text, p_session_hash text, p_phone_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
 SET lock_timeout TO '3s'
 SET statement_timeout TO '5s'
AS $function$
DECLARE
  v_existing public.guest_order_gateway_requests%ROWTYPE;
  v_lock_key TEXT;
  v_ip_burst INTEGER;
  v_ip_short INTEGER;
  v_session_short INTEGER;
  v_phone_short INTEGER;
  v_decision TEXT := 'allowed';
  v_reason TEXT := 'allowed';
  v_retry_after INTEGER := 0;
  v_existing_window INTERVAL;
BEGIN
  IF p_idempotency_key IS NULL THEN
    RAISE EXCEPTION 'Invalid gateway request.';
  END IF;

  IF COALESCE(p_ip_hash, '') !~ '^[0-9a-f]{64}$'
    OR COALESCE(p_session_hash, '') !~ '^[0-9a-f]{64}$'
    OR COALESCE(p_phone_hash, '') !~ '^[0-9a-f]{64}$'
  THEN
    RAISE EXCEPTION 'Invalid gateway identifiers.';
  END IF;

  -- Every signal is locked in one deterministic order. This keeps the limit
  -- atomic under concurrency without retaining raw network or customer data.
  FOR v_lock_key IN
    SELECT lock_key
    FROM unnest(ARRAY[
      'guest-order:idempotency:' || p_idempotency_key::TEXT,
      'guest-order:ip:' || p_ip_hash,
      'guest-order:phone:' || p_phone_hash,
      'guest-order:session:' || p_session_hash
    ]) AS lock_key
    ORDER BY lock_key
  LOOP
    PERFORM pg_advisory_xact_lock(hashtextextended(v_lock_key, 0));
  END LOOP;

  SELECT * INTO v_existing
  FROM public.guest_order_gateway_requests
  WHERE idempotency_key = p_idempotency_key
  FOR UPDATE;

  IF FOUND THEN
    IF v_existing.ip_hash <> p_ip_hash
      OR v_existing.session_hash <> p_session_hash
      OR v_existing.phone_hash <> p_phone_hash
    THEN
      RAISE EXCEPTION 'Gateway retry context does not match.';
    END IF;

    IF v_existing.decision = 'allowed' THEN
      RETURN jsonb_build_object(
        'allowed', true,
        'reason', v_existing.reason,
        'retry_after_seconds', 0,
        'idempotent_replay', true
      );
    END IF;

    v_existing_window := CASE v_existing.reason
      WHEN 'ip_burst' THEN INTERVAL '1 minute'
      WHEN 'ip_short_window' THEN INTERVAL '15 minutes'
      ELSE INTERVAL '10 minutes'
    END;

    IF v_existing.created_at >= NOW() - v_existing_window THEN
      RETURN jsonb_build_object(
        'allowed', false,
        'reason', v_existing.reason,
        'retry_after_seconds', GREATEST(
          1,
          CEIL(EXTRACT(EPOCH FROM (
            v_existing.created_at + v_existing_window - NOW()
          )))::INTEGER
        ),
        'idempotent_replay', true
      );
    END IF;

    -- A denied operation may be retried with the same business idempotency key
    -- after its limit window. Successful operations remain immutable replays.
    DELETE FROM public.guest_order_gateway_requests
    WHERE id = v_existing.id;
  END IF;

  SELECT
    COUNT(*) FILTER (
      WHERE ip_hash = p_ip_hash
        AND created_at >= NOW() - INTERVAL '1 minute'
    )::INTEGER,
    COUNT(*) FILTER (
      WHERE ip_hash = p_ip_hash
        AND created_at >= NOW() - INTERVAL '15 minutes'
    )::INTEGER,
    COUNT(*) FILTER (
      WHERE session_hash = p_session_hash
        AND created_at >= NOW() - INTERVAL '10 minutes'
    )::INTEGER,
    COUNT(*) FILTER (
      WHERE phone_hash = p_phone_hash
        AND created_at >= NOW() - INTERVAL '10 minutes'
    )::INTEGER
  INTO v_ip_burst, v_ip_short, v_session_short, v_phone_short
  FROM public.guest_order_gateway_requests
  WHERE created_at >= NOW() - INTERVAL '15 minutes'
    AND (
      ip_hash = p_ip_hash
      OR session_hash = p_session_hash
      OR phone_hash = p_phone_hash
    );

  -- Limits intentionally allow a normal second order and several customers
  -- behind one household/store network, while stopping identifier rotation.
  IF v_ip_burst >= 6 THEN
    v_decision := 'rate_limited';
    v_reason := 'ip_burst';
    v_retry_after := 60;
  ELSIF v_ip_short >= 20 THEN
    v_decision := 'rate_limited';
    v_reason := 'ip_short_window';
    v_retry_after := 900;
  ELSIF v_session_short >= 4 THEN
    v_decision := 'rate_limited';
    v_reason := 'session_short_window';
    v_retry_after := 600;
  ELSIF v_phone_short >= 3 THEN
    v_decision := 'rate_limited';
    v_reason := 'phone_short_window';
    v_retry_after := 600;
  END IF;

  INSERT INTO public.guest_order_gateway_requests (
    idempotency_key,
    ip_hash,
    session_hash,
    phone_hash,
    decision,
    reason,
    outcome
  ) VALUES (
    p_idempotency_key,
    p_ip_hash,
    p_session_hash,
    p_phone_hash,
    v_decision,
    v_reason,
    CASE WHEN v_decision = 'allowed' THEN 'pending' ELSE 'rate_limited' END
  );

  RETURN jsonb_build_object(
    'allowed', v_decision = 'allowed',
    'reason', v_reason,
    'retry_after_seconds', v_retry_after,
    'idempotent_replay', false
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.cancel_customer_order_v2(p_order_id uuid, p_idempotency_key text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_key TEXT := NULLIF(BTRIM(p_idempotency_key), '');
  v_actor_hash TEXT;
  v_request JSONB;
  v_fingerprint TEXT;
  v_replay JSONB;
  v_operation_id UUID := gen_random_uuid();
BEGIN
  PERFORM public.assert_erp_role(
    ARRAY['owner', 'admin', 'manager', 'sales'], 'إلغاء طلب عميل V2'
  );
  IF v_user_id IS NULL OR v_key IS NULL OR CHAR_LENGTH(v_key) NOT BETWEEN 16 AND 200 THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_IDEMPOTENCY_INPUT_INVALID: Cancellation identity is invalid.';
  END IF;
  v_actor_hash := public.phase3_actor_scope_hash_internal(
    'erp_user', v_user_id, NULL, NULL
  );
  v_request := JSONB_BUILD_OBJECT(
    'contract_version', 'phase3-customer-cancellation-v1',
    'actor_scope_hash', v_actor_hash, 'order_id', LOWER(p_order_id::TEXT),
    'reason', NULLIF(BTRIM(p_reason), '')
  );
  v_fingerprint := public.phase3_request_fingerprint_internal(v_request);
  v_replay := public.phase3_resolve_operation_replay_internal(
    'phase3_customer_cancellation_v1', v_key, 'erp_user',
    v_actor_hash, v_fingerprint
  );
  IF v_replay->>'decision' = 'REPLAY' THEN
    RETURN v_replay->'result_snapshot';
  END IF;
  RETURN public.phase3_release_customer_reservations_internal(
    p_order_id, v_operation_id, 'phase3_customer_cancellation_v1', v_key,
    v_fingerprint, v_request, 'erp_user', v_actor_hash, v_user_id,
    'cancelled', COALESCE(NULLIF(BTRIM(p_reason), ''), 'إلغاء طلب عميل V2')
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.cancel_empty_cash_shift(p_shift_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  PERFORM public.assert_erp_role(
    ARRAY['owner', 'admin', 'manager'],
    'إلغاء وردية فُتحت بالخطأ'
  );

  PERFORM 1 FROM public.cash_shifts WHERE id = p_shift_id FOR UPDATE;

  IF EXISTS (
    SELECT 1 FROM public.sales_return_events
    WHERE cash_shift_id = p_shift_id
      AND settlement_status <> 'cancelled'
  ) OR EXISTS (
    SELECT 1 FROM public.customer_collection_operations WHERE cash_shift_id = p_shift_id
  ) OR EXISTS (
    SELECT 1 FROM public.supplier_opening_payments WHERE cash_shift_id = p_shift_id
  ) OR EXISTS (
    SELECT 1 FROM public.supplier_cheque_claim_payments WHERE cash_shift_id=p_shift_id
  ) THEN
    RAISE EXCEPTION
      'لا يمكن إلغاء الوردية لأنها تحتوي حركة مالية. صحح العملية ثم أغلق الوردية طبيعيًا.';
  END IF;

  RETURN public._cancel_empty_cash_shift_before_return_events(p_shift_id, p_reason);
END;
$function$

