CREATE OR REPLACE FUNCTION public.correct_product_cost_v1(p_product_id uuid, p_unit_cost_in_minor_units numeric, p_reason text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_reason TEXT := BTRIM(COALESCE(p_reason, ''));
  v_key TEXT := BTRIM(COALESCE(p_idempotency_key, ''));
  v_exact NUMERIC(24, 6);
  v_legacy BIGINT;
  v_fingerprint TEXT;
  v_existing public.product_cost_corrections%ROWTYPE;
  v_product public.products%ROWTYPE;
  v_correction_id UUID;
BEGIN
  PERFORM public.assert_erp_role(ARRAY['owner'], 'تصحيح تكلفة المنتج');

  IF char_length(v_key) NOT BETWEEN 16 AND 200 THEN
    RAISE EXCEPTION 'PRODUCT_COST_CORRECTION_KEY_INVALID: مفتاح العملية غير صالح.';
  END IF;
  IF char_length(v_reason) NOT BETWEEN 5 AND 500 THEN
    RAISE EXCEPTION 'PRODUCT_COST_CORRECTION_REASON_REQUIRED: اكتب سبب التصحيح (5 إلى 500 حرف).';
  END IF;
  IF p_unit_cost_in_minor_units IS NULL OR p_unit_cost_in_minor_units < 0
    OR p_unit_cost_in_minor_units > 1000000000000 THEN
    RAISE EXCEPTION 'PRODUCT_COST_CORRECTION_VALUE_INVALID: تكلفة الحبة يجب أن تكون صفراً أو أكثر.';
  END IF;

  v_exact := ROUND(p_unit_cost_in_minor_units, 6);
  v_legacy := ROUND(v_exact)::BIGINT;
  v_fingerprint := md5(p_product_id::TEXT || '|' || v_exact::TEXT || '|' || v_reason);

  SELECT * INTO v_existing
  FROM public.product_cost_corrections correction
  WHERE correction.idempotency_key = v_key;
  IF FOUND THEN
    IF v_existing.request_fingerprint <> v_fingerprint THEN
      RAISE EXCEPTION 'PRODUCT_COST_CORRECTION_KEY_CONFLICT: استُخدم مفتاح العملية لتصحيح مختلف.';
    END IF;
    RETURN jsonb_build_object(
      'success', true,
      'idempotentReplay', true,
      'correctionId', v_existing.id,
      'productId', v_existing.product_id,
      'priorExactInMinorUnits', v_existing.prior_exact_in_minor_units::TEXT,
      'priorCostPriceInMinorUnits', v_existing.prior_cost_price_in_minor_units,
      'newExactInMinorUnits', v_existing.new_exact_in_minor_units::TEXT,
      'newCostPriceInMinorUnits', v_existing.new_cost_price_in_minor_units,
      'updatedAt', (SELECT product.updated_at FROM public.products product WHERE product.id = v_existing.product_id)
    );
  END IF;

  SELECT * INTO v_product
  FROM public.products product
  WHERE product.id = p_product_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'المنتج المحدد غير موجود.';
  END IF;
  IF v_product.is_flavor_master THEN
    RAISE EXCEPTION 'PRODUCT_COST_CORRECTION_FLAVOR_MASTER: المنتج الأساسي للنكهات بلا مخزون؛ صحّح تكلفة النكهة نفسها.';
  END IF;

  UPDATE public.products
  SET
    wac_cost_in_minor_units_exact = v_exact,
    cost_price_in_minor_units = v_legacy,
    updated_at = NOW()
  WHERE id = p_product_id;

  INSERT INTO public.product_cost_corrections (
    product_id, idempotency_key, request_fingerprint,
    prior_exact_in_minor_units, prior_cost_price_in_minor_units,
    new_exact_in_minor_units, new_cost_price_in_minor_units,
    reason, created_by
  ) VALUES (
    p_product_id, v_key, v_fingerprint,
    v_product.wac_cost_in_minor_units_exact, v_product.cost_price_in_minor_units,
    v_exact, v_legacy,
    v_reason, auth.uid()
  ) RETURNING id INTO v_correction_id;

  INSERT INTO public.audit_logs (user_id, action, entity_name, entity_id, details)
  VALUES (
    auth.uid(),
    'CORRECT_PRODUCT_COST',
    'products',
    p_product_id,
    jsonb_build_object(
      'correction_id', v_correction_id,
      'reason', v_reason,
      'prior_exact_in_minor_units', v_product.wac_cost_in_minor_units_exact,
      'prior_cost_price_in_minor_units', v_product.cost_price_in_minor_units,
      'new_exact_in_minor_units', v_exact,
      'new_cost_price_in_minor_units', v_legacy
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'idempotentReplay', false,
    'correctionId', v_correction_id,
    'productId', p_product_id,
    'priorExactInMinorUnits', v_product.wac_cost_in_minor_units_exact::TEXT,
    'priorCostPriceInMinorUnits', v_product.cost_price_in_minor_units,
    'newExactInMinorUnits', v_exact::TEXT,
    'newCostPriceInMinorUnits', v_legacy,
    'updatedAt', (SELECT product.updated_at FROM public.products product WHERE product.id = p_product_id)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.create_direct_supplier_receipt_v2(p_supplier_id uuid, p_warehouse_id uuid, p_branch_id uuid DEFAULT NULL::uuid, p_supplier_invoice_number text DEFAULT NULL::text, p_supplier_invoice_date date DEFAULT NULL::date, p_received_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_header_discount_in_minor_units bigint DEFAULT 0, p_supplier_freight_in_minor_units bigint DEFAULT 0, p_legacy_tax_in_minor_units bigint DEFAULT 0, p_amount_paid_at_receipt_in_minor_units bigint DEFAULT 0, p_payment_method text DEFAULT 'cash'::text, p_payment_reference text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_internal_notes text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text, p_lines jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_key TEXT := NULLIF(BTRIM(p_idempotency_key), '');
  v_invoice_number TEXT := NULLIF(BTRIM(p_supplier_invoice_number), '');
  v_normalized_invoice TEXT := LOWER(NULLIF(BTRIM(p_supplier_invoice_number), ''));
  v_payment_method TEXT := LOWER(COALESCE(NULLIF(BTRIM(p_payment_method), ''), 'cash'));
  v_payment_reference TEXT := NULLIF(BTRIM(p_payment_reference), '');
  v_canonical_lines JSONB;
  v_canonical_request JSONB;
  v_fingerprint TEXT;
  v_legacy_key UUID;
  v_existing_operation public.business_operations%ROWTYPE;
  v_operation_id UUID := gen_random_uuid();
  v_receipt_id UUID := gen_random_uuid();
  v_receipt_number TEXT;
  v_result JSONB;
  v_line_weights JSONB;
  v_header_allocations JSONB;
  v_freight_allocations JSONB;
  v_component_weights JSONB;
  v_component_merchandise_allocations JSONB;
  v_component_final_allocations JSONB;
  v_inventory_components JSONB := '[]'::JSONB;
  v_wac_results JSONB;
  v_line JSONB;
  v_component JSONB;
  v_line_id UUID;
  v_item_id UUID;
  v_line_sequence INTEGER := 0;
  v_line_kind TEXT;
  v_client_line_id UUID;
  v_commercial_quantity INTEGER;
  v_units_per_parcel INTEGER;
  v_base_quantity INTEGER;
  v_product_id UUID;
  v_gross BIGINT;
  v_line_discount BIGINT;
  v_line_net BIGINT;
  v_line_header_discount BIGINT;
  v_line_freight BIGINT;
  v_line_acquisition BIGINT;
  v_component_merchandise BIGINT;
  v_component_acquisition BIGINT;
  v_merchandise_gross NUMERIC := 0;
  v_line_discount_total NUMERIC := 0;
  v_line_net_total NUMERIC := 0;
  v_acquisition_total NUMERIC;
  v_invoice_payable NUMERIC;
  v_outstanding NUMERIC;
  v_product public.products%ROWTYPE;
  v_purchase_unit_name TEXT;
  v_base_unit_name TEXT;
BEGIN
  PERFORM public.assert_erp_role(
    ARRAY['owner', 'admin', 'manager', 'warehouse_keeper'],
    'استلام بضاعة الموردين - نموذج الطرود'
  );

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'PHASE2_AUTH_REQUIRED: يجب تسجيل الدخول.';
  END IF;
  IF v_key IS NULL OR CHAR_LENGTH(v_key) NOT BETWEEN 16 AND 255 THEN
    RAISE EXCEPTION USING ERRCODE = '22023',
      MESSAGE = 'PHASE2_IDEMPOTENCY_KEY_INVALID: مفتاح منع التكرار غير صالح.';
  END IF;
  v_legacy_key := public.phase2_try_parse_uuid_internal(v_key);
  IF v_legacy_key IS NOT NULL THEN
    v_key := v_legacy_key::TEXT;
  END IF;
  IF p_header_discount_in_minor_units < 0
    OR p_supplier_freight_in_minor_units < 0
    OR p_legacy_tax_in_minor_units < 0
    OR p_amount_paid_at_receipt_in_minor_units < 0
  THEN
    RAISE EXCEPTION USING ERRCODE = '22023',
      MESSAGE = 'PHASE2_FINANCIAL_VALUE_INVALID: القيم المالية لا يمكن أن تكون سالبة.';
  END IF;
  IF v_payment_method NOT IN ('cash', 'cliq', 'bank_transfer', 'deferred') THEN
    RAISE EXCEPTION USING ERRCODE = '22023',
      MESSAGE = 'PHASE2_PAYMENT_METHOD_INVALID: طريقة الدفع غير مدعومة.';
  END IF;
  IF v_payment_method = 'deferred'
    AND p_amount_paid_at_receipt_in_minor_units > 0
  THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      CONSTRAINT = 'phase2_deferred_payment_zero_check',
      MESSAGE = 'PHASE2_DEFERRED_PAYMENT_INVALID: الاستلام الآجل لا يقبل دفعة فورية.';
  END IF;
  IF v_payment_method IN ('cliq', 'bank_transfer')
    AND p_amount_paid_at_receipt_in_minor_units > 0
    AND v_payment_reference IS NULL
  THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      CONSTRAINT = 'phase2_payment_reference_required_check',
      MESSAGE = 'PHASE2_PAYMENT_REFERENCE_REQUIRED: مرجع الدفعة الإلكترونية مطلوب.';
  END IF;
  v_canonical_lines := public.phase2_canonicalize_receipt_lines_internal(p_lines);

  v_canonical_request := jsonb_build_object(
    'contract_version', 2,
    'operation_type', 'supplier_receipt_v2',
    'supplier_id', LOWER(p_supplier_id::TEXT),
    'warehouse_id', LOWER(p_warehouse_id::TEXT),
    'branch_id', CASE WHEN p_branch_id IS NULL THEN NULL ELSE LOWER(p_branch_id::TEXT) END,
    'supplier_invoice_number', v_normalized_invoice,
    'supplier_invoice_date', p_supplier_invoice_date,
    'received_at', CASE WHEN p_received_at IS NULL THEN NULL ELSE TO_CHAR(p_received_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"') END,
    'header_discount_in_minor_units', p_header_discount_in_minor_units,
    'supplier_freight_in_minor_units', p_supplier_freight_in_minor_units,
    'legacy_tax_in_minor_units', p_legacy_tax_in_minor_units,
    'amount_paid_at_receipt_in_minor_units', p_amount_paid_at_receipt_in_minor_units,
    'payment_method', v_payment_method,
    'payment_reference', v_payment_reference,
    'notes', NULLIF(BTRIM(p_notes), ''),
    'internal_notes', NULLIF(BTRIM(p_internal_notes), ''),
    'lines', v_canonical_lines
  );
  v_fingerprint := public.phase2_request_fingerprint_internal(v_canonical_request);

  -- Legacy and V2 direct receipts share one normalized key lock. A historical
  -- legacy UUID has no trustworthy Phase-2 fingerprint, so V2 fails closed.
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'supplier_receipt:' || v_key,
    0
  ));

  IF v_legacy_key IS NOT NULL THEN
    IF EXISTS (
      SELECT 1
      FROM public.supplier_receipts receipt
      WHERE receipt.idempotency_key = v_legacy_key
    ) THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001',
        MESSAGE = 'LEGACY_IDEMPOTENCY_IDENTITY_UNPROVEN: لا يمكن إثبات تطابق العملية التاريخية.';
    END IF;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.business_operations operation
    WHERE operation.operation_type = 'supplier_receipt_v2'
      AND operation.idempotency_key = v_key
      AND operation.initiated_by IS DISTINCT FROM v_user_id
  ) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'IDEMPOTENCY_CONFLICT: مفتاح الاستلام غير متاح لهذا المستخدم.';
  END IF;

  SELECT * INTO v_existing_operation
  FROM public.business_operations operation
  WHERE operation.operation_type = 'supplier_receipt_v2'
    AND operation.initiated_by = v_user_id
    AND operation.idempotency_key = v_key;

  IF FOUND THEN
    IF v_existing_operation.request_fingerprint IS NULL
      OR v_existing_operation.result_snapshot IS NULL
    THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001',
        MESSAGE = 'LEGACY_IDEMPOTENCY_IDENTITY_UNPROVEN: لا يمكن إثبات تطابق العملية التاريخية.';
    END IF;
    IF v_existing_operation.request_fingerprint IS DISTINCT FROM v_fingerprint THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001',
        MESSAGE = 'IDEMPOTENCY_CONFLICT: استُخدم المفتاح نفسه لطلب مختلف.';
    END IF;
    RETURN v_existing_operation.result_snapshot;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.suppliers supplier
    WHERE supplier.id = p_supplier_id AND supplier.is_active
  ) THEN
    RAISE EXCEPTION 'PHASE2_SUPPLIER_INVALID: المورد غير موجود أو غير نشط.';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.warehouses warehouse
    WHERE warehouse.id = p_warehouse_id AND warehouse.is_active
  ) THEN
    RAISE EXCEPTION 'PHASE2_WAREHOUSE_INVALID: المستودع غير موجود أو غير نشط.';
  END IF;
  IF p_branch_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.branches branch
    WHERE branch.id = p_branch_id AND branch.is_active
  ) THEN
    RAISE EXCEPTION 'PHASE2_BRANCH_INVALID: الفرع غير موجود أو غير نشط.';
  END IF;

  PERFORM public.phase2_lock_payment_shift_internal(
    p_branch_id, v_payment_method, p_amount_paid_at_receipt_in_minor_units
  );
  PERFORM public.phase2_lock_inventory_products_internal(ARRAY(
    SELECT DISTINCT (component->>'product_id')::UUID
    FROM jsonb_array_elements(v_canonical_lines) line
    CROSS JOIN LATERAL jsonb_array_elements(line->'components') component
    ORDER BY (component->>'product_id')::UUID
  ));
  PERFORM public.phase2_validate_receipt_lines_internal(v_canonical_lines);

  SELECT
    COALESCE(SUM((line->>'gross_amount_in_minor_units')::NUMERIC), 0),
    COALESCE(SUM((line->>'line_discount_in_minor_units')::NUMERIC), 0)
  INTO v_merchandise_gross, v_line_discount_total
  FROM jsonb_array_elements(v_canonical_lines) line;
  v_line_net_total := v_merchandise_gross - v_line_discount_total;

  IF v_merchandise_gross > 9223372036854775807::NUMERIC
    OR v_line_discount_total > 9223372036854775807::NUMERIC
    OR v_line_net_total > 9223372036854775807::NUMERIC
  THEN
    RAISE EXCEPTION USING ERRCODE = '22003',
      MESSAGE = 'PHASE2_MONEY_OVERFLOW: إجمالي الفاتورة يتجاوز الحد المدعوم.';
  END IF;
  IF p_header_discount_in_minor_units > v_line_net_total THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      CONSTRAINT = 'phase2_header_discount_total_check',
      MESSAGE = 'PHASE2_HEADER_DISCOUNT_EXCEEDS_NET: خصم رأس الفاتورة يتجاوز صافي البضاعة.';
  END IF;
  IF v_line_net_total = 0
    AND (p_header_discount_in_minor_units > 0 OR p_supplier_freight_in_minor_units > 0)
  THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      CONSTRAINT = 'phase2_zero_allocation_basis_check',
      MESSAGE = 'PHASE2_ZERO_ALLOCATION_BASIS: لا يمكن توزيع خصم أو شحن على أساس صفري.';
  END IF;

  v_acquisition_total := v_line_net_total
    - p_header_discount_in_minor_units::NUMERIC
    + p_supplier_freight_in_minor_units::NUMERIC;
  v_invoice_payable := v_acquisition_total + p_legacy_tax_in_minor_units::NUMERIC;
  IF v_acquisition_total > 9223372036854775807::NUMERIC
    OR v_invoice_payable > 9223372036854775807::NUMERIC
  THEN
    RAISE EXCEPTION USING ERRCODE = '22003',
      MESSAGE = 'PHASE2_MONEY_OVERFLOW: تكلفة الاستحواذ أو إجمالي الفاتورة يتجاوز الحد المدعوم.';
  END IF;
  IF p_amount_paid_at_receipt_in_minor_units::NUMERIC > v_invoice_payable THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      CONSTRAINT = 'phase2_payment_upper_bound_check',
      MESSAGE = 'PHASE2_PAYMENT_EXCEEDS_PAYABLE: الدفعة تتجاوز إجمالي فاتورة المورد.';
  END IF;
  v_outstanding := v_invoice_payable - p_amount_paid_at_receipt_in_minor_units::NUMERIC;

  IF v_normalized_invoice IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(hashtextextended(
      'supplier_invoice:' || p_supplier_id::TEXT || ':' || v_normalized_invoice,
      0
    ));
    IF EXISTS (
      SELECT 1 FROM public.supplier_financial_invoice_identities identity
      WHERE identity.supplier_id = p_supplier_id
        AND identity.normalized_invoice_number = v_normalized_invoice
        AND identity.is_active
    ) OR EXISTS (
      SELECT 1 FROM public.supplier_receipts receipt
      WHERE receipt.supplier_id = p_supplier_id
        AND LOWER(BTRIM(receipt.supplier_invoice_number)) = v_normalized_invoice
        AND receipt.status <> 'cancelled'
    ) OR EXISTS (
      SELECT 1 FROM public.purchase_receipts receipt
      WHERE receipt.supplier_id = p_supplier_id
        AND LOWER(BTRIM(receipt.supplier_invoice_number)) = v_normalized_invoice
        AND receipt.status <> 'cancelled'
    ) THEN
      RAISE EXCEPTION USING ERRCODE = '23505',
        CONSTRAINT = 'uq_supplier_financial_invoice_active',
        MESSAGE = 'DUPLICATE_SUPPLIER_INVOICE: رقم فاتورة المورد مستخدم في سند مالي نشط.';
    END IF;
  END IF;

  v_receipt_number := 'GRN-' || TO_CHAR(NOW(), 'YYYY') || '-'
    || LPAD(NEXTVAL('public.supplier_receipt_seq')::TEXT, 6, '0');
  v_result := jsonb_build_object(
    'success', true,
    'idempotent', false,
    'operation_id', v_operation_id,
    'receipt_id', v_receipt_id,
    'receipt_number', v_receipt_number,
    'inventory_acquisition_cost_in_minor_units', v_acquisition_total::BIGINT,
    'supplier_invoice_payable_total_in_minor_units', v_invoice_payable::BIGINT,
    'supplier_outstanding_balance_effect_in_minor_units', v_outstanding::BIGINT
  );

  INSERT INTO public.business_operations (
    id, operation_type, idempotency_key, request_fingerprint,
    initiated_by, result_snapshot, completed_at
  ) VALUES (
    v_operation_id, 'supplier_receipt_v2', v_key, v_fingerprint,
    v_user_id, v_result, NOW()
  );

  INSERT INTO public.supplier_receipts (
    id, receipt_number, supplier_id, warehouse_id, branch_id,
    supplier_invoice_number, supplier_invoice_date, received_at, received_by,
    subtotal_in_minor_units, discount_in_minor_units,
    delivery_fee_in_minor_units, tax_in_minor_units, total_in_minor_units,
    amount_paid_in_minor_units, amount_due_in_minor_units, payment_status,
    payment_method, payment_reference, notes, internal_notes, status,
    idempotency_key, operation_id, phase2_finalized_at,
    merchandise_gross_snapshot_in_minor_units,
    line_discount_total_snapshot_in_minor_units,
    header_discount_snapshot_in_minor_units,
    supplier_freight_snapshot_in_minor_units,
    legacy_tax_snapshot_in_minor_units,
    inventory_acquisition_cost_snapshot_in_minor_units,
    supplier_invoice_payable_total_snapshot_in_minor_units,
    amount_paid_at_receipt_snapshot_in_minor_units,
    supplier_outstanding_balance_effect_snapshot_in_minor_units
  ) VALUES (
    v_receipt_id, v_receipt_number, p_supplier_id, p_warehouse_id, p_branch_id,
    v_invoice_number, p_supplier_invoice_date, COALESCE(p_received_at, NOW()), v_user_id,
    v_line_net_total::BIGINT, p_header_discount_in_minor_units,
    p_supplier_freight_in_minor_units, p_legacy_tax_in_minor_units,
    v_invoice_payable::BIGINT, p_amount_paid_at_receipt_in_minor_units,
    v_outstanding::BIGINT,
    CASE WHEN v_outstanding = 0 THEN 'paid'
      WHEN p_amount_paid_at_receipt_in_minor_units > 0 THEN 'partially_paid'
      ELSE 'unpaid' END,
    v_payment_method, v_payment_reference,
    NULLIF(BTRIM(p_notes), ''), NULLIF(BTRIM(p_internal_notes), ''),
    'completed', NULL, v_operation_id, NOW(),
    v_merchandise_gross::BIGINT, v_line_discount_total::BIGINT,
    p_header_discount_in_minor_units, p_supplier_freight_in_minor_units,
    p_legacy_tax_in_minor_units, v_acquisition_total::BIGINT,
    v_invoice_payable::BIGINT, p_amount_paid_at_receipt_in_minor_units,
    v_outstanding::BIGINT
  );

  IF v_normalized_invoice IS NOT NULL THEN
    INSERT INTO public.supplier_financial_invoice_identities (
      supplier_id, normalized_invoice_number, operation_id, supplier_receipt_id
    ) VALUES (
      p_supplier_id, v_normalized_invoice, v_operation_id, v_receipt_id
    );
  END IF;

  SELECT jsonb_agg(jsonb_build_object(
    'key', line->>'client_line_id',
    'weight', (
      (line->>'gross_amount_in_minor_units')::BIGINT
      - (line->>'line_discount_in_minor_units')::BIGINT
    )
  )) INTO v_line_weights
  FROM jsonb_array_elements(v_canonical_lines) line;

  SELECT COALESCE(jsonb_object_agg(allocation_key, allocated_amount), '{}'::JSONB)
  INTO v_header_allocations
  FROM public.phase2_allocate_largest_remainder_internal(
    p_header_discount_in_minor_units, v_line_weights
  );
  SELECT COALESCE(jsonb_object_agg(allocation_key, allocated_amount), '{}'::JSONB)
  INTO v_freight_allocations
  FROM public.phase2_allocate_largest_remainder_internal(
    p_supplier_freight_in_minor_units, v_line_weights
  );

  FOR v_line IN SELECT * FROM jsonb_array_elements(v_canonical_lines)
  LOOP
    v_line_sequence := v_line_sequence + 1;
    v_line_id := gen_random_uuid();
    v_client_line_id := (v_line->>'client_line_id')::UUID;
    v_line_kind := v_line->>'line_kind';
    v_commercial_quantity := (v_line->>'commercial_quantity')::INTEGER;
    v_units_per_parcel := NULLIF(v_line->>'units_per_parcel', '')::INTEGER;
    v_gross := (v_line->>'gross_amount_in_minor_units')::BIGINT;
    v_line_discount := (v_line->>'line_discount_in_minor_units')::BIGINT;
    v_line_net := v_gross - v_line_discount;
    v_line_header_discount := COALESCE(
      (v_header_allocations->>v_client_line_id::TEXT)::BIGINT, 0
    );
    v_line_freight := COALESCE(
      (v_freight_allocations->>v_client_line_id::TEXT)::BIGINT, 0
    );
    v_line_acquisition := v_line_net - v_line_header_discount + v_line_freight;

    INSERT INTO public.supplier_receipt_commercial_lines (
      id, supplier_receipt_id, operation_id, line_sequence,
      commercial_line_kind, family_product_id, parcel_configuration_id,
      configuration_revision, commercial_quantity, units_per_parcel_snapshot,
      base_unit_name_snapshot, parcel_unit_name_snapshot,
      gross_amount_snapshot_in_minor_units, discount_snapshot_in_minor_units,
      line_total_snapshot_in_minor_units, client_line_id,
      received_parcel_quantity, received_base_unit_quantity,
      allocated_header_discount_in_minor_units,
      allocated_supplier_freight_in_minor_units,
      final_acquisition_amount_in_minor_units, finalized_at
    ) VALUES (
      v_line_id, v_receipt_id, v_operation_id, v_line_sequence,
      v_line_kind,
      NULLIF(v_line->>'family_product_id', '')::UUID,
      NULLIF(v_line->>'parcel_configuration_id', '')::UUID,
      NULLIF(v_line->>'configuration_revision', '')::INTEGER,
      v_commercial_quantity, v_units_per_parcel,
      v_line->>'base_unit_name', NULLIF(v_line->>'parcel_unit_name', ''),
      v_gross, v_line_discount, v_line_net, v_client_line_id,
      CASE WHEN v_line_kind = 'configurable_parcel' THEN v_commercial_quantity END,
      (SELECT SUM((component->>'base_quantity')::INTEGER)
       FROM jsonb_array_elements(v_line->'components') component),
      v_line_header_discount, v_line_freight, v_line_acquisition, NOW()
    );

    SELECT jsonb_agg(jsonb_build_object(
      'key', component->>'product_id',
      'weight', CASE
        WHEN component->>'explicit_merchandise_cost_in_minor_units' IS NULL
          THEN (component->>'base_quantity')::BIGINT
        ELSE (component->>'explicit_merchandise_cost_in_minor_units')::BIGINT
      END
    )) INTO v_component_weights
    FROM jsonb_array_elements(v_line->'components') component;

    SELECT COALESCE(jsonb_object_agg(allocation_key, allocated_amount), '{}'::JSONB)
    INTO v_component_merchandise_allocations
    FROM public.phase2_allocate_largest_remainder_internal(
      v_line_net, v_component_weights
    );
    SELECT COALESCE(jsonb_object_agg(allocation_key, allocated_amount), '{}'::JSONB)
    INTO v_component_final_allocations
    FROM public.phase2_allocate_largest_remainder_internal(
      v_line_acquisition, v_component_weights
    );

    FOR v_component IN SELECT * FROM jsonb_array_elements(v_line->'components')
    LOOP
      v_item_id := gen_random_uuid();
      v_product_id := (v_component->>'product_id')::UUID;
      v_base_quantity := (v_component->>'base_quantity')::INTEGER;
      v_component_merchandise :=
        (v_component_merchandise_allocations->>v_product_id::TEXT)::BIGINT;
      v_component_acquisition :=
        (v_component_final_allocations->>v_product_id::TEXT)::BIGINT;

      SELECT * INTO v_product FROM public.products WHERE id = v_product_id;
      SELECT unit.name_ar INTO v_purchase_unit_name
      FROM public.units unit WHERE unit.id = v_product.purchase_unit_id;
      SELECT unit.name_ar INTO v_base_unit_name
      FROM public.units unit WHERE unit.id = v_product.unit_id;

      INSERT INTO public.supplier_receipt_items (
        id, supplier_receipt_id, product_id, purchase_unit_id, base_unit_id,
        purchase_unit_name, base_unit_name, package_quantity,
        units_per_package, total_base_units, package_price_in_minor_units,
        base_unit_cost_in_minor_units, discount_in_minor_units,
        line_total_in_minor_units, batch_number, production_date, expiry_date,
        notes, selling_price_in_minor_units, commercial_line_id, operation_id,
        merchandise_net_cost_in_minor_units, allocated_cost_in_minor_units,
        exact_unit_cost_in_minor_units
      ) VALUES (
        v_item_id, v_receipt_id, v_product_id,
        v_product.purchase_unit_id, v_product.unit_id,
        COALESCE(v_purchase_unit_name, v_line->>'base_unit_name'),
        COALESCE(v_base_unit_name, v_line->>'base_unit_name'),
        v_base_quantity, 1, v_base_quantity,
        ROUND(v_component_merchandise::NUMERIC / v_base_quantity)::BIGINT,
        ROUND(v_component_acquisition::NUMERIC / v_base_quantity)::BIGINT,
        0, v_component_merchandise,
        NULLIF(v_component->>'batch_number', ''),
        NULLIF(v_component->>'production_date', '')::DATE,
        NULLIF(v_component->>'expiry_date', '')::DATE,
        NULLIF(v_component->>'notes', ''),
        0, v_line_id, v_operation_id,
        v_component_merchandise, v_component_acquisition,
        ROUND(v_component_acquisition::NUMERIC / v_base_quantity, 6)
      );

      v_inventory_components := v_inventory_components || jsonb_build_array(
        jsonb_build_object(
          'item_id', v_item_id,
          'client_line_id', v_client_line_id,
          'product_id', v_product_id,
          'base_quantity', v_base_quantity,
          'allocated_cost_in_minor_units', v_component_acquisition
        )
      );
    END LOOP;
  END LOOP;

  v_wac_results := public.phase2_apply_inventory_and_wac_internal(
    v_operation_id,
    p_warehouse_id,
    'supplier_receipt',
    v_receipt_id,
    v_inventory_components,
    v_user_id,
    'استلام مورد Phase 2 - ' || v_receipt_number
  );

  UPDATE public.suppliers
  SET current_balance_in_minor_units =
      current_balance_in_minor_units + v_outstanding::BIGINT,
    updated_at = NOW()
  WHERE id = p_supplier_id;

  IF p_amount_paid_at_receipt_in_minor_units > 0 THEN
    INSERT INTO public.supplier_payments (
      supplier_id, supplier_receipt_id, amount_in_minor_units,
      payment_method, reference_number, payment_date, notes,
      created_by, operation_id
    ) VALUES (
      p_supplier_id, v_receipt_id, p_amount_paid_at_receipt_in_minor_units,
      v_payment_method, v_payment_reference, COALESCE(p_received_at, NOW()),
      'دفعة عند استلام السند ' || v_receipt_number,
      v_user_id, v_operation_id
    );
  END IF;

  INSERT INTO public.audit_logs (
    user_id, action, entity_name, entity_id, details
  ) VALUES (
    v_user_id,
    'CREATE_DIRECT_SUPPLIER_RECEIPT_V2',
    'supplier_receipts',
    v_receipt_id,
    jsonb_build_object(
      'operation_id', v_operation_id,
      'receipt_number', v_receipt_number,
      'inventory_acquisition_cost_in_minor_units', v_acquisition_total::BIGINT,
      'supplier_invoice_payable_total_in_minor_units', v_invoice_payable::BIGINT,
      'supplier_outstanding_balance_effect_in_minor_units', v_outstanding::BIGINT,
      'wac', v_wac_results
    )
  );

  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_erp_staff_account_record(p_user_id uuid, p_full_name text, p_phone text DEFAULT NULL::text, p_role_code text DEFAULT 'cashier'::text, p_branch_id uuid DEFAULT NULL::uuid, p_job_title text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_full_name TEXT := NULLIF(BTRIM(p_full_name), '');
  v_phone TEXT := NULLIF(BTRIM(p_phone), '');
  v_role_code TEXT := LOWER(NULLIF(BTRIM(p_role_code), ''));
  v_job_title TEXT := NULLIF(BTRIM(p_job_title), '');
  v_role_id UUID;
BEGIN
  PERFORM public.assert_erp_role(ARRAY['owner'], 'إضافة حساب موظف أو مالك نظام');

  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'معرّف حساب المستخدم مطلوب.';
  END IF;
  IF v_full_name IS NULL OR CHAR_LENGTH(v_full_name) < 2 OR CHAR_LENGTH(v_full_name) > 120 THEN
    RAISE EXCEPTION 'اسم المستخدم يجب أن يكون بين حرفين و120 حرفًا.';
  END IF;
  IF v_phone IS NOT NULL AND v_phone !~ '^[0-9+() -]{7,24}$' THEN
    RAISE EXCEPTION 'رقم الهاتف غير صالح.';
  END IF;

  SELECT id INTO v_role_id FROM public.roles WHERE code = v_role_code;
  IF v_role_id IS NULL THEN
    RAISE EXCEPTION 'الدور المحدد غير معتمد.';
  END IF;
  IF p_branch_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.branches WHERE id = p_branch_id AND is_active = true
  ) THEN
    RAISE EXCEPTION 'الفرع المحدد غير موجود أو غير فعّال.';
  END IF;
  IF EXISTS (SELECT 1 FROM public.profiles WHERE id = p_user_id) THEN
    RAISE EXCEPTION 'هذا الحساب مرتبط بمستخدم بالفعل.';
  END IF;

  INSERT INTO public.profiles (id, full_name, phone, job_title, branch_id, is_active)
  VALUES (p_user_id, v_full_name, v_phone, v_job_title, p_branch_id, true);
  INSERT INTO public.user_roles (user_id, role_id) VALUES (p_user_id, v_role_id);

  INSERT INTO public.audit_logs (user_id, action, entity_name, entity_id, details)
  VALUES (
    auth.uid(),
    CASE WHEN v_role_code = 'owner' THEN 'إنشاء مالك نظام إضافي' ELSE 'إنشاء حساب موظف' END,
    'staff_account', p_user_id,
    jsonb_build_object('full_name', v_full_name, 'role_code', v_role_code, 'branch_id', p_branch_id, 'has_phone', v_phone IS NOT NULL)
  );

  RETURN jsonb_build_object('success', true, 'userId', p_user_id,
    'message', CASE WHEN v_role_code = 'owner' THEN 'تم إنشاء مالك النظام الإضافي.' ELSE 'تم إنشاء حساب الموظف وتعيين صلاحياته.' END);
END;
$function$

CREATE OR REPLACE FUNCTION public.create_operational_expense(p_branch_id uuid, p_category text, p_description text, p_amount_in_minor_units bigint, p_payment_method text, p_reference_number text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_shift_id UUID;
  v_expense_id UUID;
  v_expense_number TEXT;
BEGIN
  PERFORM public.assert_erp_role(
    ARRAY['owner', 'admin', 'manager', 'accountant'],
    'تسجيل مصروف تشغيلي'
  );
  IF CHAR_LENGTH(TRIM(COALESCE(p_category, ''))) NOT BETWEEN 2 AND 80 THEN
    RAISE EXCEPTION 'فئة المصروف غير صحيحة.';
  END IF;
  IF CHAR_LENGTH(TRIM(COALESCE(p_description, ''))) NOT BETWEEN 2 AND 500 THEN
    RAISE EXCEPTION 'وصف المصروف يجب أن يكون واضحًا.';
  END IF;
  IF COALESCE(p_amount_in_minor_units, 0) <= 0 THEN
    RAISE EXCEPTION 'قيمة المصروف يجب أن تكون أكبر من صفر.';
  END IF;
  IF p_payment_method NOT IN ('cash', 'cliq') THEN
    RAISE EXCEPTION 'طريقة دفع المصروف يجب أن تكون كاش أو CliQ.';
  END IF;
  IF p_payment_method = 'cliq' AND NULLIF(TRIM(p_reference_number), '') IS NULL THEN
    RAISE EXCEPTION 'رقم مرجع CliQ مطلوب للمصروف الإلكتروني.';
  END IF;

  SELECT id INTO v_shift_id
  FROM public.cash_shifts
  WHERE branch_id = p_branch_id AND status = 'open'
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'افتح وردية الصندوق أولًا قبل تسجيل المصروف.';
  END IF;

  v_expense_number := 'EXP-' || TO_CHAR(NOW(), 'YYYYMMDD') || '-' || LPAD(NEXTVAL('public.operational_expense_number_seq')::TEXT, 6, '0');
  INSERT INTO public.operational_expenses (
    expense_number, branch_id, shift_id, category, description,
    amount_in_minor_units, payment_method, reference_number, created_by
  ) VALUES (
    v_expense_number, p_branch_id, v_shift_id, TRIM(p_category),
    TRIM(p_description), p_amount_in_minor_units, p_payment_method,
    NULLIF(TRIM(p_reference_number), ''), v_user_id
  ) RETURNING id INTO v_expense_id;

  INSERT INTO public.audit_logs (user_id, action, entity_name, entity_id, details)
  VALUES (v_user_id, 'CREATE_OPERATIONAL_EXPENSE', 'operational_expenses', v_expense_id,
    jsonb_build_object('expense_number', v_expense_number, 'shift_id', v_shift_id,
      'amount_in_minor_units', p_amount_in_minor_units, 'payment_method', p_payment_method));

  RETURN jsonb_build_object(
    'success', true,
    'expenseId', v_expense_id,
    'expenseNumber', v_expense_number,
    'shift', public.get_cash_shift_summary(v_shift_id),
    'message', 'تم تسجيل المصروف وربطه بالوردية بنجاح.'
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.create_owner_cash_withdrawal_v1(p_shift_id uuid, p_amount_in_minor_units bigint, p_reason text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_key TEXT := BTRIM(COALESCE(p_idempotency_key, ''));
  v_reason TEXT := NULLIF(BTRIM(COALESCE(p_reason, '')), '');
  v_fingerprint TEXT;
  v_existing public.owner_cash_withdrawals%ROWTYPE;
  v_shift public.cash_shifts%ROWTYPE;
  v_expected BIGINT;
  v_id UUID;
BEGIN
  PERFORM public.assert_erp_role(ARRAY['owner'], 'سحب المالك من الدرج');
  IF char_length(v_key) NOT BETWEEN 16 AND 200 THEN
    RAISE EXCEPTION 'OWNER_WITHDRAWAL_KEY_INVALID: مفتاح العملية غير صالح.';
  END IF;
  IF p_shift_id IS NULL THEN
    RAISE EXCEPTION 'OWNER_WITHDRAWAL_SHIFT_REQUIRED: اختر الوردية المفتوحة.';
  END IF;
  IF p_amount_in_minor_units IS NULL OR p_amount_in_minor_units <= 0 THEN
    RAISE EXCEPTION 'OWNER_WITHDRAWAL_AMOUNT_INVALID: مبلغ السحب يجب أن يكون أكبر من صفر.';
  END IF;
  IF v_reason IS NOT NULL AND char_length(v_reason) > 500 THEN
    RAISE EXCEPTION 'OWNER_WITHDRAWAL_REASON_TOO_LONG: السبب أطول من 500 حرف.';
  END IF;
  v_fingerprint := md5(p_shift_id::TEXT || '|' || p_amount_in_minor_units::TEXT || '|' || COALESCE(v_reason, ''));

  -- Same request replays its stored result without writing, even after close.
  SELECT * INTO v_existing FROM public.owner_cash_withdrawals
  WHERE created_by = v_user_id AND idempotency_key = v_key;
  IF FOUND THEN
    IF v_existing.request_fingerprint <> v_fingerprint THEN
      RAISE EXCEPTION 'OWNER_WITHDRAWAL_KEY_CONFLICT: استُخدم مفتاح العملية لطلب سحب مختلف.';
    END IF;
    RETURN public.owner_withdrawal_result_internal(v_existing.id, true);
  END IF;

  -- Lock order: full-shift reversal domain, then the shift row.
  PERFORM pg_advisory_xact_lock(hashtextextended('cash-shift-full-reversal:' || p_shift_id::TEXT, 0));
  SELECT * INTO v_shift FROM public.cash_shifts WHERE id = p_shift_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'OWNER_WITHDRAWAL_SHIFT_NOT_FOUND: الوردية المحددة غير موجودة.';
  END IF;
  IF v_shift.status <> 'open' THEN
    RAISE EXCEPTION 'OWNER_WITHDRAWAL_SHIFT_NOT_OPEN: السحب من وردية مفتوحة فقط.';
  END IF;
  -- Re-check after the lock: a concurrent double-click with the same key waits here.
  SELECT * INTO v_existing FROM public.owner_cash_withdrawals
  WHERE created_by = v_user_id AND idempotency_key = v_key;
  IF FOUND THEN
    IF v_existing.request_fingerprint <> v_fingerprint THEN
      RAISE EXCEPTION 'OWNER_WITHDRAWAL_KEY_CONFLICT: استُخدم مفتاح العملية لطلب سحب مختلف.';
    END IF;
    RETURN public.owner_withdrawal_result_internal(v_existing.id, true);
  END IF;

  v_expected := COALESCE((public.get_cash_shift_summary(p_shift_id)->>'expectedCashInMinorUnits')::BIGINT, 0);
  IF p_amount_in_minor_units > v_expected THEN
    RAISE EXCEPTION 'OWNER_WITHDRAWAL_EXCEEDS_DRAWER: بالدرج % فقط.',
      public.owner_withdrawal_format_jod_internal(GREATEST(v_expected, 0))
      USING DETAIL = jsonb_build_object('expectedCashInMinorUnits', v_expected)::TEXT;
  END IF;

  INSERT INTO public.owner_cash_withdrawals (
    withdrawal_number, branch_id, cash_shift_id, amount_in_minor_units, reason,
    created_by, idempotency_key, request_fingerprint
  ) VALUES (
    'OW-' || lpad(nextval('public.owner_cash_withdrawal_number_seq')::TEXT, 6, '0'),
    v_shift.branch_id, p_shift_id, p_amount_in_minor_units, v_reason,
    v_user_id, v_key, v_fingerprint
  ) RETURNING id INTO v_id;

  INSERT INTO public.audit_logs (user_id, action, entity_name, entity_id, details)
  VALUES (v_user_id, 'CREATE_OWNER_CASH_WITHDRAWAL', 'owner_cash_withdrawals', v_id,
    jsonb_build_object('shift_id', p_shift_id, 'branch_id', v_shift.branch_id,
      'amount_in_minor_units', p_amount_in_minor_units, 'reason', v_reason,
      'expected_cash_before_in_minor_units', v_expected,
      'expected_cash_after_in_minor_units', v_expected - p_amount_in_minor_units));

  RETURN public.owner_withdrawal_result_internal(v_id, false)
    || jsonb_build_object('shiftSummary', public.get_cash_shift_summary(p_shift_id));
END;
$function$

CREATE OR REPLACE FUNCTION public.create_pos_sale_v2(p_warehouse_id uuid, p_branch_id uuid, p_customer_id uuid, p_customer_name text, p_payment_method text, p_lines jsonb, p_discount_in_minor_units bigint DEFAULT 0, p_amount_received_in_minor_units bigint DEFAULT 0, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_key TEXT:=nullif(btrim(p_idempotency_key),'');
BEGIN
  PERFORM public.assert_erp_role(ARRAY['owner','admin','manager','sales'],'تنفيذ بيع الكاشير');
  IF v_key IS NULL OR length(v_key) NOT BETWEEN 16 AND 200 THEN
    RAISE EXCEPTION 'PHASE3_IDEMPOTENCY_INPUT_INVALID: Invalid POS key';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtext(v_key));
  IF EXISTS(SELECT 1 FROM public.pos_uncommitted_attempt_cancellations
    WHERE actor_id=auth.uid() AND idempotency_key=v_key) THEN
    RAISE EXCEPTION 'PACKAGE_D_POS_ATTEMPT_CANCELLED: هذه المحاولة ألغيت بعد إثبات عدم تسجيلها؛ ابدأ بيعاً جديداً';
  END IF;
  -- Historical committed replay still uses its exact original payment fact.
  IF NOT EXISTS(SELECT 1 FROM public.business_operations WHERE idempotency_key=v_key)
    AND (p_payment_method IS NULL OR lower(btrim(p_payment_method)) NOT IN ('cash','cliq','debt')) THEN
    RAISE EXCEPTION 'PHASE3_POS_PAYMENT_METHOD_INVALID: الكاشير يدعم كاش وCliQ ودين فقط';
  END IF;
  RETURN public.package_d_create_pos_sale_before_attempt_guard_internal(
    p_warehouse_id,p_branch_id,p_customer_id,p_customer_name,p_payment_method,p_lines,
    p_discount_in_minor_units,p_amount_received_in_minor_units,p_idempotency_key);
END;
$function$

CREATE OR REPLACE FUNCTION public.create_product_family_with_flavors_v1(p_sku text, p_barcode text DEFAULT NULL::text, p_name_ar text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_category_id uuid DEFAULT NULL::uuid, p_brand_id uuid DEFAULT NULL::uuid, p_unit_id uuid DEFAULT NULL::uuid, p_purchase_unit_id uuid DEFAULT NULL::uuid, p_units_per_purchase_unit integer DEFAULT 1, p_default_purchase_price_in_minor_units bigint DEFAULT 0, p_sale_unit_id uuid DEFAULT NULL::uuid, p_units_per_sale_unit integer DEFAULT 1, p_default_sale_price_in_minor_units bigint DEFAULT 0, p_cost_price_in_minor_units bigint DEFAULT 0, p_min_stock_level integer DEFAULT 0, p_max_stock_level integer DEFAULT NULL::integer, p_warehouse_id uuid DEFAULT NULL::uuid, p_image_url text DEFAULT NULL::text, p_flavors jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_master_result JSONB;
  v_master_id UUID;
  v_flavor JSONB;
  v_flavor_count INTEGER;
BEGIN
  PERFORM public.assert_erp_role(
    ARRAY['owner', 'admin', 'manager', 'warehouse_keeper'],
    'إنشاء منتج بنكهات'
  );

  IF jsonb_typeof(COALESCE(p_flavors, '[]'::JSONB)) <> 'array' THEN
    RAISE EXCEPTION 'قائمة النكهات غير صالحة.';
  END IF;

  v_flavor_count := jsonb_array_length(COALESCE(p_flavors, '[]'::JSONB));
  IF v_flavor_count < 1 THEN
    RAISE EXCEPTION 'أضف نكهة واحدة على الأقل.';
  END IF;
  IF v_flavor_count > 30 THEN
    RAISE EXCEPTION 'الحد الأعلى هو 30 نكهة للمنتج الواحد.';
  END IF;

  -- The family root never carries stock. Every real unit is created on its
  -- flavor row below, inside this same PostgreSQL transaction.
  v_master_result := public.create_product_with_opening_stock_v4(
    p_sku,
    p_barcode,
    p_name_ar,
    p_description,
    p_category_id,
    p_brand_id,
    p_unit_id,
    p_purchase_unit_id,
    p_units_per_purchase_unit,
    p_default_purchase_price_in_minor_units,
    p_sale_unit_id,
    p_units_per_sale_unit,
    p_default_sale_price_in_minor_units,
    p_cost_price_in_minor_units,
    p_min_stock_level,
    p_max_stock_level,
    p_warehouse_id,
    0,
    'بطاقة منتج أساسية لمجموعة نكهات',
    p_image_url
  );

  v_master_id := NULLIF(v_master_result->>'product_id', '')::UUID;
  IF v_master_id IS NULL THEN
    RAISE EXCEPTION 'تعذر إنشاء المنتج الأساسي لمجموعة النكهات.';
  END IF;

  FOR v_flavor IN
    SELECT value
    FROM jsonb_array_elements(p_flavors)
  LOOP
    PERFORM public.create_product_flavor_v1(
      v_master_id,
      v_flavor->>'nameAr',
      GREATEST(
        0,
        COALESCE((v_flavor->>'openingSalePackages')::INTEGER, 0)
      ),
      p_warehouse_id,
      NULLIF(BTRIM(v_flavor->>'imageUrl'), ''),
      NULL
    );
  END LOOP;

  INSERT INTO public.audit_logs (
    user_id,
    action,
    entity_name,
    entity_id,
    details
  ) VALUES (
    auth.uid(),
    'CREATE_PRODUCT_FLAVOR_FAMILY',
    'products',
    v_master_id,
    jsonb_build_object(
      'flavor_count', v_flavor_count,
      'atomic', true
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'productId', v_master_id,
    'flavorCount', v_flavor_count,
    'message', 'تم إنشاء المنتج وجميع نكهاته ومخزونها بنجاح.'
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.create_product_flavor_v1(p_master_product_id uuid, p_flavor_name_ar text, p_opening_sale_packages integer DEFAULT 0, p_warehouse_id uuid DEFAULT NULL::uuid, p_image_url text DEFAULT NULL::text, p_barcode text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_master public.products%ROWTYPE;
  v_warehouse_id UUID;
  v_result JSONB;
  v_flavor_id UUID;
  v_flavor_name TEXT;
  v_sku TEXT;
  v_master_stock BIGINT;
  v_sort_order INTEGER;
BEGIN
  PERFORM public.assert_erp_role(
    ARRAY['owner', 'admin', 'manager', 'warehouse_keeper'],
    'إضافة نكهة للمنتج'
  );

  v_flavor_name := NULLIF(BTRIM(p_flavor_name_ar), '');
  IF v_flavor_name IS NULL THEN
    RAISE EXCEPTION 'اكتب اسم النكهة.';
  END IF;
  IF COALESCE(p_opening_sale_packages, 0) < 0 THEN
    RAISE EXCEPTION 'كمية الافتتاح لا يمكن أن تكون سالبة.';
  END IF;

  SELECT * INTO v_master
  FROM public.products
  WHERE id = p_master_product_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'المنتج الأساسي غير موجود.';
  END IF;
  IF v_master.flavor_master_product_id IS NOT NULL THEN
    RAISE EXCEPTION 'اختر المنتج الأساسي وليس إحدى نكهاته.';
  END IF;
  IF NOT v_master.is_active THEN
    RAISE EXCEPTION 'فعّل المنتج الأساسي قبل إضافة النكهات.';
  END IF;
  IF v_master.sale_unit_id IS NULL
     OR COALESCE(v_master.units_per_sale_unit, 0) < 1
     OR COALESCE(v_master.default_sale_price_in_minor_units, 0) <= 0 THEN
    RAISE EXCEPTION 'أكمل طرد البيع وسعره في المنتج الأساسي أولًا.';
  END IF;

  IF NOT v_master.is_flavor_master THEN
    SELECT COALESCE(SUM(ib.on_hand_quantity + ib.reserved_quantity), 0)
      INTO v_master_stock
    FROM public.inventory_balances ib
    WHERE ib.product_id = v_master.id;

    IF v_master_stock <> 0 THEN
      RAISE EXCEPTION 'قبل تفعيل النكهات يجب أن يكون رصيد المنتج الأساسي صفرًا؛ بعدها أضف الرصيد لكل نكهة.';
    END IF;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.products p
    WHERE p.flavor_master_product_id = v_master.id
      AND LOWER(BTRIM(p.flavor_name_ar)) = LOWER(v_flavor_name)
  ) THEN
    RAISE EXCEPTION 'هذه النكهة موجودة مسبقًا.';
  END IF;

  v_warehouse_id := p_warehouse_id;
  IF v_warehouse_id IS NULL THEN
    SELECT w.id INTO v_warehouse_id
    FROM public.warehouses w
    WHERE w.is_active = true
    ORDER BY w.created_at, w.id
    LIMIT 1;
  END IF;
  IF v_warehouse_id IS NULL THEN
    RAISE EXCEPTION 'لا يوجد مستودع نشط لإضافة رصيد النكهة.';
  END IF;

  SELECT COALESCE(MAX(p.flavor_sort_order), 0) + 10
    INTO v_sort_order
  FROM public.products p
  WHERE p.flavor_master_product_id = v_master.id;

  v_sku := LEFT(v_master.sku, 42) || '-F-' ||
    UPPER(SUBSTRING(MD5(v_flavor_name || CLOCK_TIMESTAMP()::TEXT), 1, 8));

  v_result := public.create_product_with_opening_stock_v4(
    v_sku,
    NULLIF(BTRIM(p_barcode), ''),
    v_master.name_ar || ' - ' || v_flavor_name,
    v_master.description,
    v_master.category_id,
    v_master.brand_id,
    v_master.unit_id,
    v_master.purchase_unit_id,
    v_master.units_per_purchase_unit,
    v_master.default_purchase_price_in_minor_units,
    v_master.sale_unit_id,
    v_master.units_per_sale_unit,
    v_master.default_sale_price_in_minor_units,
    v_master.cost_price_in_minor_units,
    v_master.min_stock_level,
    v_master.max_stock_level,
    v_warehouse_id,
    COALESCE(p_opening_sale_packages, 0) * v_master.units_per_sale_unit,
    'رصيد افتتاحي لنكهة ' || v_flavor_name,
    COALESCE(NULLIF(BTRIM(p_image_url), ''), (
      SELECT pi.image_url
      FROM public.product_images pi
      WHERE pi.product_id = v_master.id
      ORDER BY pi.is_primary DESC, pi.display_order, pi.created_at
      LIMIT 1
    ))
  );

  v_flavor_id := NULLIF(v_result->>'product_id', '')::UUID;
  IF v_flavor_id IS NULL THEN
    RAISE EXCEPTION 'تعذر إنشاء سجل النكهة.';
  END IF;

  UPDATE public.products
  SET
    flavor_master_product_id = v_master.id,
    flavor_name_ar = v_flavor_name,
    flavor_sort_order = v_sort_order,
    updated_at = NOW()
  WHERE id = v_flavor_id;

  UPDATE public.products
  SET is_flavor_master = true, updated_at = NOW()
  WHERE id = v_master.id;

  INSERT INTO public.audit_logs (
    user_id, action, entity_name, entity_id, details
  ) VALUES (
    auth.uid(),
    'CREATE_PRODUCT_FLAVOR',
    'products',
    v_flavor_id,
    jsonb_build_object(
      'master_product_id', v_master.id,
      'flavor_name_ar', v_flavor_name,
      'opening_sale_packages', COALESCE(p_opening_sale_packages, 0),
      'inherited_sale_price_in_minor_units',
        v_master.default_sale_price_in_minor_units
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'productId', v_flavor_id,
    'masterProductId', v_master.id,
    'flavorNameAr', v_flavor_name,
    'message', 'تمت إضافة النكهة بمخزون مستقل وسعر المنتج الأساسي.'
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.create_product_with_opening_stock_v3(p_sku text, p_barcode text DEFAULT NULL::text, p_name_ar text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_category_id uuid DEFAULT NULL::uuid, p_brand_id uuid DEFAULT NULL::uuid, p_unit_id uuid DEFAULT NULL::uuid, p_purchase_unit_id uuid DEFAULT NULL::uuid, p_units_per_purchase_unit integer DEFAULT 1, p_default_purchase_price_in_minor_units bigint DEFAULT 0, p_cost_price_in_minor_units bigint DEFAULT 0, p_sale_price_in_minor_units bigint DEFAULT 0, p_wholesale_price_in_minor_units bigint DEFAULT 0, p_min_stock_level integer DEFAULT 0, p_max_stock_level integer DEFAULT NULL::integer, p_warehouse_id uuid DEFAULT NULL::uuid, p_opening_quantity integer DEFAULT 0, p_notes text DEFAULT 'رصيد افتتاحي عند إضافة المنتج'::text, p_image_url text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_result JSONB;
  v_product_id UUID;
  v_image_url TEXT := NULLIF(BTRIM(p_image_url), '');
BEGIN
  PERFORM public.assert_erp_role(
    ARRAY['owner', 'admin', 'manager', 'warehouse_keeper'],
    'إضافة المنتجات والأرصدة الافتتاحية'
  );

  v_result := public.create_product_with_opening_stock_v2(
    p_sku,
    p_barcode,
    p_name_ar,
    p_description,
    p_category_id,
    p_brand_id,
    p_unit_id,
    p_purchase_unit_id,
    p_units_per_purchase_unit,
    p_default_purchase_price_in_minor_units,
    p_cost_price_in_minor_units,
    p_sale_price_in_minor_units,
    p_wholesale_price_in_minor_units,
    p_min_stock_level,
    p_max_stock_level,
    p_warehouse_id,
    p_opening_quantity,
    p_notes
  );

  v_product_id := NULLIF(v_result->>'product_id', '')::UUID;
  IF v_product_id IS NULL THEN
    RAISE EXCEPTION 'لم يتم إرجاع معرف المنتج بعد إنشائه.';
  END IF;

  IF v_image_url IS NOT NULL THEN
    PERFORM public.set_product_primary_image(
      v_product_id,
      v_image_url
    );
  END IF;

  RETURN v_result || jsonb_build_object(
    'image_url',
    v_image_url
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.create_product_with_opening_stock_v4(p_sku text, p_barcode text DEFAULT NULL::text, p_name_ar text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_category_id uuid DEFAULT NULL::uuid, p_brand_id uuid DEFAULT NULL::uuid, p_unit_id uuid DEFAULT NULL::uuid, p_purchase_unit_id uuid DEFAULT NULL::uuid, p_units_per_purchase_unit integer DEFAULT 1, p_default_purchase_price_in_minor_units bigint DEFAULT 0, p_sale_unit_id uuid DEFAULT NULL::uuid, p_units_per_sale_unit integer DEFAULT 1, p_default_sale_price_in_minor_units bigint DEFAULT 0, p_cost_price_in_minor_units bigint DEFAULT 0, p_min_stock_level integer DEFAULT 0, p_max_stock_level integer DEFAULT NULL::integer, p_warehouse_id uuid DEFAULT NULL::uuid, p_opening_quantity integer DEFAULT 0, p_notes text DEFAULT 'رصيد افتتاحي عند إضافة المنتج'::text, p_image_url text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_result JSONB;
  v_product_id UUID;
  v_unit_sale_price BIGINT;
BEGIN
  PERFORM public.assert_erp_role(
    ARRAY['owner', 'admin', 'manager', 'warehouse_keeper'],
    'إضافة منتج جملة'
  );

  IF COALESCE(p_opening_quantity, 0) <> 0 THEN
    RAISE EXCEPTION
      'لا يُضاف مخزون أثناء إنشاء المنتج؛ استخدم الاستلام أو تهيئة المخزون الموثقة.';
  END IF;
  IF COALESCE(p_units_per_sale_unit, 0) < 1 THEN
    RAISE EXCEPTION 'عدد الحبات داخل طرد البيع يجب أن يكون أكبر من صفر.';
  END IF;
  IF COALESCE(p_default_sale_price_in_minor_units, 0) <= 0 THEN
    RAISE EXCEPTION 'سعر بيع طرد الجملة يجب أن يكون أكبر من صفر.';
  END IF;
  IF p_sale_unit_id IS NULL OR EXISTS (
    SELECT 1 FROM public.units
    WHERE id = p_sale_unit_id AND code = 'PCS'
  ) THEN
    RAISE EXCEPTION 'طرد البيع يجب أن يكون عبوة جملة وليس حبة أو قطعة.';
  END IF;

  v_unit_sale_price := ROUND(
    p_default_sale_price_in_minor_units::NUMERIC / p_units_per_sale_unit
  )::BIGINT;

  v_result := public.create_product_with_opening_stock_v3(
    p_sku, p_barcode, p_name_ar, p_description, p_category_id, p_brand_id,
    p_unit_id, p_purchase_unit_id, p_units_per_purchase_unit,
    p_default_purchase_price_in_minor_units, p_cost_price_in_minor_units,
    v_unit_sale_price, v_unit_sale_price, p_min_stock_level,
    p_max_stock_level, p_warehouse_id, 0, p_notes, p_image_url
  );

  v_product_id := NULLIF(v_result->>'product_id', '')::UUID;
  IF v_product_id IS NULL THEN
    RAISE EXCEPTION 'لم يتم إرجاع معرف المنتج بعد إنشائه.';
  END IF;

  UPDATE public.products
  SET
    sale_unit_id = COALESCE(p_sale_unit_id, p_purchase_unit_id, p_unit_id),
    units_per_sale_unit = p_units_per_sale_unit,
    default_sale_price_in_minor_units = p_default_sale_price_in_minor_units,
    updated_at = NOW()
  WHERE id = v_product_id;

  INSERT INTO public.audit_logs (
    user_id, action, entity_name, entity_id, details
  ) VALUES (
    auth.uid(), 'SET_PRODUCT_WHOLESALE_PACKAGE', 'products', v_product_id,
    jsonb_build_object(
      'sale_unit_id', COALESCE(p_sale_unit_id, p_purchase_unit_id, p_unit_id),
      'units_per_sale_unit', p_units_per_sale_unit,
      'default_sale_price_in_minor_units',
        p_default_sale_price_in_minor_units,
      'opening_stock_created', false
    )
  );

  RETURN v_result || jsonb_build_object(
    'saleUnitId', COALESCE(p_sale_unit_id, p_purchase_unit_id, p_unit_id),
    'unitsPerSaleUnit', p_units_per_sale_unit,
    'defaultSalePriceInMinorUnits', p_default_sale_price_in_minor_units,
    'openingStockCreated', false
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.create_purchase_order_v2(p_supplier_id uuid, p_branch_id uuid DEFAULT NULL::uuid, p_warehouse_id uuid DEFAULT NULL::uuid, p_expected_delivery_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_expected_header_discount_in_minor_units bigint DEFAULT 0, p_expected_supplier_freight_in_minor_units bigint DEFAULT 0, p_notes text DEFAULT NULL::text, p_internal_notes text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text, p_lines jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_key TEXT := NULLIF(BTRIM(p_idempotency_key), '');
  v_canonical_lines JSONB;
  v_canonical_request JSONB;
  v_fingerprint TEXT;
  v_existing_operation public.business_operations%ROWTYPE;
  v_operation_id UUID := gen_random_uuid();
  v_purchase_order_id UUID := gen_random_uuid();
  v_purchase_order_number TEXT;
  v_result JSONB;
  v_line JSONB;
  v_component JSONB;
  v_po_item_id UUID;
  v_line_kind TEXT;
  v_commercial_quantity INTEGER;
  v_units_per_parcel INTEGER;
  v_ordered_base_quantity INTEGER;
  v_gross BIGINT;
  v_line_discount BIGINT;
  v_line_net BIGINT;
  v_line_net_total NUMERIC;
  v_total NUMERIC;
  v_product_id UUID;
  v_product public.products%ROWTYPE;
BEGIN
  PERFORM public.assert_erp_role(
    ARRAY['owner', 'admin', 'manager', 'warehouse_keeper'],
    'إنشاء أمر شراء - نموذج الطرود'
  );
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'PHASE2_AUTH_REQUIRED: يجب تسجيل الدخول.';
  END IF;
  IF v_key IS NULL OR CHAR_LENGTH(v_key) NOT BETWEEN 16 AND 255 THEN
    RAISE EXCEPTION USING ERRCODE = '22023',
      MESSAGE = 'PHASE2_IDEMPOTENCY_KEY_INVALID: مفتاح منع التكرار غير صالح.';
  END IF;
  IF p_expected_header_discount_in_minor_units < 0
    OR p_expected_supplier_freight_in_minor_units < 0
  THEN
    RAISE EXCEPTION USING ERRCODE = '22023',
      MESSAGE = 'PHASE2_FINANCIAL_VALUE_INVALID: قيم أمر الشراء لا يمكن أن تكون سالبة.';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.suppliers supplier
    WHERE supplier.id = p_supplier_id AND supplier.is_active
  ) THEN
    RAISE EXCEPTION 'PHASE2_SUPPLIER_INVALID: المورد غير موجود أو غير نشط.';
  END IF;
  IF p_warehouse_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.warehouses warehouse
    WHERE warehouse.id = p_warehouse_id AND warehouse.is_active
  ) THEN
    RAISE EXCEPTION 'PHASE2_WAREHOUSE_INVALID: المستودع غير موجود أو غير نشط.';
  END IF;
  IF p_branch_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.branches branch
    WHERE branch.id = p_branch_id AND branch.is_active
  ) THEN
    RAISE EXCEPTION 'PHASE2_BRANCH_INVALID: الفرع غير موجود أو غير نشط.';
  END IF;

  v_canonical_lines := public.phase2_canonicalize_receipt_lines_internal(p_lines);
  PERFORM public.phase2_validate_receipt_lines_internal(v_canonical_lines);
  SELECT COALESCE(SUM(
    (line->>'gross_amount_in_minor_units')::NUMERIC
    - (line->>'line_discount_in_minor_units')::NUMERIC
  ), 0)
  INTO v_line_net_total
  FROM jsonb_array_elements(v_canonical_lines) line;

  IF p_expected_header_discount_in_minor_units > v_line_net_total THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      CONSTRAINT = 'phase2_purchase_order_header_discount_check',
      MESSAGE = 'PHASE2_HEADER_DISCOUNT_EXCEEDS_NET: الخصم المتوقع يتجاوز صافي أمر الشراء.';
  END IF;
  IF v_line_net_total = 0
    AND (p_expected_header_discount_in_minor_units > 0
      OR p_expected_supplier_freight_in_minor_units > 0)
  THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      CONSTRAINT = 'phase2_purchase_order_zero_basis_check',
      MESSAGE = 'PHASE2_ZERO_ALLOCATION_BASIS: لا يمكن وضع خصم أو شحن متوقع على أساس صفري.';
  END IF;
  v_total := v_line_net_total
    - p_expected_header_discount_in_minor_units::NUMERIC
    + p_expected_supplier_freight_in_minor_units::NUMERIC;
  IF v_line_net_total > 9223372036854775807::NUMERIC
    OR v_total > 9223372036854775807::NUMERIC
  THEN
    RAISE EXCEPTION USING ERRCODE = '22003',
      MESSAGE = 'PHASE2_MONEY_OVERFLOW: قيمة أمر الشراء تتجاوز الحد المدعوم.';
  END IF;

  v_canonical_request := jsonb_build_object(
    'contract_version', 2,
    'operation_type', 'purchase_order_v2',
    'supplier_id', LOWER(p_supplier_id::TEXT),
    'branch_id', CASE WHEN p_branch_id IS NULL THEN NULL ELSE LOWER(p_branch_id::TEXT) END,
    'warehouse_id', CASE WHEN p_warehouse_id IS NULL THEN NULL ELSE LOWER(p_warehouse_id::TEXT) END,
    'expected_delivery_date', CASE WHEN p_expected_delivery_date IS NULL THEN NULL ELSE TO_CHAR(p_expected_delivery_date AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"') END,
    'expected_header_discount_in_minor_units', p_expected_header_discount_in_minor_units,
    'expected_supplier_freight_in_minor_units', p_expected_supplier_freight_in_minor_units,
    'notes', NULLIF(BTRIM(p_notes), ''),
    'internal_notes', NULLIF(BTRIM(p_internal_notes), ''),
    'lines', v_canonical_lines
  );
  v_fingerprint := public.phase2_request_fingerprint_internal(v_canonical_request);

  PERFORM pg_advisory_xact_lock(hashtextextended(
    'purchase_order_v2:' || v_user_id::TEXT || ':' || v_key, 0
  ));
  SELECT * INTO v_existing_operation
  FROM public.business_operations operation
  WHERE operation.operation_type = 'purchase_order_v2'
    AND operation.initiated_by = v_user_id
    AND operation.idempotency_key = v_key;
  IF FOUND THEN
    IF v_existing_operation.request_fingerprint IS NULL
      OR v_existing_operation.result_snapshot IS NULL
    THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001',
        MESSAGE = 'LEGACY_IDEMPOTENCY_IDENTITY_UNPROVEN: لا يمكن إثبات تطابق العملية التاريخية.';
    END IF;
    IF v_existing_operation.request_fingerprint IS DISTINCT FROM v_fingerprint THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001',
        MESSAGE = 'IDEMPOTENCY_CONFLICT: استُخدم المفتاح نفسه لطلب مختلف.';
    END IF;
    RETURN v_existing_operation.result_snapshot;
  END IF;

  LOOP
    v_purchase_order_number := 'PO-' || TO_CHAR(NOW(), 'YYYY') || '-'
      || LPAD(FLOOR(100000 + RANDOM() * 900000)::BIGINT::TEXT, 6, '0');
    EXIT WHEN NOT EXISTS (
      SELECT 1 FROM public.purchase_orders purchase_order
      WHERE purchase_order.purchase_order_number = v_purchase_order_number
    );
  END LOOP;

  v_result := jsonb_build_object(
    'success', true,
    'idempotent', false,
    'operation_id', v_operation_id,
    'purchase_order_id', v_purchase_order_id,
    'purchase_order_number', v_purchase_order_number,
    'expected_total_in_minor_units', v_total::BIGINT
  );
  INSERT INTO public.business_operations (
    id, operation_type, idempotency_key, request_fingerprint,
    initiated_by, result_snapshot, completed_at
  ) VALUES (
    v_operation_id, 'purchase_order_v2', v_key, v_fingerprint,
    v_user_id, v_result, NOW()
  );
  INSERT INTO public.purchase_orders (
    id, purchase_order_number, supplier_id, branch_id, warehouse_id,
    status, order_date, expected_delivery_date, subtotal_in_minor_units,
    discount_in_minor_units, delivery_fee_in_minor_units,
    total_in_minor_units, amount_paid_in_minor_units,
    notes, internal_notes, created_by, operation_id
  ) VALUES (
    v_purchase_order_id, v_purchase_order_number, p_supplier_id,
    p_branch_id, p_warehouse_id, 'draft', NOW(), p_expected_delivery_date,
    v_line_net_total::BIGINT, p_expected_header_discount_in_minor_units,
    p_expected_supplier_freight_in_minor_units, v_total::BIGINT, 0,
    NULLIF(BTRIM(p_notes), ''), NULLIF(BTRIM(p_internal_notes), ''),
    v_user_id, v_operation_id
  );

  FOR v_line IN SELECT * FROM jsonb_array_elements(v_canonical_lines)
  LOOP
    v_po_item_id := gen_random_uuid();
    v_line_kind := v_line->>'line_kind';
    v_commercial_quantity := (v_line->>'commercial_quantity')::INTEGER;
    v_units_per_parcel := NULLIF(v_line->>'units_per_parcel', '')::INTEGER;
    v_ordered_base_quantity := (
      SELECT SUM((component->>'base_quantity')::INTEGER)
      FROM jsonb_array_elements(v_line->'components') component
    );
    v_gross := (v_line->>'gross_amount_in_minor_units')::BIGINT;
    v_line_discount := (v_line->>'line_discount_in_minor_units')::BIGINT;
    v_line_net := v_gross - v_line_discount;
    IF v_line_kind = 'base_unit' THEN
      v_product_id := (v_line->'components'->0->>'product_id')::UUID;
    ELSE
      v_product_id := (v_line->>'family_product_id')::UUID;
    END IF;

    INSERT INTO public.purchase_order_items (
      id, purchase_order_id, product_id, ordered_quantity,
      received_quantity, purchase_price_in_minor_units,
      discount_in_minor_units, line_total_in_minor_units,
      commercial_line_kind, family_product_id, parcel_configuration_id,
      configuration_revision, base_unit_name_snapshot,
      parcel_unit_name_snapshot, parcel_quantity, client_line_id,
      units_per_parcel_snapshot, received_parcel_quantity,
      commercial_quantity_snapshot, gross_amount_snapshot_in_minor_units,
      line_discount_snapshot_in_minor_units, line_net_snapshot_in_minor_units
    ) VALUES (
      v_po_item_id, v_purchase_order_id, v_product_id,
      v_ordered_base_quantity, 0,
      ROUND(v_gross::NUMERIC / v_ordered_base_quantity)::BIGINT,
      v_line_discount, v_line_net, v_line_kind,
      NULLIF(v_line->>'family_product_id', '')::UUID,
      NULLIF(v_line->>'parcel_configuration_id', '')::UUID,
      NULLIF(v_line->>'configuration_revision', '')::INTEGER,
      v_line->>'base_unit_name', NULLIF(v_line->>'parcel_unit_name', ''),
      CASE WHEN v_line_kind = 'configurable_parcel' THEN v_commercial_quantity END,
      (v_line->>'client_line_id')::UUID, v_units_per_parcel, 0,
      v_commercial_quantity, v_gross, v_line_discount, v_line_net
    );

    FOR v_component IN SELECT * FROM jsonb_array_elements(v_line->'components')
    LOOP
      v_product_id := (v_component->>'product_id')::UUID;
      SELECT * INTO v_product FROM public.products WHERE id = v_product_id;
      INSERT INTO public.purchase_order_item_components (
        purchase_order_item_id, product_id, expected_base_quantity,
        product_name_snapshot, sku_snapshot
      ) VALUES (
        v_po_item_id, v_product_id,
        (v_component->>'base_quantity')::INTEGER,
        v_product.name_ar, v_product.sku
      );
    END LOOP;
  END LOOP;

  INSERT INTO public.audit_logs (
    user_id, action, entity_name, entity_id, details
  ) VALUES (
    v_user_id, 'CREATE_PURCHASE_ORDER_V2', 'purchase_orders',
    v_purchase_order_id,
    jsonb_build_object(
      'operation_id', v_operation_id,
      'purchase_order_number', v_purchase_order_number,
      'expected_total_in_minor_units', v_total::BIGINT
    )
  );
  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_draft_purchase_order(p_purchase_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_purchase_order_number TEXT;
  v_status TEXT;
BEGIN
  PERFORM public.assert_erp_role(
    ARRAY['owner', 'admin', 'manager'],
    'حذف أوامر الشراء'
  );

  SELECT purchase_order_number, status
  INTO v_purchase_order_number, v_status
  FROM public.purchase_orders
  WHERE id = p_purchase_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'أمر الشراء المحدد غير موجود.';
  END IF;
  IF v_status <> 'draft' THEN
    RAISE EXCEPTION 'يمكن حذف أمر الشراء عندما تكون حالته مسودة فقط.';
  END IF;

  DELETE FROM public.purchase_orders
  WHERE id = p_purchase_order_id;

  INSERT INTO public.audit_logs (
    user_id,
    action,
    entity_name,
    entity_id,
    details
  ) VALUES (
    v_user_id,
    'DELETE_DRAFT_PURCHASE_ORDER',
    'purchase_orders',
    p_purchase_order_id,
    jsonb_build_object(
      'purchase_order_number', v_purchase_order_number
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'purchase_order_id', p_purchase_order_id,
    'purchase_order_number', v_purchase_order_number
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.endorse_customer_cheque_v1(p_cheque_id uuid, p_supplier_id uuid, p_expected_version integer, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_c public.deferred_cheques%ROWTYPE;v_plan JSONB;v_request JSONB;v_replay JSONB;v_payment UUID;
BEGIN
  PERFORM public.assert_erp_role(ARRAY['owner','manager'],'تجيير شيك لمورد');
  v_request:=jsonb_build_object('action','endorse','cheque',p_cheque_id,'supplier',p_supplier_id,'version',p_expected_version);
  v_replay:=public.cheque_replay_internal(p_idempotency_key,v_request);IF v_replay IS NOT NULL THEN RETURN v_replay;END IF;
  -- Supplier before cheque; no order/payment/shift locks are discovered later.
  PERFORM 1 FROM public.suppliers WHERE id=p_supplier_id AND is_active FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'المورد غير موجود أو غير نشط.';END IF;
  SELECT * INTO STRICT v_c FROM public.deferred_cheques WHERE id=p_cheque_id FOR UPDATE;
  IF v_c.version IS DISTINCT FROM p_expected_version OR v_c.direction<>'incoming' OR v_c.status<>'pending' THEN
    RAISE EXCEPTION 'CHEQUE_INVALID_TRANSITION: التجيير لوارد قيد الانتظار فقط؛ حدّث التفاصيل.';
  END IF;
  v_plan:=public.cheque_supplier_plan_internal(p_supplier_id,v_c.amount_in_minor_units);
  INSERT INTO public.cheque_party_keys(party_kind,party_id,bank_key,cheque_number,cheque_id)
  VALUES('supplier',p_supplier_id,v_c.bank_key,v_c.cheque_number,v_c.id);
  v_payment:=public.cheque_pay_supplier_internal(v_c.id,p_supplier_id,v_plan);
  UPDATE public.deferred_cheques SET status='endorsed',endorsed_supplier_id=p_supplier_id,supplier_payment_id=v_payment,
    version=version+1,changed_by=auth.uid(),changed_at=CURRENT_TIMESTAMP WHERE id=v_c.id;
  RETURN public.cheque_finish_event_internal(v_c.id,'endorsed',v_c.status,NULL,p_idempotency_key,v_request);
END;
$function$

