CREATE OR REPLACE FUNCTION public.enforce_product_flavor_inheritance()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_master public.products%ROWTYPE;
BEGIN
  IF NEW.flavor_master_product_id IS NULL THEN
    IF NEW.is_flavor_master AND NEW.flavor_name_ar IS NOT NULL THEN
      RAISE EXCEPTION 'المنتج الأساسي لا يحمل اسم نكهة.';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.flavor_master_product_id = NEW.id THEN
    RAISE EXCEPTION 'لا يمكن ربط المنتج بنفسه كمنتج أساسي.';
  END IF;

  SELECT * INTO v_master
  FROM public.products
  WHERE id = NEW.flavor_master_product_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'المنتج الأساسي للنكهة غير موجود.';
  END IF;
  IF v_master.flavor_master_product_id IS NOT NULL THEN
    RAISE EXCEPTION 'لا يمكن إنشاء نكهة داخل نكهة أخرى.';
  END IF;

  NEW.flavor_name_ar := BTRIM(NEW.flavor_name_ar);
  NEW.is_flavor_master := false;
  NEW.category_id := v_master.category_id;
  NEW.brand_id := v_master.brand_id;
  NEW.unit_id := v_master.unit_id;
  NEW.purchase_unit_id := v_master.purchase_unit_id;
  NEW.units_per_purchase_unit := v_master.units_per_purchase_unit;
  NEW.default_purchase_price_in_minor_units :=
    v_master.default_purchase_price_in_minor_units;
  NEW.sale_unit_id := v_master.sale_unit_id;
  NEW.units_per_sale_unit := v_master.units_per_sale_unit;
  NEW.default_sale_price_in_minor_units :=
    v_master.default_sale_price_in_minor_units;
  IF TG_OP = 'INSERT' THEN
    NEW.cost_price_in_minor_units := v_master.cost_price_in_minor_units;
  END IF;
  NEW.sale_price_in_minor_units := v_master.sale_price_in_minor_units;
  NEW.wholesale_price_in_minor_units :=
    v_master.wholesale_price_in_minor_units;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_product_identifier_integrity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_sku TEXT := UPPER(BTRIM(NEW.sku));
  v_barcode TEXT := NULLIF(BTRIM(NEW.barcode), '');
  v_barcode_normalized TEXT;
  v_lock_key TEXT;
BEGIN
  IF v_sku IS NULL OR v_sku = '' THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'رمز الصنف SKU مطلوب.',
      CONSTRAINT = 'products_sku_canonical_check';
  END IF;

  IF COALESCE(NEW.is_flavor_master, false) AND v_barcode IS NOT NULL THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'المنتج الأساسي للنكهات للتجميع فقط ولا يحمل باركود بيع.',
      CONSTRAINT = 'products_flavor_master_no_barcode_check';
  END IF;

  NEW.sku := v_sku;
  NEW.barcode := v_barcode;
  v_barcode_normalized := LOWER(v_barcode);

  -- Serialize every normalized identifier before checking the shared SKU /
  -- barcode namespace. Sorted acquisition prevents inverse-pair deadlocks.
  FOR v_lock_key IN
    SELECT DISTINCT identifier
    FROM (
      VALUES (LOWER(v_sku)), (v_barcode_normalized)
    ) AS identifiers(identifier)
    WHERE identifier IS NOT NULL
    ORDER BY identifier
  LOOP
    PERFORM pg_advisory_xact_lock(
      hashtextextended('product_identifier:' || v_lock_key, 0)
    );
  END LOOP;

  IF EXISTS (
    SELECT 1
    FROM public.products product
    WHERE product.id IS DISTINCT FROM NEW.id
      AND UPPER(BTRIM(product.sku)) = v_sku
  ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '23505',
      MESSAGE = 'رمز الصنف SKU مستخدم بالفعل لمنتج آخر.',
      CONSTRAINT = 'products_sku_normalized_key';
  END IF;

  IF v_barcode_normalized IS NOT NULL AND EXISTS (
    SELECT 1
    FROM public.products product
    WHERE product.id IS DISTINCT FROM NEW.id
      AND LOWER(BTRIM(product.barcode)) = v_barcode_normalized
  ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '23505',
      MESSAGE = 'الباركود مستخدم بالفعل لمنتج آخر.',
      CONSTRAINT = 'products_barcode_normalized_key';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.products product
    WHERE product.id IS DISTINCT FROM NEW.id
      AND NULLIF(BTRIM(product.barcode), '') IS NOT NULL
      AND LOWER(BTRIM(product.barcode)) = LOWER(v_sku)
  ) OR (
    v_barcode_normalized IS NOT NULL
    AND EXISTS (
      SELECT 1
      FROM public.products product
      WHERE product.id IS DISTINCT FROM NEW.id
        AND LOWER(BTRIM(product.sku)) = v_barcode_normalized
    )
  ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '23505',
      MESSAGE = 'لا يمكن استخدام نفس الرقم كـSKU لمنتج وباركود لمنتج آخر.',
      CONSTRAINT = 'product_identifier_cross_collision';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enqueue_automation_event(p_event_key text, p_event_type text, p_entity_id uuid, p_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_event_id UUID;v_event_key TEXT:=NULLIF(TRIM(p_event_key),'');v_payload JSONB:=COALESCE(p_payload,'{}'::JSONB);
BEGIN
  IF v_event_key IS NULL OR length(v_event_key)>300 THEN RAISE EXCEPTION 'Invalid automation event key.';END IF;
  IF p_event_type NOT IN('new_order','low_stock','out_of_stock','shift_closed','order_unprocessed','order_near_expiry','order_expired',
    'shift_close_reminder','shift_close_overdue','purchase_order_overdue','expense_daily_threshold','business_alert_recovery',
    'business_daily_summary','business_weekly_summary','business_integrity_warning','cheque_due','cheque_returned') THEN
    RAISE EXCEPTION 'Invalid automation event type.';
  END IF;
  IF p_entity_id IS NULL THEN RAISE EXCEPTION 'Automation event entity is required.';END IF;
  IF jsonb_typeof(v_payload)<>'object' OR octet_length(v_payload::TEXT)>32768 THEN RAISE EXCEPTION 'Invalid automation event payload.';END IF;
  INSERT INTO public.automation_events(event_key,event_type,entity_id,payload) VALUES(v_event_key,p_event_type,p_entity_id,v_payload)
  ON CONFLICT(event_key) DO NOTHING RETURNING id INTO v_event_id;
  IF v_event_id IS NULL THEN SELECT id INTO v_event_id FROM public.automation_events WHERE event_key=v_event_key;END IF;
  RETURN v_event_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.enqueue_business_summary(p_summary_type text, p_period_start date, p_period_end date, p_scheduled_for timestamp with time zone, p_generated_at timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_run_id UUID;
  v_event_id UUID;
  v_event_key TEXT;
  v_event_type TEXT;
  v_payload JSONB;
BEGIN
  IF p_summary_type NOT IN ('daily', 'weekly') OR p_scheduled_for IS NULL THEN
    RAISE EXCEPTION 'Invalid Business summary enqueue request.';
  END IF;
  v_event_key := 'business_summary:' || p_summary_type || ':'
    || p_period_start::TEXT || ':' || p_period_end::TEXT;
  PERFORM pg_advisory_xact_lock(hashtextextended(v_event_key, 0));

  SELECT id, event_id INTO v_run_id, v_event_id
  FROM public.business_summary_runs
  WHERE summary_type = p_summary_type
    AND period_start = p_period_start AND period_end = p_period_end;
  IF FOUND THEN
    RETURN jsonb_build_object(
      'success', true, 'created', false,
      'runId', v_run_id, 'eventId', v_event_id
    );
  END IF;

  v_run_id := gen_random_uuid();
  v_payload := public.build_business_summary(
    p_summary_type, p_period_start, p_period_end, p_generated_at
  );
  v_event_type := CASE p_summary_type
    WHEN 'daily' THEN 'business_daily_summary'
    ELSE 'business_weekly_summary'
  END;
  v_event_id := public.enqueue_automation_event(
    v_event_key, v_event_type, v_run_id, v_payload
  );

  INSERT INTO public.business_summary_runs(
    id, summary_type, period_start, period_end, scheduled_for,
    run_status, event_id, generated_at
  ) VALUES (
    v_run_id, p_summary_type, p_period_start, p_period_end,
    p_scheduled_for, 'queued', v_event_id, p_generated_at
  );

  RETURN jsonb_build_object(
    'success', true, 'created', true,
    'runId', v_run_id, 'eventId', v_event_id
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.enqueue_order_push_webhook(p_payload jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'vault', 'net', 'pg_temp'
AS $function$
DECLARE
  v_secret TEXT;
  v_url TEXT;
  v_request_id BIGINT;
BEGIN
  SELECT decrypted_secret
  INTO v_secret
  FROM vault.decrypted_secrets
  WHERE name = 'order_push_webhook_secret'
  ORDER BY created_at DESC
  LIMIT 1;

  IF NULLIF(v_secret, '') IS NULL THEN
    RAISE EXCEPTION 'سر إشعارات الطلبات غير مهيأ.';
  END IF;

  SELECT decrypted_secret
  INTO v_url
  FROM vault.decrypted_secrets
  WHERE name = 'order_push_webhook_url'
  ORDER BY created_at DESC
  LIMIT 1;

  IF NULLIF(TRIM(v_url), '') IS NULL THEN
    RAISE EXCEPTION 'رابط إشعارات الطلبات غير مهيأ.';
  END IF;

  SELECT net.http_post(
    url := v_url,
    body := p_payload,
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'x-order-push-secret', v_secret
    ),
    timeout_milliseconds := 5000
  )
  INTO v_request_id;

  RETURN v_request_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.expire_stale_new_website_orders(p_batch_size integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_order RECORD;
  v_item RECORD;
  v_expired_count INTEGER := 0;
  v_failed_count INTEGER := 0;
  v_attempted_count INTEGER := 0;
  v_candidate_limit INTEGER;
  v_scan_exhausted BOOLEAN := false;
  v_expired_order_ids UUID[] := ARRAY[]::UUID[];
  v_failed_order_ids UUID[] := ARRAY[]::UUID[];
  v_reason CONSTANT TEXT := 'انتهت مهلة حجز طلب الموقع (5 ساعات) قبل قبول الطلب.';
BEGIN
  IF p_batch_size IS NULL OR p_batch_size NOT BETWEEN 1 AND 100 THEN
    RAISE EXCEPTION 'دفعة إنهاء صلاحية الطلبات يجب أن تكون بين 1 و100.';
  END IF;
  -- p_batch_size is a success target.  Candidate attempts are independently
  -- bounded so poison rows cannot consume the success quota or cause a hot loop.
  v_candidate_limit := LEAST(1000, GREATEST(p_batch_size * 10, p_batch_size + 25));
  PERFORM SET_CONFIG('lock_timeout', '3s', true);
  PERFORM SET_CONFIG('statement_timeout', '25s', true);

  FOR v_order IN
    SELECT customer_order.id, customer_order.order_number,
      customer_order.warehouse_id,
      operation.operation_type = 'phase3_customer_reservation_v1' AS is_v2
    FROM public.orders customer_order
    LEFT JOIN public.business_operations operation
      ON operation.id = customer_order.operation_id
    WHERE customer_order.source = 'website'
      AND customer_order.status = 'new'
      AND customer_order.reservation_expires_at IS NOT NULL
      AND customer_order.reservation_expires_at <= NOW()
      AND customer_order.reservation_released_at IS NULL
    ORDER BY customer_order.reservation_expires_at, customer_order.id
    LIMIT v_candidate_limit
    FOR UPDATE OF customer_order SKIP LOCKED
  LOOP
    v_attempted_count := v_attempted_count + 1;
    BEGIN
      IF v_order.is_v2 THEN
        PERFORM public.phase3_expire_customer_order_v2_internal(v_order.id);
      ELSE
        IF v_order.warehouse_id IS NULL THEN
          RAISE EXCEPTION 'الطلب (%) لا يملك مستودعًا صالحًا لتحرير الحجز.',
            v_order.order_number;
        END IF;
        FOR v_item IN
          SELECT item.product_id, SUM(item.quantity)::INTEGER quantity
          FROM public.order_items item WHERE item.order_id = v_order.id
          GROUP BY item.product_id ORDER BY item.product_id
        LOOP
          UPDATE public.inventory_balances balance
          SET reserved_quantity = balance.reserved_quantity - v_item.quantity,
            updated_at = NOW()
          WHERE balance.warehouse_id = v_order.warehouse_id
            AND balance.product_id = v_item.product_id
            AND balance.reserved_quantity >= v_item.quantity;
          IF NOT FOUND THEN
            RAISE EXCEPTION
              'تعذر تحرير حجز الطلب (%): رصيد الحجز للصنف (%) غير متطابق.',
              v_order.order_number, v_item.product_id;
          END IF;
        END LOOP;
        UPDATE public.orders SET status = 'expired', expired_at = NOW(),
          expired_reason = v_reason, reservation_released_at = NOW(),
          updated_at = NOW()
        WHERE id = v_order.id AND source = 'website' AND status = 'new'
          AND reservation_expires_at <= NOW()
          AND reservation_released_at IS NULL;
        IF NOT FOUND THEN
          RAISE EXCEPTION
            'تغيرت حالة الطلب (%) أثناء إنهاء الصلاحية؛ تم إلغاء العملية بأمان.',
            v_order.order_number;
        END IF;
        INSERT INTO public.order_status_history(
          order_id, old_status, new_status, changed_by, notes
        ) VALUES (v_order.id, 'new', 'expired', NULL, v_reason);
        INSERT INTO public.audit_logs(user_id, action, entity_name, entity_id, details)
        VALUES (NULL, 'EXPIRE_STALE_NEW_WEBSITE_ORDER', 'orders', v_order.id,
          JSONB_BUILD_OBJECT('order_number', v_order.order_number,
            'source', 'website', 'reason', v_reason, 'actor', 'system'));
      END IF;
      v_expired_count := v_expired_count + 1;
      v_expired_order_ids := ARRAY_APPEND(v_expired_order_ids, v_order.id);
    EXCEPTION WHEN OTHERS THEN
      -- A poison row is isolated by this subtransaction. The scheduler can
      -- continue releasing unrelated eligible orders and reports the exact
      -- opaque IDs that require operational review.
      v_failed_count := v_failed_count + 1;
      v_failed_order_ids := ARRAY_APPEND(v_failed_order_ids, v_order.id);
      INSERT INTO public.audit_logs(
        user_id, action, entity_name, entity_id, details
      ) VALUES (
        NULL,
        'EXPIRE_STALE_WEBSITE_ORDER_FAILED',
        'orders',
        v_order.id,
        JSONB_BUILD_OBJECT(
          'order_number', v_order.order_number,
          'source', 'website',
          'actor', 'system',
          'sqlstate', SQLSTATE,
          'error', LEFT(SQLERRM, 500)
        )
      );
    END;
    EXIT WHEN v_expired_count >= p_batch_size;
  END LOOP;

  IF v_attempted_count >= v_candidate_limit
    AND v_expired_count < p_batch_size
  THEN
    SELECT EXISTS (
      SELECT 1
      FROM public.orders customer_order
      WHERE customer_order.source = 'website'
        AND customer_order.status = 'new'
        AND customer_order.reservation_expires_at IS NOT NULL
        AND customer_order.reservation_expires_at <= NOW()
        AND customer_order.reservation_released_at IS NULL
        AND NOT (customer_order.id = ANY(v_failed_order_ids))
    ) INTO v_scan_exhausted;
  END IF;
  RETURN JSONB_BUILD_OBJECT(
    'success', v_failed_count = 0,
    'attempted_count', v_attempted_count,
    'expired_count', v_expired_count,
    'expired_order_ids', v_expired_order_ids,
    'failed_count', v_failed_count,
    'failed_order_ids', v_failed_order_ids,
    'scan_exhausted', v_scan_exhausted
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.extract_google_maps_coordinates(p_google_maps_url text)
 RETURNS double precision[]
 LANGUAGE plpgsql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_url TEXT := NULLIF(TRIM(p_google_maps_url), '');
  v_match TEXT[];
  v_latitude DOUBLE PRECISION;
  v_longitude DOUBLE PRECISION;
BEGIN
  IF v_url IS NULL THEN
    RETURN NULL;
  END IF;

  v_match := REGEXP_MATCH(
    v_url,
    '[?&](?:q|query)=(-?[0-9]+(?:\.[0-9]+)?)(?:,|%2c)(-?[0-9]+(?:\.[0-9]+)?)',
    'i'
  );

  IF v_match IS NULL THEN
    v_match := REGEXP_MATCH(
      v_url,
      '/@(-?[0-9]+(?:\.[0-9]+)?),(-?[0-9]+(?:\.[0-9]+)?)(?:,|/|$)',
      'i'
    );
  END IF;

  IF v_match IS NULL THEN
    RETURN NULL;
  END IF;

  v_latitude := v_match[1]::DOUBLE PRECISION;
  v_longitude := v_match[2]::DOUBLE PRECISION;

  IF v_latitude NOT BETWEEN -90 AND 90
    OR v_longitude NOT BETWEEN -180 AND 180
  THEN
    RETURN NULL;
  END IF;

  RETURN ARRAY[v_latitude, v_longitude];
EXCEPTION
  WHEN invalid_text_representation OR numeric_value_out_of_range THEN
    RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.finalize_guest_order_gateway(p_idempotency_key uuid, p_outcome text, p_order_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
 SET lock_timeout TO '3s'
 SET statement_timeout TO '5s'
AS $function$
DECLARE
  v_request public.guest_order_gateway_requests%ROWTYPE;
BEGIN
  IF p_outcome NOT IN ('succeeded', 'order_rejected', 'gateway_error') THEN
    RAISE EXCEPTION 'Invalid gateway outcome.';
  END IF;

  SELECT * INTO v_request
  FROM public.guest_order_gateway_requests
  WHERE idempotency_key = p_idempotency_key
  FOR UPDATE;

  IF NOT FOUND OR v_request.decision <> 'allowed' THEN
    RAISE EXCEPTION 'Gateway authorization was not found.';
  END IF;

  IF v_request.outcome = 'succeeded' THEN
    IF p_outcome <> 'succeeded'
      OR v_request.order_id IS DISTINCT FROM p_order_id
    THEN
      RAISE EXCEPTION 'Gateway request is already finalized.';
    END IF;
    RETURN;
  END IF;

  UPDATE public.guest_order_gateway_requests
  SET outcome = p_outcome,
      order_id = CASE WHEN p_outcome = 'succeeded' THEN p_order_id ELSE NULL END,
      finalized_at = NOW()
  WHERE idempotency_key = p_idempotency_key;
END;
$function$

CREATE OR REPLACE FUNCTION public.finish_go_live_setup_v1(p_confirmation text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_state public.go_live_setup_state%ROWTYPE;
  v_main_branch UUID;
BEGIN
  PERFORM public.assert_erp_role(ARRAY['owner'], 'إنهاء بداية التشغيل');
  SELECT * INTO STRICT v_state FROM public.go_live_setup_state WHERE id FOR UPDATE;
  IF v_state.finished_at IS NOT NULL THEN
    RETURN jsonb_build_object('success', true, 'idempotentReplay', true,
      'finishedAt', v_state.finished_at, 'finishedBy', v_state.finished_by);
  END IF;
  IF BTRIM(COALESCE(p_confirmation, '')) <> 'إنهاء بداية التشغيل' THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'GO_LIVE_CONFIRMATION_REQUIRED: اكتب عبارة التأكيد "إنهاء بداية التشغيل" حرفياً.';
  END IF;
  v_main_branch := public.go_live_main_branch_internal();
  IF v_main_branch IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'GO_LIVE_MAIN_BRANCH_REQUIRED: اختر الفرع الرئيسي الذي تُنسب إليه الديون الافتتاحية قبل الإنهاء.';
  END IF;
  UPDATE public.go_live_setup_state
  SET finished_at = NOW(), finished_by = v_user_id, main_branch_id = v_main_branch
  WHERE id RETURNING * INTO v_state;
  INSERT INTO public.audit_logs(user_id, action, entity_name, entity_id, details)
  VALUES (v_user_id, 'GO_LIVE_SETUP_FINISHED', 'go_live_setup_state', NULL,
    jsonb_build_object('finished_at', v_state.finished_at, 'main_branch_id', v_state.main_branch_id,
      'status', public.go_live_setup_counts_internal()));
  RETURN jsonb_build_object('success', true, 'idempotentReplay', false,
    'finishedAt', v_state.finished_at, 'finishedBy', v_state.finished_by);
END;
$function$

CREATE OR REPLACE FUNCTION public.get_cash_shift_archive_page(p_branch_id uuid DEFAULT NULL::uuid, p_cashier_id uuid DEFAULT NULL::uuid, p_status text DEFAULT NULL::text, p_shift_number text DEFAULT NULL::text, p_date_from date DEFAULT NULL::date, p_date_to date DEFAULT NULL::date, p_limit integer DEFAULT 25, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_limit INTEGER := COALESCE(p_limit, 25);
  v_offset INTEGER := COALESCE(p_offset, 0);
  v_status TEXT := NULLIF(TRIM(p_status), '');
  v_number_query TEXT := NULLIF(TRIM(p_shift_number), '');
  v_total_count INTEGER := 0;
  v_items JSONB := '[]'::JSONB;
  v_cashiers JSONB := '[]'::JSONB;
BEGIN
  PERFORM public.assert_erp_role(
    ARRAY['owner', 'admin', 'manager', 'accountant'],
    'عرض أرشيف الورديات'
  );

  IF v_limit NOT BETWEEN 1 AND 100 THEN
    RAISE EXCEPTION 'حجم صفحة أرشيف الورديات غير صحيح.';
  END IF;
  IF v_offset < 0 THEN
    RAISE EXCEPTION 'بداية صفحة أرشيف الورديات غير صحيحة.';
  END IF;
  IF v_status IS NOT NULL AND v_status NOT IN ('open', 'closed', 'cancelled', 'reversed') THEN
    RAISE EXCEPTION 'حالة الوردية غير صحيحة.';
  END IF;
  IF p_date_from IS NOT NULL AND p_date_to IS NOT NULL AND p_date_from > p_date_to THEN
    RAISE EXCEPTION 'تاريخ البداية يجب أن يسبق تاريخ النهاية.';
  END IF;

  SELECT COUNT(*)::INTEGER
  INTO v_total_count
  FROM public.cash_shifts cs
  WHERE (p_branch_id IS NULL OR cs.branch_id = p_branch_id)
    AND (p_cashier_id IS NULL OR cs.opened_by = p_cashier_id)
    AND (v_status IS NULL OR cs.status = v_status)
    AND (v_number_query IS NULL OR cs.shift_number ILIKE '%' || v_number_query || '%')
    AND (p_date_from IS NULL OR cs.opened_at >= p_date_from::TIMESTAMPTZ)
    AND (p_date_to IS NULL OR cs.opened_at < (p_date_to + 1)::TIMESTAMPTZ);

  SELECT COALESCE(jsonb_agg(public.get_cash_shift_display_summary(page.id) ORDER BY page.opened_at DESC, page.id DESC), '[]'::JSONB)
  INTO v_items
  FROM (
    SELECT cs.id, cs.opened_at
    FROM public.cash_shifts cs
    WHERE (p_branch_id IS NULL OR cs.branch_id = p_branch_id)
      AND (p_cashier_id IS NULL OR cs.opened_by = p_cashier_id)
      AND (v_status IS NULL OR cs.status = v_status)
      AND (v_number_query IS NULL OR cs.shift_number ILIKE '%' || v_number_query || '%')
      AND (p_date_from IS NULL OR cs.opened_at >= p_date_from::TIMESTAMPTZ)
      AND (p_date_to IS NULL OR cs.opened_at < (p_date_to + 1)::TIMESTAMPTZ)
    ORDER BY cs.opened_at DESC, cs.id DESC
    OFFSET v_offset
    LIMIT v_limit
  ) page;

  -- Filter choices are bounded and exposed only through this protected read model.
  SELECT COALESCE(jsonb_agg(jsonb_build_object('id', source.id, 'name', source.name) ORDER BY source.name), '[]'::JSONB)
  INTO v_cashiers
  FROM (
    SELECT DISTINCT cs.opened_by AS id, COALESCE(profile.full_name, 'مستخدم النظام') AS name
    FROM public.cash_shifts cs
    LEFT JOIN public.profiles profile ON profile.id = cs.opened_by
    WHERE p_branch_id IS NULL OR cs.branch_id = p_branch_id
    ORDER BY name
    LIMIT 100
  ) source;

  RETURN jsonb_build_object(
    'success', true,
    'items', v_items,
    'totalCount', v_total_count,
    'limit', v_limit,
    'offset', v_offset,
    'hasMore', v_offset + jsonb_array_length(v_items) < v_total_count,
    'cashiers', v_cashiers
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.get_cash_shift_closing_report(p_shift_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_shift public.cash_shifts%ROWTYPE;
  v_report JSONB;
  v_section JSONB;
BEGIN
  PERFORM public.assert_erp_role(
    ARRAY['owner', 'admin', 'manager', 'accountant'],
    'عرض تقرير إغلاق الوردية'
  );
  SELECT * INTO v_shift
  FROM public.cash_shifts
  WHERE id = p_shift_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'الوردية المحددة غير موجودة.';
  END IF;
  IF v_shift.status = 'closed'
    AND v_shift.closing_report_snapshot IS NOT NULL
  THEN
    RETURN v_shift.closing_report_snapshot;
  END IF;
  v_report := public._get_cash_shift_closing_report_before_snapshot(p_shift_id);
  v_section := public.owner_withdrawal_closing_section_internal(p_shift_id);
  IF jsonb_array_length(v_section->'items') > 0 THEN
    v_section := v_section || jsonb_build_object('netMovementAfterWithdrawalsInMinorUnits',
      (v_report #>> '{reconciliation,netMovementInMinorUnits}')::BIGINT
        - (v_section->>'netInMinorUnits')::BIGINT);
    v_report := v_report || jsonb_build_object('ownerWithdrawals', v_section);
  END IF;
  v_section:=public.cheque_shift_settlement_section_internal(p_shift_id);
  IF jsonb_array_length(v_section->'items')>0 THEN
    v_report:=v_report||jsonb_build_object('chequeCompensationSettlements',v_section);
  END IF;
  RETURN v_report || jsonb_build_object(
    'snapshotStatus',
    CASE
      WHEN v_shift.status = 'open' THEN 'live'
      WHEN v_shift.status = 'closed' THEN 'legacy_recalculated'
      ELSE 'not_applicable'
    END
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.get_cash_shift_display_summary(p_shift_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_shift public.cash_shifts%ROWTYPE; v_opened_by_name TEXT; v_actor_name TEXT;
BEGIN
  SELECT * INTO v_shift FROM public.cash_shifts WHERE id=p_shift_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'الوردية المحددة غير موجودة.'; END IF;
  IF v_shift.status NOT IN ('cancelled','reversed') THEN RETURN public.get_cash_shift_summary(p_shift_id); END IF;
  SELECT full_name INTO v_opened_by_name FROM public.profiles WHERE id=v_shift.opened_by;
  SELECT full_name INTO v_actor_name FROM public.profiles WHERE id=CASE WHEN v_shift.status='cancelled' THEN v_shift.cancelled_by ELSE v_shift.reversed_by END;
  RETURN jsonb_build_object('id',v_shift.id,'shiftNumber',v_shift.shift_number,'branchId',v_shift.branch_id,'cashierName',COALESCE(v_opened_by_name,'مستخدم النظام'),'startTime',v_shift.opened_at,'endTime',CASE WHEN v_shift.status='cancelled' THEN v_shift.cancelled_at ELSE v_shift.reversed_at END,'openingCashInMinorUnits',v_shift.opening_cash_in_minor_units,'cashSalesInMinorUnits',0,'cliqSalesInMinorUnits',0,'cardSalesInMinorUnits',0,'cashReceiptsInMinorUnits',0,'cliqReceiptsInMinorUnits',0,'cashSupplierPaymentsInMinorUnits',0,'cliqSupplierPaymentsInMinorUnits',0,'cashExpensesInMinorUnits',0,'cliqExpensesInMinorUnits',0,'cashRefundsInMinorUnits',0,'cliqRefundsInMinorUnits',0,'expectedCashInMinorUnits',v_shift.opening_cash_in_minor_units,'actualCashInMinorUnits',NULL,'cashDiscrepancyInMinorUnits',NULL,'discrepancyReason',NULL,'status',v_shift.status,'managerSignOffBy',NULL,'cancelledByName',CASE WHEN v_shift.status='cancelled' THEN v_actor_name ELSE NULL END,'cancelledAt',v_shift.cancelled_at,'cancellationReason',v_shift.cancellation_reason,'reversedByName',CASE WHEN v_shift.status='reversed' THEN v_actor_name ELSE NULL END,'reversedAt',v_shift.reversed_at,'reversalReason',v_shift.reversal_reason,'reversalId',v_shift.reversal_id);
END; $function$

CREATE OR REPLACE FUNCTION public.get_cash_shift_summary(p_shift_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_summary JSONB;
  v_shift_status TEXT;
  v_cash_refunds BIGINT := 0;
  v_cliq_refunds BIGINT := 0;
  v_cash_opening_receipts BIGINT := 0;
  v_cliq_opening_receipts BIGINT := 0;
  v_cash_opening_supplier BIGINT := 0;
  v_cliq_opening_supplier BIGINT := 0;
  v_withdrawn BIGINT := 0;
  v_returned BIGINT := 0;
  v_comp JSONB;
BEGIN
  v_summary := public._get_cash_shift_summary_before_return_events(p_shift_id);
  SELECT status INTO v_shift_status
  FROM public.cash_shifts
  WHERE id = p_shift_id;
  SELECT effect.withdrawn_in_minor_units, effect.returned_in_minor_units
  INTO v_withdrawn, v_returned
  FROM public.owner_withdrawal_shift_effect_internal(p_shift_id) effect;
  v_summary := v_summary || jsonb_build_object(
    'ownerWithdrawalsInMinorUnits', v_withdrawn,
    'ownerWithdrawalReturnsInMinorUnits', v_returned);
  IF v_shift_status IS DISTINCT FROM 'open' THEN RETURN v_summary; END IF;
  SELECT
    COALESCE(SUM(money_refund_amount_in_minor_units) FILTER (WHERE refund_method = 'cash'), 0),
    COALESCE(SUM(money_refund_amount_in_minor_units) FILTER (WHERE refund_method = 'cliq'), 0)
  INTO v_cash_refunds, v_cliq_refunds
  FROM public.sales_return_events
  WHERE cash_shift_id = p_shift_id
    AND settlement_status = 'settled'
    AND money_refund_amount_in_minor_units > 0;
  SELECT
    COALESCE(SUM(opening_amount_in_minor_units) FILTER (WHERE payment_method = 'cash'), 0),
    COALESCE(SUM(opening_amount_in_minor_units) FILTER (WHERE payment_method = 'cliq'), 0)
  INTO v_cash_opening_receipts, v_cliq_opening_receipts
  FROM public.customer_collection_operations
  WHERE cash_shift_id = p_shift_id AND NOT is_reversed;
  SELECT
    COALESCE(SUM(payment.amount_in_minor_units) FILTER (WHERE payment.payment_method = 'cash'), 0),
    COALESCE(SUM(payment.amount_in_minor_units) FILTER (WHERE payment.payment_method = 'cliq'), 0)
  INTO v_cash_opening_supplier, v_cliq_opening_supplier
  FROM public.supplier_opening_payments link
  JOIN public.supplier_payments payment ON payment.id = link.supplier_payment_id
  WHERE link.cash_shift_id = p_shift_id AND NOT COALESCE(payment.is_reversed, false);
  v_comp:=public.cheque_shift_settlement_section_internal(p_shift_id);
  v_cash_opening_receipts:=v_cash_opening_receipts+(v_comp->>'cashReceiptsInMinorUnits')::BIGINT;
  v_cliq_opening_receipts:=v_cliq_opening_receipts+(v_comp->>'cliqReceiptsInMinorUnits')::BIGINT;
  v_cash_opening_supplier:=v_cash_opening_supplier+(v_comp->>'cashSupplierPaymentsInMinorUnits')::BIGINT;
  v_cliq_opening_supplier:=v_cliq_opening_supplier+(v_comp->>'cliqSupplierPaymentsInMinorUnits')::BIGINT;
  v_summary:=v_summary||jsonb_build_object('chequeCompensationSettlements',v_comp);
  v_summary := jsonb_set(v_summary, '{cashRefundsInMinorUnits}',
    to_jsonb(COALESCE((v_summary->>'cashRefundsInMinorUnits')::BIGINT, 0) + v_cash_refunds), true);
  v_summary := jsonb_set(v_summary, '{cliqRefundsInMinorUnits}',
    to_jsonb(COALESCE((v_summary->>'cliqRefundsInMinorUnits')::BIGINT, 0) + v_cliq_refunds), true);
  v_summary := jsonb_set(v_summary, '{cashReceiptsInMinorUnits}',
    to_jsonb(COALESCE((v_summary->>'cashReceiptsInMinorUnits')::BIGINT, 0) + v_cash_opening_receipts), true);
  v_summary := jsonb_set(v_summary, '{cliqReceiptsInMinorUnits}',
    to_jsonb(COALESCE((v_summary->>'cliqReceiptsInMinorUnits')::BIGINT, 0) + v_cliq_opening_receipts), true);
  v_summary := jsonb_set(v_summary, '{cashSupplierPaymentsInMinorUnits}',
    to_jsonb(COALESCE((v_summary->>'cashSupplierPaymentsInMinorUnits')::BIGINT, 0) + v_cash_opening_supplier), true);
  v_summary := jsonb_set(v_summary, '{cliqSupplierPaymentsInMinorUnits}',
    to_jsonb(COALESCE((v_summary->>'cliqSupplierPaymentsInMinorUnits')::BIGINT, 0) + v_cliq_opening_supplier), true);
  v_summary := v_summary || jsonb_build_object(
    'openingDebtCashReceiptsInMinorUnits', v_cash_opening_receipts-(v_comp->>'cashReceiptsInMinorUnits')::BIGINT,
    'openingDebtCliqReceiptsInMinorUnits', v_cliq_opening_receipts-(v_comp->>'cliqReceiptsInMinorUnits')::BIGINT,
    'openingSupplierCashPaymentsInMinorUnits', v_cash_opening_supplier-(v_comp->>'cashSupplierPaymentsInMinorUnits')::BIGINT,
    'openingSupplierCliqPaymentsInMinorUnits', v_cliq_opening_supplier-(v_comp->>'cliqSupplierPaymentsInMinorUnits')::BIGINT);
  RETURN jsonb_set(v_summary, '{expectedCashInMinorUnits}',
    to_jsonb(COALESCE((v_summary->>'expectedCashInMinorUnits')::BIGINT, 0)
      - v_cash_refunds + v_cash_opening_receipts - v_cash_opening_supplier
      - v_withdrawn + v_returned), true);
END;
$function$

CREATE OR REPLACE FUNCTION public.get_crm_customer_detail_page(p_customer_id uuid, p_history_page integer DEFAULT 1, p_history_page_size integer DEFAULT 25)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_result JSONB;
  v_orders JSONB;
BEGIN
  v_result := public._get_crm_customer_detail_page_before_phase42_receivables(
    p_customer_id, p_history_page, p_history_page_size
  );
  SELECT COALESCE(JSONB_AGG(
    order_row.value || JSONB_BUILD_OBJECT(
      'amount_due_in_minor_units', CASE
        WHEN order_row.value->>'status' IN ('completed', 'delivered')
          THEN COALESCE((SELECT position.outstanding_total_in_minor_units
            FROM public.phase42_order_financial_position_internal(
              (order_row.value->>'id')::UUID
            ) position), 0)
        ELSE 0
      END
    ) ORDER BY order_row.ordinality
  ), '[]'::JSONB)
  INTO v_orders
  FROM JSONB_ARRAY_ELEMENTS(COALESCE(v_result->'orders', '[]'::JSONB))
    WITH ORDINALITY order_row(value, ordinality);
  v_result := JSONB_SET(v_result, '{orders}', v_orders, true);
  v_result := JSONB_SET(
    v_result, '{stats,outstanding_in_minor_units}',
    TO_JSONB(public.phase42_customer_receivable_total_internal(p_customer_id)),
    true
  );
  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_deferred_cheque_home_alerts(p_branch_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_today DATE:=(CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Amman')::DATE;v_result JSONB;
BEGIN
  PERFORM public.assert_erp_role(ARRAY['owner','manager'],'تنبيه الشيكات');
  SELECT jsonb_build_object('dueWithinTwoDays',COUNT(*) FILTER(WHERE due_date BETWEEN v_today AND v_today+2),
    'overdue',COUNT(*) FILTER(WHERE due_date<v_today),
    'outgoingDueInMinorUnits',COALESCE(SUM(amount_in_minor_units) FILTER(WHERE direction='outgoing' AND due_date<=v_today+2),0))
  INTO v_result FROM public.deferred_cheques WHERE status='pending' AND(p_branch_id IS NULL OR branch_id=p_branch_id);
  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_expense_shift_center(p_branch_id uuid, p_expense_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_result JSONB; v_expenses JSONB; v_recent JSONB;
BEGIN
  v_result := public._get_expense_shift_center_v1(p_branch_id,p_expense_limit);
  SELECT COALESCE(jsonb_agg(public.get_cash_shift_display_summary(id) ORDER BY opened_at DESC),'[]'::JSONB) INTO v_recent FROM (SELECT id,opened_at FROM public.cash_shifts WHERE branch_id=p_branch_id AND status IN ('closed','cancelled','reversed') ORDER BY opened_at DESC LIMIT 10) r;
  SELECT COALESCE(jsonb_agg(expense_payload ORDER BY created_at DESC),'[]'::JSONB) INTO v_expenses FROM (SELECT oe.created_at,jsonb_build_object('id',oe.id,'expenseNumber',oe.expense_number,'branchId',oe.branch_id,'shiftId',oe.shift_id,'category',oe.category,'description',oe.description,'amountInMinorUnits',oe.amount_in_minor_units,'paymentMethod',oe.payment_method,'referenceNumber',oe.reference_number,'isReversed',oe.is_reversed,'reversedAt',oe.reversed_at,'reversalReason',oe.reversal_reason,'reversedByName',COALESCE(rp.full_name,''),'createdByName',COALESCE(cp.full_name,'مستخدم النظام'),'createdAt',oe.created_at) expense_payload FROM public.operational_expenses oe LEFT JOIN public.profiles cp ON cp.id=oe.created_by LEFT JOIN public.profiles rp ON rp.id=oe.reversed_by WHERE oe.branch_id=p_branch_id ORDER BY oe.created_at DESC LIMIT p_expense_limit) e;
  RETURN jsonb_set(jsonb_set(v_result,'{expenses}',v_expenses,true),'{recentShifts}',v_recent,true);
END; $function$

CREATE OR REPLACE FUNCTION public.get_home_dashboard()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_result JSONB;
  v_balances JSONB;
  v_today DATE := (now() AT TIME ZONE 'Asia/Amman')::DATE;
  v_totals JSONB;
  v_profit BIGINT;
BEGIN
  v_result := public._get_home_dashboard_before133();
  v_balances := public.phase133_supplier_balances_internal();
  v_result := jsonb_set(v_result, '{summary}', (v_result->'summary') || jsonb_build_object(
    'supplierPayablesInMinorUnits', v_balances->'supplierDueInMinorUnits',
    'supplierAdvancesInMinorUnits', v_balances->'supplierAdvancesInMinorUnits'));
  IF public.has_erp_role(ARRAY['owner']) THEN
    -- Same scope as the month profit above: all branches, Amman month to date.
    v_totals := public.owner_withdrawal_period_totals_internal(
      NULL,
      date_trunc('month', v_today)::DATE::TIMESTAMP AT TIME ZONE 'Asia/Amman',
      (v_today + 1)::TIMESTAMP AT TIME ZONE 'Asia/Amman');
    -- Unavailable profit stays unavailable: never treated as zero.
    v_profit := CASE WHEN v_result->>'financialFactsStatus' = 'available'
      THEN (v_result #>> '{summary,monthProfitInMinorUnits}')::BIGINT ELSE NULL END;
    v_result := jsonb_set(v_result, '{summary}', (v_result->'summary') || jsonb_build_object(
      'monthOwnerWithdrawalsInMinorUnits', (v_totals->>'netInMinorUnits')::BIGINT,
      'monthRemainingAfterWithdrawalsInMinorUnits', v_profit - (v_totals->>'netInMinorUnits')::BIGINT));
  END IF;
  IF public.has_erp_role(ARRAY['owner','manager']) THEN
    v_result:=v_result||jsonb_build_object('chequeAlerts',public.get_deferred_cheque_home_alerts(NULL));
  END IF;
  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_inventory_opening_setup(p_warehouse_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_payload JSONB;
  v_products JSONB;
BEGIN
  v_payload :=
    public._get_inventory_opening_setup_including_flavor_masters_v1(
