END;
$function$

CREATE OR REPLACE FUNCTION public.get_operational_business_report(p_branch_id uuid, p_date_from date, p_date_to date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_result JSONB;
  v_totals JSONB;
  v_profit BIGINT;
BEGIN
  v_result := public._get_operational_business_report_before133(p_branch_id, p_date_from, p_date_to);
