$function$

CREATE OR REPLACE FUNCTION public.phase2_validate_receipt_lines_internal(p_lines jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_line JSONB;
  v_component JSONB;
  v_line_kind TEXT;
  v_family_id UUID;
  v_configuration_id UUID;
  v_configuration_revision INTEGER;
  v_commercial_quantity INTEGER;
  v_units_per_parcel INTEGER;
  v_gross BIGINT;
  v_line_discount BIGINT;
  v_line_net BIGINT;
  v_component_count INTEGER;
  v_explicit_count INTEGER;
  v_component_quantity NUMERIC;
  v_explicit_total NUMERIC;
  v_product_id UUID;
  v_product_family UUID;
  v_is_master BOOLEAN;
  v_is_active BOOLEAN;
  v_config public.product_parcel_configurations%ROWTYPE;
  v_family public.products%ROWTYPE;
BEGIN
  IF p_lines IS NULL
    OR jsonb_typeof(p_lines) <> 'array'
    OR jsonb_array_length(p_lines) = 0
  THEN
    RAISE EXCEPTION USING
      ERRCODE = '22023',
      MESSAGE = 'PHASE2_RECEIPT_LINES_REQUIRED: يجب إضافة سطر استلام واحد على الأقل.';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_lines) line
    GROUP BY (line->>'client_line_id')::UUID
    HAVING COUNT(*) > 1
  ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '23505',
      CONSTRAINT = 'phase2_receipt_client_line_identity_unique',
      MESSAGE = 'DUPLICATE_COMMERCIAL_LINE_IDENTITY: هوية السطر التجاري مكررة.';
  END IF;

  FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines)
  LOOP
    PERFORM (v_line->>'client_line_id')::UUID;
    v_line_kind := LOWER(BTRIM(v_line->>'line_kind'));
    v_family_id := NULLIF(BTRIM(v_line->>'family_product_id'), '')::UUID;
    v_configuration_id :=
      NULLIF(BTRIM(v_line->>'parcel_configuration_id'), '')::UUID;
    v_configuration_revision :=
      NULLIF(BTRIM(v_line->>'configuration_revision'), '')::INTEGER;
    v_commercial_quantity := (v_line->>'commercial_quantity')::INTEGER;
    v_units_per_parcel :=
      NULLIF(BTRIM(v_line->>'units_per_parcel'), '')::INTEGER;
    v_gross := (v_line->>'gross_amount_in_minor_units')::BIGINT;
    v_line_discount :=
      COALESCE(NULLIF(BTRIM(v_line->>'line_discount_in_minor_units'), '')::BIGINT, 0);

    IF v_line_kind NOT IN ('base_unit', 'configurable_parcel') THEN
      RAISE EXCEPTION USING
        ERRCODE = '22023',
        MESSAGE = 'PHASE2_RECEIPT_LINE_KIND_INVALID: نوع السطر التجاري غير مدعوم.';
    END IF;
    IF v_commercial_quantity <= 0 OR v_gross < 0 OR v_line_discount < 0 THEN
      RAISE EXCEPTION USING
        ERRCODE = '22023',
        MESSAGE = 'PHASE2_RECEIPT_LINE_VALUE_INVALID: الكمية والأسعار والخصومات يجب أن تكون ضمن الحدود المسموحة.';
    END IF;
    IF v_line_discount > v_gross THEN
      RAISE EXCEPTION USING
        ERRCODE = '23514',
        CONSTRAINT = 'phase2_receipt_line_discount_check',
        MESSAGE = 'PHASE2_LINE_DISCOUNT_EXCEEDS_GROSS: خصم السطر يتجاوز إجماليه.';
    END IF;
    IF NULLIF(BTRIM(v_line->>'base_unit_name'), '') IS NULL THEN
      RAISE EXCEPTION USING
        ERRCODE = '22023',
        MESSAGE = 'PHASE2_BASE_UNIT_NAME_REQUIRED: اسم وحدة المخزون الأساسية مطلوب.';
    END IF;

    v_line_net := v_gross - v_line_discount;
    v_component_count := jsonb_array_length(COALESCE(v_line->'components', '[]'::JSONB));
    IF v_component_count = 0 THEN
      RAISE EXCEPTION USING
        ERRCODE = '22023',
        MESSAGE = 'PHASE2_RECEIPT_COMPONENTS_REQUIRED: مكونات السطر التجاري مطلوبة.';
    END IF;

    IF EXISTS (
      SELECT 1
      FROM jsonb_array_elements(v_line->'components') component
      GROUP BY (component->>'product_id')::UUID
      HAVING COUNT(*) > 1
    ) THEN
      RAISE EXCEPTION USING
        ERRCODE = '23505',
        CONSTRAINT = 'phase2_receipt_component_identity_unique',
        MESSAGE = 'DUPLICATE_COMPONENT_IDENTITY: لا يجوز تكرار نفس SKU داخل السطر التجاري.';
    END IF;

    SELECT
      COUNT(*) FILTER (
        WHERE NULLIF(BTRIM(component->>'explicit_merchandise_cost_in_minor_units'), '') IS NOT NULL
      ),
      COALESCE(SUM((component->>'base_quantity')::NUMERIC), 0),
      COALESCE(SUM(
        NULLIF(BTRIM(component->>'explicit_merchandise_cost_in_minor_units'), '')::NUMERIC
      ), 0)
    INTO v_explicit_count, v_component_quantity, v_explicit_total
    FROM jsonb_array_elements(v_line->'components') component;

    IF v_explicit_count NOT IN (0, v_component_count) THEN
      RAISE EXCEPTION USING
        ERRCODE = '23514',
        CONSTRAINT = 'phase2_component_cost_completeness_check',
        MESSAGE = 'PARTIAL_EXPLICIT_COMPONENT_COST: يجب إدخال تكلفة كل المكونات أو عدم إدخالها كلها.';
    END IF;
    IF v_explicit_count = v_component_count
      AND v_explicit_total IS DISTINCT FROM v_line_net::NUMERIC
    THEN
      RAISE EXCEPTION USING
        ERRCODE = '23514',
        CONSTRAINT = 'phase2_component_merchandise_cost_total_check',
        MESSAGE = 'EXPLICIT_COMPONENT_COST_MISMATCH: تكاليف المكونات لا تطابق صافي السطر التجاري.';
    END IF;

    FOR v_component IN SELECT * FROM jsonb_array_elements(v_line->'components')
    LOOP
      v_product_id := (v_component->>'product_id')::UUID;
      IF (v_component->>'base_quantity')::INTEGER <= 0 THEN
        RAISE EXCEPTION USING
          ERRCODE = '22023',
          MESSAGE = 'PHASE2_COMPONENT_QUANTITY_INVALID: كمية مكون SKU يجب أن تكون موجبة.';
      END IF;
      IF NULLIF(BTRIM(v_component->>'explicit_merchandise_cost_in_minor_units'), '')::BIGINT < 0 THEN
        RAISE EXCEPTION USING
          ERRCODE = '22023',
          MESSAGE = 'PHASE2_COMPONENT_COST_INVALID: تكلفة مكون SKU لا يمكن أن تكون سالبة.';
      END IF;

      SELECT
        COALESCE(product.flavor_master_product_id, product.id),
        product.is_flavor_master,
        product.is_active
      INTO v_product_family, v_is_master, v_is_active
      FROM public.products product
      WHERE product.id = v_product_id;

      IF NOT FOUND OR NOT v_is_active OR v_is_master THEN
        RAISE EXCEPTION USING
          ERRCODE = '23514',
          CONSTRAINT = 'phase2_receipt_stocked_sku_check',
          MESSAGE = 'PHASE2_STOCKED_SKU_REQUIRED: الاستلام يقبل SKU مخزنيًا نشطًا فقط.';
      END IF;
      IF v_line_kind = 'configurable_parcel'
        AND v_product_family IS DISTINCT FROM v_family_id
      THEN
        RAISE EXCEPTION USING
          ERRCODE = '23514',
          CONSTRAINT = 'phase2_receipt_component_family_check',
          MESSAGE = 'PHASE2_COMPONENT_FAMILY_MISMATCH: مكون الطرد خارج العائلة التجارية.';
      END IF;
    END LOOP;

    IF v_component_quantity > 2147483647::NUMERIC THEN
      RAISE EXCEPTION USING
        ERRCODE = '22003',
        MESSAGE = 'PHASE2_COMPONENT_QUANTITY_OVERFLOW: إجمالي كمية المكونات يتجاوز الحد المدعوم.';
    END IF;

    IF v_line_kind = 'base_unit' THEN
      IF v_family_id IS NOT NULL
        OR v_configuration_id IS NOT NULL
        OR v_configuration_revision IS NOT NULL
        OR v_units_per_parcel IS NOT NULL
        OR NULLIF(BTRIM(v_line->>'parcel_unit_name'), '') IS NOT NULL
        OR v_component_count <> 1
        OR v_component_quantity <> v_commercial_quantity::NUMERIC
      THEN
        RAISE EXCEPTION USING
          ERRCODE = '23514',
          CONSTRAINT = 'phase2_base_unit_line_shape_check',
          MESSAGE = 'PHASE2_BASE_UNIT_LINE_INVALID: سطر الوحدة الأساسية يجب أن يحتوي SKU واحدًا وكمية مطابقة.';
      END IF;
    ELSE
      PERFORM public.assert_configurable_parcel_creation_allowed();

      SELECT * INTO v_config
      FROM public.product_parcel_configurations configuration
      WHERE configuration.id = v_configuration_id
      FOR SHARE;
      SELECT * INTO v_family
      FROM public.products product
      WHERE product.id = v_family_id
      FOR SHARE;

      IF v_config.id IS NULL
        OR NOT v_config.is_active
        OR v_config.composition_mode <> 'configurable_mix'
        OR v_config.family_product_id IS DISTINCT FROM v_family_id
        OR v_config.configuration_revision IS DISTINCT FROM v_configuration_revision
        OR v_family.id IS NULL
        OR NOT v_family.is_flavor_master
        OR v_units_per_parcel IS DISTINCT FROM v_family.units_per_sale_unit
        OR NULLIF(BTRIM(v_line->>'parcel_unit_name'), '') IS NULL
      THEN
        RAISE EXCEPTION USING
          ERRCODE = '23514',
          CONSTRAINT = 'phase2_receipt_parcel_configuration_check',
          MESSAGE = 'PHASE2_PARCEL_CONFIGURATION_MISMATCH: إعداد الطرد أو نسخته أو سعته غير متطابقة.';
      END IF;

      IF v_component_quantity
        <> v_commercial_quantity::NUMERIC * v_units_per_parcel::NUMERIC
      THEN
        RAISE EXCEPTION USING
          ERRCODE = '23514',
          CONSTRAINT = 'phase2_receipt_parcel_capacity_check',
          MESSAGE = 'PHASE2_PARCEL_CAPACITY_MISMATCH: مجموع وحدات الطرد لا يطابق العدد والسعة.';
      END IF;
    END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.phase3_actor_scope_hash_internal(p_actor_scope_type text, p_erp_user_id uuid DEFAULT NULL::uuid, p_guest_phone_hash text DEFAULT NULL::text, p_guest_session_hash text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_scope_type TEXT := LOWER(NULLIF(BTRIM(p_actor_scope_type), ''));
  v_material TEXT;
BEGIN
  IF v_scope_type = 'erp_user' THEN
    IF p_erp_user_id IS NULL OR p_guest_phone_hash IS NOT NULL
      OR p_guest_session_hash IS NOT NULL
    THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001',
        MESSAGE = 'PHASE3_ACTOR_SCOPE_INVALID: ERP actor scope is malformed.';
    END IF;
    v_material := 'phase3:erp_user:v1|' || LOWER(p_erp_user_id::TEXT);
  ELSIF v_scope_type = 'guest_gateway' THEN
    IF p_erp_user_id IS NOT NULL
      OR COALESCE(p_guest_phone_hash, '') !~ '^[0-9a-f]{64}$'
      OR COALESCE(p_guest_session_hash, '') !~ '^[0-9a-f]{64}$'
    THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001',
        MESSAGE = 'PHASE3_ACTOR_SCOPE_INVALID: Guest actor scope is malformed.';
    END IF;
    v_material := 'phase3:guest_gateway:v1|'
      || p_guest_phone_hash || '|' || p_guest_session_hash;
  ELSIF v_scope_type = 'system_job' THEN
    IF p_erp_user_id IS NOT NULL OR p_guest_phone_hash IS NOT NULL
      OR p_guest_session_hash IS NOT NULL
    THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001',
        MESSAGE = 'PHASE3_ACTOR_SCOPE_INVALID: System actor scope is malformed.';
    END IF;
    v_material := 'phase3:system_job:v1|customer-reservation-lifecycle';
  ELSE
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_ACTOR_SCOPE_INVALID: Unsupported actor scope.';
  END IF;

  RETURN ENCODE(extensions.digest(v_material, 'sha256'::TEXT), 'hex');
END;
$function$

CREATE OR REPLACE FUNCTION public.phase3_assert_configurable_parcel_creation_allowed_internal(p_actor_scope_type text, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_scope_type TEXT := LOWER(NULLIF(BTRIM(p_actor_scope_type), ''));
  v_state TEXT := public.get_configurable_parcel_feature_state();
BEGIN
  IF v_scope_type = 'erp_user' THEN
    IF p_actor_user_id IS NULL
      OR auth.uid() IS NULL
      OR p_actor_user_id IS DISTINCT FROM auth.uid()
      OR NOT public.is_active_erp_staff()
    THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001',
        MESSAGE = 'PHASE3_ACTOR_NOT_AUTHORIZED: ERP actor is not authorized.';
    END IF;
  ELSIF v_scope_type = 'guest_gateway' THEN
    IF p_actor_user_id IS NOT NULL OR auth.role() IS DISTINCT FROM 'service_role' THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001',
        MESSAGE = 'PHASE3_ACTOR_NOT_AUTHORIZED: Guest gateway proof is invalid.';
    END IF;
  ELSE
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_ACTOR_NOT_AUTHORIZED: Unsupported actor scope.';
  END IF;

  IF v_state = 'ENABLED' THEN
    RETURN;
  END IF;
  IF v_state = 'OWNER_PILOT'
    AND v_scope_type = 'erp_user'
    AND public.has_erp_role(ARRAY['owner'])
  THEN
    RETURN;
  END IF;

  RAISE EXCEPTION USING ERRCODE = 'P0001',
    MESSAGE = 'CONFIGURABLE_PARCEL_DISABLED: الوظيفة غير مفعلة لإنشاء عمليات جديدة.';
END;
$function$

CREATE OR REPLACE FUNCTION public.phase3_canonicalize_components_internal(p_components jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_component JSONB;
  v_total BIGINT;
  v_result JSONB;
BEGIN
  IF JSONB_TYPEOF(p_components) IS DISTINCT FROM 'array'
    OR JSONB_ARRAY_LENGTH(p_components) = 0
  THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_SALE_CONTRACT_INVALID: Parcel components must be a non-empty array.';
  END IF;
  IF JSONB_ARRAY_LENGTH(p_components) > 200 THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_SALE_REQUEST_LIMIT_EXCEEDED: Parcel component entry limit exceeded.';
  END IF;

  FOR v_component IN SELECT value FROM JSONB_ARRAY_ELEMENTS(p_components)
  LOOP
    IF JSONB_TYPEOF(v_component) IS DISTINCT FROM 'object' THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001',
        MESSAGE = 'PHASE3_SALE_CONTRACT_INVALID: Parcel component must be an object.';
    END IF;
    PERFORM public.phase3_require_uuid_internal(
      v_component->>'product_id', 'component product_id'
    );
    PERFORM public.phase3_require_positive_integer_internal(
      v_component->>'base_quantity', 'component base_quantity'
    );
  END LOOP;

  SELECT SUM(quantity), JSONB_AGG(
    JSONB_BUILD_OBJECT(
      'product_id', LOWER(product_id::TEXT),
      'base_quantity', quantity
    )
    ORDER BY product_id
  )
  INTO v_total, v_result
  FROM (
    SELECT
      (component->>'product_id')::UUID AS product_id,
      SUM((component->>'base_quantity')::BIGINT) AS quantity
    FROM JSONB_ARRAY_ELEMENTS(p_components) component
    GROUP BY (component->>'product_id')::UUID
  ) normalized;

  IF v_total > 2147483647
    OR EXISTS (
      SELECT 1
      FROM JSONB_ARRAY_ELEMENTS(v_result) component
      WHERE (component->>'base_quantity')::NUMERIC > 2147483647
    )
  THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_SALE_CONTRACT_INVALID: Parcel component quantity exceeds integer capacity.';
  END IF;

  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.phase3_canonicalize_sale_request_internal(p_request jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor_scope_type TEXT;
  v_actor_scope_hash TEXT;
  v_source TEXT;
  v_lines JSONB;
  v_line JSONB;
  v_line_kind TEXT;
  v_canonical_lines JSONB := '[]'::JSONB;
  v_canonical_line JSONB;
  v_instances JSONB;
  v_instance JSONB;
  v_canonical_instances JSONB;
  v_canonical_components JSONB;
  v_instance_fingerprint TEXT;
  v_line_discount BIGINT;
  v_price_override BIGINT;
  v_price_authority TEXT;
  v_total_commercial_quantity BIGINT := 0;
  v_total_instances INTEGER := 0;
  v_branch_id UUID;
  v_customer_id UUID;
  v_customer_hash TEXT;
  v_delivery_hash TEXT;
  v_amount_received BIGINT;
BEGIN
  IF JSONB_TYPEOF(p_request) IS DISTINCT FROM 'object'
    OR p_request->>'contract_version' IS DISTINCT FROM 'phase3-sale-v1'
  THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_SALE_CONTRACT_INVALID: Unsupported sale contract version.';
  END IF;

  v_actor_scope_type := LOWER(NULLIF(BTRIM(p_request->>'actor_scope_type'), ''));
  v_actor_scope_hash := LOWER(NULLIF(BTRIM(p_request->>'actor_scope_hash'), ''));
  v_source := LOWER(NULLIF(BTRIM(p_request->>'operation_source'), ''));
  IF v_actor_scope_type NOT IN ('erp_user', 'guest_gateway')
    OR COALESCE(v_actor_scope_hash, '') !~ '^[0-9a-f]{64}$'
    OR v_source NOT IN ('admin_pos', 'customer_reservation')
  THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_SALE_CONTRACT_INVALID: Actor or operation source is invalid.';
  END IF;

  PERFORM public.phase3_require_uuid_internal(
    p_request->>'warehouse_id', 'warehouse_id'
  );
  IF NULLIF(BTRIM(p_request->>'branch_id'), '') IS NOT NULL THEN
    v_branch_id := public.phase3_require_uuid_internal(
      p_request->>'branch_id', 'branch_id'
    );
  END IF;
  IF NULLIF(BTRIM(p_request->>'customer_id'), '') IS NOT NULL THEN
    v_customer_id := public.phase3_require_uuid_internal(
      p_request->>'customer_id', 'customer_id'
    );
  END IF;

  v_customer_hash := LOWER(NULLIF(BTRIM(p_request->>'customer_identity_hash'), ''));
  v_delivery_hash := LOWER(NULLIF(BTRIM(p_request->>'delivery_identity_hash'), ''));
  IF (v_customer_hash IS NOT NULL AND v_customer_hash !~ '^[0-9a-f]{64}$')
    OR (v_delivery_hash IS NOT NULL AND v_delivery_hash !~ '^[0-9a-f]{64}$')
  THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_SALE_CONTRACT_INVALID: Privacy-safe customer or delivery identity is invalid.';
  END IF;

  IF NULLIF(BTRIM(p_request->>'amount_received_in_minor_units'), '') IS NOT NULL THEN
    v_amount_received := public.phase3_require_nonnegative_bigint_internal(
      p_request->>'amount_received_in_minor_units',
      'amount_received_in_minor_units'
    );
  END IF;

  v_lines := p_request->'lines';
  IF JSONB_TYPEOF(v_lines) IS DISTINCT FROM 'array'
    OR JSONB_ARRAY_LENGTH(v_lines) = 0
  THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_SALE_CONTRACT_INVALID: Sale lines must be a non-empty array.';
  END IF;
  IF JSONB_ARRAY_LENGTH(v_lines) > 50 THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_SALE_REQUEST_LIMIT_EXCEEDED: Commercial line limit exceeded.';
  END IF;

  FOR v_line IN SELECT value FROM JSONB_ARRAY_ELEMENTS(v_lines)
  LOOP
    IF JSONB_TYPEOF(v_line) IS DISTINCT FROM 'object' THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001',
        MESSAGE = 'PHASE3_SALE_CONTRACT_INVALID: Sale line must be an object.';
    END IF;
    v_line_kind := LOWER(NULLIF(BTRIM(v_line->>'commercial_line_kind'), ''));
    IF v_line_kind NOT IN (
      'base_unit', 'legacy_single_sku_parcel', 'configurable_parcel'
    ) THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001',
        MESSAGE = 'PHASE3_SALE_CONTRACT_INVALID: Unsupported commercial line kind.';
    END IF;

    v_line_discount := public.phase3_require_nonnegative_bigint_internal(
      COALESCE(NULLIF(BTRIM(v_line->>'line_discount_in_minor_units'), ''), '0'),
      'line_discount_in_minor_units'
    );
    v_price_authority := LOWER(COALESCE(
      NULLIF(BTRIM(v_line->>'price_authority'), ''), 'server_catalog'
    ));
    v_price_override := NULL;
    IF NULLIF(BTRIM(v_line->>'commercial_unit_price_override_in_minor_units'), '')
      IS NOT NULL
    THEN
      v_price_override := public.phase3_require_nonnegative_bigint_internal(
        v_line->>'commercial_unit_price_override_in_minor_units',
        'commercial_unit_price_override_in_minor_units'
      );
    END IF;
    IF (v_price_authority = 'server_catalog' AND v_price_override IS NOT NULL)
      OR (v_price_authority = 'authorized_override' AND v_price_override IS NULL)
      OR v_price_authority NOT IN ('server_catalog', 'authorized_override')
    THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001',
        MESSAGE = 'PHASE3_SALE_CONTRACT_INVALID: Price authority and override are inconsistent.';
    END IF;

    IF v_line_kind = 'base_unit' THEN
      v_canonical_line := JSONB_BUILD_OBJECT(
        'commercial_line_kind', v_line_kind,
        'product_id', LOWER(public.phase3_require_uuid_internal(
          v_line->>'product_id', 'base-unit product_id'
        )::TEXT),
        'base_quantity', public.phase3_require_positive_integer_internal(
          v_line->>'base_quantity', 'base_quantity'
        ),
        'price_authority', v_price_authority,
        'commercial_unit_price_override_in_minor_units', v_price_override,
        'line_discount_in_minor_units', v_line_discount
      );
      v_total_commercial_quantity := v_total_commercial_quantity
        + (v_canonical_line->>'base_quantity')::INTEGER;
    ELSIF v_line_kind = 'legacy_single_sku_parcel' THEN
      v_canonical_line := JSONB_BUILD_OBJECT(
        'commercial_line_kind', v_line_kind,
        'product_id', LOWER(public.phase3_require_uuid_internal(
          v_line->>'product_id', 'legacy parcel product_id'
        )::TEXT),
        'parcel_quantity', public.phase3_require_positive_integer_internal(
          v_line->>'parcel_quantity', 'parcel_quantity'
        ),
        'units_per_parcel', public.phase3_require_positive_integer_internal(
          v_line->>'units_per_parcel', 'units_per_parcel'
        ),
        'price_authority', v_price_authority,
        'commercial_unit_price_override_in_minor_units', v_price_override,
        'line_discount_in_minor_units', v_line_discount
      );
      v_total_commercial_quantity := v_total_commercial_quantity
        + (v_canonical_line->>'parcel_quantity')::INTEGER;
    ELSE
      v_instances := v_line->'parcel_instances';
      IF JSONB_TYPEOF(v_instances) IS DISTINCT FROM 'array'
        OR JSONB_ARRAY_LENGTH(v_instances) = 0
      THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001',
          MESSAGE = 'PHASE3_SALE_CONTRACT_INVALID: Configurable Parcel requires instances.';
      END IF;
      IF JSONB_ARRAY_LENGTH(v_instances) > 200
        OR v_total_instances + JSONB_ARRAY_LENGTH(v_instances) > 200
      THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001',
          MESSAGE = 'PHASE3_SALE_REQUEST_LIMIT_EXCEEDED: Parcel Instance limit exceeded.';
      END IF;

      v_canonical_instances := '[]'::JSONB;
      FOR v_instance IN SELECT value FROM JSONB_ARRAY_ELEMENTS(v_instances)
      LOOP
        IF JSONB_TYPEOF(v_instance) IS DISTINCT FROM 'object' THEN
          RAISE EXCEPTION USING ERRCODE = 'P0001',
            MESSAGE = 'PHASE3_SALE_CONTRACT_INVALID: Parcel Instance must be an object.';
        END IF;
        v_canonical_components := public.phase3_canonicalize_components_internal(
          v_instance->'components'
        );
        v_instance_fingerprint := public.phase3_request_fingerprint_internal(
          v_canonical_components
        );
        v_canonical_instances := v_canonical_instances || JSONB_BUILD_ARRAY(
          JSONB_BUILD_OBJECT(
            'composition_fingerprint', v_instance_fingerprint,
            'components', v_canonical_components
          )
        );
      END LOOP;

      SELECT JSONB_AGG(
        JSONB_BUILD_OBJECT(
          'instance_sequence', sequence,
          'composition_fingerprint', item->>'composition_fingerprint',
          'components', item->'components'
        )
        ORDER BY sequence
      )
      INTO v_canonical_instances
      FROM (
        SELECT
          value AS item,
          ROW_NUMBER() OVER (
            ORDER BY value->>'composition_fingerprint', value::TEXT
          )::INTEGER AS sequence
        FROM JSONB_ARRAY_ELEMENTS(v_canonical_instances)
      ) ordered_instances;

      v_canonical_line := JSONB_BUILD_OBJECT(
        'commercial_line_kind', v_line_kind,
        'family_product_id', LOWER(public.phase3_require_uuid_internal(
          v_line->>'family_product_id', 'family_product_id'
        )::TEXT),
        'parcel_configuration_id', LOWER(public.phase3_require_uuid_internal(
          v_line->>'parcel_configuration_id', 'parcel_configuration_id'
        )::TEXT),
        'configuration_revision', public.phase3_require_positive_integer_internal(
          v_line->>'configuration_revision', 'configuration_revision'
        ),
        'parcel_quantity', JSONB_ARRAY_LENGTH(v_canonical_instances),
        'parcel_instances', v_canonical_instances,
        'price_authority', v_price_authority,
        'commercial_unit_price_override_in_minor_units', v_price_override,
        'line_discount_in_minor_units', v_line_discount
      );
      v_total_instances := v_total_instances
        + JSONB_ARRAY_LENGTH(v_canonical_instances);
      v_total_commercial_quantity := v_total_commercial_quantity
        + JSONB_ARRAY_LENGTH(v_canonical_instances);
    END IF;

    v_canonical_lines := v_canonical_lines || JSONB_BUILD_ARRAY(v_canonical_line);
  END LOOP;

  IF v_total_commercial_quantity > 10000 THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_SALE_REQUEST_LIMIT_EXCEEDED: Total commercial quantity limit exceeded.';
  END IF;

  SELECT JSONB_AGG(value ORDER BY value::TEXT)
  INTO v_canonical_lines
  FROM JSONB_ARRAY_ELEMENTS(v_canonical_lines);

  RETURN JSONB_BUILD_OBJECT(
    'contract_version', 'phase3-sale-v1',
    'actor_scope_type', v_actor_scope_type,
    'actor_scope_hash', v_actor_scope_hash,
    'operation_source', v_source,
    'warehouse_id', LOWER((p_request->>'warehouse_id')::UUID::TEXT),
    'branch_id', CASE WHEN v_branch_id IS NULL THEN NULL ELSE LOWER(v_branch_id::TEXT) END,
    'customer_id', CASE WHEN v_customer_id IS NULL THEN NULL ELSE LOWER(v_customer_id::TEXT) END,
    'customer_identity_hash', v_customer_hash,
    'delivery_identity_hash', v_delivery_hash,
    'payment_method', LOWER(NULLIF(BTRIM(p_request->>'payment_method'), '')),
    'delivery_zone', LOWER(NULLIF(BTRIM(p_request->>'delivery_zone'), '')),
    'promotion_code', UPPER(NULLIF(BTRIM(p_request->>'promotion_code'), '')),
    'order_discount_in_minor_units',
      public.phase3_require_nonnegative_bigint_internal(
        COALESCE(NULLIF(BTRIM(p_request->>'order_discount_in_minor_units'), ''), '0'),
        'order_discount_in_minor_units'
      ),
    'amount_received_in_minor_units', v_amount_received,
    'lines', v_canonical_lines
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.phase3_customer_line_identity_internal(p_line jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_kind TEXT := LOWER(NULLIF(BTRIM(p_line->>'commercial_line_kind'), ''));
BEGIN
  IF v_kind = 'base_unit' THEN
    RETURN 'base_unit:' || LOWER(public.phase3_require_uuid_internal(
      p_line->>'product_id', 'quote product_id'
    )::TEXT);
  ELSIF v_kind = 'legacy_single_sku_parcel' THEN
    RETURN 'legacy_single_sku_parcel:' || LOWER(public.phase3_require_uuid_internal(
      p_line->>'product_id', 'quote product_id'
    )::TEXT);
  ELSIF v_kind = 'configurable_parcel' THEN
    RETURN 'configurable_parcel:'
      || LOWER(public.phase3_require_uuid_internal(
        p_line->>'family_product_id', 'quote family_product_id'
      )::TEXT) || ':'
      || LOWER(public.phase3_require_uuid_internal(
        p_line->>'parcel_configuration_id', 'quote parcel_configuration_id'
      )::TEXT) || ':'
      || public.phase3_require_positive_integer_internal(
        p_line->>'configuration_revision', 'quote configuration_revision'
      )::TEXT;
  END IF;
  RAISE EXCEPTION USING ERRCODE = 'P0001',
    MESSAGE = 'PHASE3_SALE_CONTRACT_INVALID: Unsupported Customer line kind.';
END;
$function$

CREATE OR REPLACE FUNCTION public.phase3_expire_customer_order_v2_internal(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_key TEXT := 'expiry:' || LOWER(p_order_id::TEXT);
  v_actor_hash TEXT := public.phase3_actor_scope_hash_internal(
    'system_job', NULL, NULL, NULL
  );
  v_request JSONB := JSONB_BUILD_OBJECT(
    'contract_version', 'phase3-customer-expiry-v1',
    'order_id', LOWER(p_order_id::TEXT)
  );
  v_fingerprint TEXT;
  v_replay JSONB;
  v_operation_id UUID := gen_random_uuid();
  v_reason CONSTANT TEXT := 'انتهت مهلة حجز طلب الموقع (5 ساعات) قبل قبول الطلب.';
BEGIN
  v_fingerprint := public.phase3_request_fingerprint_internal(v_request);
  v_replay := public.phase3_resolve_operation_replay_internal(
    'phase3_customer_expiry_v1', v_key, 'system_job', v_actor_hash, v_fingerprint
  );
  IF v_replay->>'decision' = 'REPLAY' THEN
    RETURN v_replay->'result_snapshot';
  END IF;
  RETURN public.phase3_release_customer_reservations_internal(
    p_order_id, v_operation_id, 'phase3_customer_expiry_v1', v_key,
    v_fingerprint, v_request, 'system_job', v_actor_hash, NULL,
    'released', v_reason
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.phase3_lock_open_pos_shift_internal(p_branch_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_shift_id UUID;
BEGIN
  IF p_branch_id IS NULL THEN
    RAISE EXCEPTION 'لا يمكن تنفيذ البيع المباشر دون فرع محدد.';
  END IF;

  SELECT shift.id INTO v_shift_id
  FROM public.cash_shifts shift
  WHERE shift.branch_id = p_branch_id
    AND shift.status = 'open'
  ORDER BY shift.id
  LIMIT 1;

  IF v_shift_id IS NULL THEN
    RAISE EXCEPTION 'افتح وردية الصندوق أولاً قبل إتمام البيع المباشر.';
  END IF;

  -- Full-shift reversal and POS reversal already serialize on this key before
  -- taking the shift row.  Joining that gate prevents the historical
  -- Inventory -> Shift / Shift -> Inventory cycle without changing V1 data or
  -- its caller-visible contract.
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'cash-shift-full-reversal:' || v_shift_id::TEXT,
    0
  ));

  PERFORM shift.id
  FROM public.cash_shifts shift
  WHERE shift.id = v_shift_id
    AND shift.branch_id = p_branch_id
    AND shift.status = 'open'
  FOR SHARE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'افتح وردية الصندوق أولاً قبل إتمام البيع المباشر.';
  END IF;

  RETURN v_shift_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.phase3_release_customer_reservations_internal(p_order_id uuid, p_lifecycle_operation_id uuid, p_operation_type text, p_idempotency_key text, p_request_fingerprint text, p_request_snapshot jsonb, p_actor_scope_type text, p_actor_scope_hash text, p_initiated_by uuid, p_terminal_state text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_order public.orders%ROWTYPE;
  v_product_ids UUID[];
  v_demand RECORD;
  v_now TIMESTAMPTZ := NOW();
  v_result JSONB;
  v_target_order_status TEXT;
  v_target_reservation_state TEXT;
BEGIN
  IF p_operation_type NOT IN (
      'phase3_customer_cancellation_v1', 'phase3_customer_expiry_v1'
    ) OR p_terminal_state NOT IN ('cancelled', 'released')
    OR (p_operation_type = 'phase3_customer_cancellation_v1'
      AND p_terminal_state <> 'cancelled')
    OR (p_operation_type = 'phase3_customer_expiry_v1'
      AND p_terminal_state <> 'released')
  THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_CUSTOMER_LIFECYCLE_INVALID: Release protocol is invalid.';
  END IF;
  v_target_order_status := CASE WHEN p_terminal_state = 'released'
    THEN 'expired' ELSE 'cancelled' END;
  v_target_reservation_state := p_terminal_state;

  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND OR NOT EXISTS (
    SELECT 1 FROM public.business_operations operation
    WHERE operation.id = v_order.operation_id
      AND operation.operation_type = 'phase3_customer_reservation_v1'
  ) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_CUSTOMER_LIFECYCLE_CONTRACT_MISMATCH: Order is not Customer V2.';
  END IF;
  IF v_order.status = 'completed' OR v_order.cost_finalized_at IS NOT NULL THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_CUSTOMER_LIFECYCLE_INVALID: Completed order cannot release reservations.';
  END IF;
  IF p_terminal_state = 'released' AND (
    v_order.status <> 'new' OR v_order.reservation_expires_at IS NULL
      OR v_order.reservation_expires_at > NOW()
  ) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_CUSTOMER_LIFECYCLE_INVALID: Order is not eligible for expiry.';
  END IF;

  SELECT ARRAY_AGG(DISTINCT reservation.product_id ORDER BY reservation.product_id)
  INTO v_product_ids FROM public.order_inventory_reservations reservation
  WHERE reservation.order_id = p_order_id
    AND reservation.reservation_state = 'active';
  IF COALESCE(CARDINALITY(v_product_ids), 0) = 0 THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_CUSTOMER_RESERVATION_TERMINAL: No active reservation remains.';
  END IF;
  PERFORM public.phase3_lock_inventory_products_internal(v_product_ids);
  PERFORM 1 FROM public.inventory_balances balance
  WHERE balance.warehouse_id = v_order.warehouse_id
    AND balance.product_id = ANY(v_product_ids)
  ORDER BY balance.product_id FOR UPDATE;

  FOR v_demand IN
    SELECT reservation.product_id,
      SUM(reservation.reserved_quantity)::INTEGER quantity
    FROM public.order_inventory_reservations reservation
    WHERE reservation.order_id = p_order_id
      AND reservation.reservation_state = 'active'
    GROUP BY reservation.product_id ORDER BY reservation.product_id
  LOOP
    UPDATE public.inventory_balances balance
    SET reserved_quantity = balance.reserved_quantity - v_demand.quantity,
      updated_at = v_now
    WHERE balance.warehouse_id = v_order.warehouse_id
      AND balance.product_id = v_demand.product_id
      AND balance.reserved_quantity >= v_demand.quantity;
    IF NOT FOUND THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001',
        MESSAGE = 'PHASE3_CUSTOMER_RESERVATION_MISMATCH: Reserved quantity cannot be released.';
    END IF;
  END LOOP;
  UPDATE public.order_inventory_reservations SET
    reservation_state = v_target_reservation_state, resolved_at = v_now
  WHERE order_id = p_order_id AND reservation_state = 'active';
  PERFORM SET_CONFIG(
    'nawasrah.customer_lifecycle_operation_id',
    p_lifecycle_operation_id::TEXT, true
  );
  INSERT INTO public.phase3_customer_lifecycle_transition_guards(
    transaction_id, lifecycle_operation_id, order_id, target_status
  ) VALUES (
    pg_current_xact_id(), p_lifecycle_operation_id, p_order_id,
    v_target_order_status
  );
  UPDATE public.orders SET
    status = v_target_order_status, reservation_released_at = v_now,
    expired_at = CASE WHEN v_target_order_status = 'expired' THEN v_now ELSE expired_at END,
    expired_reason = CASE WHEN v_target_order_status = 'expired'
      THEN p_reason ELSE expired_reason END,
    updated_at = v_now
  WHERE id = p_order_id;
  DELETE FROM public.phase3_customer_lifecycle_transition_guards
  WHERE transaction_id = pg_current_xact_id()
    AND lifecycle_operation_id = p_lifecycle_operation_id;

  INSERT INTO public.order_status_history(order_id, old_status, new_status, changed_by, notes)
  VALUES (p_order_id, v_order.status, v_target_order_status, p_initiated_by, p_reason);
  v_result := JSONB_BUILD_OBJECT(
    'success', true, 'idempotent_replay', false,
    'operation_id', p_lifecycle_operation_id, 'order_id', p_order_id,
    'order_number', v_order.order_number, 'status', v_target_order_status,
    'reservation_state', v_target_reservation_state,
    'released_reservations', (SELECT COUNT(*)
      FROM public.order_inventory_reservations
      WHERE order_id = p_order_id
        AND reservation_state = v_target_reservation_state),
    'message', CASE WHEN v_target_order_status = 'expired'
      THEN 'انتهت صلاحية طلب V2 وتم تحرير الحجز.'
      ELSE 'تم إلغاء طلب V2 وتحرير الحجز.' END
  );
  INSERT INTO public.business_operations(
    id, operation_type, idempotency_key, request_fingerprint, initiated_by,
    result_snapshot, completed_at, request_identity_version,
    request_identity_snapshot, actor_scope_type, actor_scope_hash
  ) VALUES (
    p_lifecycle_operation_id, p_operation_type, p_idempotency_key,
    p_request_fingerprint, p_initiated_by, v_result, v_now, 301,
    p_request_snapshot, p_actor_scope_type, p_actor_scope_hash
  );
  INSERT INTO public.audit_logs(user_id, action, entity_name, entity_id, details)
  VALUES (p_initiated_by, UPPER(p_operation_type), 'orders', p_order_id,
    JSONB_BUILD_OBJECT('operation_id', p_lifecycle_operation_id,
      'creation_operation_id', v_order.operation_id,
      'reservation_state', v_target_reservation_state));
  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.phase3_require_nonnegative_bigint_internal(p_value text, p_field text)
 RETURNS bigint
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_value NUMERIC;
BEGIN
  IF COALESCE(BTRIM(p_value), '') !~ '^(0|[1-9][0-9]*)$' THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_SALE_CONTRACT_INVALID: Invalid nonnegative ' || p_field || '.';
  END IF;
  v_value := BTRIM(p_value)::NUMERIC;
  IF v_value > 9223372036854775807 THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_SALE_CONTRACT_INVALID: ' || p_field || ' exceeds bigint capacity.';
  END IF;
  RETURN v_value::BIGINT;
END;
$function$

CREATE OR REPLACE FUNCTION public.phase3_require_positive_integer_internal(p_value text, p_field text)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_value NUMERIC;
BEGIN
  IF COALESCE(BTRIM(p_value), '') !~ '^[1-9][0-9]*$' THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_SALE_CONTRACT_INVALID: Invalid positive ' || p_field || '.';
  END IF;
  v_value := BTRIM(p_value)::NUMERIC;
  IF v_value > 2147483647 THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_SALE_CONTRACT_INVALID: ' || p_field || ' exceeds integer capacity.';
  END IF;
  RETURN v_value::INTEGER;
END;
$function$

CREATE OR REPLACE FUNCTION public.phase3_resolve_operation_replay_internal(p_operation_type text, p_idempotency_key text, p_actor_scope_type text, p_actor_scope_hash text, p_request_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_operation public.business_operations%ROWTYPE;
  v_operation_type TEXT := LOWER(NULLIF(BTRIM(p_operation_type), ''));
  v_key TEXT := NULLIF(BTRIM(p_idempotency_key), '');
  v_scope_type TEXT := LOWER(NULLIF(BTRIM(p_actor_scope_type), ''));
  v_scope_hash TEXT := LOWER(NULLIF(BTRIM(p_actor_scope_hash), ''));
  v_fingerprint TEXT := LOWER(NULLIF(BTRIM(p_request_fingerprint), ''));
BEGIN
  IF v_operation_type NOT IN (
    'phase3_pos_sale_v1', 'phase3_customer_reservation_v1',
    'phase3_customer_completion_v1', 'phase3_customer_cancellation_v1',
    'phase3_customer_expiry_v1'
  ) OR v_key IS NULL OR CHAR_LENGTH(v_key) > 255
    OR v_scope_type NOT IN ('erp_user', 'guest_gateway', 'system_job')
    OR COALESCE(v_scope_hash, '') !~ '^[0-9a-f]{64}$'
    OR COALESCE(v_fingerprint, '') !~ '^[0-9a-f]{64}$'
  THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_IDEMPOTENCY_INPUT_INVALID: Invalid operation identity.';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(
    'phase3-operation:' || v_operation_type || ':' || v_key, 0
  ));

  SELECT * INTO v_operation
  FROM public.business_operations operation
  WHERE operation.operation_type = v_operation_type
    AND operation.idempotency_key = v_key
  FOR SHARE;

  IF NOT FOUND THEN
    RETURN JSONB_BUILD_OBJECT('decision', 'NEW');
  END IF;
  IF v_operation.actor_scope_type IS DISTINCT FROM v_scope_type
    OR v_operation.actor_scope_hash IS DISTINCT FROM v_scope_hash
    OR v_operation.request_fingerprint IS DISTINCT FROM v_fingerprint
  THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_IDEMPOTENCY_CONFLICT: Operation identity is unavailable.';
  END IF;
  IF v_operation.request_identity_version IS DISTINCT FROM 301
    OR v_operation.request_identity_snapshot IS NULL
    OR v_operation.result_snapshot IS NULL
    OR v_operation.completed_at IS NULL
  THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_OPERATION_IDENTITY_UNPROVEN: Stored operation identity is incomplete.';
  END IF;
  RETURN JSONB_BUILD_OBJECT(
    'decision', 'REPLAY', 'operation_id', v_operation.id,
    'result_snapshot', v_operation.result_snapshot
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.phase42_apply_return_inventory_before_phase43_internal(p_operation_id uuid, p_return_event_id uuid, p_warehouse_id uuid, p_sources jsonb, p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_product RECORD;
  v_opening_global INTEGER;
  v_target_before INTEGER;
  v_target_after INTEGER;
  v_prior_exact NUMERIC(24, 6);
  v_prior_legacy BIGINT;
  v_restock_value NUMERIC(30, 6);
  v_resulting_value NUMERIC(30, 6);
  v_resulting_quantity INTEGER;
  v_new_exact NUMERIC(24, 6);
  v_new_legacy BIGINT;
  v_movement_id UUID;
  v_effects JSONB := '[]'::JSONB;
BEGIN
  IF p_operation_id IS NULL OR p_return_event_id IS NULL
    OR p_warehouse_id IS NULL OR p_user_id IS NULL
    OR p_sources IS NULL OR JSONB_TYPEOF(p_sources) IS DISTINCT FROM 'array'
  THEN
    RAISE EXCEPTION USING ERRCODE = '22023',
      MESSAGE = 'PHASE42_INVENTORY_EFFECT_INPUT_INVALID: Return inventory effect input is invalid.';
  END IF;
  IF JSONB_ARRAY_LENGTH(p_sources) = 0 THEN
    RETURN v_effects;
  END IF;

  PERFORM public.phase2_lock_inventory_products_internal(ARRAY(
    SELECT DISTINCT (source->>'product_id')::UUID
    FROM JSONB_ARRAY_ELEMENTS(p_sources) source
    ORDER BY (source->>'product_id')::UUID
  ));

  FOR v_product IN
    SELECT (source->>'product_id')::UUID AS product_id,
      SUM((source->>'quantity')::INTEGER)::INTEGER AS quantity,
      SUM((source->>'historical_value_exact')::NUMERIC(30, 6))::NUMERIC(30, 6)
        AS historical_value_exact,
      JSONB_AGG(source ORDER BY source->>'source_kind', source->>'source_id')
        AS source_evidence
    FROM JSONB_ARRAY_ELEMENTS(p_sources) source
    GROUP BY (source->>'product_id')::UUID
    ORDER BY (source->>'product_id')::UUID
  LOOP
    IF v_product.quantity <= 0 OR v_product.historical_value_exact < 0 THEN
      RAISE EXCEPTION USING ERRCODE = '23514',
        MESSAGE = 'PHASE42_INVENTORY_EFFECT_INVALID: Sellable quantity and historical value must be valid.';
    END IF;

    SELECT product.wac_cost_in_minor_units_exact,
      product.cost_price_in_minor_units
    INTO v_prior_exact, v_prior_legacy
    FROM public.products product
    WHERE product.id = v_product.product_id
    FOR NO KEY UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION USING ERRCODE = '23503',
        MESSAGE = 'PHASE42_RETURN_PRODUCT_NOT_FOUND: Return product is unavailable.';
    END IF;
    v_prior_exact := COALESCE(v_prior_exact, v_prior_legacy::NUMERIC);

    SELECT COALESCE(SUM(balance.on_hand_quantity), 0)::INTEGER
    INTO v_opening_global
    FROM public.inventory_balances balance
    WHERE balance.product_id = v_product.product_id;

    INSERT INTO public.inventory_balances(
      warehouse_id, product_id, on_hand_quantity, reserved_quantity
    ) VALUES (p_warehouse_id, v_product.product_id, 0, 0)
    ON CONFLICT (warehouse_id, product_id) DO NOTHING;

    SELECT balance.on_hand_quantity INTO v_target_before
    FROM public.inventory_balances balance
    WHERE balance.warehouse_id = p_warehouse_id
      AND balance.product_id = v_product.product_id
    FOR UPDATE;

    v_restock_value := v_product.historical_value_exact;
    v_resulting_quantity := v_opening_global + v_product.quantity;
    v_resulting_value := ROUND(
      v_opening_global::NUMERIC * v_prior_exact + v_restock_value, 6
    );
    v_new_exact := ROUND(
      v_resulting_value / v_resulting_quantity::NUMERIC, 6
    );
    v_new_legacy := ROUND(v_new_exact)::BIGINT;
    v_target_after := v_target_before + v_product.quantity;
    v_movement_id := gen_random_uuid();

    UPDATE public.products
    SET wac_cost_in_minor_units_exact = v_new_exact,
      cost_price_in_minor_units = v_new_legacy,
      updated_at = clock_timestamp()
    WHERE id = v_product.product_id;

    UPDATE public.inventory_balances
    SET on_hand_quantity = v_target_after, updated_at = clock_timestamp()
    WHERE warehouse_id = p_warehouse_id
      AND product_id = v_product.product_id;

    INSERT INTO public.inventory_movements(
      id, warehouse_id, product_id, movement_type, quantity,
      balance_before, balance_after, reference_type, reference_id,
      notes, created_by
    ) VALUES (
      v_movement_id, p_warehouse_id, v_product.product_id, 'return_in',
      v_product.quantity, v_target_before, v_target_after,
      'phase4_sales_return', p_return_event_id,
      'Phase 4.2 historical-cost sellable Return restock', p_user_id
    );

    INSERT INTO public.phase42_return_inventory_effects(
      operation_id, return_event_id, warehouse_id, product_id,
      inventory_movement_id, sellable_quantity,
      historical_restock_value_in_minor_units_exact,
      opening_global_quantity, target_balance_before, target_balance_after,
      prior_wac_in_minor_units_exact, resulting_wac_in_minor_units_exact,
      resulting_global_quantity, resulting_global_value_in_minor_units_exact,
      source_evidence
    ) VALUES (
      p_operation_id, p_return_event_id, p_warehouse_id,
      v_product.product_id, v_movement_id, v_product.quantity,
      v_restock_value, v_opening_global, v_target_before, v_target_after,
      v_prior_exact, v_new_exact, v_resulting_quantity,
      v_resulting_value, v_product.source_evidence
    );

    v_effects := v_effects || JSONB_BUILD_ARRAY(JSONB_BUILD_OBJECT(
      'productId', v_product.product_id,
      'quantity', v_product.quantity,
      'historicalRestockValueInMinorUnitsExact', v_restock_value,
      'priorWacInMinorUnitsExact', v_prior_exact,
      'resultingWacInMinorUnitsExact', v_new_exact,
      'inventoryMovementId', v_movement_id
    ));
  END LOOP;
  RETURN v_effects;
END;
$function$

CREATE OR REPLACE FUNCTION public.phase42_assert_operational_return_evidence_internal(p_operation_id uuid, p_require_settled boolean DEFAULT true)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_item RECORD; v_root RECORD;
BEGIN
  PERFORM public.package_d_assert_return_evidence_before_single_sku_internal(p_operation_id,p_require_settled);
  FOR v_item IN SELECT * FROM public.sales_return_items
    WHERE operation_id=p_operation_id AND return_scope='base_unit' LOOP
    PERFORM public.package_d_assert_whole_single_sku_quantity_internal(v_item.order_item_id,v_item.returned_quantity);
    PERFORM public.package_d_assert_carton_return_item_internal(to_jsonb(v_item));
  END LOOP;
  FOR v_item IN SELECT source_kind,source_id,product_id,consumed_quantity
    FROM public.sales_aftercare_consumptions WHERE operation_id=p_operation_id LOOP
