$function$

CREATE OR REPLACE FUNCTION public.preview_guest_promotion_v2(p_lines jsonb, p_promotion_code text DEFAULT NULL::text, p_customer_phone text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_phone TEXT := CASE
    WHEN NULLIF(BTRIM(p_customer_phone), '') IS NULL THEN NULL
    ELSE public.normalize_customer_phone(p_customer_phone)
  END;
  v_promotion_code TEXT := UPPER(NULLIF(BTRIM(p_promotion_code), ''));
  v_request JSONB;
  v_canonical_request JSONB;
  v_line JSONB;
  v_raw_line JSONB;
  v_instance JSONB;
  v_components JSONB;
  v_line_kind TEXT;
  v_line_identity TEXT;
  v_expected_price BIGINT;
  v_unit_price BIGINT;
  v_commercial_quantity INTEGER;
  v_subtotal BIGINT := 0;
  v_discount BIGINT := 0;
  v_product public.products%ROWTYPE;
  v_configuration public.product_parcel_configurations%ROWTYPE;
  v_capacity INTEGER;
  v_component_total BIGINT;
  v_invalid_component_count INTEGER;
  v_missing_wac_count INTEGER;
  v_promotion public.promotion_codes%ROWTYPE;
BEGIN
  -- Reuse the approved Phase-3 canonical line grammar and all bounded input
  -- limits.  The synthetic actor/location fields are validation-only and are
  -- never returned or persisted.
  IF jsonb_typeof(p_lines)='array' THEN
    FOR v_raw_line IN SELECT value FROM jsonb_array_elements(p_lines) LOOP
      IF jsonb_typeof(v_raw_line->'parcel_instances')='array' THEN
        FOR v_instance IN SELECT value FROM jsonb_array_elements(v_raw_line->'parcel_instances') LOOP
          IF jsonb_typeof(v_instance->'components')='array' AND EXISTS(
            SELECT 1 FROM jsonb_array_elements(v_instance->'components') c
            WHERE jsonb_typeof(c->'product_id') IS DISTINCT FROM 'string'
              OR (c->>'product_id') !~* '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$') THEN
            RAISE EXCEPTION USING ERRCODE='22023',
              MESSAGE='PARCEL_COMPONENT_INVALID: هوية النكهة غير صحيحة؛ حدّث الصفحة وأعد المحاولة.';
          END IF;
        END LOOP;
      END IF;
    END LOOP;
  END IF;
  v_request := JSONB_BUILD_OBJECT(
    'contract_version', 'phase3-sale-v1',
    'actor_scope_type', 'guest_gateway',
    'actor_scope_hash', REPEAT('0', 64),
    'operation_source', 'customer_reservation',
    'warehouse_id', '00000000-0000-0000-0000-000000000001',
    'promotion_code', v_promotion_code,
    'order_discount_in_minor_units', 0,
    'lines', p_lines
  );
  v_canonical_request := public.phase3_canonicalize_sale_request_internal(v_request);

  IF EXISTS (
    SELECT 1
    FROM JSONB_ARRAY_ELEMENTS(p_lines) candidate
    GROUP BY public.phase3_customer_line_identity_internal(candidate)
    HAVING COUNT(*) > 1
  ) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_SALE_CONTRACT_INVALID: Customer commercial identities must be unique.';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM JSONB_ARRAY_ELEMENTS(v_canonical_request->'lines') candidate
    WHERE candidate->>'commercial_line_kind' = 'configurable_parcel'
  ) AND public.get_configurable_parcel_feature_state() IS DISTINCT FROM 'ENABLED' THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'CONFIGURABLE_PARCEL_DISABLED: Configurable Parcel is unavailable for guest preview.';
  END IF;

  FOR v_line IN
    SELECT value
    FROM JSONB_ARRAY_ELEMENTS(v_canonical_request->'lines')
    ORDER BY value::TEXT
  LOOP
    v_line_kind := v_line->>'commercial_line_kind';
    v_line_identity := public.phase3_customer_line_identity_internal(v_line);

    SELECT raw_line.value
    INTO STRICT v_raw_line
    FROM JSONB_ARRAY_ELEMENTS(p_lines) raw_line(value)
    WHERE public.phase3_customer_line_identity_internal(raw_line.value)
      = v_line_identity;
    v_expected_price := public.phase3_require_nonnegative_bigint_internal(
      v_raw_line->>'expected_unit_price_in_minor_units',
      'expected_unit_price_in_minor_units'
    );

    IF v_line_kind = 'base_unit' THEN
      SELECT * INTO v_product
      FROM public.products product
      WHERE product.id = (v_line->>'product_id')::UUID
        AND product.is_active;
      IF NOT FOUND OR v_product.is_flavor_master THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001',
          MESSAGE = 'PHASE3_CUSTOMER_PRODUCT_INVALID: Base Unit is unavailable.';
      END IF;
      v_commercial_quantity := (v_line->>'base_quantity')::INTEGER;
      v_unit_price := v_product.sale_price_in_minor_units;

    ELSIF v_line_kind = 'legacy_single_sku_parcel' THEN
      SELECT * INTO v_product
      FROM public.products product
      WHERE product.id = (v_line->>'product_id')::UUID
        AND product.is_active;
      IF NOT FOUND
        OR v_product.units_per_sale_unit IS DISTINCT FROM
          (v_line->>'units_per_parcel')::INTEGER
        OR COALESCE(v_product.default_sale_price_in_minor_units, 0) <= 0
      THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001',
          MESSAGE = 'PHASE3_CUSTOMER_PRICE_OR_PACKAGE_STALE: Legacy Parcel changed.';
      END IF;
      v_commercial_quantity := (v_line->>'parcel_quantity')::INTEGER;
      v_unit_price := v_product.default_sale_price_in_minor_units;

    ELSE
      SELECT * INTO v_product
      FROM public.products product
      WHERE product.id = (v_line->>'family_product_id')::UUID
        AND product.is_active;
      IF NOT FOUND OR NOT v_product.is_flavor_master
        OR COALESCE(v_product.default_sale_price_in_minor_units, 0) <= 0
      THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001',
          MESSAGE = 'PHASE3_CUSTOMER_PRICE_OR_PACKAGE_STALE: Configurable Parcel changed.';
      END IF;

      SELECT * INTO v_configuration
      FROM public.product_parcel_configurations configuration
      WHERE configuration.id = (v_line->>'parcel_configuration_id')::UUID;
      IF NOT FOUND
        OR NOT v_configuration.is_active
        OR v_configuration.composition_mode <> 'configurable_mix'
        OR v_configuration.family_product_id IS DISTINCT FROM v_product.id
        OR v_configuration.configuration_revision IS DISTINCT FROM
          (v_line->>'configuration_revision')::INTEGER
      THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001',
          MESSAGE = 'PARCEL_CONFIGURATION_STALE: Parcel configuration is unavailable or changed.';
      END IF;

      v_capacity := v_product.units_per_sale_unit;
      IF COALESCE(v_capacity, 0) <= 0 THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001',
          MESSAGE = 'PARCEL_CONFIGURATION_STALE: Parcel Family capacity is invalid.';
      END IF;

      FOR v_instance IN
        SELECT value
        FROM JSONB_ARRAY_ELEMENTS(v_line->'parcel_instances') instance(value)
        ORDER BY (value->>'instance_sequence')::INTEGER
      LOOP
        v_components := v_instance->'components';
        -- Validate all identifiers before any UUID cast (including the policy
        -- lookup below). SQL evaluation order is not a validation boundary.
        IF EXISTS(SELECT 1 FROM jsonb_array_elements(v_components) c
          WHERE jsonb_typeof(c->'product_id') IS DISTINCT FROM 'string'
            OR (c->>'product_id') !~* '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$') THEN
          RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='PARCEL_COMPONENT_INVALID: هوية النكهة غير صحيحة؛ حدّث الصفحة وأعد المحاولة.';
        END IF;
        IF EXISTS(SELECT 1 FROM jsonb_array_elements(v_components) c WHERE NOT EXISTS(
          SELECT 1 FROM public.product_parcel_allowed_components allowed
          WHERE allowed.configuration_id=v_configuration.id AND allowed.product_id=(c->>'product_id')::uuid)) THEN
          RAISE EXCEPTION 'PARCEL_COMPONENT_NOT_ALLOWED: إحدى النكهات غير مسموحة لهذا الطرد';
        END IF;
        SELECT
          SUM((component->>'base_quantity')::BIGINT),
          COUNT(*) FILTER (
            WHERE product.id IS NULL
              OR NOT product.is_active
              OR product.is_flavor_master
              OR COALESCE(product.flavor_master_product_id, product.id)
                IS DISTINCT FROM v_product.id
          ),
          COUNT(*) FILTER (
            WHERE product.id IS NOT NULL
              AND product.wac_cost_in_minor_units_exact IS NULL
          )
        INTO v_component_total, v_invalid_component_count, v_missing_wac_count
        FROM JSONB_ARRAY_ELEMENTS(v_components) component
        LEFT JOIN public.products product
          ON product.id = (component->>'product_id')::UUID;

        IF v_component_total IS DISTINCT FROM v_capacity::BIGINT THEN
          RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'phase3_parcel_capacity_check',
            MESSAGE = 'PARCEL_CAPACITY_MISMATCH: Parcel composition must equal configured capacity.';
        END IF;
        IF v_invalid_component_count <> 0 THEN
          RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'phase3_parcel_component_family_check',
            MESSAGE = 'PARCEL_COMPONENT_FAMILY_MISMATCH: Parcel component is not an eligible stocked SKU.';
        END IF;
        IF v_missing_wac_count <> 0 THEN
          RAISE EXCEPTION USING ERRCODE = 'P0001',
            MESSAGE = 'PHASE3_EXACT_WAC_UNAVAILABLE: Exact WAC is required for configurable Parcel sale.';
        END IF;
      END LOOP;

      v_commercial_quantity := (v_line->>'parcel_quantity')::INTEGER;
      v_unit_price := v_product.default_sale_price_in_minor_units;
    END IF;

    IF v_unit_price IS DISTINCT FROM v_expected_price THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001',
        MESSAGE = 'PHASE3_CUSTOMER_QUOTE_STALE: Commercial price changed.';
    END IF;
    v_subtotal := v_subtotal + v_commercial_quantity::BIGINT * v_unit_price;
  END LOOP;

  IF v_promotion_code IS NOT NULL THEN
    IF v_phone IS NULL OR v_phone !~ '^07[789][0-9]{7}$' THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001',
        MESSAGE = 'PHASE3_CUSTOMER_INPUT_INVALID: Customer phone is required for promotion eligibility.';
    END IF;

    -- Deliberately no FOR UPDATE: preview observes current eligibility but does
    -- not reserve quota.  Final V2 checkout owns authoritative locking.
    SELECT * INTO v_promotion
    FROM public.promotion_codes promotion
    WHERE promotion.code = v_promotion_code;
    IF NOT FOUND OR NOT v_promotion.is_active
      OR (v_promotion.starts_at IS NOT NULL AND NOW() < v_promotion.starts_at)
      OR (v_promotion.expires_at IS NOT NULL AND NOW() >= v_promotion.expires_at)
      OR v_subtotal < v_promotion.minimum_subtotal_in_minor_units
    THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001',
        MESSAGE = 'PHASE3_CUSTOMER_PROMOTION_INVALID: Promotion is unavailable.';
    END IF;
    IF v_promotion.maximum_total_redemptions IS NOT NULL AND (
      SELECT COUNT(*)
      FROM public.promotion_redemptions redemption
      WHERE redemption.promotion_code_id = v_promotion.id
    ) >= v_promotion.maximum_total_redemptions THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001',
        MESSAGE = 'PHASE3_CUSTOMER_PROMOTION_INVALID: Promotion is exhausted.';
    END IF;
    IF (
      SELECT COUNT(*)
      FROM public.promotion_redemptions redemption
      WHERE redemption.promotion_code_id = v_promotion.id
        AND redemption.customer_phone = v_phone
    ) >= v_promotion.maximum_redemptions_per_phone THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001',
        MESSAGE = 'PHASE3_CUSTOMER_PROMOTION_INVALID: Promotion is unavailable for this customer.';
    END IF;

    IF v_promotion.discount_type = 'fixed' THEN
      v_discount := LEAST(v_promotion.discount_value, v_subtotal);
    ELSE
      v_discount := FLOOR(
        v_subtotal::NUMERIC * v_promotion.discount_value / 10000
      )::BIGINT;
      IF v_promotion.maximum_discount_in_minor_units IS NOT NULL THEN
        v_discount := LEAST(
          v_discount, v_promotion.maximum_discount_in_minor_units
        );
      END IF;
    END IF;
    v_discount := LEAST(GREATEST(v_discount, 0), v_subtotal);
  END IF;

  RETURN JSONB_BUILD_OBJECT(
    'success', true,
    'contractVersion', 'phase3-customer-promotion-preview-v2',
    'merchandiseSubtotalInMinorUnits', v_subtotal,
    'promotionDiscountInMinorUnits', v_discount,
    'finalMerchandiseTotalInMinorUnits', v_subtotal - v_discount,
    'promotion', CASE WHEN v_promotion_code IS NULL THEN NULL ELSE JSONB_BUILD_OBJECT(
      'code', v_promotion.code,
      'descriptionAr', v_promotion.description_ar
    ) END
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.product_edit_assert_version_internal(p_product_id uuid, p_expected_updated_at timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_current TIMESTAMPTZ;
BEGIN
  IF p_expected_updated_at IS NULL THEN
    RAISE EXCEPTION 'PRODUCT_EDIT_VERSION_REQUIRED: أعد فتح المنتج ثم احفظ التعديل.';
  END IF;

  SELECT product.updated_at
  INTO v_current
  FROM public.products product
  WHERE product.id = p_product_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'المنتج المحدد غير موجود.';
  END IF;

  IF v_current IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION USING
      MESSAGE = 'PRODUCT_EDIT_CONFLICT: عدّل مستخدم آخر هذا المنتج قبل قليل.',
      DETAIL = public.product_edit_snapshot_internal(p_product_id)::TEXT,
      HINT = 'اعرض القيم الحالية ثم أعد تطبيق تعديلاتك.';
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.receive_customer_cheque_v1(p_customer_id uuid, p_branch_id uuid, p_bank_name text, p_cheque_number text, p_due_date date, p_amount_in_minor_units bigint, p_notes text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_id UUID:=gen_random_uuid();v_request JSONB;v_replay JSONB;v_plan JSONB;v_result JSONB;v_part JSONB;v_payment_id UUID;
BEGIN
  PERFORM public.assert_erp_role(ARRAY['owner','admin','manager','accountant','cashier','sales'],'استلام شيك عميل');
  v_request:=jsonb_build_object('action','receive','customer',p_customer_id,'branch',p_branch_id,'bank',btrim(p_bank_name),
    'number',btrim(p_cheque_number),'due',p_due_date,'amount',p_amount_in_minor_units,'notes',NULLIF(btrim(p_notes),''));
  v_replay:=public.cheque_replay_internal(p_idempotency_key,v_request);IF v_replay IS NOT NULL THEN RETURN v_replay;END IF;
  IF NOT EXISTS(SELECT 1 FROM public.branches WHERE id=p_branch_id AND is_active) THEN RAISE EXCEPTION 'اختر فرعاً نشطاً.';END IF;
  IF NOT EXISTS(SELECT 1 FROM public.customers WHERE id=p_customer_id AND NOT is_deleted) THEN RAISE EXCEPTION 'العميل غير موجود.';END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('go-live-collection-customer:'||p_customer_id::TEXT,0));
  INSERT INTO public.deferred_cheques(id,tracking_number,direction,cheque_number,bank_name,due_date,amount_in_minor_units,
    customer_id,branch_id,notes,created_by,changed_by)
  VALUES(v_id,'CHQ-'||lpad(nextval('public.deferred_cheque_number_seq')::TEXT,8,'0'),'incoming',btrim(p_cheque_number),
    btrim(p_bank_name),p_due_date,p_amount_in_minor_units,p_customer_id,p_branch_id,NULLIF(btrim(p_notes),''),auth.uid(),auth.uid());
  INSERT INTO public.cheque_party_keys(party_kind,party_id,bank_key,cheque_number,cheque_id)
  VALUES('customer',p_customer_id,lower(btrim(p_bank_name)),btrim(p_cheque_number),v_id);
  v_plan:=public.go_live_plan_customer_collection_internal(p_customer_id,p_amount_in_minor_units);
  v_result:=public.collect_customer_balance_v1(p_customer_id,p_amount_in_minor_units,'cheque',p_branch_id,btrim(p_cheque_number),
    left(COALESCE(NULLIF(btrim(p_notes),'')||' — ','')||'استلام شيك مؤجل',300),'cheque-collect-'||v_id::TEXT);
  UPDATE public.deferred_cheques SET collection_operation_id=(v_result->>'operationId')::UUID WHERE id=v_id;
  FOR v_part IN SELECT value FROM jsonb_array_elements(v_plan->'parts') WHERE(value->>'allocateInMinorUnits')::BIGINT>0 LOOP
    v_payment_id:=NULL;
    IF v_part->>'kind'='order' THEN
      SELECT customer_payment_id INTO STRICT v_payment_id FROM public.customer_collection_order_payments
      WHERE operation_id=(v_result->>'operationId')::UUID AND order_id=(v_part->>'id')::UUID;
    END IF;
    INSERT INTO public.deferred_cheque_allocations(cheque_id,party_kind,party_id,origin_kind,origin_id,original_debt_at,amount_in_minor_units,customer_payment_id)
    VALUES(v_id,'customer',p_customer_id,v_part->>'kind',(v_part->>'id')::UUID,(v_part->>'originalDebtAt')::TIMESTAMPTZ,
      (v_part->>'allocateInMinorUnits')::BIGINT,v_payment_id);
  END LOOP;
  RETURN public.cheque_finish_event_internal(v_id,'received',NULL,NULL,p_idempotency_key,v_request);
END;
$function$

CREATE OR REPLACE FUNCTION public.receive_purchase_order_v2(p_purchase_order_id uuid, p_warehouse_id uuid DEFAULT NULL::uuid, p_supplier_invoice_number text DEFAULT NULL::text, p_supplier_invoice_date date DEFAULT NULL::date, p_received_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_header_discount_in_minor_units bigint DEFAULT 0, p_supplier_freight_in_minor_units bigint DEFAULT 0, p_legacy_tax_in_minor_units bigint DEFAULT 0, p_amount_paid_at_receipt_in_minor_units bigint DEFAULT 0, p_payment_method text DEFAULT 'cash'::text, p_payment_reference text DEFAULT NULL::text, p_supplier_delivery_note text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text, p_lines jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_key TEXT := NULLIF(BTRIM(p_idempotency_key), '');
  v_invoice_number TEXT := NULLIF(BTRIM(p_supplier_invoice_number), '');
  v_normalized_invoice TEXT := LOWER(NULLIF(BTRIM(p_supplier_invoice_number), ''));
  v_payment_method TEXT := LOWER(COALESCE(NULLIF(BTRIM(p_payment_method), ''), 'cash'));
  v_payment_reference TEXT := NULLIF(BTRIM(p_payment_reference), '');
  v_po public.purchase_orders%ROWTYPE;
  v_po_item public.purchase_order_items%ROWTYPE;
  v_target_warehouse_id UUID;
  v_canonical_lines JSONB;
  v_canonical_request JSONB;
  v_fingerprint TEXT;
  v_existing_operation public.business_operations%ROWTYPE;
  v_operation_id UUID := gen_random_uuid();
  v_receipt_id UUID := gen_random_uuid();
  v_receipt_number TEXT;
  v_result JSONB;
  v_line_weights JSONB;
  v_header_allocations JSONB;
  v_freight_allocations JSONB;
  v_component_weights JSONB;
  v_component_merchandise_allocations JSONB;
  v_component_final_allocations JSONB;
  v_inventory_components JSONB := '[]'::JSONB;
  v_wac_results JSONB;
  v_line JSONB;
  v_component JSONB;
  v_line_id UUID;
  v_item_id UUID;
  v_line_sequence INTEGER := 0;
  v_po_item_id UUID;
  v_line_kind TEXT;
  v_client_line_id UUID;
  v_commercial_quantity INTEGER;
  v_units_per_parcel INTEGER;
  v_received_base_quantity INTEGER;
  v_base_quantity INTEGER;
  v_product_id UUID;
  v_gross BIGINT;
  v_line_discount BIGINT;
  v_line_net BIGINT;
  v_line_header_discount BIGINT;
  v_line_freight BIGINT;
  v_line_acquisition BIGINT;
  v_component_merchandise BIGINT;
  v_component_acquisition BIGINT;
  v_merchandise_gross NUMERIC := 0;
  v_line_discount_total NUMERIC := 0;
  v_line_net_total NUMERIC := 0;
  v_acquisition_total NUMERIC;
  v_invoice_payable NUMERIC;
  v_outstanding NUMERIC;
  v_all_completed BOOLEAN;
BEGIN
  PERFORM public.assert_erp_role(
    ARRAY['owner', 'admin', 'manager', 'warehouse_keeper'],
    'استلام أمر شراء - نموذج الطرود'
  );
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'PHASE2_AUTH_REQUIRED: يجب تسجيل الدخول.';
  END IF;
  IF v_key IS NULL OR CHAR_LENGTH(v_key) NOT BETWEEN 16 AND 255 THEN
    RAISE EXCEPTION USING ERRCODE = '22023',
      MESSAGE = 'PHASE2_IDEMPOTENCY_KEY_INVALID: مفتاح منع التكرار غير صالح.';
  END IF;
  IF p_header_discount_in_minor_units < 0
    OR p_supplier_freight_in_minor_units < 0
    OR p_legacy_tax_in_minor_units < 0
    OR p_amount_paid_at_receipt_in_minor_units < 0
  THEN
    RAISE EXCEPTION USING ERRCODE = '22023',
      MESSAGE = 'PHASE2_FINANCIAL_VALUE_INVALID: القيم المالية لا يمكن أن تكون سالبة.';
  END IF;
  IF v_payment_method NOT IN ('cash', 'cliq', 'bank_transfer', 'deferred') THEN
    RAISE EXCEPTION USING ERRCODE = '22023',
      MESSAGE = 'PHASE2_PAYMENT_METHOD_INVALID: طريقة الدفع غير مدعومة.';
  END IF;
  IF v_payment_method = 'deferred'
    AND p_amount_paid_at_receipt_in_minor_units > 0
  THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      CONSTRAINT = 'phase2_deferred_payment_zero_check',
      MESSAGE = 'PHASE2_DEFERRED_PAYMENT_INVALID: الاستلام الآجل لا يقبل دفعة فورية.';
  END IF;
  IF v_payment_method IN ('cliq', 'bank_transfer')
    AND p_amount_paid_at_receipt_in_minor_units > 0
    AND v_payment_reference IS NULL
  THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      CONSTRAINT = 'phase2_payment_reference_required_check',
      MESSAGE = 'PHASE2_PAYMENT_REFERENCE_REQUIRED: مرجع الدفعة الإلكترونية مطلوب.';
  END IF;

  v_canonical_lines := public.phase2_canonicalize_receipt_lines_internal(p_lines);

  v_canonical_request := jsonb_build_object(
    'contract_version', 2,
    'operation_type', 'purchase_order_receipt_v2',
    'purchase_order_id', LOWER(p_purchase_order_id::TEXT),
    'warehouse_id', CASE WHEN p_warehouse_id IS NULL THEN NULL ELSE LOWER(p_warehouse_id::TEXT) END,
    'supplier_invoice_number', v_normalized_invoice,
    'supplier_invoice_date', p_supplier_invoice_date,
    'received_at', CASE WHEN p_received_at IS NULL THEN NULL ELSE TO_CHAR(p_received_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"') END,
    'header_discount_in_minor_units', p_header_discount_in_minor_units,
    'supplier_freight_in_minor_units', p_supplier_freight_in_minor_units,
    'legacy_tax_in_minor_units', p_legacy_tax_in_minor_units,
    'amount_paid_at_receipt_in_minor_units', p_amount_paid_at_receipt_in_minor_units,
    'payment_method', v_payment_method,
    'payment_reference', v_payment_reference,
    'supplier_delivery_note', NULLIF(BTRIM(p_supplier_delivery_note), ''),
    'notes', NULLIF(BTRIM(p_notes), ''),
    'lines', v_canonical_lines
  );
  v_fingerprint := public.phase2_request_fingerprint_internal(v_canonical_request);

  PERFORM pg_advisory_xact_lock(hashtextextended(
    'purchase_order_receipt_v2:' || v_user_id::TEXT || ':' || v_key, 0
  ));
  SELECT * INTO v_existing_operation
  FROM public.business_operations operation
  WHERE operation.operation_type = 'purchase_order_receipt_v2'
    AND operation.initiated_by = v_user_id
    AND operation.idempotency_key = v_key;
  IF FOUND THEN
    IF v_existing_operation.request_fingerprint IS NULL
      OR v_existing_operation.result_snapshot IS NULL
    THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001',
        MESSAGE = 'LEGACY_IDEMPOTENCY_IDENTITY_UNPROVEN: لا يمكن إثبات تطابق العملية التاريخية.';
    END IF;
    IF v_existing_operation.request_fingerprint IS DISTINCT FROM v_fingerprint THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001',
        MESSAGE = 'IDEMPOTENCY_CONFLICT: استُخدم المفتاح نفسه لطلب مختلف.';
    END IF;
    RETURN v_existing_operation.result_snapshot;
  END IF;

  PERFORM public.phase2_lock_payment_shift_internal(
    (SELECT branch_id FROM public.purchase_orders WHERE id = p_purchase_order_id),
    v_payment_method, p_amount_paid_at_receipt_in_minor_units
  );
  PERFORM public.phase2_lock_inventory_products_internal(ARRAY(
    SELECT DISTINCT (component->>'product_id')::UUID
    FROM jsonb_array_elements(v_canonical_lines) line
    CROSS JOIN LATERAL jsonb_array_elements(line->'components') component
    ORDER BY (component->>'product_id')::UUID
  ));
  PERFORM public.phase2_validate_receipt_lines_internal(v_canonical_lines);
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(v_canonical_lines) line
    WHERE line->>'purchase_order_item_id' IS NULL
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '22023',
      MESSAGE = 'PHASE2_PO_ITEM_ID_REQUIRED: كل سطر استلام يجب أن يرتبط بسطر أمر شراء.';
  END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(v_canonical_lines) line
    GROUP BY (line->>'purchase_order_item_id')::UUID
    HAVING COUNT(*) > 1
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23505',
      CONSTRAINT = 'phase2_purchase_receipt_po_item_unique',
      MESSAGE = 'PHASE2_DUPLICATE_PO_ITEM: لا يجوز تكرار سطر أمر الشراء داخل نفس سند الاستلام.';
  END IF;

  SELECT
    COALESCE(SUM((line->>'gross_amount_in_minor_units')::NUMERIC), 0),
    COALESCE(SUM((line->>'line_discount_in_minor_units')::NUMERIC), 0)
  INTO v_merchandise_gross, v_line_discount_total
  FROM jsonb_array_elements(v_canonical_lines) line;
  v_line_net_total := v_merchandise_gross - v_line_discount_total;
  IF p_header_discount_in_minor_units > v_line_net_total THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      CONSTRAINT = 'phase2_header_discount_total_check',
      MESSAGE = 'PHASE2_HEADER_DISCOUNT_EXCEEDS_NET: خصم رأس الفاتورة يتجاوز صافي البضاعة.';
  END IF;
  IF v_line_net_total = 0
    AND (p_header_discount_in_minor_units > 0 OR p_supplier_freight_in_minor_units > 0)
  THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      CONSTRAINT = 'phase2_zero_allocation_basis_check',
      MESSAGE = 'PHASE2_ZERO_ALLOCATION_BASIS: لا يمكن توزيع خصم أو شحن على أساس صفري.';
  END IF;
  v_acquisition_total := v_line_net_total
    - p_header_discount_in_minor_units::NUMERIC
    + p_supplier_freight_in_minor_units::NUMERIC;
  v_invoice_payable := v_acquisition_total + p_legacy_tax_in_minor_units::NUMERIC;
  IF v_merchandise_gross > 9223372036854775807::NUMERIC
    OR v_line_discount_total > 9223372036854775807::NUMERIC
    OR v_line_net_total > 9223372036854775807::NUMERIC
    OR v_acquisition_total > 9223372036854775807::NUMERIC
    OR v_invoice_payable > 9223372036854775807::NUMERIC
  THEN
    RAISE EXCEPTION USING ERRCODE = '22003',
      MESSAGE = 'PHASE2_MONEY_OVERFLOW: قيمة الاستلام تتجاوز الحد المدعوم.';
  END IF;
  IF p_amount_paid_at_receipt_in_minor_units::NUMERIC > v_invoice_payable THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      CONSTRAINT = 'phase2_payment_upper_bound_check',
      MESSAGE = 'PHASE2_PAYMENT_EXCEEDS_PAYABLE: الدفعة تتجاوز إجمالي فاتورة المورد.';
  END IF;
  v_outstanding := v_invoice_payable - p_amount_paid_at_receipt_in_minor_units::NUMERIC;

  SELECT * INTO v_po
  FROM public.purchase_orders purchase_order
  WHERE purchase_order.id = p_purchase_order_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'PHASE2_PURCHASE_ORDER_NOT_FOUND: أمر الشراء غير موجود.';
  END IF;
  IF v_po.status NOT IN ('approved', 'partially_received') THEN
    RAISE EXCEPTION 'PHASE2_PURCHASE_ORDER_STATUS_INVALID: أمر الشراء غير جاهز للاستلام.';
  END IF;
  IF COALESCE((SELECT SUM(payment.amount_in_minor_units) FROM public.supplier_payments payment
       WHERE payment.purchase_order_id=p_purchase_order_id AND NOT payment.is_reversed),0)
       +p_amount_paid_at_receipt_in_minor_units > GREATEST(v_po.total_in_minor_units::NUMERIC,
         v_invoice_payable+COALESCE((SELECT SUM(r.supplier_invoice_payable_total_snapshot_in_minor_units::NUMERIC)
           FROM public.purchase_receipts r WHERE r.purchase_order_id=p_purchase_order_id
             AND r.status='completed' AND r.phase2_finalized_at IS NOT NULL),0)
         +COALESCE((SELECT payable::NUMERIC FROM public.phase133_legacy_po_payables_internal()
           WHERE purchase_order_id=p_purchase_order_id),0)) THEN
    RAISE EXCEPTION 'SUPPLIER_PO_PAYMENT_EXCEEDS_PAYABLE: إجمالي دفعات أمر الشراء يتجاوز قيمته المستحقة.';
  END IF;
  -- Existing PO payments have ALREADY reduced the supplier balance.
  -- No allocation/backfill into immutable receipt snapshots is needed.
  -- Receiving adds gross payable minus ONLY its own newly committed payment.

  v_target_warehouse_id := COALESCE(p_warehouse_id, v_po.warehouse_id);
  IF v_target_warehouse_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.warehouses warehouse
    WHERE warehouse.id = v_target_warehouse_id AND warehouse.is_active
  ) THEN
    RAISE EXCEPTION 'PHASE2_WAREHOUSE_INVALID: المستودع غير موجود أو غير نشط.';
  END IF;

  PERFORM item.id
  FROM public.purchase_order_items item
  JOIN (
    SELECT DISTINCT (line->>'purchase_order_item_id')::UUID AS item_id
    FROM jsonb_array_elements(v_canonical_lines) line
  ) input_item ON input_item.item_id = item.id
  WHERE item.purchase_order_id = p_purchase_order_id
  ORDER BY item.id
  FOR UPDATE OF item;

  FOR v_line IN SELECT * FROM jsonb_array_elements(v_canonical_lines)
  LOOP
    v_po_item_id := (v_line->>'purchase_order_item_id')::UUID;
    SELECT * INTO v_po_item
    FROM public.purchase_order_items item
    WHERE item.id = v_po_item_id
      AND item.purchase_order_id = p_purchase_order_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'PHASE2_PO_ITEM_NOT_FOUND: سطر أمر الشراء غير موجود.';
    END IF;
    v_line_kind := v_line->>'line_kind';
    v_commercial_quantity := (v_line->>'commercial_quantity')::INTEGER;
    v_received_base_quantity := (
      SELECT SUM((component->>'base_quantity')::INTEGER)
      FROM jsonb_array_elements(v_line->'components') component
    );
    IF v_line_kind IS DISTINCT FROM v_po_item.commercial_line_kind THEN
      RAISE EXCEPTION USING ERRCODE = '23514',
        CONSTRAINT = 'phase2_purchase_receipt_line_kind_check',
        MESSAGE = 'PHASE2_PO_LINE_KIND_MISMATCH: نوع الاستلام لا يطابق سطر أمر الشراء.';
    END IF;
    IF v_line_kind = 'base_unit' THEN
      IF (v_line->'components'->0->>'product_id')::UUID
          IS DISTINCT FROM v_po_item.product_id
        OR v_received_base_quantity > v_po_item.ordered_quantity - v_po_item.received_quantity
      THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
          CONSTRAINT = 'phase2_purchase_receipt_base_quantity_check',
          MESSAGE = 'PHASE2_PO_BASE_RECEIPT_INVALID: المنتج أو الكمية يتجاوزان المتبقي في أمر الشراء.';
      END IF;
    ELSE
      IF NULLIF(v_line->>'family_product_id', '')::UUID
          IS DISTINCT FROM v_po_item.family_product_id
        OR NULLIF(v_line->>'parcel_configuration_id', '')::UUID
          IS DISTINCT FROM v_po_item.parcel_configuration_id
        OR NULLIF(v_line->>'configuration_revision', '')::INTEGER
          IS DISTINCT FROM v_po_item.configuration_revision
        OR NULLIF(v_line->>'units_per_parcel', '')::INTEGER
          IS DISTINCT FROM v_po_item.units_per_parcel_snapshot
        OR v_commercial_quantity
          > v_po_item.parcel_quantity - v_po_item.received_parcel_quantity
      THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
          CONSTRAINT = 'phase2_purchase_receipt_parcel_quantity_check',
          MESSAGE = 'PHASE2_PO_PARCEL_RECEIPT_INVALID: هوية الطرد أو كميته تتجاوز المتبقي في أمر الشراء.';
      END IF;
    END IF;
  END LOOP;

  SELECT NOT EXISTS (
    SELECT 1
    FROM public.purchase_order_items item
    LEFT JOIN LATERAL (
      SELECT
        SUM((component->>'base_quantity')::INTEGER)::INTEGER AS received_base,
        CASE WHEN line->>'line_kind' = 'configurable_parcel'
          THEN (line->>'commercial_quantity')::INTEGER ELSE 0 END AS received_parcels
      FROM jsonb_array_elements(v_canonical_lines) line
      CROSS JOIN LATERAL jsonb_array_elements(line->'components') component
      WHERE (line->>'purchase_order_item_id')::UUID = item.id
      GROUP BY line
    ) incoming ON true
    WHERE item.purchase_order_id = p_purchase_order_id
      AND (
        item.received_quantity + COALESCE(incoming.received_base, 0)
          < item.ordered_quantity
        OR (item.commercial_line_kind = 'configurable_parcel'
          AND item.received_parcel_quantity
            + COALESCE(incoming.received_parcels, 0) < item.parcel_quantity)
      )
  ) INTO v_all_completed;

  IF v_normalized_invoice IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(hashtextextended(
      'supplier_invoice:' || v_po.supplier_id::TEXT || ':' || v_normalized_invoice,
      0
    ));
    IF EXISTS (
      SELECT 1 FROM public.supplier_financial_invoice_identities identity
      WHERE identity.supplier_id = v_po.supplier_id
        AND identity.normalized_invoice_number = v_normalized_invoice
        AND identity.is_active
    ) OR EXISTS (
      SELECT 1 FROM public.supplier_receipts receipt
      WHERE receipt.supplier_id = v_po.supplier_id
        AND LOWER(BTRIM(receipt.supplier_invoice_number)) = v_normalized_invoice
        AND receipt.status <> 'cancelled'
    ) OR EXISTS (
      SELECT 1 FROM public.purchase_receipts receipt
      WHERE receipt.supplier_id = v_po.supplier_id
        AND LOWER(BTRIM(receipt.supplier_invoice_number)) = v_normalized_invoice
        AND receipt.status <> 'cancelled'
    ) THEN
      RAISE EXCEPTION USING ERRCODE = '23505',
        CONSTRAINT = 'uq_supplier_financial_invoice_active',
        MESSAGE = 'DUPLICATE_SUPPLIER_INVOICE: رقم فاتورة المورد مستخدم في سند مالي نشط.';
    END IF;
  END IF;

  LOOP
    v_receipt_number := 'GRN-' || TO_CHAR(NOW(), 'YYYY') || '-'
      || LPAD(FLOOR(100000 + RANDOM() * 900000)::BIGINT::TEXT, 6, '0');
    EXIT WHEN NOT EXISTS (
      SELECT 1 FROM public.purchase_receipts receipt
      WHERE receipt.receipt_number = v_receipt_number
    );
  END LOOP;

  v_result := jsonb_build_object(
    'success', true,
    'idempotent', false,
    'operation_id', v_operation_id,
    'receipt_id', v_receipt_id,
    'receipt_number', v_receipt_number,
    'purchase_order_id', p_purchase_order_id,
    'inventory_acquisition_cost_in_minor_units', v_acquisition_total::BIGINT,
    'supplier_invoice_payable_total_in_minor_units', v_invoice_payable::BIGINT,
    'supplier_outstanding_balance_effect_in_minor_units', v_outstanding::BIGINT,
    'is_fully_received', v_all_completed,
    'new_status', CASE WHEN v_all_completed THEN 'received' ELSE 'partially_received' END
  );
  INSERT INTO public.business_operations (
    id, operation_type, idempotency_key, request_fingerprint,
    initiated_by, result_snapshot, completed_at
  ) VALUES (
    v_operation_id, 'purchase_order_receipt_v2', v_key, v_fingerprint,
    v_user_id, v_result, NOW()
  );
  INSERT INTO public.purchase_receipts (
    id, receipt_number, purchase_order_id, supplier_id, warehouse_id,
    received_by, received_at, supplier_delivery_note, notes, operation_id,
    status, supplier_invoice_number, supplier_invoice_date,
    merchandise_gross_snapshot_in_minor_units,
    line_discount_total_snapshot_in_minor_units,
    header_discount_snapshot_in_minor_units,
    supplier_freight_snapshot_in_minor_units,
    legacy_tax_snapshot_in_minor_units,
    inventory_acquisition_cost_snapshot_in_minor_units,
    supplier_invoice_payable_total_snapshot_in_minor_units,
    amount_paid_at_receipt_snapshot_in_minor_units,
    supplier_outstanding_balance_effect_snapshot_in_minor_units,
    payment_method, payment_reference, phase2_finalized_at
  ) VALUES (
    v_receipt_id, v_receipt_number, p_purchase_order_id, v_po.supplier_id,
    v_target_warehouse_id, v_user_id, COALESCE(p_received_at, NOW()),
    NULLIF(BTRIM(p_supplier_delivery_note), ''), NULLIF(BTRIM(p_notes), ''),
    v_operation_id, 'completed', v_invoice_number, p_supplier_invoice_date,
    v_merchandise_gross::BIGINT, v_line_discount_total::BIGINT,
    p_header_discount_in_minor_units, p_supplier_freight_in_minor_units,
    p_legacy_tax_in_minor_units, v_acquisition_total::BIGINT,
    v_invoice_payable::BIGINT, p_amount_paid_at_receipt_in_minor_units,
    v_outstanding::BIGINT, v_payment_method, v_payment_reference, NOW()
  );

  IF v_normalized_invoice IS NOT NULL THEN
    INSERT INTO public.supplier_financial_invoice_identities (
      supplier_id, normalized_invoice_number, operation_id, purchase_receipt_id
    ) VALUES (
      v_po.supplier_id, v_normalized_invoice, v_operation_id, v_receipt_id
    );
  END IF;

  SELECT jsonb_agg(jsonb_build_object(
    'key', line->>'client_line_id',
    'weight', (
      (line->>'gross_amount_in_minor_units')::BIGINT
      - (line->>'line_discount_in_minor_units')::BIGINT
    )
  )) INTO v_line_weights
  FROM jsonb_array_elements(v_canonical_lines) line;
  SELECT COALESCE(jsonb_object_agg(allocation_key, allocated_amount), '{}'::JSONB)
  INTO v_header_allocations
  FROM public.phase2_allocate_largest_remainder_internal(
    p_header_discount_in_minor_units, v_line_weights
  );
  SELECT COALESCE(jsonb_object_agg(allocation_key, allocated_amount), '{}'::JSONB)
  INTO v_freight_allocations
  FROM public.phase2_allocate_largest_remainder_internal(
    p_supplier_freight_in_minor_units, v_line_weights
  );

  FOR v_line IN SELECT * FROM jsonb_array_elements(v_canonical_lines)
  LOOP
    v_line_sequence := v_line_sequence + 1;
    v_line_id := gen_random_uuid();
    v_client_line_id := (v_line->>'client_line_id')::UUID;
    v_po_item_id := (v_line->>'purchase_order_item_id')::UUID;
    v_line_kind := v_line->>'line_kind';
    v_commercial_quantity := (v_line->>'commercial_quantity')::INTEGER;
    v_units_per_parcel := NULLIF(v_line->>'units_per_parcel', '')::INTEGER;
    v_received_base_quantity := (
      SELECT SUM((component->>'base_quantity')::INTEGER)
      FROM jsonb_array_elements(v_line->'components') component
    );
    v_gross := (v_line->>'gross_amount_in_minor_units')::BIGINT;
    v_line_discount := (v_line->>'line_discount_in_minor_units')::BIGINT;
    v_line_net := v_gross - v_line_discount;
    v_line_header_discount := COALESCE(
      (v_header_allocations->>v_client_line_id::TEXT)::BIGINT, 0
    );
    v_line_freight := COALESCE(
      (v_freight_allocations->>v_client_line_id::TEXT)::BIGINT, 0
    );
    v_line_acquisition := v_line_net - v_line_header_discount + v_line_freight;

    INSERT INTO public.purchase_receipt_commercial_lines (
      id, purchase_receipt_id, purchase_order_id, purchase_order_item_id,
      operation_id, client_line_id, line_sequence, commercial_line_kind,
      family_product_id, parcel_configuration_id, configuration_revision,
      received_commercial_quantity, received_parcel_quantity,
      received_base_unit_quantity, units_per_parcel_snapshot,
      base_unit_name_snapshot, parcel_unit_name_snapshot,
      gross_amount_snapshot_in_minor_units,
      line_discount_snapshot_in_minor_units,
      line_net_merchandise_snapshot_in_minor_units,
      allocated_header_discount_in_minor_units,
      allocated_supplier_freight_in_minor_units,
      final_acquisition_amount_in_minor_units, finalized_at
    ) VALUES (
      v_line_id, v_receipt_id, p_purchase_order_id, v_po_item_id,
      v_operation_id, v_client_line_id, v_line_sequence, v_line_kind,
      NULLIF(v_line->>'family_product_id', '')::UUID,
      NULLIF(v_line->>'parcel_configuration_id', '')::UUID,
      NULLIF(v_line->>'configuration_revision', '')::INTEGER,
      v_commercial_quantity,
      CASE WHEN v_line_kind = 'configurable_parcel' THEN v_commercial_quantity END,
      v_received_base_quantity, v_units_per_parcel,
      v_line->>'base_unit_name', NULLIF(v_line->>'parcel_unit_name', ''),
      v_gross, v_line_discount, v_line_net,
      v_line_header_discount, v_line_freight, v_line_acquisition, NOW()
    );

    SELECT jsonb_agg(jsonb_build_object(
      'key', component->>'product_id',
      'weight', CASE
        WHEN component->>'explicit_merchandise_cost_in_minor_units' IS NULL
          THEN (component->>'base_quantity')::BIGINT
        ELSE (component->>'explicit_merchandise_cost_in_minor_units')::BIGINT
      END
    )) INTO v_component_weights
    FROM jsonb_array_elements(v_line->'components') component;
    SELECT COALESCE(jsonb_object_agg(allocation_key, allocated_amount), '{}'::JSONB)
    INTO v_component_merchandise_allocations
    FROM public.phase2_allocate_largest_remainder_internal(
      v_line_net, v_component_weights
    );
    SELECT COALESCE(jsonb_object_agg(allocation_key, allocated_amount), '{}'::JSONB)
    INTO v_component_final_allocations
    FROM public.phase2_allocate_largest_remainder_internal(
      v_line_acquisition, v_component_weights
    );

    FOR v_component IN SELECT * FROM jsonb_array_elements(v_line->'components')
    LOOP
      v_item_id := gen_random_uuid();
      v_product_id := (v_component->>'product_id')::UUID;
      v_base_quantity := (v_component->>'base_quantity')::INTEGER;
      v_component_merchandise :=
        (v_component_merchandise_allocations->>v_product_id::TEXT)::BIGINT;
      v_component_acquisition :=
        (v_component_final_allocations->>v_product_id::TEXT)::BIGINT;

      INSERT INTO public.purchase_receipt_items (
        id, purchase_receipt_id, purchase_order_item_id, product_id,
        received_quantity, unit_cost_in_minor_units, operation_id,
        allocated_cost_in_minor_units, exact_unit_cost_in_minor_units,
        commercial_line_id, merchandise_net_cost_in_minor_units
      ) VALUES (
        v_item_id, v_receipt_id, v_po_item_id, v_product_id,
        v_base_quantity,
        ROUND(v_component_acquisition::NUMERIC / v_base_quantity)::BIGINT,
        v_operation_id, v_component_acquisition,
        ROUND(v_component_acquisition::NUMERIC / v_base_quantity, 6),
        v_line_id, v_component_merchandise
      );
      v_inventory_components := v_inventory_components || jsonb_build_array(
        jsonb_build_object(
          'item_id', v_item_id,
          'client_line_id', v_client_line_id,
          'product_id', v_product_id,
          'base_quantity', v_base_quantity,
          'allocated_cost_in_minor_units', v_component_acquisition
        )
      );
    END LOOP;

    UPDATE public.purchase_order_items
    SET
      received_quantity = received_quantity + v_received_base_quantity,
      received_parcel_quantity = received_parcel_quantity
        + CASE WHEN v_line_kind = 'configurable_parcel'
            THEN v_commercial_quantity ELSE 0 END,
      updated_at = NOW()
    WHERE id = v_po_item_id;
  END LOOP;

  v_wac_results := public.phase2_apply_inventory_and_wac_internal(
    v_operation_id,
    v_target_warehouse_id,
    'purchase_receipt',
    v_receipt_id,
    v_inventory_components,
    v_user_id,
    'استلام أمر شراء Phase 2 - ' || v_receipt_number
  );

  UPDATE public.suppliers
  SET current_balance_in_minor_units =
      current_balance_in_minor_units + v_outstanding::BIGINT,
    updated_at = NOW()
  WHERE id = v_po.supplier_id;

  IF p_amount_paid_at_receipt_in_minor_units > 0 THEN
    INSERT INTO public.supplier_payments (
      supplier_id, purchase_order_id, purchase_receipt_id,
      amount_in_minor_units, payment_method, reference_number,
      payment_date, notes, created_by, operation_id
    ) VALUES (
      v_po.supplier_id, p_purchase_order_id, v_receipt_id,
      p_amount_paid_at_receipt_in_minor_units, v_payment_method,
      v_payment_reference, COALESCE(p_received_at, NOW()),
      'دفعة عند استلام السند ' || v_receipt_number,
      v_user_id, v_operation_id
    );
  END IF;

  UPDATE public.purchase_orders
  SET amount_paid_in_minor_units = amount_paid_in_minor_units + p_amount_paid_at_receipt_in_minor_units,
    status = CASE WHEN v_all_completed THEN 'received' ELSE 'partially_received' END,
    received_at = CASE WHEN v_all_completed THEN NOW() ELSE received_at END,
    updated_at = NOW()
  WHERE id = p_purchase_order_id;

  INSERT INTO public.audit_logs (
    user_id, action, entity_name, entity_id, details
  ) VALUES (
    v_user_id, 'RECEIVE_PURCHASE_ORDER_V2', 'purchase_receipts',
    v_receipt_id,
    jsonb_build_object(
      'operation_id', v_operation_id,
      'purchase_order_id', p_purchase_order_id,
      'receipt_number', v_receipt_number,
      'inventory_acquisition_cost_in_minor_units', v_acquisition_total::BIGINT,
      'supplier_invoice_payable_total_in_minor_units', v_invoice_payable::BIGINT,
      'supplier_outstanding_balance_effect_in_minor_units', v_outstanding::BIGINT,
      'is_fully_received', v_all_completed,
      'wac', v_wac_results
    )
  );

  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.record_customer_opening_balances_v1(p_idempotency_key text, p_rows jsonb, p_dry_run boolean DEFAULT false, p_confirm_new_customers boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_replay JSONB;
  v_row JSONB;
  v_n INTEGER := 0;
  v_errors JSONB := '[]'::JSONB;
  v_error TEXT;
  v_warning BOOLEAN;
  v_customer_id UUID;
  v_phone TEXT;
  v_name TEXT;
  v_count INTEGER;
  v_other TEXT;
  v_date DATE;
  v_notes TEXT;
  v_today DATE := (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Amman')::DATE;
  v_valid JSONB := '[]'::JSONB;
  v_new JSONB := '{}'::JSONB;
  v_new_key TEXT;
  v_batch_id UUID;
  v_created JSONB := '[]'::JSONB;
  v_entry public.customer_opening_balances%ROWTYPE;
  v_total BIGINT := 0;
  v_result JSONB;
  v_created_customers JSONB := '[]'::JSONB;
BEGIN
  PERFORM public.assert_erp_role(ARRAY['owner'], 'إدخال ديون العملاء الافتتاحية');
  PERFORM public.go_live_assert_setup_open_internal();
  IF NOT COALESCE(p_dry_run, false) THEN
    v_replay := public.go_live_begin_batch_internal('customer_opening', p_idempotency_key, p_rows);
    IF v_replay IS NOT NULL THEN
      RETURN v_replay;
    END IF;
  ELSIF p_rows IS NULL OR jsonb_typeof(p_rows) <> 'array'
    OR jsonb_array_length(p_rows) NOT BETWEEN 1 AND 500 THEN
    RAISE EXCEPTION 'الدفعة يجب أن تحتوي من 1 إلى 500 سطر.';
  END IF;

  FOR v_row IN SELECT value FROM jsonb_array_elements(p_rows)
  LOOP
    v_n := v_n + 1;
    v_error := NULL; v_warning := false; v_customer_id := NULL; v_date := NULL; v_new_key := NULL;
    v_notes := NULLIF(BTRIM(v_row->>'notes'), '');
    v_name := NULLIF(BTRIM(v_row->>'customer_name'), '');
    v_phone := NULLIF(public.normalize_customer_phone(COALESCE(v_row->>'customer_phone', '')), '');
    IF jsonb_typeof(v_row) <> 'object' THEN
      v_error := 'بيانات السطر غير صحيحة.';
    ELSIF COALESCE(v_row->>'amount_in_minor_units', '') !~ '^[1-9][0-9]{0,11}$' THEN
      v_error := 'مبلغ الدين يجب أن يكون أكبر من صفر وبثلاث منازل عشرية كحد أقصى.';
    ELSIF COALESCE(v_row->>'original_debt_date', '') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN
      v_error := 'تاريخ الدين الأصلي مطلوب بصيغة YYYY-MM-DD.';
    ELSIF v_notes IS NOT NULL AND CHAR_LENGTH(v_notes) > 300 THEN
      v_error := 'الملاحظة أطول من 300 حرف.';
    ELSIF v_name IS NOT NULL AND CHAR_LENGTH(v_name) > 150 THEN
      v_error := 'اسم العميل أطول من المسموح.';
    END IF;
    IF v_error IS NULL THEN
      BEGIN
        v_date := (v_row->>'original_debt_date')::DATE;
      EXCEPTION WHEN OTHERS THEN
        v_error := 'تاريخ الدين الأصلي غير صحيح.';
      END;
    END IF;
    IF v_error IS NULL AND v_date > v_today THEN
      v_error := 'تاريخ الدين الأصلي لا يمكن أن يكون في المستقبل.';
    ELSIF v_error IS NULL AND v_date < DATE '2000-01-01' THEN
      v_error := 'تاريخ الدين الأصلي أقدم من المسموح (2000-01-01).';
    END IF;
    IF v_error IS NULL AND COALESCE(v_row->>'customer_id', '') <> '' THEN
      IF v_row->>'customer_id' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        SELECT id INTO v_customer_id FROM public.customers
        WHERE id = (v_row->>'customer_id')::UUID AND NOT is_deleted;
      END IF;
      IF v_customer_id IS NULL THEN v_error := 'العميل غير موجود.'; END IF;
    ELSIF v_error IS NULL AND v_phone IS NOT NULL THEN
      SELECT COUNT(*), MIN(id::TEXT)::UUID INTO v_count, v_customer_id FROM public.customers
      WHERE NOT is_deleted AND public.normalize_customer_phone(phone) = v_phone;
      IF v_count > 1 THEN
        v_customer_id := NULL;
        v_error := 'يوجد أكثر من عميل بهذا الهاتف؛ أدخل الدين يدوياً باختيار العميل.';
      ELSIF v_count = 0 THEN
        v_customer_id := NULL;
        SELECT full_name || ' — ' || phone INTO v_other FROM public.customers
        WHERE NOT is_deleted AND v_name IS NOT NULL
          AND public.go_live_normalize_name_internal(full_name) = public.go_live_normalize_name_internal(v_name)
        ORDER BY created_at LIMIT 1;
        IF v_other IS NOT NULL THEN
          v_warning := true;
          v_error := 'تحذير: يوجد عميل باسم مطابق أو مشابه وهاتف مختلف (' || v_other
            || ')؛ صحّح الهاتف في الملف أو أدخل الدين يدوياً. لن يُنشأ عميل مكرر.';
        ELSIF v_name IS NULL THEN
          v_error := 'لا يوجد عميل بهذا الهاتف، واسم العميل مطلوب لإضافته كعميل جديد.';
        ELSIF v_phone !~ '^[0-9]{9,15}$' THEN
          v_error := 'رقم هاتف العميل غير صحيح.';
        ELSE
          v_new_key := v_phone;
        END IF;
      END IF;
    ELSIF v_error IS NULL THEN
      IF v_name IS NULL THEN
        v_error := 'هاتف العميل أو اسمه مطلوب لمطابقته.';
      ELSE
        SELECT COUNT(*), MIN(id::TEXT)::UUID INTO v_count, v_customer_id FROM public.customers
        WHERE NOT is_deleted AND BTRIM(full_name) = v_name;
        IF v_count > 1 THEN
          v_customer_id := NULL;
          v_error := 'يوجد أكثر من عميل بهذا الاسم؛ أضف الهاتف في الملف.';
        ELSIF v_count = 0 THEN
          v_customer_id := NULL;
          SELECT full_name || ' — ' || phone INTO v_other FROM public.customers
          WHERE NOT is_deleted
            AND public.go_live_normalize_name_internal(full_name) = public.go_live_normalize_name_internal(v_name)
          ORDER BY created_at LIMIT 1;
          IF v_other IS NOT NULL THEN
            v_warning := true;
            v_error := 'تحذير: لا هاتف في السطر ويوجد عميل باسم مشابه (' || v_other
              || ')؛ أضف الهاتف أو أدخل الدين يدوياً. لن يُنشأ عميل مكرر.';
          ELSE
            v_error := 'لا يوجد عميل بهذا الاسم؛ أضف رقم الهاتف ليُنشأ عميل جديد.';
          END IF;
        END IF;
      END IF;
    END IF;
    IF v_error IS NULL AND v_new_key IS NOT NULL AND v_new ? v_new_key
      AND public.go_live_normalize_name_internal(v_new->v_new_key->>'name')
        <> public.go_live_normalize_name_internal(v_name) THEN
      v_warning := true;
      v_error := 'تحذير: نفس الهاتف الجديد ورد في الملف باسم آخر (' || (v_new->v_new_key->>'name')
        || ')؛ وحّد الاسم أو الهاتف.';
    END IF;
    IF v_error IS NULL AND EXISTS (
      SELECT 1 FROM jsonb_array_elements(v_valid) prior
      WHERE COALESCE(prior->>'customer_id', prior->>'new_key') = COALESCE(v_customer_id::TEXT, v_new_key)
        AND (prior->>'original_debt_date')::DATE = v_date
        AND (prior->>'amount_in_minor_units')::BIGINT = (v_row->>'amount_in_minor_units')::BIGINT) THEN
      v_error := 'سطر مكرر لنفس العميل والتاريخ والمبلغ داخل الملف؛ اجمعهما في سطر واحد.';
    END IF;
    IF v_error IS NOT NULL THEN
      v_errors := v_errors || jsonb_build_object('row', v_n, 'message', v_error,
        'kind', CASE WHEN v_warning THEN 'warning' ELSE 'error' END);
    ELSE
      IF v_new_key IS NOT NULL AND NOT v_new ? v_new_key THEN
        v_new := v_new || jsonb_build_object(v_new_key, jsonb_build_object('row', v_n, 'name', v_name, 'phone', v_phone));
      END IF;
      v_valid := v_valid || jsonb_build_object('row', v_n, 'customer_id', v_customer_id, 'new_key', v_new_key,
        'amount_in_minor_units', (v_row->>'amount_in_minor_units')::BIGINT,
        'original_debt_date', v_date, 'notes', v_notes);
      v_total := v_total + (v_row->>'amount_in_minor_units')::BIGINT;
    END IF;
  END LOOP;

  IF COALESCE(p_dry_run, false) THEN
    RETURN jsonb_build_object('success', true, 'dryRun', true, 'rowCount', v_n,
      'validCount', jsonb_array_length(v_valid), 'errors', v_errors,
      'validTotalInMinorUnits', v_total,
      'newCustomers', COALESCE((SELECT jsonb_agg(value ORDER BY (value->>'row')::INTEGER)
        FROM jsonb_each(v_new)), '[]'::JSONB),
      'customerCount', (SELECT COUNT(DISTINCT COALESCE(v->>'customer_id', v->>'new_key'))
        FROM jsonb_array_elements(v_valid) v));
  END IF;
  IF jsonb_array_length(v_errors) > 0 THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'GO_LIVE_BATCH_INVALID: الملف يحتوي أسطراً غير صالحة أو تحذيرات؛ لم يُحفظ أي سطر.',
      DETAIL = v_errors::TEXT;
  END IF;
  IF v_new <> '{}'::JSONB AND NOT COALESCE(p_confirm_new_customers, false) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'GO_LIVE_NEW_PARTIES_CONFIRMATION_REQUIRED: سيُضاف ' || (SELECT COUNT(*) FROM jsonb_object_keys(v_new))
        || ' عميل جديد؛ أكّد إضافتهم قبل الحفظ.';
  END IF;

  -- New customers first, through the existing customer contract.
  FOR v_new_key IN SELECT key FROM jsonb_each(v_new) ORDER BY (value->>'row')::INTEGER
  LOOP
    v_result := public.save_customer(v_new->v_new_key->>'name', v_new->v_new_key->>'phone');
    v_new := jsonb_set(v_new, ARRAY[v_new_key, 'customer_id'], to_jsonb(v_result->>'customer_id'));
    v_created_customers := v_created_customers || jsonb_build_object('customerId', v_result->>'customer_id',
      'name', v_new->v_new_key->>'name', 'phone', v_new->v_new_key->>'phone');
  END LOOP;

  v_batch_id := gen_random_uuid();
  FOR v_row IN SELECT value FROM jsonb_array_elements(v_valid)
  LOOP
    v_date := (v_row->>'original_debt_date')::DATE;
    v_customer_id := COALESCE((v_row->>'customer_id')::UUID, (v_new->(v_row->>'new_key')->>'customer_id')::UUID);
    INSERT INTO public.customer_opening_balances(entry_number, customer_id, amount_in_minor_units,
      original_debt_date, occurred_at, notes, batch_id, created_by)
    VALUES ('COB-' || LPAD(nextval('public.customer_opening_balance_number_seq')::TEXT, 6, '0'),
      v_customer_id, (v_row->>'amount_in_minor_units')::BIGINT, v_date,
      v_date::TIMESTAMP AT TIME ZONE 'Asia/Amman', v_row->>'notes', v_batch_id, v_user_id)
    RETURNING * INTO v_entry;
    v_created := v_created || jsonb_build_object('row', (v_row->>'row')::INTEGER,
      'entryId', v_entry.id, 'entryNumber', v_entry.entry_number, 'customerId', v_entry.customer_id,
      'amountInMinorUnits', v_entry.amount_in_minor_units, 'originalDebtDate', v_entry.original_debt_date);
  END LOOP;
  v_result := jsonb_build_object('success', true, 'dryRun', false, 'idempotentReplay', false,
    'kind', 'customer_opening', 'batchId', v_batch_id, 'rowCount', v_n,
    'totalInMinorUnits', v_total, 'created', v_created, 'createdCustomers', v_created_customers);
  INSERT INTO public.go_live_import_batches(id, batch_kind, idempotency_key, request_hash, row_count, result, created_by)
  VALUES (v_batch_id, 'customer_opening', BTRIM(p_idempotency_key), md5(p_rows::TEXT), v_n, v_result, v_user_id);
  INSERT INTO public.audit_logs(user_id, action, entity_name, entity_id, details)
  VALUES (v_user_id, 'GO_LIVE_CUSTOMER_OPENING_BALANCES', 'go_live_import_batches', v_batch_id,
    jsonb_build_object('idempotency_key', BTRIM(p_idempotency_key), 'row_count', v_n,
      'total_in_minor_units', v_total, 'created_customers', v_created_customers,
      'entries', (SELECT jsonb_agg(jsonb_build_object('entry_number', c->>'entryNumber',
        'customer_id', c->>'customerId', 'amount_in_minor_units', (c->>'amountInMinorUnits')::BIGINT,
        'original_debt_date', c->>'originalDebtDate')) FROM jsonb_array_elements(v_created) c)));
  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.record_customer_order_payment(p_order_id uuid, p_amount_in_minor_units bigint, p_payment_method text, p_reference_number text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id UUID:=auth.uid();v_order RECORD;v_due BIGINT;v_new_paid BIGINT;
  v_payment_id UUID;v_payment_number TEXT;v_position RECORD;
BEGIN
  PERFORM public.cheque_assert_customer_payment_role_internal(p_order_id,p_payment_method);
  PERFORM public.phase4_lock_customer_order_context_internal(p_order_id,
    LOWER(COALESCE(p_payment_method,'')) IN ('cash','cliq'),false);
  SELECT * INTO v_position FROM public.phase42_order_financial_position_internal(p_order_id);
  IF COALESCE(p_amount_in_minor_units,0)<=0 OR p_amount_in_minor_units>v_position.outstanding_total_in_minor_units THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='PHASE42_CUSTOMER_PAYMENT_EXCEEDS_EFFECTIVE_OUTSTANDING: Payment exceeds the Return-adjusted receivable.';
  END IF;
  IF p_amount_in_minor_units IS NULL OR p_amount_in_minor_units<=0 THEN RAISE EXCEPTION 'مبلغ الدفعة يجب أن يكون أكبر من صفر.';END IF;
  IF p_payment_method NOT IN ('cash','cliq','card','bank_transfer','cheque') THEN RAISE EXCEPTION 'طريقة الدفع غير معتمدة.';END IF;
  SELECT * INTO v_order FROM public.orders WHERE id=p_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'الطلب غير موجود.';END IF;
  IF v_order.status<>'completed' THEN RAISE EXCEPTION 'يمكن تسجيل الدفعة على طلب مكتمل فقط.';END IF;
  IF v_order.customer_id IS NULL THEN RAISE EXCEPTION 'الطلب غير مرتبط بعميل مسجل.';END IF;
  v_due:=GREATEST(v_order.total_in_minor_units-v_order.amount_paid_in_minor_units,0);
  IF v_due=0 THEN RAISE EXCEPTION 'الطلب مدفوع بالكامل.';END IF;
  IF p_amount_in_minor_units>v_due THEN
    RAISE EXCEPTION 'مبلغ الدفعة أكبر من المتبقي على الطلب (% د.أ).',TO_CHAR(v_due::NUMERIC/1000,'FM999999990.000');
  END IF;
  v_new_paid:=v_order.amount_paid_in_minor_units+p_amount_in_minor_units;
  v_payment_number:='CRV-'||TO_CHAR(NOW(),'YYYYMMDD')||'-'||LPAD(NEXTVAL('public.customer_payment_number_seq')::TEXT,6,'0');
  UPDATE public.orders SET amount_paid_in_minor_units=v_new_paid,
    payment_status=CASE WHEN v_new_paid>=total_in_minor_units THEN 'paid' ELSE 'partially_paid' END,
    updated_at=NOW() WHERE id=p_order_id;
  INSERT INTO public.customer_payments(payment_number,customer_id,order_id,amount_in_minor_units,payment_method,
    reference_number,notes,created_by)
  VALUES(v_payment_number,v_order.customer_id,p_order_id,p_amount_in_minor_units,p_payment_method,
    NULLIF(TRIM(p_reference_number),''),NULLIF(TRIM(p_notes),''),v_user_id) RETURNING id INTO v_payment_id;
  INSERT INTO public.audit_logs(user_id,action,entity_name,entity_id,details)
  VALUES(v_user_id,'RECORD_CUSTOMER_PAYMENT','customer_payments',v_payment_id,
    jsonb_build_object('payment_number',v_payment_number,'order_id',p_order_id,'order_number',v_order.order_number,
      'customer_id',v_order.customer_id,'amount_in_minor_units',p_amount_in_minor_units,
      'remaining_in_minor_units',v_order.total_in_minor_units-v_new_paid));
  RETURN jsonb_build_object('success',true,'payment_id',v_payment_id,'payment_number',v_payment_number,
    'order_id',p_order_id,'order_number',v_order.order_number,'amount_in_minor_units',p_amount_in_minor_units,
    'remaining_in_minor_units',v_order.total_in_minor_units-v_new_paid);
END;
$function$

CREATE OR REPLACE FUNCTION public.record_customer_order_payment_once(p_order_id uuid, p_amount_in_minor_units bigint, p_payment_method text, p_reference_number text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id UUID:=auth.uid();v_key TEXT:=NULLIF(TRIM(p_idempotency_key),'');
  v_existing public.customer_payments%ROWTYPE;v_result JSONB;
BEGIN
  PERFORM public.cheque_assert_customer_payment_role_internal(p_order_id,p_payment_method);
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'يجب تسجيل الدخول لتسجيل دفعة عميل.';END IF;
  IF v_key IS NULL OR CHAR_LENGTH(v_key) NOT BETWEEN 16 AND 200 THEN RAISE EXCEPTION 'مفتاح تكرار الدفعة غير صالح.';END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(v_user_id::TEXT||':'||v_key,0));
  SELECT * INTO v_existing FROM public.customer_payments WHERE created_by=v_user_id AND idempotency_key=v_key FOR UPDATE;
  IF FOUND THEN
    IF v_existing.order_id IS DISTINCT FROM p_order_id
      OR v_existing.amount_in_minor_units IS DISTINCT FROM p_amount_in_minor_units
      OR v_existing.payment_method IS DISTINCT FROM p_payment_method
      OR(p_payment_method='cliq' AND NULLIF(TRIM(v_existing.reference_number),'') IS DISTINCT FROM NULLIF(TRIM(p_reference_number),'')) THEN
      RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='PAYMENT_IDEMPOTENCY_CONFLICT: مفتاح الدفعة مستخدم لطلب مختلف.';
    END IF;
    RETURN jsonb_build_object('success',true,'idempotent',true,'payment_id',v_existing.id,
      'payment_number',v_existing.payment_number,'order_id',v_existing.order_id,
      'amount_in_minor_units',v_existing.amount_in_minor_units,'remaining_in_minor_units',
      GREATEST((SELECT total_in_minor_units-amount_paid_in_minor_units FROM public.orders WHERE id=v_existing.order_id),0));
  END IF;
  v_result:=public.record_customer_order_payment(p_order_id,p_amount_in_minor_units,p_payment_method,p_reference_number,p_notes);
  UPDATE public.customer_payments SET idempotency_key=v_key WHERE id=(v_result->>'payment_id')::UUID
    AND created_by=v_user_id AND idempotency_key IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'تعذر تثبيت مفتاح منع تكرار الدفعة.';END IF;
  RETURN v_result||jsonb_build_object('idempotent',false);
END;
$function$

CREATE OR REPLACE FUNCTION public.record_erp_staff_password_reset(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_full_name TEXT;
  v_target_is_owner BOOLEAN := false;
BEGIN
  PERFORM public.assert_erp_role(ARRAY['owner'], 'إعادة تعيين كلمة مرور مستخدم');
  IF p_user_id IS NULL OR p_user_id = auth.uid() THEN
    RAISE EXCEPTION 'لا يمكن إعادة تعيين كلمة مرور حسابك الحالي من هذه الشاشة.';
  END IF;
  SELECT profile.full_name INTO v_full_name FROM public.profiles profile WHERE profile.id = p_user_id;
  IF v_full_name IS NULL THEN
    RAISE EXCEPTION 'حساب المستخدم غير موجود.';
  END IF;
  SELECT EXISTS (
    SELECT 1 FROM public.user_roles assignment
    JOIN public.roles role ON role.id = assignment.role_id
    WHERE assignment.user_id = p_user_id AND role.code = 'owner'
  ) INTO v_target_is_owner;

  INSERT INTO public.audit_logs (user_id, action, entity_name, entity_id, details)
  VALUES (
    auth.uid(),
    CASE WHEN v_target_is_owner THEN 'إعادة تعيين كلمة مرور مالك نظام' ELSE 'إعادة تعيين كلمة مرور مستخدم' END,
    'staff_account', p_user_id,
    jsonb_build_object('full_name', v_full_name, 'is_owner', v_target_is_owner)
  );
  RETURN jsonb_build_object('success', true, 'userId', p_user_id, 'message', 'تم تسجيل إعادة تعيين كلمة المرور.');
END;
$function$

CREATE OR REPLACE FUNCTION public.record_go_live_cheques_v1(p_branch_id uuid, p_idempotency_key text, p_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_envelope JSONB:=jsonb_build_array(jsonb_build_object('branch',p_branch_id,'rows',p_rows));
  v_replay JSONB;v_plan JSONB;v_locked_rows JSONB;v_row JSONB;v_party RECORD;v_id UUID;v_index INTEGER:=0;v_created JSONB:='[]'::JSONB;v_result JSONB;
BEGIN
  PERFORM public.assert_erp_role(ARRAY['owner'],'تسجيل الشيكات القائمة قبل التشغيل');
  v_replay:=public.go_live_begin_batch_internal('opening_cheques',p_idempotency_key,v_envelope);
  IF EXISTS(SELECT 1 FROM public.go_live_import_batches WHERE idempotency_key=p_idempotency_key AND created_by<>auth.uid()) THEN
    RAISE EXCEPTION 'GO_LIVE_BATCH_KEY_CONFLICT: المفتاح يخص عملية لفاعل آخر.';END IF;
  IF v_replay IS NOT NULL THEN RETURN v_replay;END IF;
  PERFORM public.go_live_assert_setup_open_internal();
  -- Discover all parties before row locks. Same customer gate as collection;
  -- supplier rows are locked in UUID order before any cheque row is created.
  v_plan:=public.preview_go_live_cheques_v1(p_branch_id,p_rows);
  IF jsonb_array_length(v_plan->'errors')>0 THEN RAISE EXCEPTION USING MESSAGE='GO_LIVE_CHEQUE_ROWS_INVALID: صحح الأسطر قبل الحفظ.',DETAIL=(v_plan->'errors')::TEXT;END IF;
  v_locked_rows:=v_plan->'rows';
  FOR v_party IN SELECT DISTINCT (r->>'customerId')::UUID id FROM jsonb_array_elements(v_plan->'rows') r
    WHERE r->>'customerId' IS NOT NULL ORDER BY id LOOP
    PERFORM pg_advisory_xact_lock(hashtextextended('go-live-collection-customer:'||v_party.id::TEXT,0));
  END LOOP;
  FOR v_party IN SELECT DISTINCT (r->>'customerId')::UUID id FROM jsonb_array_elements(v_plan->'rows') r
    WHERE r->>'customerId' IS NOT NULL ORDER BY id LOOP
    PERFORM 1 FROM public.customers WHERE id=v_party.id AND NOT is_deleted FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'العميل غير موجود أو حُذف؛ أعد المعاينة.';END IF;
  END LOOP;
  FOR v_party IN SELECT DISTINCT COALESCE(r->>'supplierId',r->>'endorsedSupplierId')::UUID id FROM jsonb_array_elements(v_plan->'rows') r
    WHERE COALESCE(r->>'supplierId',r->>'endorsedSupplierId') IS NOT NULL ORDER BY id LOOP
    PERFORM 1 FROM public.suppliers WHERE id=v_party.id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'المورد غير موجود؛ أعد المعاينة.';END IF;
  END LOOP;
  -- Revalidate duplicates under party gates;preview is never write authority.
  v_plan:=public.preview_go_live_cheques_v1(p_branch_id,p_rows);
  IF jsonb_array_length(v_plan->'errors')>0 THEN RAISE EXCEPTION USING MESSAGE='GO_LIVE_CHEQUE_ROWS_INVALID: صحح الأسطر قبل الحفظ.',DETAIL=(v_plan->'errors')::TEXT;END IF;
  IF v_plan->'rows' IS DISTINCT FROM v_locked_rows THEN
    RAISE EXCEPTION 'GO_LIVE_CHEQUE_PARTIES_CHANGED: تغيّرت هوية الأطراف أثناء الحفظ؛ أعد المعاينة.';
  END IF;
  FOR v_row IN SELECT value FROM jsonb_array_elements(v_plan->'rows') LOOP
    v_index:=v_index+1;v_id:=gen_random_uuid();
    INSERT INTO public.deferred_cheques(id,tracking_number,direction,origin,cheque_number,bank_name,due_date,amount_in_minor_units,
      customer_id,supplier_id,endorsed_supplier_id,branch_id,status,original_debt_at,notes,created_by,changed_by)
    VALUES(v_id,'CHQ-'||lpad(nextval('public.deferred_cheque_number_seq')::TEXT,8,'0'),v_row->>'direction','opening',
      v_row->>'number',v_row->>'bank',(v_row->>'dueDate')::DATE,(v_row->>'amount')::BIGINT,
      (v_row->>'customerId')::UUID,(v_row->>'supplierId')::UUID,(v_row->>'endorsedSupplierId')::UUID,p_branch_id,
      v_row->>'status',(v_row->>'originalDebtAt')::TIMESTAMPTZ,v_row->>'notes',auth.uid(),auth.uid());
    FOR v_party IN SELECT 'customer'::TEXT kind,(v_row->>'customerId')::UUID id WHERE v_row->>'customerId' IS NOT NULL
      UNION ALL SELECT 'supplier',COALESCE(v_row->>'supplierId',v_row->>'endorsedSupplierId')::UUID
        WHERE COALESCE(v_row->>'supplierId',v_row->>'endorsedSupplierId') IS NOT NULL LOOP
      INSERT INTO public.cheque_party_keys(party_kind,party_id,bank_key,cheque_number,cheque_id)
      VALUES(v_party.kind,v_party.id,lower(v_row->>'bank'),v_row->>'number',v_id);
      INSERT INTO public.deferred_cheque_allocations(cheque_id,party_kind,party_id,origin_kind,origin_id,original_debt_at,amount_in_minor_units)
      VALUES(v_id,v_party.kind,v_party.id,'opening_cheque',v_id,(v_row->>'originalDebtAt')::TIMESTAMPTZ,(v_row->>'amount')::BIGINT);
    END LOOP;
    v_result:=public.cheque_finish_event_internal(v_id,'opening_registered',NULL,NULL,
      'opening-cheque-'||md5(p_idempotency_key)||'-'||v_index::TEXT,
      jsonb_build_object('action','opening_register','branch',p_branch_id,'batchKey',p_idempotency_key,'row',v_row));
    v_created:=v_created||jsonb_build_array(jsonb_build_object('id',v_id,'trackingNumber',v_result#>>'{cheque,tracking_number}'));
  END LOOP;
  v_result:=jsonb_build_object('success',true,'idempotentReplay',false,'created',v_created,'rowCount',v_index,
    'parties',v_plan->'parties','balanceEffectInMinorUnits',0);
  INSERT INTO public.go_live_import_batches(batch_kind,idempotency_key,request_hash,row_count,result,created_by)
  VALUES('opening_cheques',p_idempotency_key,md5(v_envelope::TEXT),v_index,v_result,auth.uid());
  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.record_supplier_opening_balances_v1(p_idempotency_key text, p_rows jsonb, p_dry_run boolean DEFAULT false, p_confirm_new_suppliers boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_replay JSONB;
  v_row JSONB;
  v_n INTEGER := 0;
  v_errors JSONB := '[]'::JSONB;
  v_error TEXT;
  v_supplier_id UUID;
  v_count INTEGER;
  v_warning BOOLEAN;
  v_name TEXT;
  v_phone TEXT;
  v_other TEXT;
  v_new_key TEXT;
  v_new JSONB := '{}'::JSONB;
  v_created_suppliers JSONB := '[]'::JSONB;
  v_date DATE;
  v_direction TEXT;
  v_notes TEXT;
  v_today DATE := (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Amman')::DATE;
  v_valid JSONB := '[]'::JSONB;
  v_batch_id UUID;
  v_created JSONB := '[]'::JSONB;
  v_entry public.supplier_opening_balances%ROWTYPE;
  v_payable BIGINT := 0;
  v_advance BIGINT := 0;
  v_supplier UUID;
  v_signed BIGINT;
  v_result JSONB;
BEGIN
  PERFORM public.assert_erp_role(ARRAY['owner'], 'إدخال أرصدة الموردين الافتتاحية');
  PERFORM public.go_live_assert_setup_open_internal();
  IF NOT COALESCE(p_dry_run, false) THEN
    v_replay := public.go_live_begin_batch_internal('supplier_opening', p_idempotency_key, p_rows);
    IF v_replay IS NOT NULL THEN
      RETURN v_replay;
    END IF;
  ELSIF p_rows IS NULL OR jsonb_typeof(p_rows) <> 'array'
    OR jsonb_array_length(p_rows) NOT BETWEEN 1 AND 500 THEN
    RAISE EXCEPTION 'الدفعة يجب أن تحتوي من 1 إلى 500 سطر.';
  END IF;

  FOR v_row IN SELECT value FROM jsonb_array_elements(p_rows)
  LOOP
    v_n := v_n + 1;
    v_error := NULL; v_warning := false; v_supplier_id := NULL; v_date := NULL; v_new_key := NULL; v_other := NULL;
    v_name := NULLIF(BTRIM(v_row->>'supplier_name'), '');
    v_phone := NULLIF(public.normalize_customer_phone(COALESCE(v_row->>'supplier_phone', '')), '');
    v_direction := v_row->>'direction';
    v_notes := NULLIF(BTRIM(v_row->>'notes'), '');
    IF jsonb_typeof(v_row) <> 'object' THEN
      v_error := 'بيانات السطر غير صحيحة.';
    ELSIF v_direction IS NULL OR v_direction NOT IN ('payable', 'advance') THEN
      v_error := 'اتجاه الرصيد يجب أن يكون "له" أو "عليه".';
    ELSIF COALESCE(v_row->>'amount_in_minor_units', '') !~ '^[1-9][0-9]{0,11}$' THEN
      v_error := 'المبلغ يجب أن يكون أكبر من صفر وبثلاث منازل عشرية كحد أقصى.';
    ELSIF COALESCE(v_row->>'original_balance_date', '') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN
      v_error := 'تاريخ الرصيد الأصلي مطلوب بصيغة YYYY-MM-DD.';
    ELSIF v_notes IS NOT NULL AND CHAR_LENGTH(v_notes) > 300 THEN
      v_error := 'الملاحظة أطول من 300 حرف.';
    END IF;
    IF v_error IS NULL THEN
      BEGIN
        v_date := (v_row->>'original_balance_date')::DATE;
      EXCEPTION WHEN OTHERS THEN
        v_error := 'تاريخ الرصيد الأصلي غير صحيح.';
      END;
    END IF;
    IF v_error IS NULL AND v_date > v_today THEN
      v_error := 'تاريخ الرصيد الأصلي لا يمكن أن يكون في المستقبل.';
    ELSIF v_error IS NULL AND v_date < DATE '2000-01-01' THEN
      v_error := 'تاريخ الرصيد الأصلي أقدم من المسموح (2000-01-01).';
    END IF;
    IF v_error IS NULL AND v_name IS NOT NULL AND CHAR_LENGTH(v_name) > 150 THEN
      v_error := 'اسم المورد أطول من المسموح.';
    END IF;
    IF v_error IS NULL AND COALESCE(v_row->>'supplier_id', '') <> '' THEN
      IF v_row->>'supplier_id' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        SELECT id INTO v_supplier_id FROM public.suppliers
        WHERE id = (v_row->>'supplier_id')::UUID AND is_active;
      END IF;
      IF v_supplier_id IS NULL THEN v_error := 'المورد غير موجود أو غير نشط.'; END IF;
    ELSIF v_error IS NULL AND v_name IS NULL AND v_phone IS NULL THEN
      v_error := 'اسم المورد أو هاتفه مطلوب لمطابقته.';
    ELSIF v_error IS NULL THEN
      IF v_phone IS NOT NULL THEN
        SELECT COUNT(*), MIN(id::TEXT)::UUID INTO v_count, v_supplier_id FROM public.suppliers
        WHERE is_active AND NULLIF(public.normalize_customer_phone(COALESCE(phone, '')), '') = v_phone;
        IF v_count > 1 THEN
          v_supplier_id := NULL;
          v_error := 'يوجد أكثر من مورد بهذا الهاتف؛ أدخل الرصيد يدوياً باختيار المورد.';
        ELSIF v_count = 0 THEN
          v_supplier_id := NULL;
        END IF;
      ELSE
        SELECT COUNT(*), MIN(id::TEXT)::UUID INTO v_count, v_supplier_id FROM public.suppliers
        WHERE is_active AND BTRIM(company_name) = v_name;
        IF v_count > 1 THEN
          v_supplier_id := NULL;
          v_error := 'يوجد أكثر من مورد بهذا الاسم؛ أدخل الرصيد يدوياً باختيار المورد.';
        ELSIF v_count = 0 THEN
          v_supplier_id := NULL;
        END IF;
      END IF;
      IF v_error IS NULL AND v_supplier_id IS NULL THEN
        SELECT company_name || COALESCE(' — ' || NULLIF(phone, ''), '') INTO v_other FROM public.suppliers
        WHERE is_active AND v_name IS NOT NULL
          AND public.go_live_normalize_name_internal(company_name) = public.go_live_normalize_name_internal(v_name)
        ORDER BY created_at LIMIT 1;
        IF v_other IS NOT NULL THEN
          v_warning := true;
          v_error := 'تحذير: يوجد مورد باسم مطابق أو مشابه '
            || CASE WHEN v_phone IS NULL THEN 'والسطر بلا هاتف' ELSE 'وهاتف مختلف' END
            || ' (' || v_other || ')؛ صحّح السطر أو أدخل الرصيد يدوياً. لن يُنشأ مورد مكرر.';
        ELSIF v_name IS NULL THEN
          v_error := 'لا يوجد مورد بهذا الهاتف، واسم المورد مطلوب لإضافته كمورد جديد.';
        ELSE
          v_new_key := public.go_live_normalize_name_internal(v_name);
        END IF;
      END IF;
    END IF;
    IF v_error IS NULL AND EXISTS (
      SELECT 1 FROM jsonb_array_elements(v_valid) prior
      WHERE COALESCE(prior->>'supplier_id', prior->>'new_key') = COALESCE(v_supplier_id::TEXT, v_new_key)) THEN
      v_error := 'المورد مكرر داخل الملف؛ اجعل لكل مورد سطراً واحداً بصافي رصيده.';
    END IF;
    IF v_error IS NOT NULL THEN
      v_errors := v_errors || jsonb_build_object('row', v_n, 'message', v_error,
        'kind', CASE WHEN v_warning THEN 'warning' ELSE 'error' END);
    ELSE
      IF v_new_key IS NOT NULL THEN
        v_new := v_new || jsonb_build_object(v_new_key, jsonb_build_object('row', v_n, 'name', v_name, 'phone', v_phone));
      END IF;
      v_valid := v_valid || jsonb_build_object('row', v_n, 'supplier_id', v_supplier_id, 'new_key', v_new_key,
        'direction', v_direction, 'amount_in_minor_units', (v_row->>'amount_in_minor_units')::BIGINT,
        'original_balance_date', v_date, 'notes', v_notes);
      IF v_direction = 'payable' THEN
        v_payable := v_payable + (v_row->>'amount_in_minor_units')::BIGINT;
      ELSE
        v_advance := v_advance + (v_row->>'amount_in_minor_units')::BIGINT;
      END IF;
    END IF;
  END LOOP;

  IF COALESCE(p_dry_run, false) THEN
    RETURN jsonb_build_object('success', true, 'dryRun', true, 'rowCount', v_n,
      'validCount', jsonb_array_length(v_valid), 'errors', v_errors,
      'newSuppliers', COALESCE((SELECT jsonb_agg(value ORDER BY (value->>'row')::INTEGER)
        FROM jsonb_each(v_new)), '[]'::JSONB),
      'payableTotalInMinorUnits', v_payable, 'advanceTotalInMinorUnits', v_advance);
  END IF;
  IF jsonb_array_length(v_errors) > 0 THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'GO_LIVE_BATCH_INVALID: الملف يحتوي أسطراً غير صالحة أو تحذيرات؛ لم يُحفظ أي سطر.',
      DETAIL = v_errors::TEXT;
  END IF;
  IF v_new <> '{}'::JSONB AND NOT COALESCE(p_confirm_new_suppliers, false) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'GO_LIVE_NEW_PARTIES_CONFIRMATION_REQUIRED: سيُضاف ' || (SELECT COUNT(*) FROM jsonb_object_keys(v_new))
        || ' مورد جديد؛ أكّد إضافتهم قبل الحفظ.';
  END IF;

  FOR v_new_key IN SELECT key FROM jsonb_each(v_new) ORDER BY (value->>'row')::INTEGER
  LOOP
    INSERT INTO public.suppliers(company_name, phone, is_active)
    VALUES (v_new->v_new_key->>'name', v_new->v_new_key->>'phone', true)
    RETURNING id INTO v_supplier_id;
    v_new := jsonb_set(v_new, ARRAY[v_new_key, 'supplier_id'], to_jsonb(v_supplier_id));
    v_created_suppliers := v_created_suppliers || jsonb_build_object('supplierId', v_supplier_id,
      'name', v_new->v_new_key->>'name', 'phone', v_new->v_new_key->>'phone');
    INSERT INTO public.audit_logs(user_id, action, entity_name, entity_id, details)
    VALUES (v_user_id, 'GO_LIVE_SUPPLIER_CREATED', 'suppliers', v_supplier_id,
      jsonb_build_object('company_name', v_new->v_new_key->>'name', 'phone', v_new->v_new_key->>'phone'));
  END LOOP;
  v_valid := (SELECT COALESCE(jsonb_agg(CASE WHEN v->>'supplier_id' IS NULL
      THEN jsonb_set(v, '{supplier_id}', v_new->(v->>'new_key')->'supplier_id') ELSE v END
      ORDER BY (v->>'row')::INTEGER), '[]'::JSONB)
    FROM jsonb_array_elements(v_valid) v);

  -- Lock suppliers in a stable order before changing their stored balances.
  FOR v_supplier IN SELECT DISTINCT (v->>'supplier_id')::UUID FROM jsonb_array_elements(v_valid) v ORDER BY 1
  LOOP
    PERFORM 1 FROM public.suppliers WHERE id = v_supplier FOR UPDATE;
  END LOOP;

  v_batch_id := gen_random_uuid();
  FOR v_row IN SELECT value FROM jsonb_array_elements(v_valid)
  LOOP
    INSERT INTO public.supplier_opening_balances(entry_number, supplier_id, direction,
      amount_in_minor_units, original_balance_date, notes, batch_id, created_by)
    VALUES ('SOB-' || LPAD(nextval('public.supplier_opening_balance_number_seq')::TEXT, 6, '0'),
      (v_row->>'supplier_id')::UUID, v_row->>'direction', (v_row->>'amount_in_minor_units')::BIGINT,
      (v_row->>'original_balance_date')::DATE, v_row->>'notes', v_batch_id, v_user_id)
    RETURNING * INTO v_entry;
    v_signed := CASE WHEN v_entry.direction = 'payable' THEN v_entry.amount_in_minor_units
      ELSE -v_entry.amount_in_minor_units END;
    UPDATE public.suppliers
    SET current_balance_in_minor_units = current_balance_in_minor_units + v_signed, updated_at = NOW()
    WHERE id = v_entry.supplier_id;
    v_created := v_created || jsonb_build_object('row', (v_row->>'row')::INTEGER,
      'entryId', v_entry.id, 'entryNumber', v_entry.entry_number, 'supplierId', v_entry.supplier_id,
      'direction', v_entry.direction, 'amountInMinorUnits', v_entry.amount_in_minor_units,
      'originalBalanceDate', v_entry.original_balance_date);
  END LOOP;
  v_result := jsonb_build_object('success', true, 'dryRun', false, 'idempotentReplay', false,
    'kind', 'supplier_opening', 'batchId', v_batch_id, 'rowCount', v_n,
    'payableTotalInMinorUnits', v_payable, 'advanceTotalInMinorUnits', v_advance, 'created', v_created,
    'createdSuppliers', v_created_suppliers);
  INSERT INTO public.go_live_import_batches(id, batch_kind, idempotency_key, request_hash, row_count, result, created_by)
  VALUES (v_batch_id, 'supplier_opening', BTRIM(p_idempotency_key), md5(p_rows::TEXT), v_n, v_result, v_user_id);
  INSERT INTO public.audit_logs(user_id, action, entity_name, entity_id, details)
  VALUES (v_user_id, 'GO_LIVE_SUPPLIER_OPENING_BALANCES', 'go_live_import_batches', v_batch_id,
    jsonb_build_object('idempotency_key', BTRIM(p_idempotency_key), 'row_count', v_n,
      'payable_total_in_minor_units', v_payable, 'advance_total_in_minor_units', v_advance,
      'created_suppliers', v_created_suppliers,
      'entries', (SELECT jsonb_agg(jsonb_build_object('entry_number', c->>'entryNumber',
        'supplier_id', c->>'supplierId', 'direction', c->>'direction',
        'amount_in_minor_units', (c->>'amountInMinorUnits')::BIGINT,
        'original_balance_date', c->>'originalBalanceDate')) FROM jsonb_array_elements(v_created) c)));
  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.record_supplier_payment(p_supplier_id uuid, p_purchase_order_id uuid DEFAULT NULL::uuid, p_amount_in_minor_units bigint DEFAULT 0, p_payment_method text DEFAULT 'cash'::text, p_reference_number text DEFAULT NULL::text, p_payment_date timestamp with time zone DEFAULT now(), p_notes text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_key TEXT := NULLIF(TRIM(p_idempotency_key), '');
  v_existing public.supplier_payments%ROWTYPE;
  v_result JSONB;
  v_po public.purchase_orders%ROWTYPE;
  v_active_paid NUMERIC;
  v_actual_payable NUMERIC;
BEGIN
  PERFORM public.assert_erp_role(
    ARRAY['owner', 'admin', 'manager', 'accountant'],
    'تسجيل دفعات الموردين'
  );

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'يجب تسجيل الدخول لتسجيل دفعة مورد.';
  END IF;
  IF p_payment_method IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '22004',
      MESSAGE = 'SUPPLIER_PAYMENT_METHOD_REQUIRED: طريقة دفع المورد مطلوبة.';
  END IF;
  IF v_key IS NULL OR CHAR_LENGTH(v_key) NOT BETWEEN 16 AND 200 THEN
    RAISE EXCEPTION 'مفتاح منع تكرار دفعة المورد غير صالح.';
  END IF;

  IF p_payment_method IN ('check','cheque') THEN
    PERFORM public.assert_erp_role(ARRAY['owner','manager'],'إصدار شيك مورد');
    IF NOT EXISTS(
      SELECT 1 FROM public.cheque_party_keys k
      JOIN public.deferred_cheques c ON c.id=k.cheque_id
      WHERE k.party_kind='supplier' AND k.party_id=p_supplier_id
        AND k.registered_by=v_user_id AND k.registration_txid=txid_current()
        AND c.status='pending' AND c.supplier_payment_id IS NULL
        AND c.amount_in_minor_units=p_amount_in_minor_units
        AND k.bank_key=c.bank_key AND k.cheque_number=c.cheque_number
        AND p_reference_number=c.cheque_number
        AND v_key='cheque-supplier-'||c.id::TEXT
        AND ((c.direction='outgoing' AND c.supplier_id=p_supplier_id)
          OR(c.direction='incoming' AND c.endorsed_supplier_id IS NULL))
    ) THEN
      RAISE EXCEPTION 'CHEQUE_REGISTRATION_REQUIRED: الشيك يحتاج البنك والرقم والاستحقاق عبر دورة الشيكات؛ لا تسجيل مباشر.';
    END IF;
  END IF;

  -- Serialize equal retries before the underlying implementation mutates the
  -- purchase order, supplier balance, cash shift, and audit history.
  PERFORM pg_advisory_xact_lock(
    hashtextextended(
      v_user_id::TEXT || ':purchase_order_payment:' || v_key,
      0
    )
  );

  SELECT * INTO v_existing
  FROM public.supplier_payments
  WHERE created_by = v_user_id
    AND idempotency_scope = 'purchase_order_payment'
    AND idempotency_key = v_key
  FOR UPDATE;

  IF FOUND THEN
    IF v_existing.supplier_id IS DISTINCT FROM p_supplier_id
      OR v_existing.purchase_order_id IS DISTINCT FROM p_purchase_order_id
      OR v_existing.amount_in_minor_units IS DISTINCT FROM p_amount_in_minor_units
      OR v_existing.payment_method IS DISTINCT FROM p_payment_method
      OR NULLIF(BTRIM(v_existing.reference_number),'') IS DISTINCT FROM NULLIF(BTRIM(p_reference_number),'')
    THEN RAISE EXCEPTION 'SUPPLIER_PAYMENT_IDEMPOTENCY_CONFLICT: استُخدم مفتاح الدفعة لطلب مختلف.'; END IF;
    RETURN jsonb_build_object(
      'success', true,
      'idempotent', true,
      'payment_id', v_existing.id,
      'supplier_id', v_existing.supplier_id,
      'purchase_order_id', v_existing.purchase_order_id,
      'amount_in_minor_units', v_existing.amount_in_minor_units,
      'message', 'تمت معالجة طلب الدفعة سابقًا.'
    );
  END IF;

  PERFORM public.phase2_lock_payment_shift_internal(
    (SELECT branch_id FROM public.purchase_orders WHERE id = p_purchase_order_id),
    p_payment_method, p_amount_in_minor_units
  );
  IF p_purchase_order_id IS NOT NULL THEN
    SELECT * INTO v_po FROM public.purchase_orders WHERE id=p_purchase_order_id FOR UPDATE;
    IF NOT FOUND OR v_po.supplier_id IS DISTINCT FROM p_supplier_id THEN
      RAISE EXCEPTION 'أمر الشراء لا يتبع المورد المحدد.';
    END IF;
    SELECT COALESCE(SUM(amount_in_minor_units),0) INTO v_active_paid
    FROM public.supplier_payments WHERE purchase_order_id=p_purchase_order_id AND NOT is_reversed;
    v_actual_payable := GREATEST(v_po.total_in_minor_units::NUMERIC,
      COALESCE((SELECT SUM(r.supplier_invoice_payable_total_snapshot_in_minor_units::NUMERIC)
        FROM public.purchase_receipts r WHERE r.purchase_order_id=p_purchase_order_id
          AND r.status='completed' AND r.phase2_finalized_at IS NOT NULL),0)
      +COALESCE((SELECT payable::NUMERIC FROM public.phase133_legacy_po_payables_internal()
        WHERE purchase_order_id=p_purchase_order_id),0));
    IF v_active_paid+p_amount_in_minor_units > v_actual_payable THEN
      RAISE EXCEPTION USING MESSAGE=format(
        'SUPPLIER_PO_PAYMENT_EXCEEDS_PAYABLE: المستحق الفعلي %s، المدفوع %s، الحد الأقصى المسموح الآن %s دينار.',
        v_actual_payable/1000.0,v_active_paid/1000.0,GREATEST(v_actual_payable-v_active_paid,0)/1000.0),
        DETAIL=jsonb_build_object('payable',v_actual_payable,'paid',v_active_paid,
          'maxAllowed',GREATEST(v_actual_payable-v_active_paid,0))::TEXT;
    END IF;
  END IF;
  v_result := public._record_supplier_payment_impl(
    p_supplier_id,
    p_purchase_order_id,
    p_amount_in_minor_units,
    p_payment_method,
    p_reference_number,
    p_payment_date,
    p_notes
  );

  -- One new committed payment reduces supplier debt even when it precedes
  -- receiving. The idempotent branch above never reaches this UPDATE.
  UPDATE public.suppliers
  SET current_balance_in_minor_units = current_balance_in_minor_units - p_amount_in_minor_units,
    updated_at = NOW()
  WHERE id = p_supplier_id;

  UPDATE public.supplier_payments
  SET
    idempotency_scope = 'purchase_order_payment',
    idempotency_key = v_key
  WHERE id = (v_result->>'payment_id')::UUID
    AND created_by = v_user_id
    AND idempotency_scope IS NULL
    AND idempotency_key IS NULL;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'تعذر تثبيت مفتاح منع تكرار دفعة المورد.';
  END IF;

  RETURN v_result || jsonb_build_object('idempotent', false);
END;
$function$

CREATE OR REPLACE FUNCTION public.record_supplier_receipt_payment(p_receipt_id uuid, p_amount_in_minor_units bigint, p_payment_method text DEFAULT 'cash'::text, p_reference_number text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_key TEXT := NULLIF(TRIM(p_idempotency_key), '');
  v_existing public.supplier_payments%ROWTYPE;
  v_result JSONB;
BEGIN
  PERFORM public.assert_erp_role(
    ARRAY['owner', 'admin', 'manager', 'accountant'],
    'تسجيل دفعات الموردين'
  );

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'يجب تسجيل الدخول لتسجيل دفعة مورد.';
  END IF;
  IF v_key IS NULL OR CHAR_LENGTH(v_key) NOT BETWEEN 16 AND 200 THEN
    RAISE EXCEPTION 'مفتاح منع تكرار دفعة المورد غير صالح.';
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended(
      v_user_id::TEXT || ':supplier_receipt_payment:' || v_key,
      0
    )
  );

  SELECT * INTO v_existing
  FROM public.supplier_payments
  WHERE created_by = v_user_id
    AND idempotency_scope = 'supplier_receipt_payment'
    AND idempotency_key = v_key
  FOR UPDATE;

  IF FOUND THEN
    RETURN jsonb_build_object(
      'success', true,
      'idempotent', true,
      'payment_id', v_existing.id,
      'supplier_id', v_existing.supplier_id,
      'receipt_id', v_existing.supplier_receipt_id,
      'amount_in_minor_units', v_existing.amount_in_minor_units,
      'message', 'تمت معالجة طلب الدفعة سابقًا.'
    );
  END IF;

  PERFORM public.phase2_lock_payment_shift_internal((SELECT branch_id FROM public.supplier_receipts WHERE id = p_receipt_id), COALESCE(p_payment_method, 'cash'), p_amount_in_minor_units);
  v_result := public._record_supplier_receipt_payment_impl(
    p_receipt_id,
    p_amount_in_minor_units,
    p_payment_method,
    p_reference_number,
    p_notes
  );

  UPDATE public.supplier_payments
  SET
    idempotency_scope = 'supplier_receipt_payment',
    idempotency_key = v_key
  WHERE id = (v_result->>'payment_id')::UUID
    AND created_by = v_user_id
    AND idempotency_scope IS NULL
    AND idempotency_key IS NULL;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'تعذر تثبيت مفتاح منع تكرار دفعة المورد.';
  END IF;

  RETURN v_result || jsonb_build_object('idempotent', false);
END;
$function$

CREATE OR REPLACE FUNCTION public.reorder_product_flavors_v1(p_master_product_id uuid, p_ordered_flavor_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_expected_count INTEGER;
  v_requested_count INTEGER;
BEGIN
  PERFORM public.assert_erp_role(
    ARRAY['owner', 'admin', 'manager', 'warehouse_keeper'],
    'ترتيب نكهات المنتج'
  );

  PERFORM 1
  FROM public.products
  WHERE id = p_master_product_id
    AND flavor_master_product_id IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'المنتج الأساسي غير موجود.';
  END IF;

  SELECT COUNT(*)::INTEGER INTO v_expected_count
  FROM public.products
  WHERE flavor_master_product_id = p_master_product_id;

  v_requested_count := COALESCE(CARDINALITY(p_ordered_flavor_ids), 0);
  IF v_requested_count <> v_expected_count THEN
    RAISE EXCEPTION 'يجب إرسال جميع نكهات المنتج عند ترتيبها.';
  END IF;
  IF (
    SELECT COUNT(DISTINCT requested.flavor_id)
    FROM UNNEST(p_ordered_flavor_ids) AS requested(flavor_id)
  ) <> v_requested_count THEN
    RAISE EXCEPTION 'قائمة ترتيب النكهات تحتوي على تكرار.';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM UNNEST(p_ordered_flavor_ids) AS requested(flavor_id)
    LEFT JOIN public.products p
      ON p.id = requested.flavor_id
      AND p.flavor_master_product_id = p_master_product_id
    WHERE p.id IS NULL
  ) THEN
    RAISE EXCEPTION 'قائمة ترتيب النكهات غير صالحة.';
  END IF;

  UPDATE public.products p
  SET
    flavor_sort_order = requested.position::INTEGER * 10,
    updated_at = NOW()
  FROM UNNEST(p_ordered_flavor_ids) WITH ORDINALITY
    AS requested(flavor_id, position)
  WHERE p.id = requested.flavor_id
    AND p.flavor_master_product_id = p_master_product_id;

  INSERT INTO public.audit_logs (
    user_id,
    action,
    entity_name,
    entity_id,
    details
  ) VALUES (
    auth.uid(),
    'REORDER_PRODUCT_FLAVORS',
    'products',
    p_master_product_id,
    jsonb_build_object(
      'ordered_flavor_ids', to_jsonb(p_ordered_flavor_ids),
      'flavor_count', v_requested_count
    )
  );

  RETURN jsonb_build_object(
    'success', TRUE,
    'productId', p_master_product_id,
    'message', 'تم ترتيب النكهات.'
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.report_admin_runtime_incident(p_fingerprint text, p_area text DEFAULT 'admin_render'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  PERFORM public.assert_erp_role(
    ARRAY['owner','admin','manager','accountant','cashier','sales','warehouse_keeper','orders','delivery_driver','view_only'],
    'تسجيل حادث تقني'
  );
  IF p_fingerprint !~ '^[a-f0-9]{64}$' OR p_area NOT IN ('admin_render','admin_global') THEN
    RAISE EXCEPTION 'Invalid runtime incident fingerprint.';
  END IF;
  INSERT INTO public.advanced_monitoring_runtime_incidents(
    fingerprint,application,area,occurrence_count,first_seen_at,last_seen_at,resolved_at,updated_at
  ) VALUES (p_fingerprint,'admin',p_area,1,NOW(),NOW(),NULL,NOW())
  ON CONFLICT(fingerprint) DO UPDATE SET occurrence_count=
    advanced_monitoring_runtime_incidents.occurrence_count+1,
    last_seen_at=NOW(),resolved_at=NULL,updated_at=NOW();
END;
$function$

CREATE OR REPLACE FUNCTION public.resolve_legacy_supplier_receipt_replay_v1(p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_receipt public.supplier_receipts%ROWTYPE;
BEGIN
  PERFORM public.assert_erp_role(
    ARRAY['owner', 'admin', 'manager', 'warehouse_keeper'],
    'مراجعة سند استلام تاريخي'
  );
  IF v_user_id IS NULL OR p_idempotency_key IS NULL THEN
    RETURN jsonb_build_object('found', false);
  END IF;

  SELECT * INTO v_receipt
  FROM public.supplier_receipts receipt
  WHERE receipt.idempotency_key = p_idempotency_key
    AND receipt.received_by = v_user_id;

  IF NOT FOUND THEN
    -- No distinction between an absent key and another actor's key.
    RETURN jsonb_build_object('found', false);
  END IF;

  RETURN jsonb_build_object(
    'found', true,
    'receipt_id', v_receipt.id,
    'receipt_number', v_receipt.receipt_number,
    'received_at', v_receipt.received_at,
    'total_in_minor_units', v_receipt.total_in_minor_units,
    'status', v_receipt.status
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.reverse_cash_shift_with_operations(p_shift_id uuid, p_reason text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id UUID;
  v_plan JSONB;
  v_result JSONB;
  v_reversal_id UUID;
  v_item JSONB;
  v_reason TEXT := NULLIF(TRIM(p_reason), '');
  v_reversed_count INTEGER := 0;
  v_reversed_amount BIGINT := 0;
  v_voided_count INTEGER := 0;
  v_voided_amount BIGINT := 0;
BEGIN
  v_user_id := public.assert_reversal_owner(
    'إلغاء الوردية وعكس جميع عملياتها'
  );
  PERFORM public.phase4_lock_full_shift_context_internal(p_shift_id);

  IF EXISTS (
    SELECT 1
    FROM public.sales_return_events return_event
    WHERE return_event.cash_shift_id = p_shift_id
      AND return_event.settlement_coordinator_version = 402
      AND return_event.settlement_status = 'settled'
      AND return_event.money_refund_amount_in_minor_units > 0
  ) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE42_SETTLED_RETURN_REFUND_DEPENDENCY: Reverse the settled Return through an approved future reversal contract before reversing its Shift.';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.customer_collection_operations op
    WHERE NOT op.is_reversed AND (op.cash_shift_id = p_shift_id OR EXISTS (
      SELECT 1 FROM public.customer_collection_order_payments link
      JOIN public.customer_payments payment ON payment.id = link.customer_payment_id
      WHERE link.operation_id = op.id AND payment.cash_shift_id = p_shift_id))
  ) OR EXISTS (
    SELECT 1 FROM public.supplier_opening_payments link
    JOIN public.supplier_payments payment ON payment.id = link.supplier_payment_id
    WHERE link.cash_shift_id = p_shift_id AND NOT COALESCE(payment.is_reversed, false)
  ) OR EXISTS (
    SELECT 1 FROM public.supplier_cheque_claim_payments link JOIN public.supplier_payments payment ON payment.id=link.supplier_payment_id
    WHERE link.cash_shift_id=p_shift_id AND NOT payment.is_reversed
  ) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'GO_LIVE_SHIFT_HAS_UNIFIED_OPERATIONS: الوردية تحتوي تحصيلاً موحداً أو سداد رصيد مورد افتتاحي؛ اعكس هذه العمليات أولاً.';
  END IF;

  -- Withdrawals of this shift and returns booked in it: lock, then decide
  -- before any write.
  PERFORM 1 FROM public.owner_cash_withdrawals WHERE cash_shift_id = p_shift_id ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.owner_cash_withdrawal_reversals
  WHERE effective_shift_id = p_shift_id
     OR withdrawal_id IN (SELECT id FROM public.owner_cash_withdrawals WHERE cash_shift_id = p_shift_id)
  ORDER BY id FOR UPDATE;
  v_plan := public.owner_withdrawal_shift_reversal_plan_internal(p_shift_id);
  IF NOT (v_plan->>'canExecute')::BOOLEAN THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = v_plan->>'blockedReason';
  END IF;

  v_result := public._reverse_cash_shift_with_operations_before_phase42_refund_guard(
    p_shift_id, p_reason, p_idempotency_key
  );
  IF COALESCE((v_result->>'idempotent')::BOOLEAN, false) THEN
    -- The first execution already handled withdrawals in its transaction.
    RETURN v_result || jsonb_build_object('ownerWithdrawals', v_plan);
  END IF;
  v_reversal_id := (v_result->>'reversalId')::UUID;

  FOR v_item IN SELECT value FROM jsonb_array_elements(v_plan->'withdrawalsToReverse') LOOP
    INSERT INTO public.owner_cash_withdrawal_reversals (
      withdrawal_id, effective_shift_id, amount_in_minor_units, reason, reversed_by,
      via_shift_reversal_id, idempotency_key, request_fingerprint
    ) VALUES (
      (v_item->>'withdrawalId')::UUID, p_shift_id, (v_item->>'amountInMinorUnits')::BIGINT, v_reason, v_user_id,
      v_reversal_id, 'shift-reversal:' || v_reversal_id::TEXT || ':' || (v_item->>'withdrawalId'),
      md5('shift-reversal|' || v_reversal_id::TEXT || '|' || (v_item->>'withdrawalId'))
    );
    v_reversed_count := v_reversed_count + 1;
    v_reversed_amount := v_reversed_amount + (v_item->>'amountInMinorUnits')::BIGINT;
  END LOOP;

  PERFORM set_config('nawasrah.owner_withdrawal_void', 'on', true);
  FOR v_item IN SELECT value FROM jsonb_array_elements(v_plan->'returnsToVoid') LOOP
    UPDATE public.owner_cash_withdrawal_reversals
    SET voided_at = clock_timestamp(), voided_by = v_user_id, voided_by_shift_reversal_id = v_reversal_id
    WHERE id = (v_item->>'reversalId')::UUID AND voided_at IS NULL;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'OWNER_WITHDRAWAL_RETURN_CHANGED: تغيّر عكس سحب أثناء عكس الوردية؛ أعد المحاولة.';
    END IF;
    v_voided_count := v_voided_count + 1;
    v_voided_amount := v_voided_amount + (v_item->>'amountInMinorUnits')::BIGINT;
  END LOOP;
  PERFORM set_config('nawasrah.owner_withdrawal_void', 'off', true);

  IF v_reversed_count + v_voided_count > 0 THEN
    INSERT INTO public.audit_logs (user_id, action, entity_name, entity_id, details)
    VALUES (v_user_id, 'REVERSE_OWNER_WITHDRAWALS_FOR_SHIFT', 'cash_shifts', p_shift_id,
      jsonb_build_object('reversal_id', v_reversal_id, 'reason', v_reason,
        'withdrawals_reversed', v_plan->'withdrawalsToReverse', 'returns_voided', v_plan->'returnsToVoid'));
  END IF;

  RETURN v_result || jsonb_build_object('ownerWithdrawals', jsonb_build_object(
    'withdrawalsReversedCount', v_reversed_count,
    'withdrawalsReversedInMinorUnits', v_reversed_amount,
    'returnsVoidedCount', v_voided_count,
    'returnsVoidedInMinorUnits', v_voided_amount));
END;
$function$

CREATE OR REPLACE FUNCTION public.reverse_customer_collection_v1(p_operation_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_reason TEXT := NULLIF(BTRIM(p_reason), '');
  v_operation public.customer_collection_operations%ROWTYPE;
  v_payment_id UUID;
BEGIN
  PERFORM public.assert_erp_role(ARRAY['owner', 'admin', 'manager', 'accountant'], 'عكس عملية تحصيل');
  IF v_reason IS NULL OR CHAR_LENGTH(v_reason) NOT BETWEEN 5 AND 500 THEN
    RAISE EXCEPTION 'اكتب سبب العكس (5 إلى 500 حرف).';
  END IF;
  SELECT * INTO v_operation FROM public.customer_collection_operations WHERE id = p_operation_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'عملية التحصيل غير موجودة.';
  END IF;
  IF v_operation.is_reversed THEN
    RETURN public.go_live_collection_result_internal(v_operation.id) || jsonb_build_object('idempotentReplay', true);
  END IF;
  IF v_operation.cash_shift_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.cash_shifts WHERE id = v_operation.cash_shift_id AND status = 'open' FOR UPDATE) THEN
    RAISE EXCEPTION 'لا يمكن عكس سند قبض مرتبط بوردية مغلقة؛ سجّل تسوية تدقيقية جديدة بدلاً من ذلك.';
  END IF;
  PERFORM set_config('nawasrah.collection_reversal', v_operation.id::TEXT, true);
  FOR v_payment_id IN SELECT customer_payment_id FROM public.customer_collection_order_payments
    WHERE operation_id = v_operation.id ORDER BY customer_payment_id
  LOOP
    PERFORM public.reverse_customer_order_payment(v_payment_id,
      'عكس عملية تحصيل ' || v_operation.operation_number || ': ' || v_reason);
  END LOOP;
  PERFORM set_config('nawasrah.collection_reversal', '', true);
  UPDATE public.customer_collection_operations
  SET is_reversed = true, reversed_at = NOW(), reversed_by = v_user_id, reversal_reason = v_reason
  WHERE id = v_operation.id RETURNING * INTO v_operation;
  INSERT INTO public.audit_logs(user_id, action, entity_name, entity_id, details)
  VALUES (v_user_id, 'CUSTOMER_UNIFIED_COLLECTION_REVERSED', 'customer_collection_operations', v_operation.id,
    jsonb_build_object('operation_number', v_operation.operation_number, 'customer_id', v_operation.customer_id,
      'amount_in_minor_units', v_operation.amount_in_minor_units, 'reason', v_reason));
  RETURN public.go_live_collection_result_internal(v_operation.id) || jsonb_build_object('idempotentReplay', false);
END;
$function$

CREATE OR REPLACE FUNCTION public.reverse_customer_opening_balance_v1(p_entry_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_reason TEXT := NULLIF(BTRIM(p_reason), '');
  v_entry public.customer_opening_balances%ROWTYPE;
  v_allocated BIGINT;
BEGIN
  PERFORM public.assert_erp_role(ARRAY['owner'], 'عكس دين عميل افتتاحي');
  IF v_reason IS NULL OR CHAR_LENGTH(v_reason) NOT BETWEEN 5 AND 300 THEN
    RAISE EXCEPTION 'اكتب سبب العكس (5 إلى 300 حرف).';
  END IF;
  SELECT * INTO v_entry FROM public.customer_opening_balances WHERE id = p_entry_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'الرصيد الافتتاحي غير موجود.';
  END IF;
  IF v_entry.is_reversed THEN
    RETURN jsonb_build_object('success', true, 'idempotentReplay', true, 'entryId', v_entry.id,
      'entryNumber', v_entry.entry_number, 'reversedAt', v_entry.reversed_at);
  END IF;
  SELECT COALESCE(SUM(a.amount_in_minor_units), 0) INTO v_allocated
  FROM public.customer_collection_opening_allocations a
  JOIN public.customer_collection_operations op ON op.id = a.operation_id
  WHERE a.opening_balance_id = p_entry_id AND NOT op.is_reversed;
  IF v_allocated > 0 THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'GO_LIVE_OPENING_HAS_COLLECTIONS: لا يمكن عكس دين قديم حُصّل منه مبلغ؛ اعكس عملية التحصيل أولاً.';
  END IF;
  UPDATE public.customer_opening_balances
  SET is_reversed = true, reversed_at = NOW(), reversed_by = v_user_id, reversal_reason = v_reason
  WHERE id = p_entry_id RETURNING * INTO v_entry;
  INSERT INTO public.audit_logs(user_id, action, entity_name, entity_id, details)
  VALUES (v_user_id, 'GO_LIVE_CUSTOMER_OPENING_REVERSED', 'customer_opening_balances', v_entry.id,
    jsonb_build_object('entry_number', v_entry.entry_number, 'customer_id', v_entry.customer_id,
      'amount_in_minor_units', v_entry.amount_in_minor_units,
      'original_debt_date', v_entry.original_debt_date, 'reason', v_reason,
      'after_go_live_finish', (SELECT finished_at IS NOT NULL FROM public.go_live_setup_state WHERE id)));
  RETURN jsonb_build_object('success', true, 'idempotentReplay', false, 'entryId', v_entry.id,
    'entryNumber', v_entry.entry_number, 'reversedAt', v_entry.reversed_at);
END;
$function$

CREATE OR REPLACE FUNCTION public.reverse_customer_order_payment(p_payment_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_order_id UUID;
  v_shift_id UUID;
  v_locked_order_id UUID;
  v_locked_shift_id UUID;
BEGIN
  PERFORM public.assert_erp_role(
    ARRAY['owner', 'admin', 'manager', 'accountant'],
    'عكس سند قبض عميل'
  );
  SELECT payment.order_id, payment.cash_shift_id
  INTO v_order_id, v_shift_id
  FROM public.customer_payments payment WHERE payment.id = p_payment_id;
  IF v_order_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'Customer payment not found.';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('phase4-order|' || v_order_id::TEXT, 0));
  IF v_shift_id IS NOT NULL THEN
    PERFORM 1 FROM public.cash_shifts shift WHERE shift.id = v_shift_id FOR UPDATE;
  END IF;
  PERFORM 1 FROM public.orders customer_order WHERE customer_order.id = v_order_id FOR UPDATE;
  SELECT payment.order_id, payment.cash_shift_id
  INTO v_locked_order_id, v_locked_shift_id
  FROM public.customer_payments payment
  WHERE payment.id = p_payment_id FOR UPDATE;
  IF v_locked_order_id IS DISTINCT FROM v_order_id
    OR v_locked_shift_id IS DISTINCT FROM v_shift_id
  THEN
    RAISE EXCEPTION USING ERRCODE = '40001',
      MESSAGE = 'PHASE4_LOCK_PLAN_CHANGED_RETRY: Customer Payment relationship changed.';
  END IF;
  RETURN public._reverse_customer_order_payment_before_phase4_lock(
    p_payment_id, p_reason
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.reverse_operational_expense(p_expense_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_shift_id UUID;
  v_locked_shift_id UUID;
BEGIN
  PERFORM public.assert_erp_role(
    ARRAY['owner', 'admin', 'manager', 'accountant'],
    'عكس مصروف تشغيلي'
  );
  SELECT expense.shift_id INTO v_shift_id
  FROM public.operational_expenses expense WHERE expense.id = p_expense_id;
  IF v_shift_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'Operational expense not found.';
  END IF;
  PERFORM 1 FROM public.cash_shifts shift WHERE shift.id = v_shift_id FOR UPDATE;
  SELECT expense.shift_id INTO v_locked_shift_id
  FROM public.operational_expenses expense
  WHERE expense.id = p_expense_id FOR UPDATE;
  IF v_locked_shift_id IS DISTINCT FROM v_shift_id THEN
    RAISE EXCEPTION USING ERRCODE = '40001',
      MESSAGE = 'PHASE4_LOCK_PLAN_CHANGED_RETRY: Expense Shift relationship changed.';
  END IF;
  RETURN public._reverse_operational_expense_before_phase4_lock(
    p_expense_id, p_reason
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.reverse_owner_cash_withdrawal_v1(p_withdrawal_id uuid, p_reason text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id UUID;
  v_key TEXT := BTRIM(COALESCE(p_idempotency_key, ''));
  v_reason TEXT := BTRIM(COALESCE(p_reason, ''));
  v_fingerprint TEXT;
  v_existing public.owner_cash_withdrawal_reversals%ROWTYPE;
  v_withdrawal public.owner_cash_withdrawals%ROWTYPE;
  v_original public.cash_shifts%ROWTYPE;
  v_effective_shift UUID;
  v_lock UUID;
  v_id UUID;
BEGIN
  v_user_id := public.assert_reversal_owner('عكس سحب المالك');
  IF char_length(v_key) NOT BETWEEN 16 AND 200 THEN
    RAISE EXCEPTION 'OWNER_WITHDRAWAL_KEY_INVALID: مفتاح العملية غير صالح.';
  END IF;
  IF char_length(v_reason) NOT BETWEEN 5 AND 500 THEN
    RAISE EXCEPTION 'OWNER_WITHDRAWAL_REVERSAL_REASON_REQUIRED: سبب العكس مطلوب (5 إلى 500 حرف).';
  END IF;
  v_fingerprint := md5(COALESCE(p_withdrawal_id::TEXT, '') || '|' || v_reason);

  SELECT * INTO v_existing FROM public.owner_cash_withdrawal_reversals
  WHERE reversed_by = v_user_id AND idempotency_key = v_key;
  IF FOUND THEN
    IF v_existing.request_fingerprint <> v_fingerprint THEN
      RAISE EXCEPTION 'OWNER_WITHDRAWAL_KEY_CONFLICT: استُخدم مفتاح العملية لطلب عكس مختلف.';
    END IF;
    RETURN public.owner_withdrawal_result_internal(v_existing.withdrawal_id, true)
      || jsonb_build_object('reversalId', v_existing.id, 'effectiveShiftId', v_existing.effective_shift_id);
  END IF;

  SELECT * INTO v_withdrawal FROM public.owner_cash_withdrawals WHERE id = p_withdrawal_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'OWNER_WITHDRAWAL_NOT_FOUND: السحب المحدد غير موجود.';
  END IF;
  SELECT * INTO v_original FROM public.cash_shifts WHERE id = v_withdrawal.cash_shift_id;
  -- The return goes back into the withdrawal's shift while it is open,
  -- otherwise into the open shift of the same branch (one per branch).
  IF v_original.status = 'open' THEN
    v_effective_shift := v_original.id;
  ELSE
    SELECT shift.id INTO v_effective_shift FROM public.cash_shifts shift
    WHERE shift.branch_id = v_withdrawal.branch_id AND shift.status = 'open';
    IF v_effective_shift IS NULL THEN
      RAISE EXCEPTION 'OWNER_WITHDRAWAL_REVERSAL_NEEDS_OPEN_SHIFT: افتح وردية في فرع السحب ليُعاد المبلغ إلى درجها.';
    END IF;
  END IF;

  -- Lock order: reversal domains (sorted), shift rows (sorted), then the withdrawal.
  FOR v_lock IN SELECT DISTINCT id FROM unnest(ARRAY[v_original.id, v_effective_shift]) id ORDER BY id LOOP
    PERFORM pg_advisory_xact_lock(hashtextextended('cash-shift-full-reversal:' || v_lock::TEXT, 0));
  END LOOP;
  PERFORM 1 FROM public.cash_shifts WHERE id IN (v_original.id, v_effective_shift) ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.owner_cash_withdrawals WHERE id = p_withdrawal_id FOR UPDATE;

  SELECT * INTO v_existing FROM public.owner_cash_withdrawal_reversals
  WHERE reversed_by = v_user_id AND idempotency_key = v_key;
  IF FOUND THEN
    IF v_existing.request_fingerprint <> v_fingerprint THEN
      RAISE EXCEPTION 'OWNER_WITHDRAWAL_KEY_CONFLICT: استُخدم مفتاح العملية لطلب عكس مختلف.';
    END IF;
    RETURN public.owner_withdrawal_result_internal(v_existing.withdrawal_id, true)
      || jsonb_build_object('reversalId', v_existing.id, 'effectiveShiftId', v_existing.effective_shift_id);
  END IF;
  IF EXISTS (SELECT 1 FROM public.owner_cash_withdrawal_reversals
    WHERE withdrawal_id = p_withdrawal_id AND voided_at IS NULL) THEN
    RAISE EXCEPTION 'OWNER_WITHDRAWAL_ALREADY_REVERSED: هذا السحب معكوس مسبقاً.';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.cash_shifts WHERE id = v_effective_shift AND status = 'open') THEN
    RAISE EXCEPTION 'OWNER_WITHDRAWAL_REVERSAL_NEEDS_OPEN_SHIFT: افتح وردية في فرع السحب ليُعاد المبلغ إلى درجها.';
  END IF;

  INSERT INTO public.owner_cash_withdrawal_reversals (
    withdrawal_id, effective_shift_id, amount_in_minor_units, reason, reversed_by,
    idempotency_key, request_fingerprint
  ) VALUES (
    p_withdrawal_id, v_effective_shift, v_withdrawal.amount_in_minor_units, v_reason, v_user_id,
    v_key, v_fingerprint
  ) RETURNING id INTO v_id;

  INSERT INTO public.audit_logs (user_id, action, entity_name, entity_id, details)
  VALUES (v_user_id, 'REVERSE_OWNER_CASH_WITHDRAWAL', 'owner_cash_withdrawals', p_withdrawal_id,
    jsonb_build_object('reversal_id', v_id, 'original_shift_id', v_original.id,
      'effective_shift_id', v_effective_shift, 'amount_in_minor_units', v_withdrawal.amount_in_minor_units,
      'reason', v_reason, 'original_shift_status', v_original.status));

  RETURN public.owner_withdrawal_result_internal(p_withdrawal_id, false)
    || jsonb_build_object('reversalId', v_id, 'effectiveShiftId', v_effective_shift,
      'shiftSummary', public.get_cash_shift_summary(v_effective_shift));
END;
$function$

CREATE OR REPLACE FUNCTION public.reverse_pos_sale(p_order_id uuid, p_reason text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id UUID;
  v_order public.orders%ROWTYPE;
  v_shift public.cash_shifts%ROWTYPE;
  v_existing public.pos_sale_reversals%ROWTYPE;
  v_reason TEXT := NULLIF(BTRIM(p_reason), '');
  v_key TEXT := NULLIF(BTRIM(p_idempotency_key), '');
  v_item RECORD;
  v_balance_before INTEGER;
  v_balance_after INTEGER;
  v_reserved INTEGER;
  v_cogs BIGINT := 0;
  v_profit BIGINT := 0;
  v_quantity INTEGER := 0;
  v_effect JSONB;
  v_product_ids UUID[];
  v_reversal_id UUID := gen_random_uuid();
BEGIN
  v_user_id := public.assert_reversal_owner('عكس بيع نقطة بيع مكتمل');
  IF p_order_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_POS_REVERSAL_ORDER_REQUIRED: بيع نقطة البيع غير محدد.';
  END IF;
  IF v_reason IS NULL OR CHAR_LENGTH(v_reason) NOT BETWEEN 3 AND 500 THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_POS_REVERSAL_REASON_INVALID: سبب العكس غير صالح.';
  END IF;
  IF v_key IS NULL OR CHAR_LENGTH(v_key) NOT BETWEEN 16 AND 200 THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_POS_REVERSAL_KEY_INVALID: مفتاح منع التكرار غير صالح.';
  END IF;

  PERFORM SET_CONFIG('lock_timeout', '3s', true);
  PERFORM SET_CONFIG('statement_timeout', '30s', true);

  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_POS_REVERSAL_ORDER_NOT_FOUND: بيع نقطة البيع غير موجود.';
  END IF;
  IF v_order.cash_shift_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_POS_REVERSAL_SHIFT_MISSING: البيع غير مرتبط بورديّة صريحة.';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(
    'cash-shift-full-reversal:' || v_order.cash_shift_id::TEXT, 0
  ));
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'pos-sale-reversal:' || p_order_id::TEXT, 0
  ));

  SELECT * INTO v_shift FROM public.cash_shifts
  WHERE id = v_order.cash_shift_id FOR UPDATE;
  IF NOT FOUND OR v_shift.status <> 'open' THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_POS_REVERSAL_SHIFT_CLOSED: لا يمكن العكس على ورديّة غير مفتوحة.';
  END IF;

  SELECT * INTO v_existing FROM public.pos_sale_reversals
  WHERE requested_by = v_user_id AND idempotency_key = v_key
  FOR UPDATE;
  IF FOUND THEN
    IF v_existing.order_id <> p_order_id THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001',
        MESSAGE = 'PHASE3_POS_REVERSAL_IDEMPOTENCY_CONFLICT: مفتاح العكس مستخدم لبيع آخر.';
    END IF;
    RETURN JSONB_BUILD_OBJECT(
      'success', true,
      'idempotent', true,
      'reversal_id', v_existing.id,
      'order_id', v_existing.order_id,
      'cash_shift_id', v_existing.cash_shift_id,
      'actual_effect', v_existing.actual_effect
    );
  END IF;

  SELECT * INTO v_order FROM public.orders
  WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND OR v_order.source IS DISTINCT FROM 'pos'
    OR v_order.cash_shift_id <> v_shift.id
  THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_POS_REVERSAL_ORDER_INVALID: السجل ليس بيع POS قابلاً للعكس.';
  END IF;

  SELECT * INTO v_existing FROM public.pos_sale_reversals
  WHERE order_id = p_order_id FOR UPDATE;
  IF FOUND THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_POS_REVERSAL_DUPLICATE: تم عكس البيع مسبقًا.';
  END IF;
  IF v_order.status <> 'completed' THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_POS_REVERSAL_ORDER_INVALID: البيع لم يعد مكتملًا قابلاً للعكس.';
  END IF;

  IF EXISTS (SELECT 1 FROM public.customer_payments payment
      WHERE payment.order_id = p_order_id)
    OR EXISTS (SELECT 1 FROM public.sales_returns return_row
      WHERE return_row.order_id = p_order_id)
  THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_POS_REVERSAL_DEPENDENCY_EXISTS: توجد دفعة أو مرتجع مرتبط بالبيع.';
  END IF;

  SELECT ARRAY_AGG(DISTINCT inventory_row.product_id
    ORDER BY inventory_row.product_id)
  INTO v_product_ids
  FROM public.phase3_pos_reversal_inventory_rows_internal(p_order_id) inventory_row;
  IF COALESCE(CARDINALITY(v_product_ids), 0) = 0 THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_POS_REVERSAL_INVENTORY_IDENTITY_MISSING: لا توجد حقيقة مخزون قابلة للعكس.';
  END IF;

  -- Reuse the same SKU advisory/balance/product hierarchy as sale and receipt.
  PERFORM public.phase3_lock_inventory_products_internal(v_product_ids);

  -- Check chronology only after taking the shared product/balance lock hierarchy.
  -- This closes the race where a concurrent sale/receipt could commit between
  -- the chronology read and the inventory restoration.
  IF EXISTS (
    SELECT 1
    FROM public.phase3_pos_reversal_inventory_rows_internal(p_order_id) inventory_row
    JOIN public.inventory_movements movement
      ON movement.warehouse_id = v_order.warehouse_id
     AND movement.product_id = inventory_row.product_id
    WHERE movement.reference_id IS DISTINCT FROM p_order_id
      AND movement.created_at >= v_order.created_at
  ) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'PHASE3_POS_REVERSAL_LATER_MOVEMENT: توجد حركة مخزون لاحقة على أحد أصناف البيع.';
  END IF;

  FOR v_item IN
    SELECT DISTINCT inventory_row.product_id
    FROM public.phase3_pos_reversal_inventory_rows_internal(p_order_id) inventory_row
    ORDER BY inventory_row.product_id
  LOOP
    SELECT balance.reserved_quantity INTO v_reserved
    FROM public.inventory_balances balance
    WHERE balance.warehouse_id = v_order.warehouse_id
      AND balance.product_id = v_item.product_id
    FOR UPDATE;
    IF NOT FOUND OR v_reserved <> 0 THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001',
        MESSAGE = 'PHASE3_POS_REVERSAL_INVENTORY_UNAVAILABLE: مخزون أحد الأصناف غير متاح أو محجوز.';
    END IF;
  END LOOP;

  SELECT
    COALESCE(SUM(item.cogs_in_minor_units), 0),
    COALESCE(SUM(item.profit_in_minor_units), 0)
  INTO v_cogs, v_profit
  FROM public.order_items item
  WHERE item.order_id = p_order_id;
  SELECT COALESCE(SUM(inventory_row.base_quantity), 0)::INTEGER
  INTO v_quantity
  FROM public.phase3_pos_reversal_inventory_rows_internal(p_order_id) inventory_row;

  v_effect := JSONB_BUILD_OBJECT(
    'payment_method', v_order.payment_method,
    'cash_in_minor_units', CASE WHEN v_order.payment_method = 'cash'
      THEN v_order.total_in_minor_units ELSE 0 END,
    'cliq_in_minor_units', CASE WHEN v_order.payment_method = 'cliq'
      THEN v_order.total_in_minor_units ELSE 0 END,
    'customer_receivable_in_minor_units', CASE WHEN v_order.payment_method = 'debt'
      THEN v_order.total_in_minor_units ELSE 0 END,
    'discount_in_minor_units', v_order.discount_in_minor_units,
    'cogs_in_minor_units', v_cogs,
    'profit_in_minor_units', v_profit,
    'restored_base_units', v_quantity
  );

  INSERT INTO public.pos_sale_reversals (
    id, order_id, cash_shift_id, requested_by, reason, idempotency_key,
    expected_effect, actual_effect
  ) VALUES (
    v_reversal_id, v_order.id, v_shift.id, v_user_id, v_reason, v_key,
    v_effect, v_effect
  );

  FOR v_item IN
    SELECT *
    FROM public.phase3_pos_reversal_inventory_rows_internal(p_order_id) inventory_row
    ORDER BY inventory_row.product_id,
      inventory_row.parcel_component_id NULLS FIRST,
      inventory_row.order_item_id
  LOOP
    SELECT balance.on_hand_quantity INTO v_balance_before
    FROM public.inventory_balances balance
    WHERE balance.warehouse_id = v_order.warehouse_id
      AND balance.product_id = v_item.product_id
    FOR UPDATE;
    v_balance_after := v_balance_before + v_item.base_quantity;
    UPDATE public.inventory_balances
    SET on_hand_quantity = v_balance_after, updated_at = NOW()
    WHERE warehouse_id = v_order.warehouse_id
      AND product_id = v_item.product_id;

    INSERT INTO public.inventory_movements (
      warehouse_id, product_id, movement_type, quantity,
      balance_before, balance_after, reference_type, reference_id,
      notes, created_by, operation_id, parcel_component_id
    ) VALUES (
      v_order.warehouse_id, v_item.product_id, 'return_in',
      v_item.base_quantity, v_balance_before, v_balance_after,
      'pos_sale_reversal', v_reversal_id,
      'عكس بيع نقطة البيع ' || v_order.order_number, v_user_id,
      v_item.operation_id, v_item.parcel_component_id
    );
  END LOOP;

  UPDATE public.orders
  SET status = 'cancelled', amount_paid_in_minor_units = 0,
    change_due_in_minor_units = 0, updated_at = NOW()
  WHERE id = v_order.id;

  INSERT INTO public.order_status_history (
    order_id, old_status, new_status, changed_by, notes
  ) VALUES (
    v_order.id, 'completed', 'cancelled', v_user_id,
    'عكس POS موثق: ' || v_reason
  );

  INSERT INTO public.audit_logs (
    user_id, action, entity_name, entity_id, details
  ) VALUES (
    v_user_id, 'REVERSE_POS_SALE', 'pos_sale_reversals', v_reversal_id,
    JSONB_BUILD_OBJECT(
      'order_id', v_order.id,
      'order_number', v_order.order_number,
      'cash_shift_id', v_shift.id,
      'reason', v_reason,
      'effect', v_effect
    )
  );

  RETURN JSONB_BUILD_OBJECT(
    'success', true,
    'idempotent', false,
    'reversal_id', v_reversal_id,
    'order_id', v_order.id,
    'cash_shift_id', v_shift.id,
    'actual_effect', v_effect
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.reverse_supplier_cheque_claim_payment_v1(p_supplier_payment_id uuid, p_reason text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_actor UUID;v_payment public.supplier_payments%ROWTYPE;v_initial public.supplier_payments%ROWTYPE;
  v_existing public.supplier_cheque_claim_reversals%ROWTYPE;v_shift public.cash_shifts%ROWTYPE;
  v_reason TEXT:=NULLIF(btrim(p_reason),'');v_key TEXT:=NULLIF(btrim(p_idempotency_key),'');v_id UUID;
BEGIN
  v_actor:=public.assert_reversal_owner('عكس سداد قيد شيك المورد');
  IF v_reason IS NULL OR char_length(v_reason) NOT BETWEEN 5 AND 500 THEN
    RAISE EXCEPTION 'سبب عكس سداد القيد مطلوب، من 5 إلى 500 حرف.';
  END IF;
  IF v_key IS NULL OR char_length(v_key) NOT BETWEEN 16 AND 160 THEN RAISE EXCEPTION 'مفتاح العكس غير صالح.';END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('supplier-cheque-claim-reversal-key:'||v_actor::TEXT||':'||v_key,0));
  SELECT * INTO v_existing FROM public.supplier_cheque_claim_reversals WHERE requested_by=v_actor AND idempotency_key=v_key;
  IF FOUND THEN
    IF v_existing.supplier_payment_id IS DISTINCT FROM p_supplier_payment_id OR v_existing.reason IS DISTINCT FROM v_reason THEN
      RAISE EXCEPTION 'CHEQUE_IDEMPOTENCY_CONFLICT: مفتاح عكس القيد مستخدم لطلب مختلف.';
    END IF;
    RETURN jsonb_build_object('success',true,'idempotentReplay',true,'reversalId',v_existing.id,'paymentId',v_existing.supplier_payment_id);
  END IF;
  SELECT * INTO v_initial FROM public.supplier_payments WHERE id=p_supplier_payment_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'دفعة سداد القيد غير موجودة.';END IF;
  -- Match the existing shift-first full-reversal/voucher lock domain.
  IF v_initial.cash_shift_id IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('cash-shift-full-reversal:'||v_initial.cash_shift_id::TEXT,0));
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('supplier-payment-reversal:'||p_supplier_payment_id::TEXT,0));
  IF v_initial.cash_shift_id IS NOT NULL THEN
    SELECT * INTO v_shift FROM public.cash_shifts WHERE id=v_initial.cash_shift_id FOR UPDATE;
    IF NOT FOUND OR v_shift.status<>'open' THEN RAISE EXCEPTION 'لا يمكن عكس سداد قيد من وردية غير مفتوحة.';END IF;
  END IF;
  SELECT * INTO v_payment FROM public.supplier_payments WHERE id=p_supplier_payment_id FOR UPDATE;
  IF NOT FOUND OR v_payment.cash_shift_id IS DISTINCT FROM v_initial.cash_shift_id
    OR v_payment.supplier_id IS DISTINCT FROM v_initial.supplier_id OR v_payment.is_reversed
    OR v_payment.supplier_receipt_id IS NOT NULL OR v_payment.purchase_order_id IS NOT NULL
    OR v_payment.payment_method NOT IN ('cash','cliq','bank_transfer')
    OR((v_payment.payment_method IN ('cash','cliq')) IS DISTINCT FROM(v_payment.cash_shift_id IS NOT NULL))
    OR EXISTS(SELECT 1 FROM public.deferred_cheques WHERE supplier_payment_id=p_supplier_payment_id)
    OR NOT EXISTS(SELECT 1 FROM public.supplier_cheque_claim_payments WHERE supplier_payment_id=p_supplier_payment_id)
    OR COALESCE((SELECT SUM(l.amount_in_minor_units) FROM public.supplier_cheque_claim_payments l
      JOIN public.cheque_compensation_claims c ON c.id=l.claim_id
      WHERE l.supplier_payment_id=p_supplier_payment_id AND c.party_kind='supplier' AND c.party_id=v_payment.supplier_id
        AND l.payment_method=v_payment.payment_method AND l.cash_shift_id IS NOT DISTINCT FROM v_payment.cash_shift_id),0)
      <>v_payment.amount_in_minor_units THEN
    RAISE EXCEPTION 'CHEQUE_CLAIM_REVERSAL_NOT_ALLOWED: هذه ليست دفعة سداد قيد مستقلة قابلة للعكس؛ دفعة الشيك الأصلية محمية.';
  END IF;
  PERFORM 1 FROM public.suppliers WHERE id=v_payment.supplier_id FOR UPDATE;
  IF(SELECT current_balance_in_minor_units FROM public.suppliers WHERE id=v_payment.supplier_id)
    IS DISTINCT FROM(SELECT balance FROM public.phase133_supplier_balance_evidence_internal() WHERE supplier_id=v_payment.supplier_id) THEN
    RAISE EXCEPTION 'CHEQUE_SUPPLIER_EVIDENCE_MISMATCH';
  END IF;
  INSERT INTO public.supplier_cheque_claim_reversals(supplier_payment_id,requested_by,reason,idempotency_key,amount_in_minor_units,cash_shift_id,payment_method)
  VALUES(v_payment.id,v_actor,v_reason,v_key,v_payment.amount_in_minor_units,v_payment.cash_shift_id,v_payment.payment_method) RETURNING id INTO v_id;
  UPDATE public.supplier_payments SET is_reversed=true,reversed_at=CURRENT_TIMESTAMP,reversed_by=v_actor,reversal_reason=v_reason WHERE id=v_payment.id;
  UPDATE public.suppliers SET current_balance_in_minor_units=current_balance_in_minor_units+v_payment.amount_in_minor_units,
    updated_at=CURRENT_TIMESTAMP WHERE id=v_payment.supplier_id;
  INSERT INTO public.audit_logs(user_id,action,entity_name,entity_id,details)
  VALUES(v_actor,'REVERSE_SUPPLIER_CHEQUE_CLAIM_PAYMENT','supplier_cheque_claim_reversals',v_id,
    jsonb_build_object('payment_id',v_payment.id,'supplier_id',v_payment.supplier_id,'amount_in_minor_units',v_payment.amount_in_minor_units,
      'cash_shift_id',v_payment.cash_shift_id,'payment_method',v_payment.payment_method,'reason',v_reason));
  RETURN jsonb_build_object('success',true,'idempotentReplay',false,'reversalId',v_id,'paymentId',v_payment.id);
END;
$function$

CREATE OR REPLACE FUNCTION public.reverse_supplier_opening_balance_v1(p_entry_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_reason TEXT := NULLIF(BTRIM(p_reason), '');
  v_entry public.supplier_opening_balances%ROWTYPE;
  v_supplier_id UUID;
BEGIN
  -- Owner decision 3: allowed also after go-live finish (owner, reason, audit).
  PERFORM public.assert_erp_role(ARRAY['owner'], 'عكس رصيد مورد افتتاحي');
  IF v_reason IS NULL OR CHAR_LENGTH(v_reason) NOT BETWEEN 5 AND 300 THEN
    RAISE EXCEPTION 'اكتب سبب العكس (5 إلى 300 حرف).';
  END IF;
  SELECT supplier_id INTO v_supplier_id FROM public.supplier_opening_balances WHERE id = p_entry_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'الرصيد الافتتاحي غير موجود.';
  END IF;
  -- Supplier first, then entry: the same order as the batch writer.
  PERFORM 1 FROM public.suppliers WHERE id = v_supplier_id FOR UPDATE;
  SELECT * INTO STRICT v_entry FROM public.supplier_opening_balances WHERE id = p_entry_id FOR UPDATE;
  IF v_entry.is_reversed THEN
    RETURN jsonb_build_object('success', true, 'idempotentReplay', true, 'entryId', v_entry.id,
      'entryNumber', v_entry.entry_number, 'reversedAt', v_entry.reversed_at);
  END IF;
  UPDATE public.supplier_opening_balances
  SET is_reversed = true, reversed_at = NOW(), reversed_by = v_user_id, reversal_reason = v_reason
  WHERE id = p_entry_id RETURNING * INTO v_entry;
  UPDATE public.suppliers
  SET current_balance_in_minor_units = current_balance_in_minor_units
    - CASE WHEN v_entry.direction = 'payable' THEN v_entry.amount_in_minor_units
      ELSE -v_entry.amount_in_minor_units END,
    updated_at = NOW()
  WHERE id = v_entry.supplier_id;
  INSERT INTO public.audit_logs(user_id, action, entity_name, entity_id, details)
  VALUES (v_user_id, 'GO_LIVE_SUPPLIER_OPENING_REVERSED', 'supplier_opening_balances', v_entry.id,
    jsonb_build_object('entry_number', v_entry.entry_number, 'supplier_id', v_entry.supplier_id,
      'direction', v_entry.direction, 'amount_in_minor_units', v_entry.amount_in_minor_units,
      'original_balance_date', v_entry.original_balance_date, 'reason', v_reason));
  RETURN jsonb_build_object('success', true, 'idempotentReplay', false, 'entryId', v_entry.id,
    'entryNumber', v_entry.entry_number, 'reversedAt', v_entry.reversed_at);
END;
$function$

CREATE OR REPLACE FUNCTION public.save_owner_warehouse_v1(p_id uuid, p_code text, p_name text, p_branch_id uuid, p_is_active boolean, p_expected_updated_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_before public.warehouses%ROWTYPE;v_after public.warehouses%ROWTYPE;
  v_name TEXT:=BTRIM(p_name);v_code TEXT:=BTRIM(p_code);v_exists BOOLEAN;
BEGIN
  PERFORM public.assert_erp_role(ARRAY['owner'],'حفظ مستودع');
  IF p_id IS NULL OR p_branch_id IS NULL OR p_is_active IS NULL
    OR v_name IS NULL OR CHAR_LENGTH(v_name) NOT BETWEEN 2 AND 120
    OR v_code IS NULL OR v_code!~'^[A-Z0-9_-]{1,32}$'
  THEN RAISE EXCEPTION 'WAREHOUSE_INPUT_INVALID: تحقق من اسم المستودع والفرع.';END IF;

  -- Rare administrative mutation: drain transactions that already read the
  -- warehouse before checking inventory, rather than modifying stock writers.
  -- The lock is transaction-scoped; no DDL, data movement or manual unlock.
  LOCK TABLE public.warehouses IN ACCESS EXCLUSIVE MODE;
  SELECT * INTO v_before FROM public.warehouses WHERE id=p_id FOR UPDATE;
  v_exists:=FOUND;
  IF v_exists AND v_before.code=v_code AND v_before.name_ar=v_name
    AND v_before.branch_id IS NOT DISTINCT FROM p_branch_id
    AND v_before.is_active=p_is_active
  THEN RETURN jsonb_build_object('warehouse',to_jsonb(v_before),'idempotentReplay',true);END IF;
  IF v_exists AND (p_expected_updated_at IS NULL OR v_before.updated_at IS DISTINCT FROM p_expected_updated_at)
  THEN RAISE EXCEPTION 'WAREHOUSE_EDIT_CONFLICT: تغير المستودع. حدّث الصفحة قبل الحفظ.';END IF;
  IF v_exists AND v_before.code<>v_code
  THEN RAISE EXCEPTION 'WAREHOUSE_CODE_IMMUTABLE: رمز المستودع لا يتغير.';END IF;
  IF NOT v_exists AND p_expected_updated_at IS NOT NULL
  THEN RAISE EXCEPTION 'WAREHOUSE_NOT_FOUND: المستودع غير موجود.';END IF;
  IF (NOT v_exists OR v_before.branch_id IS DISTINCT FROM p_branch_id)
    AND NOT EXISTS(SELECT 1 FROM public.branches WHERE id=p_branch_id AND is_active)
  THEN RAISE EXCEPTION 'WAREHOUSE_BRANCH_INVALID: اختر فرعاً نشطاً.';END IF;
  IF NOT p_is_active AND (NOT v_exists OR v_before.is_active) AND EXISTS(SELECT 1 FROM public.inventory_balances
    WHERE warehouse_id=p_id AND (on_hand_quantity<>0 OR reserved_quantity<>0))
  THEN RAISE EXCEPTION 'WAREHOUSE_HAS_STOCK: لا يمكن تعطيل مستودع لديه رصيد أو حجز.';END IF;
  IF NOT p_is_active AND v_exists AND v_before.is_active
    AND EXISTS(SELECT 1 FROM public.inventory_movements WHERE warehouse_id=p_id)
  THEN RAISE EXCEPTION 'WAREHOUSE_HAS_MOVEMENTS: لا يمكن تعطيل مستودع له حركة مخزون سابقة. تغيير الاسم مسموح.';END IF;
  IF NOT p_is_active AND v_exists AND v_before.is_active AND (
    EXISTS(SELECT 1 FROM public.inventory_balances WHERE warehouse_id=p_id)
    OR EXISTS(SELECT 1 FROM public.order_inventory_reservations WHERE warehouse_id=p_id)
    OR EXISTS(SELECT 1 FROM public.stock_alerts WHERE warehouse_id=p_id)
    OR EXISTS(SELECT 1 FROM public.inventory_opening_sessions d JOIN public.inventory_opening_items i ON i.session_id=d.id WHERE d.warehouse_id=p_id)
    OR EXISTS(SELECT 1 FROM public.orders d JOIN public.order_items i ON i.order_id=d.id WHERE d.warehouse_id=p_id)
    OR EXISTS(SELECT 1 FROM public.purchase_orders d JOIN public.purchase_order_items i ON i.purchase_order_id=d.id WHERE d.warehouse_id=p_id)
    OR EXISTS(SELECT 1 FROM public.purchase_receipts d JOIN public.purchase_receipt_items i ON i.purchase_receipt_id=d.id WHERE d.warehouse_id=p_id)
    OR EXISTS(SELECT 1 FROM public.supplier_receipts d JOIN public.supplier_receipt_items i ON i.supplier_receipt_id=d.id WHERE d.warehouse_id=p_id)
  ) THEN RAISE EXCEPTION 'WAREHOUSE_HAS_PRODUCTS: لا يمكن تعطيل مستودع مرتبط بصنف، حتى برصيد صفر ودون حركة. تغيير الاسم مسموح.';END IF;
  IF v_exists AND v_before.branch_id IS DISTINCT FROM p_branch_id
    AND EXISTS(SELECT 1 FROM public.inventory_movements WHERE warehouse_id=p_id)
  THEN RAISE EXCEPTION 'WAREHOUSE_HAS_MOVEMENTS: لا يمكن تغيير الفرع بعد حركة مخزون. تغيير الاسم مسموح.';END IF;
  IF EXISTS(SELECT 1 FROM public.warehouses WHERE code=v_code AND id<>p_id)
  THEN RAISE EXCEPTION 'WAREHOUSE_CODE_EXISTS: رمز المستودع مستخدم.';END IF;
  IF v_exists THEN
    UPDATE public.warehouses SET name_ar=v_name,branch_id=p_branch_id,is_active=p_is_active
      WHERE id=p_id RETURNING * INTO v_after;
  ELSE
    INSERT INTO public.warehouses(id,code,name_ar,branch_id,is_active)
      VALUES(p_id,v_code,v_name,p_branch_id,p_is_active) RETURNING * INTO v_after;
  END IF;
  INSERT INTO public.audit_logs(user_id,action,entity_name,entity_id,details)
  VALUES(auth.uid(),CASE WHEN v_exists THEN 'OWNER_WAREHOUSE_UPDATED' ELSE 'OWNER_WAREHOUSE_CREATED' END,
    'warehouses',p_id,jsonb_build_object('before',CASE WHEN v_exists THEN to_jsonb(v_before) ELSE NULL END,'after',to_jsonb(v_after)));
  RETURN jsonb_build_object('warehouse',to_jsonb(v_after),'idempotentReplay',false);
END;
$function$

CREATE OR REPLACE FUNCTION public.save_product_category(p_name_ar text, p_category_id uuid, p_code text, p_image_url text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_category_id UUID := COALESCE(p_category_id, gen_random_uuid());
  v_name_ar TEXT := NULLIF(BTRIM(p_name_ar), '');
  v_code TEXT;
  v_image_url TEXT := NULLIF(BTRIM(p_image_url), '');
  v_storage_path TEXT;
  v_is_new BOOLEAN := p_category_id IS NULL;
BEGIN
  PERFORM public.assert_erp_role(
    ARRAY['owner', 'admin', 'manager', 'warehouse_keeper'],
    'إدارة أقسام المنتجات'
  );

  IF v_name_ar IS NULL THEN
    RAISE EXCEPTION 'اسم القسم مطلوب.';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.categories c
    WHERE c.id <> v_category_id
      AND c.is_active = true
      AND LOWER(BTRIM(c.name_ar)) = LOWER(v_name_ar)
  ) THEN
    RAISE EXCEPTION 'يوجد قسم نشط بهذا الاسم مسبقاً.';
  END IF;

  IF p_category_id IS NOT NULL THEN
    SELECT c.code
    INTO v_code
    FROM public.categories c
    WHERE c.id = p_category_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'القسم المحدد غير موجود.';
    END IF;
  END IF;

  IF NULLIF(BTRIM(p_code), '') IS NOT NULL THEN
    v_code := NULLIF(
      BTRIM(
        REGEXP_REPLACE(
          UPPER(BTRIM(p_code)),
          '[^A-Z0-9_-]+',
          '-',
          'g'
        ),
        '-'
      ),
      ''
    );
  END IF;

  v_code := COALESCE(
    v_code,
    'CAT-' || UPPER(SUBSTRING(REPLACE(v_category_id::TEXT, '-', '') FROM 1 FOR 8))
  );

  IF v_image_url IS NOT NULL THEN
    v_storage_path := SPLIT_PART(
      v_image_url,
      '/storage/v1/object/public/product-images/',
      2
    );

    IF v_storage_path = v_image_url
      OR v_storage_path = ''
      OR NOT EXISTS (
        SELECT 1
        FROM storage.objects o
        WHERE o.bucket_id = 'product-images'
          AND o.name = v_storage_path
      )
    THEN
      RAISE EXCEPTION 'صورة القسم يجب أن تكون مرفوعة من تطبيق الإدارة.';
    END IF;
  END IF;

  INSERT INTO public.categories (
    id,
    code,
    name_ar,
    image_url,
    is_active
  ) VALUES (
    v_category_id,
    v_code,
    v_name_ar,
    v_image_url,
    true
  )
  ON CONFLICT (id) DO UPDATE
  SET
    code = EXCLUDED.code,
    name_ar = EXCLUDED.name_ar,
    image_url = EXCLUDED.image_url,
    is_active = true;

  INSERT INTO public.audit_logs (
    user_id,
    action,
    entity_name,
    entity_id,
    details
  ) VALUES (
    auth.uid(),
    CASE WHEN v_is_new THEN 'CREATE_PRODUCT_CATEGORY' ELSE 'UPDATE_PRODUCT_CATEGORY' END,
    'categories',
    v_category_id,
    jsonb_build_object(
      'name_ar', v_name_ar,
      'code', v_code,
      'has_image', v_image_url IS NOT NULL
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'categoryId', v_category_id,
    'code', v_code,
    'nameAr', v_name_ar,
    'imageUrl', v_image_url,
    'message', CASE
      WHEN v_is_new THEN 'تمت إضافة القسم بنجاح.'
      ELSE 'تم تحديث القسم بنجاح.'
    END
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.save_product_parcel_configuration_v1(p_family_product_id uuid, p_composition_mode text, p_is_active boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_units INTEGER; v_ids UUID[]; v_configuration public.product_parcel_configurations%ROWTYPE;
BEGIN
  PERFORM public.assert_erp_role(ARRAY['owner'],'إعداد الطرود');
  PERFORM pg_advisory_xact_lock(hashtextextended('parcel-configuration|' || p_family_product_id::TEXT,0));
  SELECT * INTO v_configuration FROM public.product_parcel_configurations
  WHERE family_product_id=p_family_product_id FOR UPDATE;
  SELECT units_per_sale_unit INTO v_units FROM public.products WHERE id=p_family_product_id;
  IF v_configuration.id IS NOT NULL AND v_configuration.composition_mode=p_composition_mode THEN
    SELECT array_agg(allowed.product_id ORDER BY allowed.product_id) INTO v_ids
    FROM public.product_parcel_allowed_components allowed
    JOIN public.products component ON component.id=allowed.product_id AND component.is_active
    WHERE allowed.configuration_id=v_configuration.id;
  ELSE
    SELECT array_agg(product.id ORDER BY product.id) INTO v_ids FROM public.products product
    WHERE product.is_active AND CASE WHEN p_composition_mode='single_sku'
      THEN product.id=p_family_product_id
      ELSE product.flavor_master_product_id=p_family_product_id AND NOT product.is_flavor_master END;
  END IF;
  RETURN public.save_product_parcel_configuration_v1(
    p_family_product_id,p_composition_mode,p_is_active,v_units,COALESCE(v_ids,'{}'::UUID[]));
END;
$function$

CREATE OR REPLACE FUNCTION public.save_product_parcel_configuration_v1(p_family_product_id uuid, p_composition_mode text, p_is_active boolean, p_units_per_parcel integer, p_allowed_product_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_configuration public.product_parcel_configurations%ROWTYPE;
  v_family public.products%ROWTYPE; v_previous_ids UUID[]; v_ids UUID[];
BEGIN
  PERFORM public.assert_erp_role(ARRAY['owner'], 'إعداد الطرود');
  IF p_composition_mode IS NULL OR p_composition_mode NOT IN ('single_sku','configurable_mix')
    OR p_is_active IS NULL OR p_units_per_parcel IS NULL OR p_units_per_parcel <= 0
    OR p_allowed_product_ids IS NULL OR array_position(p_allowed_product_ids,NULL) IS NOT NULL THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='PARCEL_CONFIGURATION_INVALID: راجع إعداد الطرد.';
  END IF;
  -- Configuration before family/product matches the sales validator order.
  -- Serialize creation of a previously absent configuration as well.
  PERFORM pg_advisory_xact_lock(hashtextextended('parcel-configuration|' || p_family_product_id::TEXT,0));
  SELECT * INTO v_configuration FROM public.product_parcel_configurations
  WHERE family_product_id=p_family_product_id FOR UPDATE;
  SELECT * INTO v_family FROM public.products WHERE id=p_family_product_id FOR UPDATE;
  IF NOT FOUND OR NOT v_family.is_active OR v_family.flavor_master_product_id IS NOT NULL
    OR v_family.sale_unit_id IS NULL
    OR (p_composition_mode='configurable_mix' AND NOT v_family.is_flavor_master) THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='PARCEL_CONFIGURATION_INVALID: العائلة غير صالحة لهذا الطرد.';
  END IF;
  SELECT COALESCE(array_agg(id ORDER BY id),'{}'::UUID[]) INTO v_ids
  FROM (SELECT DISTINCT unnest(p_allowed_product_ids) id) ids;
  IF (p_is_active AND cardinality(v_ids)=0)
    OR (p_composition_mode='single_sku' AND v_ids IS DISTINCT FROM ARRAY[p_family_product_id])
    OR EXISTS(SELECT 1 FROM unnest(v_ids) requested(id)
      LEFT JOIN public.products component ON component.id=requested.id
      WHERE component.id IS NULL OR NOT component.is_active
        OR (p_composition_mode='configurable_mix' AND
          (component.flavor_master_product_id IS DISTINCT FROM p_family_product_id
            OR component.is_flavor_master))) THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='PARCEL_COMPONENT_FAMILY_MISMATCH: النكهات المسموحة يجب أن تنتمي للعائلة نفسها.';
  END IF;
  SELECT COALESCE(array_agg(product_id ORDER BY product_id),'{}'::UUID[])
  INTO v_previous_ids FROM public.product_parcel_allowed_components
  WHERE configuration_id=v_configuration.id;
  IF v_family.units_per_sale_unit IS DISTINCT FROM p_units_per_parcel THEN
    UPDATE public.products SET units_per_sale_unit=p_units_per_parcel
    WHERE id=p_family_product_id;
  END IF;
  IF v_configuration.id IS NULL THEN
    INSERT INTO public.product_parcel_configurations(family_product_id,composition_mode,is_active,created_by,updated_by)
    VALUES(p_family_product_id,p_composition_mode,p_is_active,auth.uid(),auth.uid())
    RETURNING * INTO v_configuration;
  ELSE
    UPDATE public.product_parcel_configurations SET composition_mode=p_composition_mode,
      is_active=p_is_active,updated_by=auth.uid(),updated_at=now(),
      configuration_revision=configuration_revision+CASE WHEN
        v_configuration.composition_mode IS DISTINCT FROM p_composition_mode
        OR v_configuration.is_active IS DISTINCT FROM p_is_active
        OR v_family.units_per_sale_unit IS DISTINCT FROM p_units_per_parcel
        OR v_previous_ids IS DISTINCT FROM v_ids THEN 1 ELSE 0 END
    WHERE id=v_configuration.id RETURNING * INTO v_configuration;
  END IF;
  DELETE FROM public.product_parcel_allowed_components WHERE configuration_id=v_configuration.id;
  INSERT INTO public.product_parcel_allowed_components(configuration_id,product_id)
  SELECT v_configuration.id,unnest(v_ids);
  RETURN jsonb_build_object('success',true,'configuration',to_jsonb(v_configuration),
    'unitsPerParcel',p_units_per_parcel,'allowedProductIds',to_jsonb(v_ids));
END;
$function$

CREATE OR REPLACE FUNCTION public.save_product_unit(p_name_ar text, p_code text, p_conversion_factor integer DEFAULT 1, p_unit_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_unit_id UUID := p_unit_id;
  v_name_ar TEXT := NULLIF(BTRIM(p_name_ar), '');
  v_code TEXT := NULLIF(
    BTRIM(
      REGEXP_REPLACE(
        UPPER(BTRIM(p_code)),
        '[^A-Z0-9_-]+',
        '-',
        'g'
      ),
      '-'
    ),
    ''
  );
  v_existing_active BOOLEAN;
  v_existing_system BOOLEAN;
  v_is_new BOOLEAN := p_unit_id IS NULL;
  v_was_restored BOOLEAN := false;
BEGIN
  PERFORM public.assert_erp_role(
    ARRAY['owner', 'admin', 'manager', 'warehouse_keeper'],
    'إدارة وحدات القياس والتعبئة'
  );

  IF v_name_ar IS NULL THEN
    RAISE EXCEPTION 'اسم الوحدة مطلوب.';
  END IF;
  IF v_code IS NULL THEN
    RAISE EXCEPTION 'كود الوحدة مطلوب.';
  END IF;
  IF COALESCE(p_conversion_factor, 0) <= 0 THEN
    RAISE EXCEPTION 'معامل التعبئة يجب أن يكون عدداً صحيحاً أكبر من صفر.';
  END IF;

  IF p_unit_id IS NULL THEN
    SELECT u.id, u.is_active, u.is_system
    INTO v_unit_id, v_existing_active, v_existing_system
    FROM public.units u
    WHERE u.code = v_code
    FOR UPDATE;

    IF FOUND AND v_existing_active THEN
      RAISE EXCEPTION 'يوجد كود وحدة نشط بهذا الاسم مسبقاً.';
    ELSIF FOUND AND v_existing_system THEN
      RAISE EXCEPTION 'لا يمكن استبدال وحدة نظام أساسية.';
    ELSIF FOUND THEN
      v_was_restored := true;
      v_is_new := false;
    ELSE
      v_unit_id := gen_random_uuid();
    END IF;
  ELSE
    SELECT is_system
    INTO v_existing_system
    FROM public.units
    WHERE id = p_unit_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'وحدة القياس المحددة غير موجودة.';
    END IF;
    IF v_existing_system THEN
      RAISE EXCEPTION 'وحدات النظام الأساسية محمية من التعديل.';
    END IF;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.units
    WHERE id <> v_unit_id
      AND code = v_code
  ) THEN
    RAISE EXCEPTION 'كود الوحدة مستخدم مسبقاً.';
  END IF;

  INSERT INTO public.units (
    id,
    code,
    name_ar,
    conversion_factor,
    is_system,
    is_active,
    updated_at
  ) VALUES (
    v_unit_id,
    v_code,
    v_name_ar,
    p_conversion_factor,
    false,
    true,
    NOW()
  )
  ON CONFLICT (id) DO UPDATE
  SET
    code = EXCLUDED.code,
    name_ar = EXCLUDED.name_ar,
    conversion_factor = EXCLUDED.conversion_factor,
    is_active = true,
    updated_at = NOW();

  INSERT INTO public.audit_logs (
    user_id,
    action,
    entity_name,
    entity_id,
    details
  ) VALUES (
    auth.uid(),
    CASE
      WHEN v_was_restored THEN 'RESTORE_PRODUCT_UNIT'
      WHEN v_is_new THEN 'CREATE_PRODUCT_UNIT'
      ELSE 'UPDATE_PRODUCT_UNIT'
    END,
    'units',
    v_unit_id,
    jsonb_build_object(
      'name_ar', v_name_ar,
      'code', v_code,
      'conversion_factor', p_conversion_factor
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'unitId', v_unit_id,
    'nameAr', v_name_ar,
    'code', v_code,
    'conversionFactor', p_conversion_factor,
    'isActive', true,
    'message', CASE
      WHEN v_was_restored THEN 'تمت إعادة تفعيل وحدة القياس.'
      WHEN v_is_new THEN 'تمت إضافة وحدة القياس بنجاح.'
      ELSE 'تم تحديث وحدة القياس بنجاح.'
    END
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.scan_business_summaries(p_observed_at timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_settings public.business_alert_settings%ROWTYPE;
  v_local_now TIMESTAMP;
  v_latest_daily_due DATE;
  v_latest_weekly_due DATE;
  v_date DATE;
  v_due_at TIMESTAMPTZ;
  v_daily_created BOOLEAN := false;
  v_weekly_created BOOLEAN := false;
  v_missed INTEGER := 0;
  v_result JSONB;
BEGIN
  IF p_observed_at IS NULL THEN
    RAISE EXCEPTION 'Business summary observation time is required.';
  END IF;
  PERFORM set_config('lock_timeout', '3s', true);
  PERFORM set_config('statement_timeout', '25s', true);
  PERFORM pg_advisory_xact_lock(hashtextextended('scan-business-summaries', 0));

  SELECT * INTO STRICT v_settings
  FROM public.business_alert_settings WHERE id = true;
  v_local_now := p_observed_at AT TIME ZONE v_settings.business_timezone;

  IF v_settings.daily_summary_enabled THEN
    v_latest_daily_due := v_local_now::DATE
      - CASE WHEN v_local_now::TIME < v_settings.daily_summary_local_time
        THEN 1 ELSE 0 END;
    FOR v_date IN
      SELECT day_value::DATE
      FROM generate_series(
        GREATEST(
          (v_settings.summaries_activated_at AT TIME ZONE v_settings.business_timezone)::DATE,
          v_latest_daily_due - 30
        ),
        v_latest_daily_due,
        INTERVAL '1 day'
      ) day_value
      ORDER BY day_value
    LOOP
      v_due_at := (v_date + v_settings.daily_summary_local_time)
        AT TIME ZONE v_settings.business_timezone;
      CONTINUE WHEN v_due_at < v_settings.summaries_activated_at
        OR v_due_at > p_observed_at
        OR v_date - 1 < (
          v_settings.summaries_activated_at AT TIME ZONE v_settings.business_timezone
        )::DATE;
      IF v_date < v_latest_daily_due THEN
        INSERT INTO public.business_summary_runs(
          summary_type, period_start, period_end, scheduled_for, run_status
        ) VALUES ('daily', v_date - 1, v_date - 1, v_due_at, 'missed')
        ON CONFLICT (summary_type, period_start, period_end) DO NOTHING;
        v_missed := v_missed + (FOUND)::INTEGER;
      ELSE
        v_result := public.enqueue_business_summary(
          'daily', v_date - 1, v_date - 1, v_due_at, p_observed_at
        );
        v_daily_created := COALESCE((v_result->>'created')::BOOLEAN, false);
      END IF;
    END LOOP;
  END IF;

  IF v_settings.weekly_summary_enabled THEN
    v_latest_weekly_due := v_local_now::DATE
      - MOD(
          EXTRACT(ISODOW FROM v_local_now::DATE)::INTEGER
          - v_settings.weekly_summary_iso_day + 7,
          7
        );
    IF v_latest_weekly_due = v_local_now::DATE
      AND v_local_now::TIME < v_settings.weekly_summary_local_time
    THEN
      v_latest_weekly_due := v_latest_weekly_due - 7;
    END IF;

    FOR v_date IN
      SELECT due_date::DATE
      FROM generate_series(
        GREATEST(
          (v_settings.summaries_activated_at AT TIME ZONE v_settings.business_timezone)::DATE,
          v_latest_weekly_due - 56
        ),
        v_latest_weekly_due,
        INTERVAL '1 day'
      ) due_date
      WHERE EXTRACT(ISODOW FROM due_date)::INTEGER
        = v_settings.weekly_summary_iso_day
      ORDER BY due_date
    LOOP
      v_due_at := (v_date + v_settings.weekly_summary_local_time)
        AT TIME ZONE v_settings.business_timezone;
      CONTINUE WHEN v_due_at < v_settings.summaries_activated_at
        OR v_due_at > p_observed_at
        OR v_date - 7 < (
          v_settings.summaries_activated_at AT TIME ZONE v_settings.business_timezone
        )::DATE;
      IF v_date < v_latest_weekly_due THEN
        INSERT INTO public.business_summary_runs(
          summary_type, period_start, period_end, scheduled_for, run_status
        ) VALUES ('weekly', v_date - 7, v_date - 1, v_due_at, 'missed')
        ON CONFLICT (summary_type, period_start, period_end) DO NOTHING;
        v_missed := v_missed + (FOUND)::INTEGER;
      ELSE
        v_result := public.enqueue_business_summary(
          'weekly', v_date - 7, v_date - 1, v_due_at, p_observed_at
        );
        v_weekly_created := COALESCE((v_result->>'created')::BOOLEAN, false);
      END IF;
    END LOOP;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'dailyCreated', v_daily_created,
    'weeklyCreated', v_weekly_created,
    'missedRecorded', v_missed
  );
END;
$function$

