CREATE OR REPLACE FUNCTION public.set_customer_status(p_customer_id uuid, p_action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_user_id UUID:=auth.uid();v_customer_name TEXT;
BEGIN
  PERFORM public.assert_erp_role(ARRAY['owner','admin','manager','sales'],'تعديل حالة العميل');
  IF p_action NOT IN ('block','unblock','delete') THEN RAISE EXCEPTION 'إجراء حالة العميل غير معتمد.';END IF;
  IF p_action='delete' THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('go-live-collection-customer:'||p_customer_id::TEXT,0));
  END IF;
  SELECT full_name INTO v_customer_name FROM public.customers WHERE id=p_customer_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'العميل غير موجود.';END IF;
  UPDATE public.customers SET
    is_blocked=CASE WHEN p_action='block' THEN true WHEN p_action='unblock' THEN false ELSE is_blocked END,
    is_active=CASE WHEN p_action='block' THEN false WHEN p_action='unblock' THEN true WHEN p_action='delete' THEN false ELSE is_active END,
    is_deleted=CASE WHEN p_action='delete' THEN true ELSE is_deleted END,updated_at=NOW()
  WHERE id=p_customer_id;
  INSERT INTO public.audit_logs(user_id,action,entity_name,entity_id,details)
  VALUES(v_user_id,CASE p_action WHEN 'block' THEN 'BLOCK_CUSTOMER' WHEN 'unblock' THEN 'UNBLOCK_CUSTOMER' ELSE 'SOFT_DELETE_CUSTOMER' END,
    'customers',p_customer_id,jsonb_build_object('customer_name',v_customer_name,'action',p_action));
  RETURN jsonb_build_object('success',true,'customer_id',p_customer_id,'action',p_action);
END;
$function$

CREATE OR REPLACE FUNCTION public.set_erp_staff_account_active(p_user_id uuid, p_is_active boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_full_name TEXT;
  v_target_is_owner BOOLEAN := false;
  v_is_active BOOLEAN := COALESCE(p_is_active, false);
BEGIN
  PERFORM public.assert_erp_role(ARRAY['owner'], 'تفعيل أو تعطيل حساب مستخدم');

  IF p_user_id IS NULL OR p_user_id = auth.uid() THEN
    RAISE EXCEPTION 'لا يمكن تعطيل أو تعديل حسابك الحالي.';
  END IF;
  SELECT profile.full_name INTO v_full_name FROM public.profiles profile WHERE profile.id = p_user_id;
  IF v_full_name IS NULL THEN
    RAISE EXCEPTION 'حساب المستخدم غير موجود.';
  END IF;
  SELECT EXISTS (
    SELECT 1 FROM public.user_roles assignment
    JOIN public.roles role ON role.id = assignment.role_id
    WHERE assignment.user_id = p_user_id AND role.code = 'owner'
  ) INTO v_target_is_owner;

  -- Serialise owner deactivations so there is always an active owner left.
  PERFORM pg_advisory_xact_lock(pg_catalog.hashtext('nawasrah_active_owner_guard'));

  IF NOT v_is_active AND v_target_is_owner AND (
    SELECT COUNT(*)
    FROM public.profiles profile
    JOIN public.user_roles assignment ON assignment.user_id = profile.id
    JOIN public.roles role ON role.id = assignment.role_id
    WHERE profile.is_active = true AND role.code = 'owner'
  ) <= 1 THEN
    RAISE EXCEPTION 'لا يمكن تعطيل آخر مالك نظام نشط.';
  END IF;

  UPDATE public.profiles SET is_active = v_is_active WHERE id = p_user_id;
  INSERT INTO public.audit_logs (user_id, action, entity_name, entity_id, details)
  VALUES (
    auth.uid(),
    CASE
      WHEN v_target_is_owner AND v_is_active THEN 'تفعيل مالك نظام'
      WHEN v_target_is_owner THEN 'تعطيل مالك نظام'
      WHEN v_is_active THEN 'تفعيل حساب مستخدم'
      ELSE 'تعطيل حساب مستخدم'
    END,
    'staff_account', p_user_id,
    jsonb_build_object('full_name', v_full_name, 'is_active', v_is_active, 'is_owner', v_target_is_owner)
  );
  RETURN jsonb_build_object('success', true, 'userId', p_user_id, 'isActive', v_is_active,
    'message', CASE WHEN v_is_active THEN 'تم تفعيل الحساب.' ELSE 'تم تعطيل الحساب.' END);
END;
$function$

