BEGIN
  IF NULLIF(TRIM(p_tracking_token), '') IS NULL
    OR TRIM(p_tracking_token) !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
