      'updated_fields', jsonb_build_array('full_name', 'phone', 'avatar_url'),
      'has_phone', v_profile.phone IS NOT NULL,
      'has_avatar_url', v_profile.avatar_url IS NOT NULL
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'profile', jsonb_build_object(
      'id', v_profile.id,
      'fullName', v_profile.full_name,
      'phone', v_profile.phone,
      'avatarUrl', v_profile.avatar_url,
      'jobTitle', v_profile.job_title,
      'branchId', v_profile.branch_id
    )
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.update_order_status(p_order_id uuid, p_new_status text, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_order_number TEXT;
  v_old_status TEXT;
  v_user_id UUID := auth.uid();
  v_valid_transition BOOLEAN := false;
BEGIN
  PERFORM public.assert_erp_role(
    ARRAY['owner', 'admin', 'manager', 'sales'],
    'تغيير حالة الطلب'
  );

  IF p_new_status = 'processing' THEN
    p_new_status := 'preparing';
  ELSIF p_new_status = 'delivered' THEN
    p_new_status := 'completed';
  END IF;

  SELECT order_number, status
  INTO v_order_number, v_old_status
  FROM public.orders
  WHERE id = p_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'الطلب المحدد غير موجود في قاعدة البيانات.';
  END IF;

  IF v_old_status = 'new'
    AND p_new_status IN ('confirmed', 'preparing', 'cancelled')
  THEN
    v_valid_transition := true;
  ELSIF v_old_status = 'confirmed'
    AND p_new_status IN ('preparing', 'cancelled')
  THEN
    v_valid_transition := true;
  ELSIF v_old_status = 'preparing'
    AND p_new_status IN ('ready', 'out_for_delivery', 'cancelled')
  THEN
    v_valid_transition := true;
  ELSIF v_old_status = 'ready'
    AND p_new_status IN ('out_for_delivery', 'completed', 'cancelled')
  THEN
    v_valid_transition := true;
  ELSIF v_old_status = 'out_for_delivery'
    AND p_new_status IN ('completed', 'cancelled')
  THEN
    v_valid_transition := true;
  END IF;

  IF NOT v_valid_transition THEN
    RAISE EXCEPTION
      'انتقال حالة الطلب غير مسموح به من (%) إلى (%).',
      v_old_status,
      p_new_status;
  END IF;

  IF p_new_status = 'confirmed' THEN
    RETURN public.confirm_order(p_order_id, p_notes);
  ELSIF p_new_status = 'completed' THEN
    RETURN public.complete_order(p_order_id, p_notes);
  ELSIF p_new_status = 'cancelled' THEN
    RETURN public.cancel_order(p_order_id, p_notes);
  END IF;

  UPDATE public.orders
  SET status = p_new_status,
      updated_at = NOW()
  WHERE id = p_order_id;

  INSERT INTO public.order_status_history (
    order_id,
    old_status,
    new_status,
    changed_by,
    notes
  ) VALUES (
    p_order_id,
    v_old_status,
    p_new_status,
    v_user_id,
    COALESCE(p_notes, 'تغيير حالة الطلب إلى ' || p_new_status)
  );

  INSERT INTO public.audit_logs (
    user_id,
    action,
    entity_name,
    entity_id,
    details
  ) VALUES (
    v_user_id,
    'update_order_status',
    'orders',
    p_order_id,
    jsonb_build_object(
      'order_number', v_order_number,
      'old_status', v_old_status,
      'new_status', p_new_status,
      'notes', p_notes
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'order_id', p_order_id,
    'order_number', v_order_number,
    'old_status', v_old_status,
    'status', p_new_status,
    'message', 'تم تحديث حالة الطلب بنجاح إلى ' || p_new_status
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.update_product_flavor_v1(p_flavor_product_id uuid, p_flavor_name_ar text, p_barcode text DEFAULT NULL::text, p_image_url text DEFAULT NULL::text, p_is_active boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_flavor public.products%ROWTYPE;
  v_master public.products%ROWTYPE;
  v_name TEXT := NULLIF(BTRIM(p_flavor_name_ar), '');
  v_image_url TEXT := NULLIF(BTRIM(p_image_url), '');
BEGIN
  PERFORM public.assert_erp_role(
    ARRAY['owner', 'admin', 'manager', 'warehouse_keeper'],
    'تعديل نكهة المنتج'
  );

  IF v_name IS NULL THEN
    RAISE EXCEPTION 'اكتب اسم النكهة.';
  END IF;
  IF CHAR_LENGTH(v_name) > 80 THEN
    RAISE EXCEPTION 'اسم النكهة طويل جدًا.';
  END IF;

  SELECT * INTO v_flavor
  FROM public.products
  WHERE id = p_flavor_product_id
  FOR UPDATE;

  IF NOT FOUND OR v_flavor.flavor_master_product_id IS NULL THEN
    RAISE EXCEPTION 'النكهة المحددة غير موجودة.';
  END IF;

  SELECT * INTO v_master
  FROM public.products
  WHERE id = v_flavor.flavor_master_product_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'المنتج الأساسي للنكهة غير موجود.';
  END IF;
  IF COALESCE(p_is_active, TRUE) AND NOT v_master.is_active THEN
    RAISE EXCEPTION 'فعّل المنتج الأساسي قبل تفعيل هذه النكهة.';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.products p
    WHERE p.flavor_master_product_id = v_master.id
      AND p.id <> v_flavor.id
      AND LOWER(BTRIM(p.flavor_name_ar)) = LOWER(v_name)
  ) THEN
    RAISE EXCEPTION 'هذه النكهة موجودة مسبقًا.';
  END IF;

  UPDATE public.products
  SET
    flavor_name_ar = v_name,
    name_ar = v_master.name_ar || ' - ' || v_name,
    barcode = NULLIF(BTRIM(p_barcode), ''),
    is_active = COALESCE(p_is_active, TRUE),
    updated_at = NOW()
  WHERE id = v_flavor.id;

  IF v_image_url IS NOT NULL THEN
    PERFORM public.set_product_primary_image(v_flavor.id, v_image_url);
  END IF;

  INSERT INTO public.audit_logs (
    user_id,
    action,
    entity_name,
    entity_id,
    details
  ) VALUES (
    auth.uid(),
    'UPDATE_PRODUCT_FLAVOR',
    'products',
    v_flavor.id,
    jsonb_build_object(
      'master_product_id', v_master.id,
      'previous_name_ar', v_flavor.flavor_name_ar,
      'flavor_name_ar', v_name,
      'is_active', COALESCE(p_is_active, TRUE),
      'barcode_changed',
        COALESCE(v_flavor.barcode, '') IS DISTINCT FROM
        COALESCE(NULLIF(BTRIM(p_barcode), ''), ''),
      'image_changed',
        v_image_url IS NOT NULL
    )
  );

  RETURN jsonb_build_object(
    'success', TRUE,
    'productId', v_flavor.id,
    'masterProductId', v_master.id,
    'message', 'تم تحديث النكهة مع الحفاظ على مخزونها وسجلها.'
  );
END;
$function$

